	\[ \eta(x) = \begin{cases}
	(u,1) &\text{if } x=e,\\
	(d,1) &\text{if } x \in V_4 \setminus \{e\},\\
	(a,1) &\text{if } x \in D_4^1 \setminus V_4,\\
