\section{Finitely Generated $L$-subgroups}

In this section, we introduce the concepts of maximal condition on $L$-subgroups and finitely generated $L$-groups. These notions are closely related in classical group theory. A similar relation between these concepts has been provided in Theorem \ref{max_fin}. 

\begin{definition}
	Let $\mu \in L(G)$. Then, $\mu$ is said to satisfy the maximal condition  if every non-empty set $S$ of $L$-subgroups of $\mu$ contains a maximal element.
\end{definition}

\begin{theorem}
	\label{mcon_chain}
	An $L$-subgroup $\mu$ satisfies the maximal condition  if and only if each proper ascending chain of $L$-subgroups of $\mu$ is finite.
\end{theorem}
\begin{proof}
	Suppose that $\mu$ satisfies the maximal condition . Let
	\begin{equation}
	\label{chain2}
	\eta_1 \subsetneq \eta_2 \subsetneq \ldots \subsetneq \eta_n \subsetneq \ldots
	\end{equation} 
	be a proper ascending chain of $L$-subgroups in $\mu$. Let $S = \{ \eta_i \mid i \in \mathbb{N} \}$. Then, by hypothesis, $S$ contains a maximal element $\theta$, that is, there exists $\theta \in S$ such that $\theta$ is not contained in any other $\eta_i$. Since (\ref{chain2}) is a proper chain, it must terminate at $\theta$. 

	\noindent Conversely, suppose that each proper ascending chain of $L$-subgroups in $\mu$ is finite. Let $S$ be a non-empty set of $L$-subgroups of $\mu$. We show that $S$ contains an $L$-subgroup $\theta$ which is not contained in any other element of $S$. Since $S$ is non-empty, there exists $\eta_0$ in $S$. If $\eta_0$ is not contained in any other element of $S$, set $\theta = \eta_0$. Otherwise, there exists $\eta_1 \in S$ such that $\eta_0 \subsetneq \eta_1$. Again, if $\eta_1$ is not contained in any other element of $S$, set $\theta = \eta_1$. Otherwise, there exists $\eta_2 \in S$ such that $\eta_1 \subsetneq \eta_2$. Continuing in this manner, we get an ascending chain
	\begin{equation}
	\label{chain3}
		\eta_0 \subsetneq \eta_1 \subsetneq \eta_2 \subsetneq \ldots
	\end{equation}
	By hypothesis, (\ref{chain3}) is finite. Hence, there exists $\theta \in S$ which is not contained in any other element of $S$. Hence, the result.
\end{proof}

\begin{theorem}
	\label{mcon_subgp}
	Let $\mu \in L(G)$ satisfy the maximal condition and let $\eta \in L(\mu)$. Then, $\eta$ also satisfies the maximal condition.
\end{theorem}


\noindent In \cite{jaballah_Mingen}, Jaballah and Mordeson have introduced the notion of finitely generated fuzzy ideals of a ring through fuzzy singletons:

\begin{definition}(\cite{jaballah_Mingen})
	A fuzzy ideal $\mu$ of a ring R is said to be finitely generated if there exists a finite set of fuzzy singletons $\phi$ such that $\mu = \langle \phi \rangle$.
\end{definition}

\noindent Below, we define finitely genearted $L$-subgroup of a group in the spirit of the above definition.  

\begin{definition}
	An $L$-subgroup $\mu$ of $G$ is said to be finitely generated if there exist finitely many $L$-points ${a_1}_{x_1}, \ldots , {a_n}_{x_n}$ in $\mu$ such that $\mu = \langle {a_1}_{x_1}, \ldots , {a_n}_{x_n} \rangle$.
\end{definition}

\noindent Recall the definition of a minimal generating set for a fuzzy set as given in \cite{mordeson_comm}.
\begin{definition}(\cite{mordeson_comm})
	Let $\mu \in F(G)$. Let $S$ denote a set of fuzzy singletons such that if $x_a, x_b \in S$, then $a=b>0$ and $x \neq 0$. Define the fuzzy subset $\chi(S)$ of $G$ as follows: For all $x \in G$
	\[ \chi(S)(x) = \begin{cases}
		a \qquad \text{ if } x_a \in S,\\
		0 \qquad \text{ otherwise}.
	\end{cases} \]
	Set $\langle S \rangle = \langle \chi(S) \rangle$.
\end{definition}

\noindent Note that the following condition 
\[ \text{if } x_a, x_b \in S, \text{ then } a=b>0, \]
becomes redundant  in Definition 4.5 as the concept of finitely generated $L$-subgroup involves the union of $L$-points. Hence, Definition 4.5 is a simple version of the above definition.  

\noindent Here, we prove the following:

\begin{theorem}
	Let $H$ be a subgroup of $G$. Then, $H$ is finitely generated if and only if the characteristic function $1_H$ is a finitely generated $L$-subgroup of $G$.
\end{theorem}
\begin{proof}
	Let $H$ be a finitely generated subgroup of $G$. Then, there exist finitely many elements $x_1, x_2, \ldots, x_n$ in $H$ such that 
	\[ H = \langle x_1, x_2, \ldots, x_n \rangle. \]
	We claim that 
	\[ 1_H = \langle 1_{x_1}, 1_{x_2}, \ldots 1_{x_n} \rangle. \]
	Since $1_{x_1}, 1_{x_2}, \ldots, 1_{x_n} \in 1_H$,
	\[ \langle 1_{x_1}, 1_{x_2}, \ldots, 1_{x_n} \rangle \subseteq 1_H. \]
	To show the reverse inclusion, let $1_z \in 1_H$. Then, $z \in H = \langle x_1, x_2, \ldots, x_n \rangle.$ This implies
	\[ z = y_1 y_2 \ldots y_k, \text{ where } y_i \text{ or } {y_i}^{-1} \in \{x_1, x_2, \ldots, x_n\}. \]
	Thus,
	\begin{equation*}
		\begin{split}
			1_z &= 1_{y_1 y_2 \ldots y_k} \\
			&= 1_{y_1}\circ 1_{y_2} \circ \ldots 1_{y_k}\\
			&\subseteq \langle 1_{y_1}, 1_{y_2} \ldots, 1_{y_k} \rangle \\
			&\subseteq \langle 1_{x_1}, 1_{x_2}, \ldots, 1_{x_n} \rangle.
		\end{split}
	\end{equation*}
	Hence, $1_H = \langle 1_{x_1}, 1_{x_2}, \ldots 1_{x_n}\rangle$.

	\noindent Conversely, suppose that $1_H$ is finitely generated. Then, by definition, there exist finitely many $L$-points ${a_1}_{x_1}, {a_2}_{x_2}, \ldots {a_n}_{x_n}$ of $1_H$ such that
	\[ 1_H = \langle {a_1}_{x_1}, {a_2}_{x_2}, \ldots {a_n}_{x_n} \rangle. \] 
	Clearly, we can assume that each $a_i>0$. This implies
	\[ 1_H(x_i) \geq a_i > 0 \text{ for all } i=1,2,\ldots n, \]
	that is, 
	\[ 1_H(x_i) = 1. \]
	Thus, $1_{x_1}, 1_{x_2}, \ldots, 1_{x_n} \in 1_H$ and therefore,
	\[ 1_H = \langle {a_1}_{x_1}, {a_2}_{x_2}, \ldots {a_n}_{x_n} \rangle \subseteq \langle 1_{x_1}, 1_{x_2}, \ldots, 1_{x_n} \rangle \subseteq 1_H.  \]
	Thus, $1_H = \langle 1_{x_1}, 1_{x_2}, \ldots 1_{x_n} \rangle$. We claim that $H = \langle x_1, x_2, \ldots, x_n \rangle$.

	\noindent Suppose, if possible, that $H \neq \langle x_1, x_2, \ldots, x_n \rangle.$ Then, there exists $z \in H$ such that $z \notin \langle x_1, x_2, \ldots x_n \rangle$. Note that since $1_H = \langle \bigcup_{i=1}^{n} 1_{x_i} \rangle$, by Theorem \ref{gen}, 
	\begin{equation*}
		\begin{split}
			1 = 1_H(z) &= \mathop{\vee}\limits_{a \leq 1}{\left\{a \mid z\in\left\langle \left( \mathop{\cup}\limits_{i=1}^{n} 1_{x_i} \right)_{a}\right \rangle \right\}}\\ 
			&= \mathop{\vee}\limits_{a \leq 1}{\left\{a \mid z\in\left\langle \mathop{\cup}\limits_{i=1}^{n} (1_{x_i})_a \right \rangle \right\}}.
		\end{split}
	\end{equation*}
	Now, since $z \notin \langle x_1, x_2, \ldots x_n\rangle$, $z\notin\left\langle \mathop{\cup}\limits_{i=1}^{n} (1_{x_i})_a \right \rangle$ for any value of $a>0$. It follows that $1=1_H(z)=0$, which is absurd. Hence, we conclude that
	\[ H= \langle x_1, x_2, \ldots, x_n \rangle. \]	
\end{proof}


\noindent The following example illustrates Definition 4.5:

\begin{example}
	Let $G = D_8$, the dihedral group of order 8, given by
	\[ D_8 = \langle r, s \mid r^4 = s^2 = e, rs = sr^{-1} \rangle. \]
	Let $H_1 = \{e, r^2\}$ be the center of $G$, $H_2 = \{e, s\}$ and $K = \{ e, r^2, s, sr^2\}$.
	Let $L$ be the lattice represented by the following figure.
	\begin{center}
		\includegraphics[scale=0.7]{lattice1.jpg}
	\end{center}
	Define $\mu : G \rightarrow L$ as follows:
	\[ \mu(x) = \begin{cases}
		1 & \text{if } x=e,\\
		b & \text{if } x \in H_1 \setminus \{e\},\\
		c & \text{if } x \in H_2 \setminus \{e\},\\
		a & \text{if } x \in K \setminus H_1 \cup H_2,\\
		0 & \text{if } x \in D_8 \setminus K.
		\end{cases} \]
	Since each non-empty level subset $\mu_t$ is a subgroup of $G$, by Theorem \ref{lev_gp},  $\mu \in L(G)$. We show that $\mu = \langle b_{r^2}, c_s \rangle$.
	\noindent Let $\eta = b_{r^2} \cup c_s$. Then, $\eta \in L^{\mu}$ and hence, $\langle \eta \rangle \subseteq \mu$. Now, tip($\eta$) = $\mathop{\vee}\limits_{x \in G} \eta(x) = b \vee c = 1$. Hence, by Theorem \ref{gen}, for all $x \in G$,
	\[ \langle \eta \rangle (x) = \mathop{\vee}\limits_{t \leq 1} \{t \mid x \in \langle \eta_t \rangle \}. \]
	Note that 
	\[ \eta_0 = D_8, \eta_a = \{r^2, s\}, \eta_b = \{r^2\}, \eta_c = \{s\}, \eta_1 = \emptyset. \]
	Hence,
	\[ \langle \eta_0 \rangle = D_8, \langle \eta_a \rangle = K, \langle \eta_b \rangle = H_1 , \langle \eta_c \rangle = H_2, \langle \eta_1 \rangle = \{e\}. \]
	Thus, $\langle \eta \rangle = \langle b_{r^2}, c_s \rangle = \mu.$ 
\end{example}

\noindent Recall that a lattice $L$ is said to be upper well ordered if  every non-empty subset of $L$ contains its supremum. Clearly, if $L$ is upper well ordered, then each $L$-subset $\eta$ satisfies the sup-property. Also, every upper well ordered lattice is a chain.

\begin{lemma}
	\label{fgen_chain}
	Let $L$ be an upper well ordered lattice and let $\mu$ be a finitely generated $L$-group. Then, every proper ascending chain of $L$-subgroups of $\mu$ whose set union equals $\mu$ is finite.
\end{lemma}
\begin{proof}
	Suppose that $\mu = \langle {a_1}_{x_1}, \ldots , {a_n}_{x_n} \rangle.$ Let
	\[ \eta_1 \subsetneq \eta_2 \subsetneq \ldots \subsetneq \eta_l \subsetneq \ldots \]
	be a proper ascending chain of $L$-subgroups of $\mu$ such that $\cup \eta_i = \mu$. Then,
	\[ {a_j}_{x_j} \in \cup \eta_i \text{ for all } j = 1, \ldots, n. \]
	This implies 
	\[ \vee \eta_i(x_j) \geq a_j \text{ for all } j = 1, \ldots, n. \]
	Since $L$ is upper well ordered, there exists $m_j$ such that $\eta_{m_j}(x_j) \geq a_j$, that is, ${a_j}_{x_j} \in \eta_{m_j}$. Let $m$ be the maximum of $m_1, \ldots, m_n.$ Then, ${a_j}_{x_j} \in \eta_m$ for all $j = 1, \ldots, n$. Thus, $\mu = \langle {a_1}_{x_1}, \ldots, {a_n}_{x_n} \rangle \subseteq \eta_m.$ Hence, the chain terminates at some $k \leq m.$
\end{proof}

\begin{lemma}  (\cite{jahan_max})
	\label{union_subgp}
	Let $L$ be a chain and let $\mu \in L(G)$. Let $C$ be a chain of $L$-subgroups of $\mu$. Then,
	\[ \bigcup_{\eta \in C} \eta \in L(\mu). \]	
\end{lemma}

\begin{theorem}
	\label{max_fin}
	Let $\mu \in L(G)$. If $\mu$ satisfies the maximal condition, then every $L$-subgroup of $\mu$ is finitely generated. The converse holds if $L$ is an upper well ordered lattice.
\end{theorem}
\begin{proof}
	Suppose that $\mu$ satisfies the maximal condition and let $\eta \in L(\mu)$. Let ${a_1}_{x_1} \in \eta$. If $\eta=\langle {a_1}_{x_1} \rangle$, then $\eta$ is finitely generated and we are done. Hence, suppose that $\eta \neq \langle {a_1}_{x_1} \rangle$. Then, there exists ${a_2}_{x_2} \in \eta$ such that ${a_2}_{x_2} \notin \langle {a_1}_{x_1} \rangle$. If $\eta = \langle {a_1}_{x_1}, {a_2}_{x_2} \rangle$, then we are done. Otherwise, there exists ${a_3}_{x_3} \in \eta$ such that ${a_3}_{x_3} \notin \langle {a_1}_{x_1}, {a_2}_{x_2} \rangle$. Continuing this process, we can define the $L$-subgroups $\eta_i$ of $\eta$ by choosing, as long as possible, $L$-points ${a_1}_{x_1}, {a_2}_{x_2}, \ldots$, of $\eta$ such that
	\[ \eta_i = \langle {a_1}_{x_1}, \ldots {a_i}_{x_i} \rangle \text{ and } {{a_{i+1}}_{x_{i+1}}} \notin \eta_i. \]
	Then, $\eta_1 \subsetneq \eta_2 \subsetneq \ldots$ is a proper ascending chain of $L$-subgroups of $\eta$. By Theorem \ref{mcon_subgp}, $\eta$ satisfies the maximal condition. Hence, by Theorem \ref{mcon_chain}, this chain terminates at some finite $m$. Thus, there does not exist any $b_y \in \eta$ such that $b_y \notin \langle {a_1}_{x_1}, \ldots {a_m}_{x_m} \rangle = \eta_m$. This implies $\eta = \eta_m$ and hence, $\eta$ is finitely generated.

	\noindent Conversely, suppose that $L$ is upper well ordered and let $\mu \in L(G)$ such that every $L$-subgroup of $\mu$ is finitely generated.
	Let $\eta_1 \subsetneq \eta_2 \subsetneq \ldots$ be a proper ascending chain of $L$-subgroups of $\mu$. Since $L$ is an upper well ordered lattice, by Lemma \ref{union_subgp}, $\eta = \cup \eta_i$ is an $L$-subgroup of $\mu$. By hypothesis, $\eta$ is finitely generated. Hence, by Lemma \ref{fgen_chain}, the above chain of $L$-subgroups must be finite. Hence, $\mu$ satisfies the maximal condition. 
\end{proof}

\section{Frattini $L$-Subgroup of Finitely Generated $L$-Group}

In this section, we explore some properties of maximal and Frattini $L$-subgroups of finitely generated $L$-subgroups. The Frattini $L$-subgroup of an $L$-group has been investigated by the authors in \cite{jahan_max}. Moreover, the authors have defined the non-generators of an $L$-group and established a relation between the non-generators and the Frattini $L$-subgroup of $\mu$. We recall these below:   

\begin{definition}(\cite{jahan_max})
	Let $\mu \in L(G)$. The Frattini $L$-subgroup $\Phi(\mu)$ of $\mu$ is defined to be the intersection of all the maximal $L$-subgroups of $\mu$.
	If $\mu$ has no maximal $L$-subgroups, then we define $\Phi(\mu) = \mu$.
\end{definition}

\begin{definition}(\cite{jahan_max})
	Let $\mu \in L(G)$. An $L$-point $a_x \in \mu$ is said to be a non-generator of $\mu$ if, whenever $\langle \eta, a_x \rangle = \mu$ for some $\eta \in L^{\mu}$, then $\langle \eta \rangle = \mu$.
\end{definition}

\begin{theorem}(\cite{jahan_max})
	\label{frat}
	Let $\mu \in L(G)$ and define $\lambda \in L^\mu$ as follows:
	\[ \lambda =  \bigcup \{a_x \mid a_x \text{ is a non-generator of } \mu \}. \]
	Then, $\lambda \in L(\mu)$ and $\lambda \subseteq \Phi(\mu)$. Moreover, if $L$ is an upper well ordered lattice, then $\lambda = \Phi(\mu)$.
\end{theorem}

\begin{theorem}(\cite{jahan_max})
	\label{fra_nor}
	Let $L$ be an upper well ordered lattice and let $\mu$ be a normal $L$-subgroup of $G$. Then, $\Phi(\mu)$ is a normal $L$-subgroup of $\mu$.
\end{theorem}

\begin{theorem}
	Let $L$ be an upper well ordered lattice and $\mu \in L(G)$ be a non-trivial finitely generated $L$-group. Then, $\mu$ has a maximal $L$-subgroup.
\end{theorem}
\begin{proof}
	Since $\mu$ is finitely generated, there exist finitely many $L$-points ${a_1}_{x_1}, \ldots, {a_n}_{x_n}$ such that $\mu = \langle {a_1}_{x_1}, \ldots, {a_n}_{x_n} \rangle$. Let $S$ be the set of all proper $L$-subgroups of $\mu$. Then, $S$ is non-empty since the trivial $L$-subgroup $\mu^{a_{0}}_{t_{0}}\in S$ where $a_0=\mu(e)$ and $t_0=\text{inf } \mu$.  Let $C = \{ \eta_i \}_{i \in I}$ be a chain in $S$. We claim that
	\[ \bigcup_{i \in I} \eta_i \in S. \]
	\noindent Firstly, we note that by Lemma \ref{union_subgp}, $\mathop{\bigcup}\limits_{i \in I} \eta_i \in L(\mu)$. Hence, we only need to show that $\mathop{\bigcup}\limits_{i \in I} \eta_i$ is a proper $L$-subgroup of $\mu$. Suppose, if possible, that $\mathop{\bigcup}\limits_{i \in I} \eta_i$ is not a proper $L$-subgroup of $\mu$. That is,
	\[\mu = \langle {a_1}_{x_1}, \ldots, {a_n}_{x_n} \rangle = \mathop{\bigcup}\limits_{i \in I} \eta_i.\]
	Then, ${a_1}_{x_1}, \ldots, {a_n}_{x_n} \in \mathop{\bigcup}\limits_{i \in I} \eta_i$. This implies that
	\[ \bigvee_{i \in I} \eta_i(x_j) \geq a_j \text{ for each } 1 \leq j \leq n. \]  
	\noindent Since $L$ is upper well ordered, for each $j$, there exists an $L$-subgroup, say $\eta_{{i}_{j}}$, in $C$ such that $\eta_{{i}_{j}}(x_j) \geq a_j$.  Moreover, since $C$ is a chain, without loss of generality, we may assume that 
	\[ \eta_{{i}_{1}} \subseteq \eta_{{i}_{2}} \subseteq \ldots \subseteq \eta_{{i}_{n}}.\]
	Thus,
	\[\mu = \langle {a_1}_{x_1}, \ldots, {a_n}_{x_n} \rangle = \mathop{\bigcup}\limits_{i \in I} \eta_i = \eta_{{i}_{n}},\]
	\noindent which contradicts the assumption that the elements of $C$ are proper $L$-subgroups of $\mu$. Hence, $\mathop{\bigcup}\limits_{i \in I} \eta_i$ is a proper $L$-subgroup of $\mu$. Consequently, $\mathop{\bigcup}\limits_{i \in I} \eta_i \in S$, and we conclude that every chain in $S$ has an upper bound in $S$. By Zorn's lemma, $S$  has a maximal element, which is the required maximal $L$-subgroup of $\mu$. 
\end{proof}
\begin{theorem}
	\label{fgn_frat}
	Let $L$ be an upper well ordered lattice and let $\mu$ be an $L$-group with a finitely generated Frattini $L$-subgroup $\Phi(\mu)$. Then, the only $L$-subgroup $\eta$ of $\mu$ such that 
	\[	\eta \circ \Phi(\mu) = \mu	\]
	is $\eta = \mu$.
\end{theorem}
\begin{proof}
	Since $\Phi(\mu)$ is finitely generated, there exist a finite number of $L$-points ${a_1}_{x_1}, \ldots, {a_n}_{x_n}$ in $\Phi(\mu)$ such that 
	\[	\Phi(\mu) = \langle {a_1}_{x_1}, \ldots, {a_n}_{x_n} \rangle.	\]
	Clearly,
	\begin{equation*}
	\begin{split}
	\mu &= \eta \circ \Phi(\mu)\\ 
	& \subseteq \langle \eta, \Phi(\mu) \rangle \\
	& = \langle \eta, {a_1}_{x_1}, \ldots {a_n}_{x_n} \rangle\\
	& \subseteq \mu.
	\end{split} 
	\end{equation*}
	Now, since $L$ is upper well ordered, by Theorem \ref{frat},
	\[ \Phi(\mu) = \bigcup \{ a_x \mid a_x \text{is a non-generator of } \mu \}. \]
	Therefore, each of ${a_i}_{x_i}$ is a non-generator of $\mu$. This implies
	\begin{equation*}
	\begin{split}
	\mu & = \langle \eta, {a_1}_{x_1}, \ldots {a_n}_{x_n} \rangle\\
	&= \langle \eta, {a_1}_{x_1} \ldots {a_{n-1}}_{x_{n-1}} \rangle \\
	& \quad \quad \vdots \\
	& = \langle \eta \rangle = \eta.
	\end{split}
	\end{equation*}
	Hence, $\eta = \mu$.		
\end{proof}

\begin{lemma}
	\label{zrn}
	Let $L$ be an upper well ordered lattice and let $\mu \in L(G)$. Suppose that $\theta \in L(\mu)$ and let $a_x$ be an $L$-point of $\mu$ such that $a_x \notin \theta$. Then, there exists $\eta \in L(\mu)$ such that $\eta$ is maximal with respect to the conditions $\theta \subseteq \eta$ and $a_x \notin \eta$.
\end{lemma}
\begin{proof}
	Consider the set $S = \{ \nu \in L(\mu) \mid \theta \subseteq \nu \text{ and } a_x \notin \nu \}$. Then, $S$ is non-empty since $\theta \in S$.  Let $C = \{ \theta_i \}_{i \in I}$ be a chain in $S$. We claim that 
	\[\bigcup_{i \in I} \theta_i \in S. \]  
	By Lemma \ref{union_subgp}, $\mathop{\bigcup}\limits_{i \in I} \theta_i \in L(\mu)$. Also, $\theta \subseteq \mathop{\bigcup}\limits_{i \in I} \theta_i$. Now, since $L$ is upper well ordered and $a_x \notin \theta_i$ for all $i \in I$, $a_x \notin \mathop{\bigcup}\limits_{i \in I} \theta_i$. Hence, $\mathop{\bigcup}\limits_{i \in I} \theta_i \in S$ so that every chain in  $S$ has an upper bound in $S$. Therefore, by Zorn's lemma, $S$ has a maximal element $\eta$. This proves the result.
\end{proof}

\begin{theorem}
	\label{max_prp}
	Let $L$ be an upper well ordered lattice and let $\mu$ be a finitely generated $L$-group. Let $\eta$ be a proper $L$-subgroup of $\mu$. Then, $\eta$ is contained in a maximal $L$-subgroup of $\mu$.
\end{theorem}
\begin{proof}
	Let $\mu = \langle {a_1}_{x_1}, \ldots , {a_n}_{x_n} \rangle$. Since $\eta \subsetneq \mu $, let ${b_1}_{y_1}$ be the first of ${a_1}_{x_1}, \ldots, {a_n}_{x_n}$ such that ${b_1}_{y_1} \notin \eta$. By Lemma \ref{zrn}, there exists $\theta_1 \in L(\mu)$ such that $\theta_1$ is maximal with respect to the conditions $\eta \subseteq \theta_1$ and ${b_1}_{y_1} \notin \theta_1$. Hence, any $L$-subgroup of $\mu$ that contains $\theta_1$ also contains ${b_1}_{y_1}$. Let $\langle \theta_1, {b_1}_{y_1} \rangle = \nu_1$. If $\nu_1 = \mu$, then $\theta_1$ is  the required maximal $L$-subgroup. If not, let ${b_2}_{y_2}$ be the first of ${a_1}_{x_n}, \ldots, {a_n}_{x_n}$ not contained in $\nu_1$. Then, there exists $\theta_2 \in L(\mu)$ that is maximal with respect to the conditions that $\nu_1 \subseteq \theta_2$ and ${b_2}_{y_2} \notin \theta_2$. Since $\mu = \langle {a_1}_{x_1}, \ldots, {a_n}_{x_n} \rangle$, by continuing this process, we obtain $L$-points ${b_1}_{y_1}, {b_2}_{y_2}, \ldots, {b_i}_{y_i}$ and a finite chain of $L$-subgroups
	\[ \theta_1 \subseteq \theta_2 \subseteq \ldots \subseteq \theta_i \]
	such that $\langle \theta_i, {b_i}_{y_i} \rangle = \mu$. Thus, $\theta_i$ is the required maximal $L$-subgroup of $\mu$ containing $\eta$.  
\end{proof}

\begin{lemma}
	\label{prp_pro}
	Let $L$ be an upper well ordered lattice and let $\mu$ be a finitely generated $L$-group. Let $\eta \in NL(\mu)$. Suppose that $\eta$, $\Phi(\mu)$ and $\mu$ have the same tips. Then, $\eta \subseteq \Phi(\mu)$ if and only if there is no proper subgroup $\theta$ of $\mu$ such that $\eta \circ \theta = \mu$.
\end{lemma}
\begin{proof}
	Let $\eta \subseteq \Phi(\mu)$. Let $\theta$ be a proper $L$-subgroup of $\mu$. Then, by Theorem \ref{max_prp}, there exists a maximal $L$-subgroup $\nu$ of $\mu$ such that $\theta \subseteq \nu$. Then, $\eta \subseteq \Phi(\mu) \subseteq \nu$ and $\theta \subseteq \nu$, which implies that 
	\[ \eta \circ \theta \subseteq \nu \subsetneq \mu. \]
	Hence, there does not exist any proper $L$-subgroup $\theta$ of $\mu$ such that $\eta \circ \theta = \mu$.
	Conversely, suppose that there does not exist any proper $L$-subgroup $\theta$ of $\mu$ such that $\eta \circ \theta = \mu$. If $\eta \nsubseteq \Phi(\mu)$, then there exists a maximal $L$-subgroup $\nu$ of $\mu$ such that $\eta \nsubseteq \nu$. Since tip of $\Phi(\mu)$ equals tip of $\mu$, $\text{tip}~\nu = \text{tip}~\mu$. Therefore,
	\[ \nu \subsetneq \eta \circ \nu \subseteq \mu. \]
	Since $\nu$ is a maximal $L$-subgroup of $\mu$, we must have $\eta \circ \nu = \mu$, which contradicts our assumption. Hence, $\eta \subseteq \Phi(\mu)$.  
\end{proof}

\begin{lemma}
	\label{int_pro}
	Let $\eta$, $\theta$, $\sigma \in L(\mu)$ such that $\sigma \subseteq \eta$. Then,
	\[	\eta \cap (\theta \circ \sigma) = (\eta \cap \theta) \circ \sigma.	\]
\end{lemma}
\begin{proof}
	Let $x \in G$. Then,
	\begin{equation*}
	\begin{split}
	(\eta \cap (\theta \circ \sigma))(x) & = \eta(x) \wedge \left\{	\bigvee_{y \in G} \{ \theta(xy^{-1}) \wedge \sigma(y) \right\} \\
	& = \bigvee_{y \in G} \left\{ \eta(x) \wedge \theta(xy^{-1}) \wedge \eta(y^{-1}) \wedge \sigma(y) \right\} \\
	& \leq \bigvee_{y \in G} \{ \eta(xy^{-1}) \wedge \theta(xy^{-1}) \wedge \sigma(y) \} \\
	& = \bigvee_{y \in G} \left\{ (\eta \cap \theta)(xy^{-1}) \wedge \sigma(y) \right\} \\
	& = ((\eta \cap \theta) \circ \sigma)(x).
	\end{split}
	\end{equation*} 
	Hence, $\eta \cap (\theta \circ \sigma) \subseteq \eta \cap \theta) \circ \sigma$.
	Conversely, for all $y$, $z \in G$ such that $x=yz$,
	\begin{equation*}
	\begin{split}
	(\eta \cap \theta)(y) \wedge \sigma(z) & = \eta(y) \wedge \theta(y) \wedge \sigma(z) \\
	& = \eta(y) \wedge \theta(y) \wedge \eta(z) \wedge \sigma(z) \\
	& \leq \eta(x) \wedge (\theta(y) \wedge \sigma(z)). \\
	\end{split}
	\end{equation*}
	Taking supremum over all such $y$ and $z$, we get
	\begin{equation*}
	\begin{split}
	((\eta \cap \theta) \circ \sigma))(x) & = \bigvee_{x=yz} \{ (\eta \cap \theta)(y) \wedge \sigma(z) \} \\
	& \leq \bigvee_{x=yz} \{ \eta(x) \wedge \{ \theta(y) \wedge \sigma(z) 	\} \\
	& = \eta(x) \wedge (\bigvee_{x=yz} \{ \theta(y) \wedge \sigma(z) \} ) \\
	& = (\eta \cap (\theta \circ \sigma))(x).
	\end{split}
	\end{equation*}
	Hence,
	\[	\eta \cap (\theta \circ \sigma) = (\eta \cap \theta) \circ \sigma.	\]  	 
\end{proof}

\begin{theorem}
	Let $L$ be an upper well ordered lattice and $\mu$ be a finitely generated $L$-group. Let $\eta \in L(\mu)$ and $\sigma \in NL(\mu)$ such that $\eta, \sigma, \Phi(\eta)$ and $\Phi(\mu)$ have tips equal to $\text{tip}~\mu$. If $\sigma \subseteq \Phi(\eta)$, then $\sigma \subseteq \Phi(\mu)$.
\end{theorem}
\begin{proof}
	Suppose that $\sigma \nsubseteq \Phi(\mu)$. Then, by Lemma \ref{prp_pro}, there exists a proper $L$-subgroup $\theta$ of $\mu$ such that $\mu = \theta \circ \sigma$. Since $\text{tip}~\mu = \text{tip}~\sigma$, $\text{tip}~\theta = \text{tip}~\mu$. Now, since $\sigma \subseteq \Phi(\eta)$, $\sigma \subseteq \eta \subseteq \mu = \theta \circ \sigma$. Therefore, by Lemma \ref{int_pro},
	\[ \eta = \eta \cap \mu = \eta \cap (\theta \circ \sigma) = (\eta \cap \theta) \circ \sigma. \]
	Again, since $\sigma \subseteq \Phi(\eta)$, by Lemma \ref{prp_pro}, $\eta \cap \theta = \eta$. Therefore, $\sigma \subseteq \eta \subseteq \theta$, which imples that $\mu = \theta \circ \sigma = \theta$,
	which contradicts the assumption that $\theta$ is a proper $L$-subgroup of $\mu$. Hence, we must have $\sigma \subseteq \Phi(\mu)$.
\end{proof}

