\section{Phases at various disorder strength}
\label{appx:level_stat}

To characterize the dynamical phases in our system governed by Eq.~\eqref{eq:IsingModel}, we compute the level statistics, varying from the disorder strength $W=0J$ to $W=50J$, as shown in Fig.~\ref{fig:level_stat_vary_W}. In the absence of the disorder, $W=0J$, the level statistics deviates from both GOE statistics and POI distribution and the level spacing concentrates around 0, reflecting the highly degenerate energy levels and indicating the phase is neither thermalized nor MBL. Around $W=3J$, the level statistics begin to align with the GOE statistics, showing the emergence of the thermalized phase. As $W$ increases, the level statistics get closer to the GOE statistics and reaches the peak at $W=5J$, before the characteristics of the thermalized phase fade beyond this point. With further increase in the disorder strength, the distribution gradually shifts toward the Poisson distribution. The Poisson distribution is well-approximated for $W > 20J$, suggesting that the system is in the MBL phase in this strong disorder regime. Based on this transition, we select values $W$ where the level statistics are most closely aligned with the GOE statistics and the Poisson distribution to define the thermalized and MBL initialisations, respectively. 




\begin{figure}[h!]
    \centering
    \includegraphics[width=0.9\linewidth]{level_statistics_vary_W_1.jpg}
    \caption{\textbf{Crossover in level statistics from $W=0J$ to $W=50J$.} The histograms represent the level statistics of 500 instances of 9-qubit systems governed by the Hamiltonian in Eq.~\ref{eq:IsingModel}. At $W=0J$, the system is integrable, leading to the near-degenerate energy levels. As $W$ increases from $3J$ to $50J$, the level statistics evolves from GOE statistics (red curve), indicative of the thermalized phase, to the POI (blue curve), which characterize the MBL phase. The thermalized regime appears around $W=3J$ to $7J$, while the level statistics approach to the Poisson distribution at around $W=20J$. }
    \label{fig:level_stat_vary_W}
\end{figure}


\section{Proof of Eq.~\eqref{eq:variance-expressivity-bound}}
\label{appx:proof_bound}
We derive the expressivity-dependent upper bound for the variance of the loss function in Eq.~\eqref{eq:variance-expressivity-bound}. Recall that the parametrized dynamics form an ensemble $\Ubb_{\Theta_D}$, and denote $\rho_0$ as the initial state and $O$ as the observable. The variance of the loss can be expressed as
\begin{align}
    \Var_{\thv\sim \PC}[\LC(\thv)]&=\mathbb{E}_{\thv\sim \PC}[\LC(\thv)^2]-\mathbb{E}_{\thv\sim \PC}[\LC(\thv)]^2 \\
    & = \int_{U \in \Ubb_{\Theta_D}} d\mu(U) \Tr\left[ U^{\otimes2} \rho_0^{\otimes 2} U^{\dagger \otimes 2} O^{\otimes 2}  \right] - \left( \int_{U \in \Ubb_{\Theta_D}} d\mu(U)  \Tr[U\rho_0 U^\dagger O]\right)^2\;, \label{eq:proof-00}
\end{align}
where we use $\Tr[A]\Tr[B] = \Tr[A\otimes B]$ in the second equality.

Next, we consider the operator $\AC_{\Ubb_{\Theta_D}}^{(1)}(\rho_0)$ and $\AC_{\Ubb_{\Theta_D}}^{(2)}(\rho_0)$ of the form
\begin{align}
\AC_{\Ubb_{\Theta_D}}^{(1)}(\rho_0) & = \int_{V\in \,\Ubb(2^n)} d\mu_H(V) V \rho_0 V^{\dagger} - \int_{U \in \Ubb_{\Theta_D}} d\mu(U)  U \rho_0 U^{\dagger} \;, \\
    \AC_{\Ubb_{\Theta_D}}^{(2)}(\rho_0) & = \int_{V\in \,\Ubb(2^n)} d\mu_H(V) V^{\otimes 2} \rho_0^{\otimes 2} V^{\dagger \otimes2} - \int_{U \in \Ubb_{\Theta_D}} d\mu(U)  U^{\otimes2} \rho_0^{\otimes 2} U^{\dagger \otimes 2}  \;,  \label{eq:proof-expressivity-operator} 
\end{align}
where $d\mu_H(V)$ is the Haar measure over the unitary group $\Ubb(2^n)$ of size $2^n$. $\AC_{\Ubb_{\Theta_D}}^{(2)}(\rho_0)$ and $\AC_{\Ubb_{\Theta_D}}^{(2)}(\rho_0)$ indicate how far away the first and second moment operators on $\rho_0$ over $\Ubb_{\Theta_D}$ are from the Haar random.

By expressing Eq.~\eqref{eq:proof-00} in terms of the operators $\AC_{\Ubb_{\Theta_D}}^{(1)}(\rho_0)$ and  $\AC_{\Ubb_{\Theta_D}}^{(2)}(\rho_0)$, we have
\begin{align}
    \Var_{\thv\sim \PC}[\LC(\thv)]=& \int_{V\in \,\Ubb(2^n)} d\mu_H(V) \Tr\left[ V^{\otimes 2} \rho_0^{\otimes 2} V^{\dagger \otimes2} O^{\otimes 2}\right] -  \Tr\left[ \AC_{\Ubb_{\Theta_D}}^{(2)}(\rho_0) O^{\otimes 2}\right] \nonumber \\
    & - \left( \int_{V\in \,\Ubb(2^n)} d\mu_H(V) \Tr\left[ V \rho_0 V^{\dagger } O\right] -  \Tr\left[ \AC_{\Ubb_{\Theta_D}}^{(1)}(\rho_0) O\right]\right)^2 \\
    = & \Var_{\rm Haar}[\LC(\thv)] - \Tr\left[ \AC_{\Ubb_{\Theta_D}}^{(2)}(\rho_0) O^{\otimes 2}\right] + \frac{\Tr[O]}{2^{n-1}} \Tr\left[ \AC_{\Ubb_{\Theta_D}}^{(1)}(\rho_0) O\right] - \left(\Tr\left[ \AC_{\Ubb_{\Theta_D}}^{(1)}(\rho_0) O\right] \right)^2 \label{eq:proof-step-var}\\
    \leq & \Var_{\rm Haar}[\LC(\thv)]  + \| \AC_{\Ubb_{\Theta_D}}^{(2)} (\rho_0)\|_2 \| O\|^2_2 + \frac{\Tr[O]}{2^{n-1}} \| \AC_{\Ubb_{\Theta_D}}^{(1)}(\rho_0) \|_2 \| O\|_2 - \| \AC_{\Ubb_{\Theta_D}}^{(1)}(\rho_0) \|_2^2 \| O\|_2^2 \;\;,
\label{eq:proof-01}
\end{align}
where to reach the last inequality we take the absolute of the Eq.~\eqref{eq:proof-step-var} and use the triangle inequality $|a+b| < |a| + |b|$ (for some values $a,b$) followed by applying Cauchy-Schwarz inequality $\Tr|AB| \leq \|A\|_2\|B\|_2$ (for some matrices $A,B$) and $\|O^{\otimes2}\|_2 = \|O\|_2^2$. 


Next, we link the norms $\| \AC_{\Ubb_{\Theta_D}}^{(1)} (\rho_0)\|_2$ and $\| \AC_{\Ubb_{\Theta_D}}^{(2)} (\rho_0)\|_2$ in Eq.~\eqref{eq:proof-01} to their respective frame potentials. In particular, consider the $t$-order frame potentials with respect to $\mathbb{U}_{\Theta_{D}}$ and Haar random
\begin{equation}
\FC^{(t)}_{\mathbb{U}_{\Theta_{D}}} = \int\int_{U,V\in \mathbb{U}_{\Theta_{D}}} d\mu(U)d\mu(V) |\bra{0}V^\dagger U\ket{0}|^{2t}\;\;,
\end{equation}  and 
\begin{equation}\FC^{(t)}_{\rm Haar} = \int\int_{U,V\in \Ubb(2^n)} d\mu_H(U) d\mu_H(V) |\bra{0}V^\dagger U\ket{0}|^{2t} \;\;.
\end{equation}


Now, let us unroll $\| \AC_{\Ubb_{\Theta_D}}^{(t)} (\rho_0)\|_2$ as follows
\begin{align}
    \| \AC_{\Ubb_{\Theta_D}}^{(t)}(\rho_0) \|^2_2 = & \Tr\Bigg[\left(\int_{V'\in \,\Ubb(2^n)} d\mu_H(V') V'^{\otimes t} \rho_0^{\otimes t} V'^{\dagger \otimes t} - \int_{U' \in \Ubb_{\Theta_D}} d\mu(U')  U'^{\otimes t} \rho_0^{\otimes t} U'^{\dagger \otimes t} \right)^\dagger     \nonumber\\
    & \;\;\;\;\;\;\;\;\left(\int_{V\in \,\Ubb(2^n)} d\mu_H(V) V^{\otimes t} \rho_0^{\otimes t} V^{\dagger \otimes t} 
    - \int_{U \in \Ubb_{\Theta_D}} d\mu(U)  U^{\otimes t} \rho_0^{\otimes t} U^{\dagger \otimes t} \right)\Bigg] \\ 
    =&\int_{V,V'\in \,\Ubb(2^n)} d\mu_H(V) d\mu_H(V') \Tr[(V' \rho_0  V'^{\dagger} V \rho_0 V^{\dagger})^ {\otimes t}]
    + \int_{U,U' \in \Ubb_{\Theta_D}} d\mu(U) d\mu(U') \Tr[(U'\rho_0  U'^{\dagger} U \rho_0 U^{\dagger})^{ \otimes t}] \nonumber
    \\&\;- \int_{V'\in \,\Ubb(2^n)} \int_{U \in \Ubb_{\Theta_D}} d\mu_H(V') d\mu(U) \Tr[(V' \rho_0 V'^{\dagger} U \rho_0 U^{\dagger})^{\otimes t}] \nonumber
    \\&\;-  \int_{U' \in \Ubb_{\Theta_D}} \int_{V\in \,\Ubb(2^n)} d\mu(U') d\mu_H(V) \Tr[ (U' \rho_0  U'^{\dagger } V \rho_0 V^{\dagger}]^{\otimes t})]  \\
    %=&\int_{U,U' \in \Ubb_{\Theta_D}} d\mu(U) d\mu(U') (\bra{0}U'^\dagger U\ket{0} \bra{0}U^\dagger U'\ket{0})^{t}-\int_{V,V'\in \,\Ubb(2^n)} d\mu_H(V) d\mu_H(V') (\bra{0}V'^\dagger V\ket{0} \bra{0}V^\dagger V'\ket{0})^{t}\;\;,\\
    =&\int_{U,U' \in \Ubb_{\Theta_D}} d\mu(U) d\mu(U') |\bra{0} U'^\dagger U \ket{0}|^{2t} - \int_{V,V'\in \,\Ubb(2^n)} d\mu_H(V) d\mu_H(V')|\bra{0} V'^\dagger V \ket{0}|^{2t}\;\;,\\
    =& \FC^{(t)}_{\mathbb{U}_{\Theta_{D}}} - \FC^{(t)}_{\rm Haar}\;\;, \label{eq:proof-frame-norm}
\end{align}
where in the second equality we expand the product and repeatedly use $(A\otimes B)(C\otimes D) = AC \otimes BD$ (for matrices $A,B,C,D$). To reach the third equality we repeatedly use the invariant of the Haar measure, i.e., $\int_{V\in \,\Ubb(2^n)}d\mu_H(V)f(V) = \int_{V\in \,\Ubb(2^n)}d\mu_H(V) f(UV) =  \int_{V\in \,\Ubb(2^n)}d\mu_H(V) f(VU)$
for any arbitrary unitary $U$ and $\rho_0 = |0\rangle\langle0|$. In particular, we have
\begin{align}
\int_{V\in \,\Ubb(2^n)}d\mu_H(V)\Tr[VU\rho_0 U^\dagger V^\dagger] &=\int_{V\in \,\Ubb(2^n)}d\mu_H(V)\Tr[(VU)\rho_0 (V U)^\dagger] \;\;,\\
&= \int_{V\in \,\Ubb(2^n)}d\mu_H(V)\Tr[V\rho_0 V^\dagger]\;\;,
\end{align}
while in the forth inequality, we use $\rho_0 =|\vec{0}\rangle\langle \vec{0}|$. 

Thus, by plugging Eq.~\eqref{eq:proof-frame-norm} for $t=1,2$ to Eq.~\eqref{eq:proof-01}, we have 
\begin{equation}
\Var_{\thv\sim \PC}[\LC(\thv)]\leq \Var_{\rm Haar}[\LC(\thv)]  + \left( \sqrt{\FC^{(2)}_{\mathbb{U}_{\Theta_{D}}} - \FC^{(2)}_{\rm Haar}}-\FC^{(1)}_{\mathbb{U}_{\Theta_{D}}} + \FC^{(1)}_{\rm Haar}\right) \| O\|^2_2 + \frac{\Tr[O]}{2^{n-1}} \sqrt{\FC^{(1)}_{\mathbb{U}_{\Theta_{D}}} - \FC^{(1)}_{\rm Haar}} \| O\|_2 \;,
\end{equation}
which is the promised bound in Eq.~\eqref{eq:variance-expressivity-bound} and completes the proof.


\section{Disordered Ising Hamiltonian with long-range interactions}\label{appx:MoreRealisticModel}
We investigate a more realistic model inspired by experimental trapped-ion systems, as described in Ref.~\cite{smith2016many}. Specifically, we explore the system evolving under the dynamics in Eq.~\eqref{eq:quench_dynamics}, governed by a disordered Ising model with a long-range interaction Hamiltonian, and interchange the two Pauli operators, $X \leftrightarrow{Z}$, in the original Hamiltonian:
\begin{equation}
    \label{eq:expising}
        H(\thv_m) = J\sum_{i>j}\frac{Z_iZ_j}{|i-j|^\alpha}+B\sum_iX_i+ \sum_i h_i^{(m)}X_i,
\end{equation} 
where $J$ is the characteristic interaction strength, $\alpha$ controls the strength of the long-range interaction, $B$ represents a uniform effective transverse field, and $\thv_m = \{h_i^{(m)}\}^n_{i=1}$ are the on-site disordered energies at the $m$-th quench. This system can exhibit both thermalized and MBL phases. Using the same procedure as in section~\ref{subsec:phase}, we identify the thermalized phase for $W=0.6J$ and the MBL phase for $W=15J$, given $\alpha = 1$, $B=0$, and $h_i^{(m)}$ uniformly sampled from the interval $[-W/2,W/2]$. These phases are evident from the level statistics shown in Fig.~\ref{fig:exp_level_stat}. 
We investigate barren plateaus (BPs) as in the main text. However, to align with experimental setups, we initialise the quantum state in the Néel ordered state along the $x$-direction, represented as $|+-+-\cdots\rangle$ in the computational basis, where $|+\rangle = \frac{|0\rangle+|1\rangle}{\sqrt{2}}$ and $|-\rangle=\frac{|0\rangle-|1\rangle}{\sqrt{2}}$. As a result, we observe that the variance of $\langle Z_1 Z_2 \rangle$ decays as functions of the number of quenches, as shown in Fig.~\ref{fig:BP_compare_experiment}. While the variance in the thermalized initialisation decays relatively faster than in the MBL initialisation, the difference between the onset of BPs in the two initialisations is much smaller compared to the model in the main text. This suggests that although there is an advantage in the MBL initialisation over the thermalized one in this model, the smaller range of the advantageous regime in this more realistic model raises questions about the influence of the long-range interaction and the choice of the initial state.


