\subsection{System Description}
\textbf{Sub-process:} The system contains \(N\) independent sub-processes \(S_i\), each associated with an LC, and each modeled as an MDP $(\mcS_i, \mcA_i, P_{i,a_i}, r_i)$, where $\mcS_i$ is its state space with cardinality $n_i$ and ordering $<_{\mcS_i}$) and the set $\mcA_i$ is the action space with cardinality $ m_i$ and ordering $<_{\mcA_i}$). The local controller determines the local action $a_i \in \mcA_i$ for a given state $s_i$. Given a state-action pair $(s_i,a_i) \in \mcS_i \times \mcA_i$, $p_{s_i,s'_i}^{lc}(i,a_i)$ is the transition probability from state $s_i$ to $s'_i$ under action $a_i$ defined as 

\[
\small{ p_{s_i,s_i'}^{lc}(i,a_i) = \Pr(s_i(t_0+1) = s_i'| s_i(t_0) = s_i, a_i(t_0) =a_i))}.
\]
These probabilities form the entries of the transition matrix $P_{i,a_i} \in \mathbb{R}^{n_i \times n_i}$. $r_i:\mcS_i \times \mcA_i \to \Rr_+$ is the local reward for a state action pair $(s_i,a_i)$. 

\textbf{Global Controller:} The GC is modeled as an MDP $(\mcS^N,\mcA_G,\bP,R)$ where \(\mcS^N: \mcS_1\times \cdots \times \mcS_N\) is the cartesian product of all the local state spaces, the state is denoted by $\gs = [s_1,\dots,s_N]$. $\mcA_G$ is the allocation set\footnote{To differentiate the control actions of local and global controllers, we use the term action for local controller and allocation for global controller} containing all possible allocations $a_g =[a_{g,1},\dots,a_{g,N}]$ to the local sub-processes. The global allocation for the $i^{th}$ sub-process is $a_{g,i} \in \{0,1,\dots,K-1\}$. $\bP$ denotes the state transition probability rule and $R$ is GC's reward function. 

   \textbf{Global Policy:} At each epoch $t_1$, the global controller decides an allocation $a_g(t_1)$ according to policy $\Phi \ni \phi: \mcS^N \to \mcA_G$ such that $a_g(t_1) = \phi(\gs(t_1)).$

  \textbf{Local Policy:} In the $t_1^{th}$ decision epoch of the global controller, the $i^{th}$ local controller decides a sequence of $T$ control actions denoted as  
    $\mathbf{a}_i(t_1) = \{a_i(Tt_1), \dots, a_i(T(t_1+1)-1)\} $, where each $a_i(Tt_1+t) \in \mcA_i$. This is according to decision rule $\Pi_i \ni \pi_{i,t}: \mcS_i \to \mcA_i$ such that 
    \[
     a_i(t_0) = a_i(Tt_1+t) = \pi_{i,t}(s_i(Tt_1+t)) \quad t = 0,\dots,T-1.
     \]
     We define the local policy as the sequence ${\boldpi}_i := \{\pi_{i,0},\dots,\pi_{i,T-1}\}$

     and denote $\boldpi := [\bpi_1,\dots,\bpi_N]^T$, the vector of $T$-horizon local policies of all the subsystems, and we denote the space of all possible $\bpi$ as $\boldPi$.

\textbf{Global Allocation Constraint:} The global controller is constrained by a allocation budget \(B\), such that $\sum a_g(t_1) \le B$, $\forall\  t_1$ and $B < N(K-1)$. 

\textbf{Local Constraints:} The actions of the $i^{th}$ local controller over the $t_1^{\text{th}}$ epoch are constrained by the budget $a_{g,i}(t_1)$ such that $\sum_{t_0=t_1 T}^{(t_1+1)T-1}  a_i(t_0) \leq a_{g,i}(t_1)$. 

     The transition from a state $\gs(t_1) := \gs$ to $\gs(t_1+1) := \gs'$ under an allocation $a_g$ and local policy $\bpi$ is governed by the transition probability over an epoch, defined as 
\begin{align}
\label{eq:TP_EqMDP}
p^{ep}_{\gs,\gs'}(a_g,\bpi) = Pr(\gs(t_1+1) = \gs' | \gs(t_1) = \gs, a_g, \bpi).
\end{align}

    In the above system definitions, we search for local policies $\pi_i$ that are non-stationary in the faster time scale $t_0$ (i.e., $\pi_{i,t} \neq \pi_{i,t^'}, t \neq t^'$) and stationary with respect to the slower time scale \(t_1\). Further, the global allocation policy $\phi$ is assumed to be stationary with respect to $t_1.$ The normed linear space of bounded real-valued functions over the state space $\mcS$ is denoted by $\mcV$.

\subsection{Problem Formulation}
Given an initial state $\gs \in \mcS^N$, the value of that state under a global allocation policy $\phi$ and local policies $\bpi$ is defined as the expected cumulative reward expressed by the following function
\small{\begin{align}
\label{eq:V_Def}
V^{\phi,\bpi}(\gs) = \begin{aligned} \Expect_{\phi,\bpi} \left[ \sum_{t_1=0}^{\infty} \beta^{t_1} R\bigg(\gs(t_1), \phi(\gs(t_1)), \bpi(\gs(t_1)) \bigg)
 \right],
\end{aligned}
\end{align}}
\normalsize{}where $R$ is the global reward function for one epoch. This is defined to be the value function of the state $\gs$. The reward function $R$ takes the following form
\small{\begin{align}
\label{eq:R_Def}
R(& \mathbf{s}(t_1),\phi(\gs(t_1)), \bpi(\gs(t_1))) = I_g(\mathbf{s}(t_1), \phi(\gs(t_1))) \nonumber\\ &+  \sum_{i=1}^{N}
     \Expect_{s_i,\pi_i} \left[ \sum_{t=0}^{T-1}\gamma^{t} r_i(s_i(t_1T+t),a_i(t_1T+t)) \right], 
\end{align}}
\normalsize{}
where 
$
a_g(t_1) = \phi(\gs(t_1)) \ ,\ a_i(t_1T+t) = \pi_{i,t}(s_i(t_1T+t)). 
$

Here, $I_g$ is the immediate global reward for a $(\gs,a_g)$ pair, and $r_i$ is the local reward function of the $i^{\text{th}}$ sub-process at each time slot. $\beta$ and $\gamma$ are the discount factors corresponding to the global and local controllers and are in the interval $(0,1)$. 
Further, it is reasonable to assume that when there is no allocation to a sub-process during an epoch, its expected reward for that is epoch is $0$, thereby imposing the following assumptions on the reward functions 
$
R(\cdot,\mathbf{0},\cdot) = 0   \mbox{ and } r_i(\cdot,0) = 0.
$

\section{Optimization frameworks}
\label{sec:Optframeworks}
Given the cumulative discounted reward $V^{\phi,\bpi}(\gs)$ as in \eqref{eq:V_Def}, we propose two optimization frameworks for computing the policies $\phi$ and $\bpi$. These frameworks fundamentally differ in the way the optimization problems for the local policies $\bpi$ are formulated. The Federal Optimization framework (abbreviated as FOpt) uses the local policy that maximizes the cumulative local reward of each sub-process over a single epoch, while the Central Optimization framework (abbreviated as COpt) computes the local policies that optimizes the infinite-horizon discounted reward. The FOpt framework, by its formulation, provides more autonomy to the local controllers in the control hierarchy, as the optimization for local policies involves maximizing the rewards corresponding to that specific sub-process alone. We formally define the two frameworks and provide an illustrative example explaining how these frameworks can result in different policies for the same system. 

\subsection{Federal Optimization Problem (FOpt)} 
Given the expected cumulative reward as in \eqref{eq:V_Def}, we define the \textit{federal} optimization problem (FOpt) for computing the policies $\phi$ and $\bpi$ as follows:
In this framework, the objective of the global controller is to compute policy $\phi$ such that 

\begin{align}
\label{eq:ValFunD}
\small{\begin{aligned}
V_F^*(\gs) &= \max_{\phi \in \Phi} \Expect_{\gs,\phi} \left[ \sum_{t_1=0}^{\infty} \beta^{t_1} R\bigg(\gs(t_1), \phi(t_1), \bpi_\phi(\gs(t_1))\bigg)\right] \\
s.t.\ \  &\ \ \mathbf{1}^T \phi(\gs(t_1)) \leq B, \forall\ t_1,
\end{aligned}}
\end{align}
where $\bpi_\phi = [\pi^\phi_{1},\dots,\pi^{\phi}_{N}]$ are the local optimal policies for a given global allocation policy $\phi$ defined through the following local optimization problem
\small{\begin{align}
\label{eq:LocOptPolicy}
\pi_{i}^\phi &= \argmax_{\pi_i \in \Pi_i} \Expect_{s_i,\pi_i} \left[ \sum_{t=0}^{T-1}\gamma^{t} r_i(s_i(t_1T+t),{\pi_{i,t}}(s_i(t_1T+t))) \right] \nonumber \\
& \mbox{s.t.} \sum_{t=0}^{T-1} \pi_{i,t}(s_i(t_1T+t)) \leq e_i^T \phi(\gs(t_1)), 
\end{align}}
\normalsize{}
where $e_i$ is the $i^{th}$ unit vector. 

The optimal global allocation policy $\phi^*_F$ is defined as 
\begin{align}
\label{eq:FedGlobal}
\phi_F^* = \argmax_{\phi \in \Phi} V_F^*,
\end{align}
where $V_F^*$ is defined as in equation \eqref{eq:ValFunD} and the local optimal policy $\bpi_F^*$ is given by $\pi_{F,i}^* = \pi_{\phi_F^*,i}$, where $\pi_{\phi_F^*,i}$ is defined as in equation \eqref{eq:LocOptPolicy} for the optimal global allocation $\phi^*_F$. 

\subsection{Central Optimization Problem (COpt)}
A natural alternative for the federal framework considers a single controller that determines both the global allocation and local policies together as a single optimization problem. We term it as the \textit{central} optimization problem (COpt) where the overall objective is to compute $\phi,\bpi$ such that

{\small{\begin{align}
\label{eq:ValFunCent}
V_C^{*}(\gs) &:= \max_{\phi \in \Phi}\max_{\bpi \in \Pi} V^{\phi,\bpi}(\gs) \nonumber \\ &=  
\max_{\phi \in \Phi}\max_{\bpi \in \Pi} \Expect_{\gs,\phi,\bpi} \left[ \sum_{t_1=0}^{\infty} \beta^{t_1} R\bigg(\gs(t_1), \phi(\gs(t_1)), \bpi(\gs(t_1))\bigg)\right] \nonumber \\ 
    & \mbox{s.t.} \begin{cases}  \mathbf{1}^T \phi(\gs(t_1)) \leq M , & 
     \forall\ t_1,  \\
      \sum\limits_{t=t_1 T}^{(t_1+1)T-1} \pi_i(s_i(t)) \  \leq \ e_i^T \phi(\gs(t_1))  , & \forall \ i,\ \forall \ t_1. 
     \end{cases}
\end{align}} }


\normalsize{}The central optimal allocation policy $\phi_C^*$ and local policies $\bpi_C^*$ are defined as 
\begin{align}
\{\phi_C^*,\bpi_C^*\} = \argmax V_C^*(\gs),
\end{align}
where $V_C^*(\gs)$ is defined as in equation \eqref{eq:ValFunCent}.
The two problem formulations fundamentally differ in the way the optimal policy is computed. In the COpt, the optimal policy $\phi_C^*, \bpi_C^*$ are computed centrally together by a single controller while the FOpt allows the local controller to compute its own policy $\pi_{F,i}^*$ leading to a distributed computation of the policies $\phi_F^*$ and $\bpi_F^*$, thereby providing autonomy to the local controllers. 

\subsection{Non-equivalence of Central and Federal frameworks}
Here is an example illustrating the non-equivalence and possible equivalence of these frameworks under certain conditions. Let $T=1, N=1$, $B=1$, and $n_1=2$. The system operates at a single timescale, and there is only one process with two possible states. Consider the state space to be $\mcS = \{0,1\},$ the action space to be $\mcA=\{0,1\}$, and $I_g=0$. The local reward function is given by
$r_1(s,a) = \begin{bmatrix} 0.25 & 0.5 \\ 0.75 & 1 \end{bmatrix}$ for $s\in\mcS$ and $a\in\mcA$. We assume an equality constraint on allocation budget: $\sum a_g(t_1) = B$. We provide two systems that differ only in the state transition probabilities for both equivalence and non-equivalence of the two frameworks. 

\subsubsection{Example 1: Non-equivalent case}
 Let the transition probability matrices be chosen as $P_{a=0} = \begin{bmatrix} 0.2 & 0.8 \\ 0.2 & 0.8 \end{bmatrix}$, $P_{a=1} = \begin{bmatrix} 0.8 & 0.2 \\ 0.4 & 0.6 \end{bmatrix}$.  
Here, the optimal local policy computed through COpt is $\pi_C^*(s=0) = 0,$ $\pi_C^*(s=1)=1$ and the optimal policy computed through FOpt is $\pi^*_F(s=0)=1,$ $\pi^*_F(s=1)=1$. The corresponding value functions under these policies are $[74.5, 75.1]^T$ and $[66.3,67.2]^T$, for COpt and FOpt, respectively. %\Ram{can we give the value functions too?}.

\subsubsection{Example 2: Equivalent case}
When the transition probability matrices are  $P_{a=0} = \begin{bmatrix} 0.5 & 0.5 \\ 0.5 & 0.5 \end{bmatrix}$, $P_{a=1} = \begin{bmatrix} 0.2 & 0.8 \\ 0.2 & 0.8 \end{bmatrix}$,
it is found that both FOpt and COpt frameworks lead to the same policies with $\pi^*(s=0)=1$ and $\pi^*(s=1)=1$. 


\section{Analysis and Results}
\label{sec: analysis}

In this section, we prove the existence and uniqueness of the optimal value functions for both the COpt and FOpt formulations, define value iteration algorithms, and provide comparative results between the two frameworks, and bound the difference between the two value functions. Finally, we provide sufficient conditions on the system such that both frameworks yield the same value function. 

\begin{theorem}
\label{th:COpt}
For all $\gs\in \mcS^N$, there exists an unique $V_C^* \in \mcV$ satisfying
\begin{align}
\label{eq:COpt_Bellman}
\begin{aligned}
V_C^*(\gs) &= \max_{a_g \in \mcA_g^B} \max_{\bpi \in \mathbf{\Pi}_{a_g}} \bigg\lbrace  R(\gs,a_g,\bpi(\gs))   \\ &   +\beta \sum_{\gs' \in  \mcS^N} p^{ep}_{\gs,\gs{'}} (a_g,\bpi) V_C^*(\gs')   \bigg\rbrace.
\end{aligned}
\end{align}
\end{theorem}
\begin{proof}
Equation \eqref{eq:COpt_Bellman} can be viewed as a nested optimization problem on global allocation $a_g$ and local policy $\bpi$. For a pair of $a_g, \bpi$, the reward function $R(\gs,a_g,\bpi(\gs))$ is bounded, and $\beta < 1$. The Bellman operator $\Bel_C: \mcV \to \mcV$ for the COpt formulation is given by
\begin{align}
\begin{aligned}
\Bel_C V_C(\gs) = \max_{a_g \in \mcA_g^B}& \left\lbrace \max_{\bpi \in \mathbf{\Pi}_{a_g}} \Bigg[ R(\gs,a_g,\bpi(\gs))
\right. \\  & \left. +\beta \sum_{\gs' \in  \mcS^N} p^{ep}_{\gs,\gs{'}} (a_g,\bpi) V_C(\gs')  \Bigg] \right\rbrace.
\end{aligned}
\label{eq:BEL_COpt}
\end{align}

Since the state space $\mcS$ is finite and $\beta < 1$, \cite[Proposition 6.2.4 and Theorem 6.2.5]{puterman2014markov} guarantee that $\Bel_C$ is a contraction mapping on $\mcV$ and hence a fixed point $V_C^*$ exists.
\end{proof}
\begin{theorem}
\label{th:FOpt}
For all $\gs\in \mcS^N$, there exists an unique $V_F^* \in \mcV$ satisfying
\begin{align}
\begin{aligned}
V_F^*(\gs) &= \max_{a_g \in \mcA_g}\bigg \lbrace R(\gs,a_g,\bpi^{a_g}_{F}) \\ &  +\beta \sum_{\gs' \in  \mcS^N} p^{ep}_{\gs,\gs{'}} (a_g,\bpi_{F}^{a_g}) V_F^*(\gs')   \bigg\rbrace.
%
\end{aligned}
\label{eq:Fopt_Bellman}
\end{align}
\normalsize{}
where $\bpi^{a_g}_F$ is the FOpt policy corresponding to the allocation $a_g$.
\end{theorem}
\begin{proof}
For every allocation $a_g$ of the GC, the local optimization \eqref{eq:LocOptPolicy} is a finite horizon MDP with finite state and action spaces,  \cite[Proposition 4.4.3]{puterman2014markov} guarantees the existence of a deterministic local optimal policy $\bpi^{a_g}_F$ and it can be computed using any policy evaluation algorithm. Given the optimal local policies $\bpi_F^{a_g}$, the reward function $R(\gs,a_g,\bpi^{a_g}_F)$ is unique and bounded for every $(\gs,a_g)$ pair. The Bellman operator $\Bel_F$ for the FOpt problem can be defined as 
\small{\begin{align}
\label{eq:Bel_FOpt}
\begin{aligned}
\Bel_F V_F(\gs) = \max_{a_g \in \mcA_g^B}  &\Bigg[ R(\gs,a_g,\bpi_F^{a_g}(\gs)) \\ 
&+\beta \sum_{\gs' \in  \mcS^N} p^{ep}_{\gs,\gs{'}} (a_g,\bpi_F^{a_g}) V_F(\gs')  \Bigg]. 
\end{aligned}
\end{align}}
\normalsize{}
Additionally, given $\beta < 1$, and the state space $\mcS$ is finite, from  \cite[Proposition 6.2.4, Theorem 6.2.5]{puterman2014markov}, we claim that $\Bel_F$ is a contraction mapping on $\mcV$ and guarantee the uniqueness of $V_F^*$.
\end{proof}
\begin{remark}
Rewriting $\Bel_F$ as
\small{\begin{align*}
\Bel_F V_F(\gs) = \max_{a_g \in \mcA_g^B}& \left\lbrace \max_{\bpi \in \mathbf{\Pi}_{a_g}} \Bigg[ R(\gs,a_g,\bpi(\gs))
\Bigg] \right. \\  & \left. +\beta \sum_{\gs' \in  \mcS^N} p^{ep}_{\gs,\gs{'}} (a_g,\bpi) V_F(\gs')  \right\rbrace,
\end{align*}}
\normalsize{}
we immediately see the difference between the COpt \eqref{eq:BEL_COpt} and FOpt formulations, where the former is optimizing both the local and global policies over infinite horizon, while the later optimizes only the global policy over infinite horizon.
\end{remark}
\begin{remark}
From Theorems \ref{th:COpt} and \ref{th:FOpt}, a value iteration algorithm for computing the optimal value functions can be formulated as 
\begin{align}
\label{eq:ValIter}
\begin{aligned}
V_C^{(m+1)}(\gs) &= \Bel_C V_C^{(m)}(\gs), \\ 
V_F^{(m+1)}(\gs) &= \Bel_F V_F^{(m)}(\gs).
\end{aligned}
\end{align}
Starting from initial values $V_C^{(0)}$ and $V_F^{(0)}$, from Theorem 6.3.1 \cite{puterman2014markov}, we have $V_C^{(m)}  \to V_C^*$ and $V_F^{(m)} \to V_F^*$. 
\end{remark}

%
In the following results, we bound the difference between the the two values functions $||V_C^*(\gs)-V_F^*(\gs)||$, which can be viewed as the \emph{cost of autonomy}, the cost incurred for using a federal structure rather than a centralized decision framework. The following lemma gives the relationship between the two value functions.
\begin{lemma}
\label{lem:Dec-Cent1}
Given an optimal policy $\{\phi_C^*, \bpi_C^*\}$ of COpt and an optimal policy $\{\phi_F^*, \bpi_F^*\}$ of FOpt, we have
\[
V^*_F(\gs) \leq V^*_C(\gs).
\]
\end{lemma}

\begin{proof}
 From the definition of FOpt \eqref{eq:ValFunD}, we have
\small{\begin{align*}
V^*_F(\gs) &= \max_{\phi \in \Phi} \Expect_{\gs,\phi} \left[ \sum_{t_1=0}^{\infty} \beta^{t_1} R(\gs(t_1), \phi(\gs(t_1)), \bpi_\phi(\gs(t_1)))\right] 
\end{align*}
\begin{align*}
&\leq \max_{\phi \in \Phi} \max_{\bpi \in \Pi} \Expect_{\gs,\phi} \left[ \sum_{t_1=0}^{\infty} \beta^{t_1} R(\gs(t_1), \phi(\gs(t_1)), \bpi(\gs(t_1)))\right] \\ 
& = V_C^*(\gs).
\end{align*}}
\normalsize{}
The inequality is due to the fact that the COpt framework searches over a larger space $\phi,\bpi \in \Phi \times \Pi$ while the FOpt framework searches over $\phi, \bpi_\phi$, where $\bpi_\phi$ is fixed for a given $\phi$ according to equation \eqref{eq:LocOptPolicy}, thereby making the search space for policies constrained than the COpt framework.
\end{proof}
\begin{definition}[$T$-myopic policy]
A local policy $\pi_i^{myo}$ under an allocation $\phi$ is said to be $T$-myopic if it chooses actions $\mathbf{a}_i$ that maximizes the immediate expected local reward of that epoch, that is
\[
\pi_i^{myo} = \argmax_{\pi_i \in \Pi_i} \Expect_{s_i,\pi_i}\left[\sum_{t=0}^{T-1} \gamma^t r_i(s_i(t),\pi_i(s_i(t)))\right].
\]
\end{definition}

\begin{remark}
It follows from the above definition that the local policies $\pi^*_{F,i}$ computed by the FOpt framework are always $T$-myopic. 
\end{remark}

\begin{theorem}
Given the value functions $V^*_F(\gs)$ and $V^*_C(\gs)$ and the corresponding optimal policies $\{\phi_F^*,\bpi_F^*\}$ and $\{\phi_C^*,\bpi_C^*\}$ of the FOpt and COpt problems, we have
\begin{align}
\label{eq:TempT31}
V^{\phi_C^*,\bpi_{\phi_C^*}}(\gs) \leq V_F^*(\gs) \leq V_C^*(\gs).
\end{align}
where $\bpi_{\phi_C^*}$ is the solution of the local optimization problem (\ref{eq:LocOptPolicy}) under the optimal global allocation policy $\phi_C^*$ of the COpt problem. %(i.e., the federal optimization). 
Additionally,
\begin{align}
||V_C^*(\gs) - V_F^*(\gs) || \leq || V_C^*(\gs)-V^{\phi_C^*,\bpi_{\phi_C^*}}(\gs)||.
\end{align}

\end{theorem}
\begin{proof}
From Lemma \ref{lem:Dec-Cent1} we know that $V_F^*(\gs) \leq V_C^*(\gs)$. To get the other side of the required relation, given the optimal global allocation policy $\phi_C^*$ of COpt, we know that $V^{\phi_C^*,\bpi}(\gs) \leq V_C^*(\gs)$ for all $\bpi \neq \bpi_C^*$.
In particular, we choose the local policy to be $\bpi_{\phi_C^*}$, the solution of the local optimization problem \eqref{eq:LocOptPolicy} given the global allocation policy $\phi_C^*$. If $V_F^*(\gs) < V^{\phi_C^*,\bpi_{\phi_C^*}}(\gs)$, then it leads to a contradiction as $V_F^*(\gs)$ is the maximum achievable value function of FOpt than any other policies that are computed through the local optimization problem \eqref{eq:LocOptPolicy}, such as the policy $\{\phi_C^*, \bpi_{\phi_C^*}\}$. So, $V^{\phi_C^*,\bpi_{\phi_C^*}}(\gs)$ should have a value function which is upper bounded by $V_F^*(\gs)$. Hence, we have 
\begin{align}
\label{eq:temp2_T1}
V^{\phi_C^*,\bpi_{\phi_C^*}}(\gs) \leq V_F^*(\gs).
\end{align}
This above equation and Lemma \ref{lem:Dec-Cent1} proves the claim in equation \eqref{eq:TempT31}. Taking the norm of the differences between the terms, we have the second statement.
\end{proof}
In the above result, we bound how far FOpt can be from COpt by computing the $T$-myopic local policy for $\phi_C^*$. A major consequence of the above theorem is that it gives conditions under which FOpt and COpt are equivalent. 
\begin{corollary}
FOpt and COpt have the same value function iff the local policies $\pi_C^*$ of the COpt are $T$-myopic. 
\end{corollary}
We proceed to establish conditions under which the local policies $\pi_C^*$ determined by the COpt framework are $T$-myopic. We do this under the following structural assumptions on the system. 

\begin{itemize}
\item[(A1)]  $p^{ep}_{\gs} (a_g,\bpi_{a_g}^*)$ is stochastic monotone in $\gs,$ i.e., $p^{ep}_{\gs} (a_g,\bpi_{a_g}^*) \geq_s p^{ep}_{\gs^{'}} (a_g,\bpi_{a_g}^*)
$ for all $\gs \geq \gs^{'}.$
\item[(A2)] For $\bpi_{a_g}^* \neq \bpi_{a_g}$, $p^{ep}_{\gs} (a_g,\bpi_{a_g}^*)  \geq_s p^{ep}_{\gs} (a_g,\bpi_{a_g}) 
$.
\item[(A3)] For any $a_i,$ $P_{s_i}^{lc}(i,a_i)\coloneqq [p_{s_i,s_i'}^{lc}(i,a_i)]_{s_i'\in\mcS_i} $ is stochastic monotone in $s_i$. 
%
\item[(A4)] The local reward function $r_i$ is non-decreasing in both $s_i$ and $a_i.$
\item[(A5)] The immediate reward function $I_g$ is non-decreasing in $\gs$.
\end{itemize}
We refer to \cite[Section 4.7.3]{puterman2014markov} for the definition of stochastic monotonicity. 
\begin{lemma}
\label{lemma:R_monotone}
Under assumptions (A1) to (A5), the global reward function $R$ is non-decreasing in $\mcS^N$ when local optimal policy $\pi^*_{a_g}$ is employed for each allocation $a_g$.
\end{lemma}
\begin{proof}

\normalsize{}
Consider the following optimal local value function, 
\[
%V_{i,T}^{lc,*}(s_i) = 
\max_{\pi_i} \Expect_{s_i,\pi_i} \left[ \sum_{k=0}^{T-1}\gamma^{k} r_i(s_i(k),a_i(k)) \right], 
\]
subject to $\sum_{k=0}^{T-1}a_i(k) \leq a_{g,i}$ for all $i=1,2,\cdots, N.$ We will show that it is non-decreasing in $s_i.$ Monotonicity results of unconstrained finite horizon MDPs cannot be applied directly. 
%
%
However, we can cast the constrained local MDP into an equivalent unconstrained $T$-horizon MDP which has an augmented state $(s_i(t),b_i(t))$ at time $t\in \{0,1,\ldots,T-1\}$. Here, $b_i(t)$ is the budget available at time $t$. This optimal value function of this MDP satisfies the following equations (some subscripts are dropped for convenience). 
{\small{
\begin{align}
    v_{i,t}^*(s,b) &= \max_{a\in \mcA_{i}(b)} q_{i,t}^*(s,b,a),  \\
    q_{i,t}^*(s,b,a) &\coloneqq \left\lbrace r_i(s,a) + \gamma\mathbf{E}\left[ v_{i,t+1}^*(s_i(t+1),b-a)|s, b, a)\right]\right\rbrace.\nonumber
\end{align} }}
\normalsize{}
Here, $\mcA_{i}(b) = \{a\in\mcA_i|a\leq b\}$, the set of actions within the available budget. 
% We have $v^*_{i,T-1}(s,b)=r_i(s,b,a).$
For a given action $a$, assuming $v_{i,t+1}^*$ is non-decreasing in $s$, the quantity $\mathbf{E}\left[ v_{i,t+1}^*(s_i(t+1),b-a)|s, b, a)\right]$ is non-decreasing in $s$ due to the stochastic monotone property of transition probability vector $P_{s}^{lc}(i,a_i)$ in $s$. For each $t$, $q_{i,t}^*(s,b,a)$ is non-decreasing in $s$ because it is a sum of two non-decreasing quantities. 
Applying the principle of induction, it can be shown that $v_{i,t}^*$ is non-decreasing in $\mcS_i$ for a given budget for every $t=0,\ldots,T-1$. 

Now, the sum of value functions across all LCs is non-decreasing in $\mcS^N$. % and $\bar{\mcA}^{N}$.  
Additionally, the global reward function $I_g$ is non-decreasing in $\mcS^N$, which proves that $R$ is non-decreasing in $\mcS^N$. %and $\bar{\mcA}^{N}$. 
\end{proof}
%
%
\begin{lemma}
Under assumptions (A1) to (A5), $V_C^*$ is non-decreasing in $\gs$.
\label{lemma:V_C^* monotone}
\end{lemma}
\begin{proof}
 From Remark 2 we know that, $V_C^*$ can be computed through a Bellman update of $V_C^{(m)}$ at each step $m=1,2,...$ until convergence, starting from $V_C^{(1)}=R$. $R$ is non-decreasing in $\gs$ from Lemma~\ref{lemma:R_monotone}. The Bellman operation is monotone \cite{puterman2014markov} and we have $V_C^{(m+1)}=\mathcal{B}_C V_C^{(m)}\geq V_C^{(m)}$. By induction we will prove that $V_C^*$ is monotonic is $\gs$. Assume that $V_C^{(m)}$ is monotonic in $\gs$, $V_C^{(m+1)} = \mathcal{B}V_C^{(m)}$ is computed as 
%
{\small{
\begin{align*}
&V_C^{(m+1)}(\gs)  \\
&= \max_{a_g}\max_{\bpi} \left\lbrace R(\gs, a_g, \bpi(\gs)) + \beta \mathbf{E}\left[ V_C^{(m)}(\gs')|\gs, a_g, \bpi(\gs)\right] \right\rbrace , \\
&= \max_{a_g} \left\lbrace R(\gs, a_g, \bpi^*(\gs)) + \beta \mathbf{E}\left[ V_C^{(m)}(\gs')|\gs, a_g, \bpi^*(\gs)\right] \right\rbrace .
\end{align*}
}}
Since, we assumed that $V_C^{(m)}$ is non-decreasing in $\gs$, we have
{\small{
\begin{align*}
\mathbf{E}\left[ V_C^{(m)}(\gs') \vert \gs'', a_g, \bpi(\gs)\right] \geq \mathbf{E}\left[ V_C^{(m)}(\gs') \vert \gs''', a_g, \bpi(\gs)\right] .
\end{align*}
}}
for $\gs''>_{\mcS} \gs'''$. This is because of assumptions (A1), (A2), and the definition of stochastic monotonicity. Hence, $\mathbf{E}\left[ V_C^{(m)}(\gs')|\gs, a_g, \bpi^*(\gs)\right]$ is non-decreasing in $\gs$. This means $V_C^{(m+1)}(\gs)$ is non-decreasing in $\gs$. %We know that $V_C^{(1)} = R$ is monotone in $\gs$, hence, $V_C^{(1)}=R$ is non-decreasing in $\gs$. 
We know from value iteration that $V_C^{(m)}(\gs)$ converges to $V^*_C$ as $m\to \infty$. Thus, by induction, $V_C^*$ is non-decreasing in $\gs$.
\end{proof}
%
%
\begin{theorem}
Under assumptions (A1) to (A5), value functions $V_F^*(\gs)$ and $V_C^*(\gs)$ of FOpt and COpt are equal $\forall \mathbf{s}\in\mcS^N$. 

\end{theorem}
%
%
\begin{proof}
Rewriting \eqref{eq:COpt_Bellman}, we have
{\small{
\begin{align*}
V_C^{*}(\gs) &= \max_{a_g}\left\lbrace R(\gs, a_g, \bpi_{a_g}^*(\gs)) + \beta \mathbf{E}\left[ V_C^{*}(\gs')|\gs, a_g, \bpi_{a_g}^*(\gs)\right] \right\rbrace .
\end{align*}
}}
\normalsize{}
%Now, The policy $\barpi^*$ which maximizes $R(\gs, a_g, \barpi^*(\gs))$  
Consider a $T$-myopic policy $\bpi_{a_g}^*$ that maximizes $R(\gs, a_g, \bpi_{a_g}^*(\gs))$ for a state $\gs$ and allocation $a_g$. Under assumption (A2) and monotonicity of $V_C^*(\gs')$ in $\gs'$ (Lemma~\ref{lemma:V_C^* monotone}), this policy  also maximizes the expected future value $\mathbf{E}[V_C^{*}(\gs')|\gs, a_g, \bpi_{a_g}^*(\gs)]$, and hence their sum. Hence $\bpi_{a_g}^*$ is the solution to the COpt problem. From Remark 3, it is known that FOpt always uses a $T$-myopic policy, leading to the equivalence between the two frameworks. 
\end{proof}

\section{Conclusion}
We presented a hierarchical stochastic control architecture for cyber-physical systems, comprising of multiple independent sub-processes and local controllers, along with a global controller imposing budget constraints on individual local controllers. This is modeled as a two-timescale multi-MDP-based formulation, which hasn't been analyzed in the literature. We proposed two optimization frameworks FOpt and COpt, and analyzed the optimality of the value functions. Further, we show the equivalence between the two under specific structural assumptions on the model. These frameworks have applications in various domains, including budget allocation, healthcare infrastructure planning, energy systems, and coordinated control of autonomous vehicles. We plan to explore these applications in future work.


