\section{Transformation of spQUBO into two-dimensional}
\label{sec-higherorder}

In this section, we prove Theorems \myref{thm:padding-spcm} and \myref{thm:higherorderQUBO} in the text. %\LC(section9da_higherorder2-3)
In particular, these can be obtained as a corollary of the following theorem that collapses the configuration domain into two-dimensional preserving the convolutional structure: %\LC(section9da_higherorder2-4)

\begin{theorem}

\label{thm:higherorder}
Let $f\colon\Inte^D\to\Real$ be a function that has a locality of $\vran < \vlsh$, and $\mathcal{D}_1, \mathcal{D}_2$ be non-overlapping index sets such that $\mathcal{D}_1\cup \mathcal{D}_2=\{1,\ldots, D\}$ and $\mathcal{D}_1\cap \mathcal{D}_2=\varnothing$. %\LC(section9da_higherorder2-10)
Let $\vect{\tilde{\lsh}}\in\Nnum^2$ be the vector whose elements are defined as %\LC(section9da_higherorder2-11)
\AL{
\tilde{\lsh}_\gamma=\prod_{\idim\in \mathcal{D}_\gamma}(\lshd+\rand)\LB{eq:lpa}
}
for $\gamma=1,2$.  %\LC(section9da_higherorder2-18)
Then, there exist functions $f'\colon\Inte^2\to\Real$ and $\ravx\colon\InteN{\vlsh} \to \InteN{\vect{\tilde{\lsh}}}$ such that $f'$ is periodic with period $\vect{\tilde{\lsh}}$ and %\LC(section9da_higherorder2-19)
\AL{
f'(\ravx(\vpos_i)-\ravx(\vpos_j))=f(\vpos_i-\vpos_j) %\LC(section9da_higherorder2-23)
}
holds for all $\vpos_i,\vpos_j\in \InteN{\vlsh}$. %\LC(section9da_higherorder2-26)

\end{theorem}
\subsection{Mapping coordinate vectors to scalar values}

The required map $h'$ transforms $D$-dimensional coordinate vector to a pair of scalar values. %\LC(section9da_higherorder2-31)
However, designing this can be reduced to a problem of transformation into a single scalar. %\LC(section9da_higherorder2-33)

Let us denote by $\vx_{:K}=(x_1,\ldots,x_K)$ the vector obtained by taking the first $K$ elements of a vector $\vx$. %\LC(section9da_higherorder2-37)
We introduce the following notations for $k=1,\ldots,D$: %\LC(section9da_higherorder2-38)
\AL{
\vlpa&\equiv\vlsh+\vran\LB{eq:vec-lpa-onedim}\\
\ransp^{K}&\equiv\kdim[-\rand, \rand],\LN{eq:def-ransp}
{\lpa}\lkth&\equiv\kdim\lpad,\LN{eq:def-lpa}
\ravl\lkth(\vx_{:K})&\equiv\ksum x_\idim{\lpa}^{(\idim-1)},\\
\ran\lkth&\equiv \ravl\lkth(\vran_{:K}) = \ksum\rand {\lpa}^{(\idim-1)},
}
where ${\lpa}^{(0)}=\ran^{(0)}=1$ and Eq.~(\myref{eq:def-ransp}) means the Cartesian product. %\LC(section9da_higherorder2-49)
The following recurrence relations hold for $\ravl\lkth$ and $\ran\lkth$: %\LC(section9da_higherorder2-50)
\AL{
\ravl\lkth(\vx_{:K})&= x_K {\lpa}\mkth+\ravl\mkth(\vx_{:K-1}),\LN{eq:rec-ravl}
\ran\lkth&=\ran_K{\lpa}\mkth+\ran\mkth.\LB{eq:rec-ran}
}
We also use simple notations for $K=D$ as $\ransp\equiv \ransp^D$ and $\lpa\equiv{\lpa}^{(D)}$. %\LC(section9da_higherorder2-59)
We also wrap $\ravl\dimth$ to define $\ravm\colon \Inte^D\to \lpa$ as %\LC(section9da_higherorder2-61)
\AL{
\ravm(\vect{x})=\mymod{\ravl\dimth(\vect{x})}{\lpa},\LB{eq:onedim-transformed-coordinate}
}
where, for $x\in\Inte$ and $N\in\Nnum$, $\mymod{x}{N}$ denotes the unique $y\in\InteN{N}$ that satisfies $y=x+kN$ for some $k\in\Inte$. %\LC(section9da_higherorder2-67)
The wrapped map $\ravm$ preserves the structure of relative positions of local spin pairs well, so that it can be used to collapse the configuration domain. %\LC(section9da_higherorder2-69)
Specifically, the following properties hold, whose proofs are given in the following sections: %\LC(section9da_higherorder2-70)
\

\begin{prop}

\label{thm:construction}
Let $h$ be the map obtained by restricting the domain of $g$ to $\ransp$, and $I=g(\ransp)=\{g(\vrel)\mid \vrel\in\ransp\}$ be its image.  %\LC(section9da_higherorder2-75)
Then, the following hold: %\LC(section9da_higherorder2-76)

\begin{enumerate}[label=(\Alph*)]
\item $\mymod{\ravm(\vpos_i)-\ravm(\vpos_j)}{\lpa} = \ravm(\vpos_i-\vpos_j)$ for all $\vpos_i ,\vpos_j\in \Inte^D$ 
\item $h$ is injective.
\item $\ravm(\vrel)\not\in\imset$ holds for $\vrel \in \lshsp\setminus \ransp$ where $\lshsp=\ddim (-\lshd,\lshd)$.
\end{enumerate}

\end{prop}
We first present a simpler version of Theorem \myref{thm:higherorder} in one-dimensional case to see how the constructed map $g$ can be used. %\LC(section9da_higherorder2-94)

\begin{prop}[Theorem \ref{thm:higherorder} in one-dimensional case]
\label{thm:onedim}
For vectors $\vran < \vlsh\in\Nnum^D$, let $f\colon\Inte^D\to\Real$ be a function that has a locality of $\vran$ and let $\lpa \equiv \ddim(\lshd+\rand)$. %\LC(section9da_higherorder2-100)
Then, there exist functions $f': \Inte\to\Real$ with period $\lpa$ and $\ravx\colon \InteN{\vlsh} \to \InteN{\lpa}$ such that %\LC(section9da_higherorder2-101)
\AL{
f'(\ravx(\vpos_i)-\ravx(\vpos_j))=f(\vpos_i-\vpos_j).\LB{eq:onedim-commutativity} %\LC(section9da_higherorder2-104)
}
holds for all $\vpos_i,\vpos_j\in \InteN{\vlsh}$. %\LC(section9da_higherorder2-107)

\end{prop}

\begin{proof}

Let us define $f'\colon \Inte\to\Real$ as %\LC(section9da_higherorder2-111)
\AL{
f'(\rel)= %\LC(section9da_higherorder2-114)
\begin{cases}
f(\ravr^{-1}(\mymod{\rel}{\lpa}))& %\LC(section9da_higherorder2-116)
(\mymod{\rel}{\lpa} \in \imset)\\
0&
(\mymod{\rel}{\lpa} \not \in \imset)
\end{cases},\LB{eq:onedim-transformed-coupling}
}
where $h$ and $I$ are defined as Proposition \myref{thm:construction}.  %\LC(section9da_higherorder2-123)
This map is well-defined because $h$ is injective ((B) of Proposition \myref{thm:construction}). %\LC(section9da_higherorder2-124)

Let $\ravx$ be the map obtained by restricting $\ravm$ to $\InteN{\vlsh}$. %\LC(section9da_higherorder2-128)
Then, for any $\vpos_i,\vpos_j\in\InteN{\vlsh}$, it holds %\LC(section9da_higherorder2-129)
\AL{
\mymod{\ravx(\vpos_i)-\ravx(\vpos_j)}{\lpa}=g(\vpos_i-\vpos_j)
}
by (A) of Proposition \myref{thm:construction}. %\LC(section9da_higherorder2-135)
When $\vpos_i-\vpos_j \in \ransp$, it holds $g(\vpos_i-\vpos_j)\in I$. %\LC(section9da_higherorder2-137)
Then, by calculating from the definition of $f'$, Eq.~(\myref{eq:onedim-commutativity}) holds as %\LC(section9da_higherorder2-138)
\AL{
&f'(\ravx(\vpos_i)-\ravx(\vpos_j))\NN
&=f(\ravr^{-1}(\mymod{\ravx(\vpos_i)-\ravx(\vpos_j)}{\lpa}))\NN
&=f(\ravr^{-1}(g(\vpos_i-\vpos_j)))\NN
&=f(\vpos_i-\vpos_j).
}
When $\vpos_i-\vpos_j \in \lshsp\setminus\ransp$, it holds $g(\vpos_i-\vpos_j)\not\in\imset$ by (C) of Proposition \myref{thm:construction}. %\LC(section9da_higherorder2-148)
Then, we have $f'(\ravx(\vpos_i)-\ravx(\vpos_j))=0$ by definition. %\LC(section9da_higherorder2-149)
Then, because $f(\vpos_i-\vpos_j)=0$ holds from the locality of $f$, we obtain Eq.~(\myref{eq:onedim-commutativity}). %\LC(section9da_higherorder2-150)

\end{proof}
The proof can be extended to the proof of two-dimensional case as follows: %\LC(section9da_higherorder2-156)

\begin{proof}
[Proof of Theorem \ref{thm:higherorder}]
For $D$-dimensional vector $\vect{x}$ and $\gamma\in\{1,2\}$, let us denote by $\vect{x}\grp{\gamma}$ the vector consisting of the elements $x_\idim$ for $\idim\in \mathcal{D}_\gamma$. %\LC(section9da_higherorder2-160)
Let $\ravm_\gamma$ and $\imset_\gamma$ be $\ravm$ and $\imset$ of Proposition \myref{thm:construction} when $\vlsh$ and $\vran$ are $\vlsh_\gamma$ and $\vran_\gamma$, respectively. %\LC(section9da_higherorder2-161)

Let us combine $\ravm_\gamma$ to define $\ravm(\vpos)=(\ravm_1(\vpos\grp{1}),\ravm_2(\vpos\grp{2}))$. %\LC(section9da_higherorder2-165)
In addition, let $h$ be the map obtained by restricting the domain of $g$ to $\ransp$, and $I=g(\ransp)=\{g(\vrel)\mid \vrel\in\ransp\}$ be its image. %\LC(section9da_higherorder2-166)
For $\vrel\in\lshsp\setminus\ransp$, we obtain $\ravm_1(\vrel\grp{1})\not\in \imset_1$ or $\ravm_2(\vrel\grp{2})\not\in \imset_2$ from Proposition \myref{thm:construction} and thus $g(\vrel)\not\in\imset$ because $\imset=\imset_1\times\imset_2$. %\LC(section9da_higherorder2-168)
Therefore, $\ravm$ and $\ravr$ satisfies three conditions (A), (B), (C) in Proposition \myref{thm:construction} where $\lpa$ is replaced by $\vect{\tilde{\lsh}}$, because (A) and (B) are obvious from the constructions of $g$ and $h$. %\LC(section9da_higherorder2-170)

We can complete the proof by following the argument of Proposition \myref{thm:onedim}, using these $g$ and $h$ and substituting $\vect{\tilde{\lsh}}$ for $\lpa$. %\LC(section9da_higherorder2-174)

\end{proof}

\subsection{Proof of Proposition \ref{thm:construction}}
\label{sec-proofA}

\begin{lfigure}
\captionsetup[sub]{labelformat=empty}
\begin{center}

\includegraphics[ width=5.7in ]{Fig6.pdf}
\end{center}
\caption{
An example of maps used in the transformation of the configuration domain and in the proof of Proposition \myref{thm:construction}.  %\LC(section9db_proof-9)
(a) a configuration domain for $D=2$. 
The parameters are $\vlsh=(3,5)$, $\vran=(1, 2)$ and $\vlpa=(4,7)$.  %\LC(section9db_proof-11)
(b) The images of the maps at the last step of induction $K=D=2$. 
The correspondences in each map for $\vx=(0, -4)\in\mathcal{\lsh}$ and $\vx=(-1,-2),(0,0),(-1,1)\in\mathcal{\ran}$ are also shown. %\LC(section9db_proof-13)
}
\label{fig-proofs}
\end{lfigure}

Here we prove Proposition \myref{thm:construction}. %\LC(section9db_proof-17)
Figure \myref{fig-proofs} shows an example of the maps and their images used in the proof. %\LC(section9db_proof-18)

To prove Proposition \myref{thm:construction}, we use the following facts: %\LC(section9db_proof-22)

\begin{prop}

\label{prop:propB1}
It holds %\LC(section9db_proof-28)
\AL{
2\ran\lkth+1\le {\lpa}\lkth.\LB{eq:propB1}
}

\end{prop}

\begin{proof}

For any $\idim$, it holds %\LC(section9db_proof-36)
\AL{
2\rand+1\le \lpad, \LB{eq:propB1-k1}
}
because $\lpad=\lshd+\rand$ and $\rand\le \lshd-1$ by definition. %\LC(section9db_proof-42)

The inequality Eq.~(\myref{eq:propB1}) for $K=1$ holds by Eq.~(\myref{eq:propB1-k1}). %\LC(section9db_proof-46)
For $K>1$, we can inductively prove it by assuming it for $K-1$ and using the recurrence relation (\myref{eq:rec-ran}) as %\LC(section9db_proof-47)
\AL{
2\ran\lkth+1&=2\ran_K {\lpa}\mkth+2\ran\mkth+1\NN
&\le 2\ran_K {\lpa}\mkth+{\lpa}\mkth\NN
&=(2\ran_K+1){\lpa}\mkth\NN
&\le \lpa_K {\lpa}\mkth\NN
&={\lpa}\lkth.\LB{eq:propB1-5}
}

\end{proof}

\begin{prop}

\label{prop:propB2}
Let $\ravlr\lkth$ be the map obtained by restricting the domain of $\ravl\lkth$ to $\ransp^K$. %\LC(section9db_proof-67)
Then, $\ravlr\lkth$ is injective and its image is contained in $[-\ran\lkth, \ran\lkth]$. %\LC(section9db_proof-68)

\end{prop}

\begin{proof}

We prove it by induction. %\LC(section9db_proof-72)
When $K=1$, $\ravlr^{(1)}$ is injective and its image is $\ransp^1=[-\ran^{(1)}, \ran^{(1)}]$, because $\ravlr^{(1)}(x)=x$. %\LC(section9db_proof-74)

Let us assume that $K>1$ and that the statement holds for $K-1$. %\LC(section9db_proof-78)
We can use the recurrence relation (\myref{eq:rec-ravl}) to calculate $\ravl\lkth$ as %\LC(section9db_proof-79)
\AL{
&\ravl\lkth(\vx_{:K})=x_{K} {\lpa}\mkth +\ravl\mkth(\vx_{:K-1}). 
}
When $\vx_{:(K-1)}\in\ransp^{K-1}$, by this recurrence relation and the assumption, it holds that %\LC(section9db_proof-85)
\AL{
\ravl\lkth(\vx_{:K})\in [& x_{K} {\lpa}\mkth -\ran\mkth,
\TW{\NN &}
x_{K} {\lpa}\mkth +\ran\mkth]. %\LC(section9db_proof-91)
}
By considering the range $x_{K}\in [-\ran_K, \ran_K]$ and using the recurrence relation (\myref{eq:rec-ran}), we can prove that the image of $\ravlr\lkth$ is contained in $[-\ran\lkth, \ran\lkth]$. %\LC(section9db_proof-94)
For any integers $n,k>0$, we have %\LC(section9db_proof-95)
\AL{
&
((k+n) {\lpa}\mkth-\ran\mkth)-(k {\lpa}\mkth+\ran\mkth)
\NN &
=n{\lpa}\mkth -2\ran\mkth\NN
&\geq{\lpa}\mkth-2\ran\mkth\NN
&>0,
}
where the last inequality is from Proposition \myref{prop:propB1}. %\LC(section9db_proof-107)
It tells us that the images of $\ravlr\lkth(x_1,\ldots,x_{K-1},x_{K})$ for different $x_{K}=k$ do not overlap. %\LC(section9db_proof-108)
Therefore $\ravlr\lkth$ is injective, due to Eq.~(\myref{eq:rec-ravl}) and the assumption. %\LC(section9db_proof-109)

\end{proof}

The proof of each statement in Proposition \myref{thm:construction} is as follows: %\LC(section9dc_proofAB-2)

\begin{proof}[Proof of Proposition \ref{thm:construction}]
~\paragraph{Statement (A).}
By definitions, it holds %\LC(section9dc_proofAB-10)
\AL{
\TW{&}
\mymod{\ravm(\vpos_i)-\ravm(\vpos_j)}{\lpa}
\TW{\NN}
&= \mymod{\ravl\dimth(\vect{\vpos_i})-\ravl\dimth(\vect{\vpos_j})}{\lpa}
\NN
&=\mymod{\ravl\dimth(\vect{\vpos_i}-\vect{\vpos_j})}{\lpa}\NN
&=\ravm(\vect{\vpos_i}-\vect{\vpos_j}).
}
for $\vpos_i ,\vpos_j\in\Inte^D$. %\LC(section9dc_proofAB-23)

~\paragraph{Statement (B).}

Let $\ravlr\dimth$ be the injective function defined as Proposition \myref{prop:propB2}. %\LC(section9dc_proofAB-31)
Then, the restricted map $h$ is represented as %\LC(section9dc_proofAB-33)
\AL{
\ravr(x)=\mymod{\ravlr\dimth(x)}{{\lpa}\dimth}.
}
This $h$ is also injective because the image of $\ravlr\dimth$ is contained in $[-\ran\dimth, \ran\dimth]$ and, by Proposition \myref{prop:propB1}, we have $\ran\dimth<{\lpa}\dimth-\ran\dimth$. %\LC(section9dc_proofAB-40)

~\paragraph{Statement (C).}

Let us assume $\vrel\in\lshsp \setminus \ransp$. %\LC(section9dd_proofC-5)
Then, there exists $K$ such that $\vrel_{:K-1}\in\ransp\mkth$ and $\rel_{K}\not\in [-\ran_K, \ran_K]$. %\LC(section9dd_proofC-6)
For such $K$, it holds $\ravl\mkth(\vrel_{:K-1})\in[-\ran\lkth, \ran\lkth]$ %\LC(section9dd_proofC-7)
by Proposition \myref{prop:propB2}. %\LC(section9dd_proofC-8)
Let us introduce the set $\cfil$ as follows: %\LC(section9dd_proofC-9)
\AL{
\cfil=\{x\in\Inte \mid {}&\exists b \in [-\ran\lkth, \ran\lkth], \TW{\NN
&}\mymod{(x-b)}{{\lpa}\lkth}=0\}.
}

When $\rel_K>\ran_K$, it holds $\ran_K<\rel_K<\lsh_K=\lpa_K-\ran_K$, and thus $\ran_K+1\le \rel_K \le \lpa_K-\ran_K-1$. %\LC(section9dd_proofC-19)
By using Proposition \myref{prop:propB1} and the recurrence relations Eqs.~(\myref{eq:rec-ravl}) and (\myref{eq:rec-ran}) we have %\LC(section9dd_proofC-21)
\AL{
\ravl\lkth(\vrel_{:K})&\in[(\ran_K+1){\lpa}\mkth-\ran\mkth,
\TW{\NN&\quad\;}
(\lpa_K-\ran_K-1){\lpa}\mkth+\ran\mkth]\NN
&\subset(\ran_K{\lpa}\mkth+\ran\mkth,
\TW{\NN&\quad}
(\lpa_K-\ran_K){\lpa}\mkth-\ran\mkth)\NN
&=(\ran\lkth,{\lpa}\lkth-\ran\lkth)\NN
&\subset \Inte \setminus \cfil.
}
Likewise, when $\rel_K<-\ran_K$, it holds  $-\lpa_K+\ran_K=-\lsh_K<\rel_K<-\ran_K$, and thus $-\lpa_K+\ran_K+1\le \rel_K\le -\ran_K-1$. %\LC(section9dd_proofC-35)
Thus, we have %\LC(section9dd_proofC-37)
\AL{
\ravl\lkth(\vrel_{:K})&\in[(-\lpa_K+\ran_K+1){\lpa}\mkth-\ran\mkth,
\TW{\NN&\quad\;}
(-\ran_K-1){\lpa}\mkth+\ran\mkth]\NN
&\subset((-\lpa_K+\ran_K){\lpa}\mkth+\ran\mkth,
\TW{\NN&\quad\;}
-\ran_K{\lpa}\mkth-\ran\mkth)\NN
&=(-{\lpa}\lkth+\ran\lkth,-\ran\lkth)\NN
&\subset \Inte \setminus \cfil.
}
In either case, we have $\ravl\lkth(\vrel_{:K})\notin \cfil$. %\LC(section9dd_proofC-51)

Suppose that $\ravm(\vrel)\in\imset$, that is, there exists $\vrel'\in\ransp$ such that $\ravm(\vrel)=\ravm(\vrel')$. %\LC(section9dd_proofC-55)
We have %\LC(section9dd_proofC-57)
\AL{
\ravl\dimth(\tilde{\vrel})&=\Bigg(\sum_{k=K+1}^{D}\tilde{\rel}_k{\lpa}^{(k-1)}\Bigg)+\ravl\lkth(\tilde{\vrel}_{:K})
}
for both $\tilde{\vrel}\in\{\vrel, \vrel'\}$. %\LC(section9dd_proofC-63)
By Proposition \myref{prop:propB2} and $\vrel'_{:K}\in\ransp\lkth$, we have $\ravl\lkth(\vrel'_{:K})\in[-\ran\lkth, \ran\lkth]\subset\cfil$. %\LC(section9dd_proofC-65)
Then, because ${\lpa}^{(k-1)}$ is divisible by ${\lpa}\lkth$ for $k=K+1,\ldots,D$, we have $\ravl\dimth(\vrel)\not \in\cfil$ and $\ravl\dimth(\vrel')\in\cfil$. %\LC(section9dd_proofC-67)

For both $\tilde{\vrel}=\{\vrel, \vrel'\}$, we have %\LC(section9dd_proofC-71)
\AL{
\mymod{\ravm(\tilde{\vrel})}{{\lpa}\lkth} &=\mymod{(\mymod{\ravl\dimth(\tilde{\vrel})}{\lpa})}{{\lpa}\lkth} \NN
&=\mymod{\ravl\dimth(\tilde{\vrel})}{{\lpa}\lkth}
}
because $\lpa$ is divisible by ${\lpa}\lkth$, and thus $\ravl\dimth(\tilde{\vrel})\in\cfil \Leftrightarrow \ravm(\tilde{\vrel})\in\cfil$. %\LC(section9dd_proofC-79)
Since this contradicts the assumption $\ravm(\vrel)=\ravm(\vrel')$, it follows that $\ravm(\vrel)\not\in\imset$. %\LC(section9dd_proofC-81)

\end{proof}



\section{Calculations for spQUBO using DFT}
\label{sec-proof-fft}

Let us denote the two-dimensional DFT of function $\phi\colon\Inte^2\to\Real$ with period $\vlsh$ and its inverse as %\LC(section9e_fft-3)
\AL{
\fou\phi(\spos)=\sum_{\vx\in\InteN{\vlsh}}\phi(\vx)W_{\spos,\vx}\\
\ifou\phi(\spos)=\frac{1}{V}\sum_{\vx\in\InteN{\vlsh}}\phi(\vx)W_{\spos,-\vx}
}
where $W_{\spos, \vx}=\exp\AS{-2\pi \iunit \sum_{d=1}^{2}(\spos_d\vx_d/\lsh_d)}$ and $V=\lsh_1\lsh_2$. %\LC(section9e_fft-10)

Theorems 3 and 4 can be reduced to the case where $c_i=1$: %\LC(section9e_fft-14)

\begin{prop}

\label{thm:fft-mvm-base}
For a spatial coupling function $f$ of an spQUBO, let $a_i$ be elements of the matrix-vector product defined as %\LC(section9e_fft-19)
\AL{
a_i = \sumj f(\vdi-\vdj)v_j, %\LC(section9e_fft-23)
}
where $\vect{v}\in\Real^N$. %\LC(section9e_fft-27)
We define a function $\xi\colon\Inte^2\to\Real$ with period $\vlsh$ as %\LC(section9e_fft-29)
\AL{
\xi(\vx) = \begin{cases}
v_i & \text{if } \vx = \vdi, \\ %\LC(section9e_fft-34)
0 & \text{otherwise}
\end{cases}
}
for $\vx\in\InteN{\vlsh}$. %\LC(section9e_fft-40)
Then, it holds that %\LC(section9e_fft-42)
\AL{
a_i = \ifouAS{\fou{\xi}\odot\fou{f}}(\vdi), %\LC(section9e_fft-46)
}
where $\odot$ denotes the Hadamard element-wise product. %\LC(section9e_fft-50)

\end{prop}

\begin{proof}

Because $\vpos_i$ are all different and by definitions, we can represent $\vect{a}$ as the convolution of $f$ and $\xi$, in particular, for a function %\LC(section9e_fft-54)
\AL{
a(\vx_1)=\sum_{\vx_2\in\InteN{\vlsh}}f(\vx_1-\vx_2)\xi(\vx_2), %\LC(section9e_fft-58)
}
the $i$-th element of $\vect{a}$ is represented as %\LC(section9e_fft-62)
\AL{
a_i&=a(\vpos_i). %\LC(section9e_fft-65)
}
Because $f$ has period of $\vlsh$, we can represent the cyclic convolution as %\LC(section9e_fft-69)
\AL{
a(\vx)=\ifouAS{{\fou{\xi}} \odot \fou{f}}(\vx), %\LC(section9e_fft-72)
}
and this completes the proof. %\LC(section9e_fft-75)

\end{proof}
This can be easily extended for the Hamiltonian calculation: %\LC(section9e_fft-79)

\begin{proof}
 [Proof of Theorem \myref{thm:fft-hamiltonian}]
Let $\vect{a}$ and $\xi$ be as defined in Proposition \myref{thm:fft-mvm-base}, with $v_i=c_ix_i$, so that $a_i = \ifouAS{{\fou{\xi}}\cdot \fou{f}}(\vpos_i)$. %\LC(section9e_fft-82)
Because $\vpos_i$ are all different, we have %\LC(section9e_fft-83)
\AL{
\hamil&=\frac{1}{2}\sumi v_i a_i\NN
&=\frac{1}{2}\sum_{\vx\in\InteN{\vlsh}} \xi(\vx)\cdot \AS{\ifouAS{{\fou{\xi}}\cdot \fou{f}}(\vx)}\NN
&=\frac{1}{2V}\sum_{\spos\in\InteN{\vlsh}} \overline{\fou{\xi}(\spos)}\cdot \AS{{\fou{\xi}}(\spos)\cdot \fou{f}(\spos)}\NN
&=\frac{1}{2V}\sum_{\spos\in\InteN{\vlsh}} \|\fou{\xi}(\spos)\|^2\cdot \fou{f}(\spos).
}

\end{proof}
Theorem \myref{thm:fft-mvm} can also be obtained as a corollary of Proposition \myref{thm:fft-mvm-base}. %\LC(section9e_fft-95)

\section{MVPs in Ising solvers}
\label{sec-mvms-in-solver}

As mentioned in Introduction, many of the computational principles of physical Ising solvers can be written in dynamical systems \mycite{CAC,CACScaling,MA,SBM}. %\LC(section9f_mvms_in_solver-3)
The MVP $J\vect{x}$ argued in the text is incorporated in these systems as below, showing the potential benefits of its improvement. %\LC(section9f_mvms_in_solver-5)

If we model the behavior of the coherent Ising machine (CIM) \mycite{CIMPRA2013,CIMScience2016,CIMAPL2020} as classical dynamics with a time interval $\Delta t$, we obtain %\LC(section9f_mvms_in_solver-9)
\AL{
\tau\frac{\vect{q}_{k}-\vect{q}_{k-1}}{\Delta t}&=c(-\vect{q}_{k-1}^3+a\vect{q}_{k-1})+J\vect{q}_{k-1},
}
where $\vect{q}_k$ is the system state at the $k$-th iteration, $\tau$ is the time constant, $c$ and $a$ are the other system parameters, and $\vect{q}^n$ means the element-wise $n$-th power of the vector. %\LC(section9f_mvms_in_solver-15)
This system can be interpreted as the gradient system or the gradient descent method on the energy function $\hamil(\vect{q})$, defined as %\LC(section9f_mvms_in_solver-17)
\AL{
E(\vect{q})&=-\frac{1}{2}\vect{q}\tr J\vect{q}+\vect{\phi}_a(\vect{q}),\\ %\LC(section9f_mvms_in_solver-20)
\phi_a(\vect{q})&=\frac{c}{4}\AS{\vect{q}^4-2a\vect{q}^2}.
}
This function simulates the Ising Hamiltonian well when each amplitude is close to one $(q_i)^2\simeq 1$. %\LC(section9f_mvms_in_solver-25)
It is shown that the performance is improved by adding the controlling terms for this condition \mycite{CAC,CACScaling}. %\LC(section9f_mvms_in_solver-26)

In contrast, the simulated bifurcation machine (SBM) \mycite{SBM} simulates the following dynamical system: %\LC(section9f_mvms_in_solver-31)
\AL{
\tau_q\frac{\vect{q}_k-\vect{q}_{k-1}}{\Delta t}&=\vect{p}_{k-1}\\
\tau_p\frac{\vect{p}_k-\vect{p}_{k-1}}{\Delta t}&=c(-\vect{q}_{k}^3+a\vect{q}_k) + J \vect{q}_k,
}
where $\vect{q}_k$ and $\vect{p}_k$ are the system states at the $k$-th iteration, and $\tau_p, \tau_q$ are the time constants. %\LC(section9f_mvms_in_solver-38)
It is also related to the energy function $E(\vect{q})$, as it simulates the Hamiltonian system defined with $E(\vect{q})$. %\LC(section9f_mvms_in_solver-39)

In momentum annealing (MA) \mycite{MA}, two layers $\vect{\sigma}^L,\vect{\sigma}^R$ of spin vectors to be optimized are prepared. %\LC(section9f_mvms_in_solver-43)
These two layers of spins are coupled with their coefficient matrix $J$ and additional inter-layer couplings represented by a diagonal coefficient matrix $W$. %\LC(section9f_mvms_in_solver-45)
Then, they are updated following the Gibbs sampling procedure, whose update formula is expressed as %\LC(section9f_mvms_in_solver-46)
\AL{
\vect{I}_k&=\vect{h}+(J+W)\vect{\sigma}_{k-1},\LN{eq:MA-inte}
\sigma_k&=\sgn \AS{\vect{I}^{(k)}+\frac{T_k}{2}\vect{\Gamma}_k \vect{\sigma}_{k-2}},\LB{eq:MA-flip}
}
where $\vect{\sigma}_k$ represents $\vect{\sigma}^L$ or $\vect{\sigma}^R$ depending on the parity of $k$, $T_k$ is the temperature parameter, and $\Gamma$ is a gamma distribution with the shape and scale parameters set to one. %\LC(section9f_mvms_in_solver-54)

\section{Settings in numerical example of placement problem}
\label{sec-placement-numerical}

For the example placement problem used in the text, we consider the region of interest represented as $X=[0, H]\times [0, W]$ for $H,W>0$. %\LC(section9gb_placement_numerical-3)
For $B\in\Nnum$, let us consider the grid points obtained by dividing a square of unit side length into $B^2$ cells. %\LC(section9gb_placement_numerical-4)
Namely, the $i$-th grid point $\vect{p}_i$ corresponds to the integer grid point $\vpos_i = (n, m)\tr$ as %\LC(section9gb_placement_numerical-5)
\AL{
\vect{p}_i=\AS{\frac{n}{B},\frac{m}{B}},
}
where $n=0,\ldots,HB,m=0,\ldots,WB$. %\LC(section9gb_placement_numerical-11)
We assign spins to every grid point, so the number of spins is $O(HWB^2)$. %\LC(section9gb_placement_numerical-12)

We set the parameters for the interaction as follows: %\LC(section9gb_placement_numerical-16)
Let us denote the area of the circle with radius $\rho$ by $S=\pi \rho^2$. %\LC(section9gb_placement_numerical-18)
We assume the point-wise utility $\xi_\vz$ at $\vz$ using the density of the facilities within the area of radius $\rho$ from $\vz$, denoted by $x_\vz=n_{\vz}/S$. %\LC(section9gb_placement_numerical-20)
Specifically, we assume %\LC(section9gb_placement_numerical-21)
\AL{
\xi_\vz=-(\tilde{a}/2)(x_\vz/K-1)^2,
}
where $\tilde{a}$ is the scaling parameter of the utility and $K$ is the reference density. %\LC(section9gb_placement_numerical-28)
The number of facilities in the circle with radius $\rho$ at the reference density is $\nu\equiv SK$. %\LC(section9gb_placement_numerical-30)
Thus, we have %\LC(section9gb_placement_numerical-32)
\AL{
\xi_\vz=-(\tilde{a}/2)(n_{\vz}/\nu-1)^2.
}
For $(a,b)=(\tilde{a}/2\nu^2, \tilde{a}/\nu)$, we can compute the integral of the utility up to the constant similarly to the text as %\LC(section9gb_placement_numerical-39)
\AL{
\Xi &= \int_\vz (-an_\vz^2+bn_\vz) d\vz = -a \sumij W'_{ij}x_ix_j+b\sumi b'_i x_i,
}
where  %\LC(section9gb_placement_numerical-47)
\AL{
W'_{ij}&=f(\rel_{ij})=\begin{cases} %\LC(section9gb_placement_numerical-51)
2(\rho^2\theta_{ij} - \rel_{ij}^2\tan\theta_{ij}/4)&(\rel_{ij}<2\rho)\\
0&(\rel_{ij}\ge 2\rho)
\end{cases},\\
b'_i&=S, %\LC(section9gb_placement_numerical-55)
}
for $r_{ij} = \|\vect{p}_i-\vect{p}_j\|$ and $\theta_{ij}=\cos^{-1} (\rel_{ij}/2\rho)$. %\LC(section9gb_placement_numerical-59)
We set $\tilde{a}=\nu/S$ such that the bias values $bb'_i$ become a unit, and set $(H, W, K, \rho)=(5, 5, 2, 0.25)$. %\LC(section9gb_placement_numerical-60)
We used $B=40$ for Fig.~\myref{fig:placement_qubo}, and varied $B=1,2,\ldots, 40$ for Fig.~\myref{fig:fig2}. %\LC(section9gb_placement_numerical-61)
Using Theorem \myref{thm:padding-spcm} in the main text, we converted the problem to the equivalent two-dimensional periodic spQUBO. %\LC(section9gb_placement_numerical-62)
The locality parameter is set to be the minimum number such that it is no less than $2\rho B$. %\LC(section9gb_placement_numerical-63)

We randomly assigned the placement cost for each point as follows: %\LC(section9gb_placement_numerical-67)
Let the placement cost at $\vect{p}_i$ be assigned as $\plcost_i=f(\vect{p}_i)$ for $f\colon X\to\Real$. %\LC(section9gb_placement_numerical-69)
The cost distribution $f$ consists of {\it line} and {\it blob} components. %\LC(section9gb_placement_numerical-70)
In particular, it is defined as %\LC(section9gb_placement_numerical-71)
\AL{
f(x)&\equiv{A}\exp(\tilde{f}(x))-{B},\\ %\LC(section9gb_placement_numerical-74)
\tilde{f}(x)&\equiv\tilde{A}\left(\coline\sum_{i=1}^{\nline}\fline_i(x)\TW{\right.\NN
&\quad\left.}+\sum_{i=1}^{\nblob}\coblob_i\fblob_i(x)\right)-\tilde{B},\\
\fline_i(x)&\equiv\exp\AS{-\frac{\langle x-m_i,v_i\rangle^2}{2(\sline)^2}}\quad(i=1,\ldots,\nline),\\
\fblob_i(x)&\equiv\exp\AS{-\frac{\| x-\mu_i\|^2}{2(\sblob)^2}}\quad(i=1,\ldots,\nblob),
}
with the parameters below: %\LC(section9gb_placement_numerical-81)
There are $\nline=4$ line components determined by the vectors $m_i, v_i \in \Real^2$, which represent the center and the normal direction of the line components and set as %\LC(section9gb_placement_numerical-83)
\AL{
(4m_i)\tr&=(1,2),(2,1),(3,2),(2,3),\\
v_i\tr&=(1,0),(0,1),(1,0),(0,1), %\LC(section9gb_placement_numerical-87)
}
respectively. %\LC(section9gb_placement_numerical-90)
There are also $\nblob$ blob components whose centers are determined by the vectors $\mu_i\in X$, each of which is uniformly randomly sampled from $X$. %\LC(section9gb_placement_numerical-91)
The scales of the line and blob components are determined by the parameters $\sline,\sblob > 0$, respectively. %\LC(section9gb_placement_numerical-92)
$\coblob_i$, which is drawn uniformly randomly from $[-1, +1]$, represents the sign and weight of each blob component, and the balance between lines and blobs is controlled by $\coline$.
$\tilde{f}$ represents the relative cost distribution and we rescaled it to obtain the cost distribution $f$: $\tilde{A},\tilde{B}$ are chosen so that the mean and variance of $\{\tilde{f}(\vpos_i)\}$ are $0$ and $(\sigma^{(f)})^2$, respectively, and $A,B$ are set such that the minimum and the maximum value of $f(p_i)$ are $0$ and $\cmax$, respectively, where $\cmax$ is the scale parameter for costs.
We set the parameters as $(\coline, \sline, \nblob, \sblob, (\sigma^{(f)})^2, \cmax) = (10, 0.05, 1000, 0.3, 1.5, 1.5)$. %\LC(section9gb_placement_numerical-96)

For Figure 4, the parameters for the MA were set as follows: %\LC(section9gb_placement_numerical-100)
\AL{
% p_k& = \max (0, p_0 (1 - k / T))\\
p_k& = p_0 (1 - k / T)\\ %\LC(section9gb_placement_numerical-105)
c_k& = 1\\ %\LC(section9gb_placement_numerical-106)
T_k& =  \frac{T_0\theta_1}{\theta_1 + \log(1 + \theta_2(k-1)/T)}, %\LC(section9gb_placement_numerical-107)
}
where $p_k, c_k$ and $T_k$ are the same parameter as the original study \mycite{MA} of MA for each $k$-th step, $T=10000$ is the number of steps, and $(T_0, p_0, \theta_1, \theta_2) = (0.1, 0.05, 0.001, 0.1)$. %\LC(section9gb_placement_numerical-111)
We set the inter-layer coupling strengths as $w_i = \sum_j |J_{ij}|/2$ for all spins, which are a more simplified choice than the original study. %\LC(section9gb_placement_numerical-112)

\section{Settings in numerical example of clustering problem}
\label{sec-clustering-synthetic}

For the example clustering problem used in the text, we used the following settings. %\LC(section9gc_clustering_numerical-4)
For $B\in\Nnum$, let us consider the grid points obtained by equally dividing the unit square $[0, 1]^2$ into $(B-1)^2$ cells. %\LC(section9gc_clustering_numerical-6)
Namely, each point $x_i$ is represented as %\LC(section9gc_clustering_numerical-7)
\AL{
\vx_i=\AS{\frac{n}{B-1},\frac{m}{B-1}}
}
for $n,m\in\{0,\ldots,B-1\}$. %\LC(section9gc_clustering_numerical-13)
We consider $K$ clusters, and generated $M$ points for each the $k$-th cluster $C_k$ as follows: %\LC(section9gc_clustering_numerical-14)
Let us suppose the center $\vect{v}_k\in\Real^2$ and the scale parameter $\sigma_k>0$ for each $k$. %\LC(section9gc_clustering_numerical-16)
We compute the density parameter %\LC(section9gc_clustering_numerical-17)
\AL{
f_{k,i}=\frac{1}{\sqrt{2\pi\sigma_k^2}}\exp\AS{-\frac{(x-v_k)}{2\sigma_k^2}} %\LC(section9gc_clustering_numerical-20)
}
for each $k$ and grid point $x_i$. %\LC(section9gc_clustering_numerical-23)
The cluster $K_i$ is assigned to each grid point $x_i$ such that it maximizes the density parameter: %\LC(section9gc_clustering_numerical-24)
\AL{
K_i=\argmax_k f_{k,i}. %\LC(section9gc_clustering_numerical-27)
}
For each $k$-th cluster, we sample $M$ points without replacement using selection probabilities proportional to $f_{k,i}$. %\LC(section9gc_clustering_numerical-30)

Specifically, we set $(B,K,M)=(51,7,100)$. %\LC(section9gc_clustering_numerical-34)
In addition, we used the parameters for the density parameter given by %\LC(section9gc_clustering_numerical-35)
\AL{
v_k&=0.1v'_k\\ %\LC(section9gc_clustering_numerical-38)
({v'_k})\tr&= (1,1),(1,9),(9,1),(9,9),\TW{\NN
&\quad\quad} (3,5),(6,3),(6,7)
}
and $\sigma_k=0.1$ for all $k$. %\LC(section9gc_clustering_numerical-44)
The weight parameter $C$ for the Hamiltonian $H=H_{\mathrm{A}}+CH_{\mathrm{B}}$ is set to $C=50$. %\LC(section9gc_clustering_numerical-46)
The parameters for the MA were set as follows: %\LC(section9gc_clustering_numerical-48)
\AL{
p_k& = \max (0, p_0 - k / T)\\ %\LC(section9gc_clustering_numerical-52)
c_k& = \min (1, \sqrt{\theta_1 k / T})\\ %\LC(section9gc_clustering_numerical-53)
T_k& =  \frac{T_0}{ \log(1 + k)}, %\LC(section9gc_clustering_numerical-54)
}
where $p_k, c_k$ and $T_k$ are the same parameter as the original study \mycite{MA} of MA for each $k$-th step, $T=1000$ is the number of steps, and $(T_0, p_0, \theta_1) = (1, 0.5, 2)$. %\LC(section9gc_clustering_numerical-58)
