% Within the braces of a theorem environment, I think it looks better to have the Theorem number outside the square brackets, and in italics
\begin{conjecture}[{\rm\cite{hhh2023}}, Conjecture {\small III}\/]\label{conjblocky}
Suppose that $A$ is a finite boolean matrix
with $\normgamma A\le \gamma$. Then we may write
\begin{equation}A = \sum_{i=1}^L \sigma_i B_i,\end{equation}
where the $\sigma_i$ are signs, the $B_i$ are blocky matrices, and $L$ depends only on $\gamma$.
\end{conjecture}

As mentioned before, the Green--Sanders theorem shows that \Cref{conjblocky} is true for convolution matrices, i.e., those of the form $A(x,y) = f(y^{-1}x)$ for some boolean function $f$ (here we stated the case for general, possibly non-abelian groups).

We define the \emph{block complexity} $\block(A)$ of an $m\times n$ matrix $A$ to be the smallest integer $L$ such that there exist blocky matrices $B_1, \ldots, B_L$ and signs $\sigma_1, \ldots, \sigma_L$ with $A = \sum_{i=1}^L \sigma_i B_i$. \Cref{conjblocky} claims that any matrix of bounded $\gamma_2$ norm has constant block complexity.
In the present paper, we are able to show that a matrix of any matrix of bounded $\gamma_2$ norm has block complexity at most polylogarithmic in its dimension.

\begin{theorem}[Main theorem]\label{thmmain}
Let $A$ be an $m\times n$ integer matrix with $\normgamma A\le \gamma$. The block complexity of $A$ satisfies
\begin{equation}\block(A) \le 2^{O(\gamma^7)} \log\bigl(\min\{m,n\}\bigr)^2.\end{equation}
\end{theorem}



\paragraph{Definitions and notation.}\hskip-0.3em%
We shall often find it convenient to regard a matrix as a function with a set $X\times Y$ as its domain. In the rest of the paper, $X$ and $Y$ will be assumed finite unless otherwise stated, and we reserve in advance the variables $m = |X|$ and $n=|Y|$. Then, when we write $A\in \ZZ^{X\times Y}$ (for instance), we mean that $A$ is an $m\times n$ integer matrix with rows indexed by $X$ and columns indexed by $Y$.
If $A$ is a matrix with domain $X\times Y$ and let $X'\subseteq X$ and $Y'\subseteq Y$, we may write $A_{X'\times Y'}$ for the matrix on the domain $X'\times Y'$ with $A_{X'\times Y'}(x,y) = A(x,y)$ for all $x\in X'$ and $y\in Y'$.

Now suppose that $A$ is a real matrix with $\normgamma A\le \gamma$.
By rescaling the vectors given by the definition of factorization norm, we may express $A$ as a product $A = UV$ for some real matrices $U$ and $V$ such that
\begin{equation*}\max\bigl( \norm{u_1}_2,\ldots,\norm{u_m}_2\bigr) \le 1\end{equation*}
and
\begin{equation*}\max\bigl(\norm{v_1}_2,\ldots,\norm{v_n}_2\bigr) \le \gamma,\end{equation*}
where $u_1,\ldots, u_m$ are the rows of $U$ and $v_1,\ldots, v_n$ are the columns of $V$. We shall call such a factorization of $A$ a \emph{$\gamma$-factorization}. If $U$ is $m\times t$ and $V$ is $t\times n$ for some integer $t$, note that the set $\{u_1, \ldots, u_m, v_1, \ldots, v_n\}$ is contained in a $t'$-dimensional subspace of $\RR^t$ for some $t'\le m+n$. So, without loss of generality, we always assume that all the vectors in a $\gamma$-factorization of an $m\times n$ matrix belong to $\RR^{m+n}$.

All logarithms in this paper are understood to be natural.

\section{The Littlestone dimension}

Towards a generalization of the Littlestone dimension for real matrices, we devote this section to recalling some properties of the ordinary Littlestone dimension~\cite{littlestone1988}.

We begin with the definition of the \emph{Vapnik--Chervonenkis (VC) dimension}. For a sign matrix $A \in \{-1,1\}^{X\times Y}$, this is the size of the largest subset $X'$ of $X$ such that for every $b : X'\to \{-1,1\}$, there exists a column $y$ such that $A(x,y) = b(x)$ for all $x\in X'$. Such a set $X'$ is said to be \emph{shattered} by $A$.

The Littlestone dimension relaxes this definition by shattering decision trees instead of sets. A \emph{mistake tree} of depth $d$ over a domain $X$ is a complete binary tree of depth $d$ in which
\begin{itemize}\setlength\itemsep{-2pt}
\item[i)] each internal node $v$ is labelled with an element $x(v)\in X$; and
\item[ii)] each edge $e$ is labelled with a sign $\sigma(e)\in \{-1,1\}$, where $b(e) = -1$ indicates a left child and $\sigma(e) = 1$ indicates a right child.
\end{itemize}

For the purposes of the Littlestone dimension, a matrix $A \in \{-1,1\}^{X\times Y}$ is said to \emph{shatter} a mistake tree over $X$ if, for every root-to-leaf path $(v_1,\ldots, v_{d+1})$, there exists a column $y\in Y$ such that $A\bigl( x(v_i), y\bigr) = \sigma(v_i v_{i+1})$ for all $i\in [d]$. Then the \emph{Littlestone dimension} of $A$, denoted by $\Ldim(A)$, is the largest integer $d$ for which there exists a mistake tree of depth $d$ that is shattered by $A$. The Littlestone dimension is at least the VC dimension, since every shattered set $X' = \{x_1,\ldots,x_d\}$ gives rise to a mistake tree of depth $d$ where all nodes at level $i$ are labelled with $x_i$.

For any sign matrix $A$ with $\Ldim(A) = d$ and any $0<\eps<1/2$, one can find a fixed sign vector that matches an $\eps^d$ proportion of the columns of $A$, with error at most $\eps$.

\begin{proposition}\label{propsubset}
Let $A\in \{-1,1\}^{X\times Y}$ be a matrix with $\Ldim(A) = d$ and let $\eps\in (0,1/2)$. There exists a function $\sigma : X\to \{-1,1\}$ and some subset $S\subseteq Y$ with $|S|\ge \eps^d|Y|$ such that
\begin{equation}\Pr_{y\in S} \bigl[ A(x,y) \ne \sigma(x)\bigr] \le \eps\end{equation}
for all $x\in X$.
\end{proposition}

\begin{proof}
Let $A\in \{-1,1\}^{X\times Y}$ be a matrix, and let $x\in S$ be an arbitrary row of $A$. Let
\begin{equation*}Y_x^- = \{y\in Y : A(x,y) = -1\}\qquad\hbox{and}\qquad Y_x^+ = \{y\in Y : A(x,y) = 1\}.\end{equation*}
By the definition of the Littlestone dimension, we have
\begin{equation}\Ldim(A) = 1+ \min\bigl\{ \Ldim(A_{X\times Y_x^-}), \Ldim(A_{X\times Y_x^+})\bigr\},\end{equation}
which implies that the Littlestone dimension must drop on at least one of $A_{X\times Y_x^-}$ or $A_{X\times Y_x^+}$.

If $S=Y$ and $\sigma(x) = \sgn\bigl( \sum_{y\in S} A(x,y)\bigr)$ does not satisfy the condition, then there is a row $x\in X$ with
\begin{equation}\Pr_{y\in S} \bigl[ A(x,y) \ne \sigma(x)\bigr] > \eps,\end{equation}
which implies that $Y_x^-$ and $Y_x^+$ both comprise at most a $(1-\eps)$ proportion of $Y$. By the claim of the previous paragraph, removing all the columns in one of these two sets decreases the Littlestone dimension by $1$, and in the resulting matrix, $x$ no longer violates our desired condition.

The proposition now follows by induction on $d$, since when $d=0$, each row must either contain only $-1$s or only $1$s, which forces all columns to be identical.
\end{proof}

Next, we show that for sign matrices, the Littlestone dimension provides a lower bound for (the square of) the $\gamma_2$ norm. The following proposition essentially follows from the classic mistake-bound analysis~\cite{rosenblatt1958} of the perceptron algorithm~\cite{mp43}.

\begin{proposition}\label{propldimbound}
Every $A\in \{-1,1\}^{X\times Y}$ satisfies
\begin{equation}\normgamma A \ge \sqrt{\Ldim(A)}.\end{equation}
\end{proposition}

\begin{proof}
Let $\gamma = \normgamma A$ and $d = \Ldim(A)$.
Consider a $\gamma$-factorization $A = UV$ of $A$ (so that $\norm{u_x} \le 1$ for all $x\in X$ and $\norm{v_y} \le \gamma$ for all $y\in Y$). By the definition of the Littlestone dimension, $A$ shatters a mistake tree of depth $d$ over $X$.
We shall recursively construct a root-to-leaf path $(v_1, \ldots, v_{d+1})$ that furnishes our desired bound. Let $v_1$ be the root of the tree and set $\sigma_1 = 1$. Now for all $1\le k\le d$, let $v_{k+1}$ be the child of $v_k$ with $\sigma(v_kv_{k+1}) = \sigma_k$
and set
\begin{equation}\sigma_{k+1} = -\sgn \biggl\langle \sum_{i=1}^k \sigma_i u_{x(v_i)}, u_{x(v_{k+1})}\biggr\rangle.\end{equation}
For each $1\le k\le d-1$, we have
\begin{align}
\normm{\sum_{i=1}^{k+1} \sigma_i u_{x(v_i)}}^2 &=
\normm{\sum_{i=1}^k \sigma_i u_{x(v_i)}}^2 + \bignorm{u_{x(v_{k+1})}}^2 + 2\sigma_{k+1} \biggl\langle \sum_{i=1}^k \sigma_i u_{x(v_i)}, u_{x(v_{k+1})}\biggr\rangle \cr
&\le \bignorm{u_{x(v_{k+1})}}^2 + 1,
\end{align}
by our choice of $\sigma_{k+1}$, and consequently
\begin{equation}\normm{\sum_{i=1}^d \sigma_i u_{x(v_i)}}^2 \le d.\end{equation}
By assumption, $A$ shatters the mistake tree, so there is a column $y\in Y$ with $A\bigl(x(v_i),y\bigr) = \sigma_i$ for all $1\le i\le d$. Hence
\begin{equation} d = \sum_{i=1}^d A\bigl( x(v_i), y\bigr) \sigma_i
= \biggl\langle \sum_{i=1}^d \sigma_i u_{x(v_i)}, v_y\biggr\rangle
\le \sqrt d \norm{v_y} \le \gamma \sqrt d,\end{equation}
by the Cauchy--Schwarz inequality.
\end{proof}

\section{A weighted Littlestone dimension for real matrices}

Because the inductive step in our eventual proof of \Cref{thmmain} does not preserve the boolean entries of the starting matrix, we must develop a generalization of the Littlestone dimension for real matrices. This we shall do in the present section, proving analogues of Propositions~\ref{propsubset} and~\ref{propldimbound}.

Let $\alpha > 0$ be a parameter. An \emph{$\alpha$-weighted mistake tree} of depth $d$ over a domain $X$ is a complete binary tree of depth $d$ in which
\begin{itemize}\setlength\itemsep{-2pt}
\item[i)] each internal node $v$ is labelled with an element $x(v)\in X$; and
\item[ii)] each edge $e$ is labelled with a real number $w(e)\in \RR$, such that if $e_1$ and $e_2$ are the two edges connecting a vertex $v$ to its children, then $\bigl| w(e_1) - w(e_2)\bigr| \ge \alpha$.
\end{itemize}

We say that $A\in \RR^{X\times Y}$ \emph{shatters} such a weighted mistake tree if for every root-to-leaf path $(v_1,\ldots, v_{d+1})$, there exists a column $y\in Y$ such that $A\bigl( x(v_i), y\bigr) = w(v_i v_{i+1})$ for all $1\le i\le d$. Then we define the \emph{$\alpha$-weighted Littlestone dimension}, denoted $\Ldim_\alpha(A)$, to be the largest $d$ such that there exists an $\alpha$-weighted mistake tree of depth $d$ shattered by $A$.

The following proposition shows that for all real matrices $A$ with small $\Ldim_\alpha(A)$, there is a function $g$ such that the entries in each row $x$ are mostly within $2\alpha$ of $g(x)$, after restricting to a large subset of columns.

\begin{proposition}\label{propalphasubset}
Let $\alpha$ and $\eps$ be positive parameters. Suppose that $A\in \RR^{X\times Y}$ is a matrix with $\Ldim_\alpha(A) = d$
and $\normmax A = M$. There exists a subset $S\subseteq Y$ with 
\begin{equation}|S|\ge |Y| \biggl(\frac{\eps\alpha}{2M}\biggr)^d\end{equation}
and a function $g : X\to [-M,M]$ such that for every $x\in X$,
\begin{equation} \Pr_{y \in Y}\Bigl[\bigl| A(x,y) - g(x)\bigr|\ge 2\alpha \Bigr]\le\eps.\end{equation}
\end{proposition}

\begin{proof}
If for every $x\in X$ there is some $k\in \NN$ with
\begin{equation}\biggl|\Bigl\{ y\in Y : A(x,y) \in \bigl[-M + (k-2)\alpha, -M+ (k+2)\alpha\bigr] \Bigr\}\biggr| \ge (1-\eps)|Y|,\end{equation}
then we can set $g(x) = -M+k\alpha$ and $S=Y$ to prove the assertion. So, assume that there is some $x\in X$ for which such a $k$ does not exist. Letting
\begin{equation} S_i = \Bigl\{ y\in Y : A(x,y) \in \bigl[-M + (i-1)\alpha, -M+ i\alpha\bigr] \Bigr\},\end{equation}
this assumption can be re-expressed as
\begin{equation}|S_{k-1} \cup S_k \cup S_{k+1} \cup S_{k+2}| \le (1-\eps) |Y|\end{equation}
for all $k\in \NN$. 
Since $A(x,y)\in [-M,M]$ for all $y\in Y$, there must exist some $i\in \NN$ with $|S_i| \ge \alpha|Y| / (2M)$.
On the other hand, we know that
\begin{equation}|S_{i-1} \cup S_i \cup S_{i+1} \cup S_{i+2}| \le (1-\eps) |Y|,\end{equation}
so there must be some $j\in \NN$ with $|j-i|\ge 2$ such that
$|S_j| \ge \eps\alpha|Y| / (2M)$. Note that every $y\in S_i$ and $y'\in S_j$ satisfy $\bigl| A(x,y) - A(x,y')\bigr| \ge \alpha$, so we see that
\begin{equation}\Ldim_\alpha(A) \ge 1 + \min \bigl\{ \Ldim_\alpha(A_{X\times S_i}), \Ldim_\alpha(A_{X\times S_j})\bigr\}.\end{equation}
Hence we have $\Ldim_\alpha(A_{X\times S_i})\le d-1$
or $\Ldim_\alpha(A_{X\times S_j})\le d-1$, and may now perform induction on $d$.

When $d=0$, pick any $y_0\in Y$ and let $g(x) = A(x,y_0)$ for all $x\in X$. The fact that $A$ does not shatter any $\alpha$-weighted mistake tree of positive depth tells us that $A(x,y) \in \bigl( g(x) - \alpha, g(x) + \alpha)$ for all $(x,y)\in X\times Y$, and hence we may take $S=Y$. 
\end{proof}

Like the ordinary Littlestone dimension, our $\alpha$-weighted Littlestone dimension is boun\-ded polynomially in terms of the $\gamma_2$-norm (up to a constant factor that depends on $\alpha$).

\begin{proposition}\label{propldimalphabound}
Let $A\in \RR^{X\times Y}$ be a matrix with $\Ldim_\alpha(A) = d$ (for some $\alpha > 0$), $\normgamma A = \gamma$, and $\normmax A = M$. Then
\begin{equation} \gamma \ge \frac{\alpha\sqrt d}{2(M+1)} - 1,\end{equation}
and consequently
\begin{equation} d = O_\alpha(\gamma^4).\end{equation}
\end{proposition}

\begin{proof}
Consider a $\gamma$-factorization $A = UV$, where $U$ has rows $u_x$ indexed by $x\in X$ and $V$ has columns $v_y$ indexed by $y\in Y$. Fix an $\alpha$-weighted mistake tree of depth $d$ shattered by $A$. For each internal node $v$ in the tree with edges $e$ and $e'$ connecting it to its children, we define
\begin{equation}\tilde u(v) = u_{x(v)} \oplus \frac{w(e) + w(e')}{2}\end{equation}
(where, for a vector $u\in \RR^t$ and a real number $\beta$,
$u\oplus \beta$ denotes the vector in $\RR^{t+1}$ obtained by appending $\beta$ to $u$).

As in the proof of \Cref{propldimbound}, we recursively define a root-to-leaf path that supplies our final bound. We let $v_1$ denote the root of the tree and set $\sigma_1 = 1$. For $1\le k\le d$, let $v$ and $v'$ be the two children of $v_k$, where we may assume that $w(v_kv) \ge \alpha + w(v_kv')$ without losing generality. Let
\begin{equation}\sigma_{k+1} = -\sgn \biggl\langle \sum_{i=1}^k \sigma_i \tilde u(v_i), \tilde u(v_{k+1})\biggr\rangle.\end{equation}
If $\sigma_{k+1} = 1$, set
\begin{equation*}v_{i+1} = v\qquad\hbox{and}\qquad v_{i+1}' = v'\end{equation*}
and if $\sigma_{k+1} = -1$, set
\begin{equation*}v_{i+1} = v'\qquad\hbox{and}\qquad v_{i+1}' = v.\end{equation*}
Either way, we have
\begin{equation}
\label{eq:alpha}
\sigma_{k+1} \bigl( w(v_i v_{i+1}) - w(v_i v_{i+1}')\bigr) \ge \alpha.\end{equation}
Note that for all $1\le k \le d-1$,
\begin{align*}
\normm{\sum_{i=1}^{k+1} \sigma_i \tilde u(v_i)}^2 &=
\normm{\sum_{i=1}^k \sigma_i \tilde u(v_i)}^2 + \bignorm{\tilde u(v_i)}^2 + 2\sigma_{k+1} \biggl\langle \sum_{i=1}^k \sigma_i \tilde u(v_i), \tilde u(v_{k+1})\biggr\rangle \cr
&\le \normm{\sum_{i=1}^k \sigma_i \tilde u(v_i)}^2 + \bignorm{\tilde u(v_{k+1})}^2,
\end{align*}
which shows that
\begin{equation}\normm{\sum_{i=1}^k \sigma_i \tilde u(v_i)}^2
\le \sum_{i=1}^d \bignorm{\tilde u(v_i)}^2 \le d(M+1)^2.\end{equation}
On the other hand, since $A$ shatters the tree, there exists a column $y\in Y$ with
\begin{equation}\bigl\langle  u_{x(v_i)} , v_y\bigr\rangle = A\bigl(x(v_i), y\bigr) = w(v_iv_{i+1})\end{equation}
for all $1\le i\le d$. Let $\tilde v = v_y \oplus -1$.
Now by~\eqref{eq:alpha}, we bound  
\begin{align}
\biggl\langle \sum_{i=1}^d \sigma_i u_i, \tilde v\biggr\rangle &= \sum_{i=1}^d \sigma_i \biggl( \bigl\langle u_{x(v_i)}, v_y\bigr\rangle - \frac{w(v_iv_{i+1}) + w(v_iv_{i+1}')}{2}\biggr) \cr
&= \sum_{i=1}^d \sigma_i \biggl(\frac{w(v_iv_{i+1}) - w(v_iv_{i+1}')}{2} \biggr) \cr &\ge \frac{\alpha d}{2}. \cr
\end{align}
By the Cauchy--Schwarz inequality, we see that
\begin{equation} \frac{\alpha d}{2} \le
\normm{\sum_{i=1}^d b_i\tilde u(v_i)}\cdot
\bignorm{\tilde v} \le \sqrt d (M+1) (1+\gamma).
\end{equation}
Hence
\begin{equation}\gamma \ge \frac{\alpha\sqrt d}{2(M+1)} - 1,\end{equation}
and we also have
$d = O(\gamma^4/\alpha^2)$, since $\normmax A \le \normgamma A$.
\end{proof}

\section{Three lemmas}

In this section, we establish three miscellaneous lemmas. We begin with a simple upper bound on the block complexity of an integer matrix in terms of the $\ell_1$ norms of its rows.

\begin{lemma}\label{lemblockcomplexitybound}
If $A\in \ZZ^{X\times Y}$ contains only nonnegative entries, then
\begin{equation}\block(A) \le \max_{x\in X} \sum_{y\in Y} \bigl| A(x,y)\bigr|.\end{equation}
More generally, every $A\in \ZZ^{X\times Y}$ satisfies
\begin{equation}\block(A) \le 2 \max_{x\in X} \sum_{y\in Y} \bigl| A(x,y)\bigr|.\end{equation}
\end{lemma}

\begin{proof}
The second statement follows from the first by splitting a matrix $A$ into $A_+ - A_-$, where both $A_+$ and $A_-$ are nonnegative, and then observing that $\block(A) \le \block(A_+) + \block(A_-)$.

Hence, we may assume that all entries of $A$ are nonnegative.
Let $X'$ be the set of nonzero rows of $A$. For every row $x\in X'$, choose $y(x)\in Y$ such that $A\bigl(x,y(x)\bigr) \ne 0$. The set $\bigl\{ \bigl( x,y(x)\bigr) : x\in X'\bigr\}$ defines a blocky matrix $B\in \{0,1\}^{X\times Y}$. Furthermore, all the entries in $A' = A-B$ are nonnegative, and
\begin{equation}\max_{x\in X} \sum_{y\in Y} A'(x,y) = \max_{x\in X} \sum_{y\in Y} A(x,y) - 1.\end{equation}
This argument may be iterated until $A$ is the zero matrix.
\end{proof}

Next, we prove a simple technical lemma, showing that if some set of bounded vectors has a large average vector $\hat v$, then subtracting $\hat v$ from many of the individual vectors significantly reduces their norms.

\begin{lemma}\label{lemsubtractaverage}
Let $v_1, \ldots, v_r$ be vectors in a Hilbert space, and let $\hat v = \ex_{i\in [r]} v_i$ denote their average. If  $\norm{v_i} \le \gamma$ for all $1\le i\le r$, and $\norm{\hat v} = c$, there exists a subset $S\subseteq [r]$ with $|S| \ge c^2 r / (2\gamma^2)$ such that for every $i\in S$,
\begin{equation}\norm{v_i - \hat v}^2 \le \norm{v_i}^2 - \frac{c^2}{2}.\end{equation}
\end{lemma}

\begin{proof}
Define
\begin{equation}S = \bigl\{ i\in [r] : \norm{v_i-\hat v}^2 \le \norm{v_i}^2 - c^2/2\bigr\},\end{equation}
and observe that
\begin{equation}\ex_{i\in [r]} \norm{v_i - \hat v}^2 = \ex_{i\in [r]} \norm{v_i}^2 - \norm{\hat v}^2 = \ex_{i\in [r]} \norm{v_i}^2 - c^2.\end{equation}
Therefore,
\begin{equation}c^2 = \ex_{i\in[r]}  \norm{v_i}^2 - \norm{v_i - \hat  v}^2  \le \frac{c^2}{2} + \frac{|S|}{r} \gamma^2.\end{equation}
This gives
\begin{equation} \frac{|S|}{r} \ge \frac{c^2}{2\gamma^2},\end{equation}
which is what we wanted.
\end{proof}

For a boolean matrix $A\in \{0,1\}^{X\times Y}$ with $|Y| =n$, the third and final lemma of this section supplies a partition $ Y = \bigcup_{i=1}^k S_i$ such that 
\begin{itemize}\setlength\itemsep{-2pt}
\item[i)] for every $S_i$ there is a row $x_i$ such that $A(x_i,y)=1$ for all $y \in S_i$; and
\item[ii)] for every row $x$ and every $\delta>0$, there are at most $O_\delta(\log n)$ sets $S_i$ with
\begin{equation}\Pr_{y \in S_i}\bigl[A(x,y)=1\bigr] \ge \delta.\end{equation}
\end{itemize}
In fact, we may establish a more general version of this statement for integer-valued matrices.

\begin{lemma}\label{lemfirstpartition}
Let $A\in \ZZ^{X\times Y}$ be an integer matrix with no all-zero columns. There exists a partition $Y = \bigcup_{i=1}^k S_i$, along with rows $x_1,\ldots,x_k\in X$ and nonzero integers $b_1\ldots, b_k\in \ZZ\setminus\{0\}$ such that
\begin{itemize}\setlength\itemsep{-2pt}
\item[i)] for every $1\le i\le k$, we have $A(x_i,y) = b_i$ for all $y\in S_i$; and
\item[ii)] for all $\delta > 0$, every $x\in X$, and every $b\in \ZZ\setminus \{0\}$, the number of indices $1\le i\le k$ for which
\begin{equation}\Pr\bigl[ A(x,y) = b\bigr] \ge \delta\end{equation}
is at most $(\log |Y| + 1)/\delta$.
\end{itemize}
\end{lemma}
\goodbreak

\begin{proof}
% Consider the greedy algorithm presented in \Cref{alg:greedy}. 

% \begin{algorithm}[ht]
% \caption{\label{alg:greedy} 
% Given an integer matrix $A \in \ZZ^{X \times Y}$, the algorithm computes a partition $Y = \bigcup_{i=1}^k S_i$, along with rows $x_1, \dots, x_k \in X$ and nonzero integers $b_1, \dots, b_k \in \ZZ \setminus \{0\}$.}
% \begin{algorithmic}[1]
% \STATE \textbf{Initialize:} Set $R \gets Y$ and $i \gets 1$.
% \WHILE{$R \ne \emptyset$}
%     \STATE \textbf{Greedy selection:} Choose $(x_i, b_i) \in X \times (\ZZ \setminus \{0\})$ that maximizes the size of 
%     \[
%         S_i \gets \{ y \in R : A(x_i, y) = b_i \}.
%     \]
%     \STATE \textbf{Update:} Set $R \gets R \setminus S_i$ and increment $i \gets i + 1$.
% \ENDWHILE
% \end{algorithmic}
% \end{algorithm}
Consider the following greedy algorithm.

\alg{Algorithm S}{Construct sets $S_i$}
Given an integer matrix $A\in \ZZ^{X\times Y}$, this algorithm outputs a partition $Y = \bigcup_{i=1}^k S_i$, as well as rows $x_1,\ldots, x_k$ and nonzero integers $b_1, \ldots, b_k$.
\begin{itemize}\setlength\itemsep{-2pt}
\item[\textbf{S1.}] [Initialize.] Set $R\gets Y$ and $i \gets 1$.
\item[\textbf{S2.}] [Loop.] While $R\ne \emptyset$, repeat steps S3 and S4.
\begin{itemize}
\item[\textbf{S3.}] [Greedy choice.] Choose $(x_i, b_i)\in X\times \bigl( \ZZ \setminus \{0\}\bigr)$ that maximizes the size of
\[S_i = \bigl\{y \in R : A(x_i, y) = b_i\bigr\}.\]
\item[\textbf{S4.}] [Update.] Set $R \gets R\setminus S_i$ and increment $i\gets i+1$.
\end{itemize}
\end{itemize}
\goodbreak

The claim is that the output of Algorithm~S satisfies our two desired properties. It is clear that the sets $S_i$ form a partition of $Y$, and by their definition in step S3, they satisfy property (i).

To prove the second assertion, we assign the cost $c(y) = 1/|S_i|$ to each $y\in S_i$. Let $x\in X$ and $b\in \ZZ\setminus\{0\}$ be arbitrary, and consider the set
\begin{equation*}\{y_1,\ldots, y_t\} = \bigl\{ y\in Y : A(x,y) = b\bigr\},\end{equation*}
which we have ordered such that $c(y_1) \le \cdots \le c(y_t)$.

First we show that for every $1\le i\le t$,
\begin{equation} c(y_i) \le \frac{1}{t-i+1}.\end{equation}
Indeed, suppose that $c(y_i) > 1/(t-i+1)$. Let
$S_r$ be the member of our partition with $y_i\in S_r$, and suppose that $|S_r| = k$, so that $1/k = c(y_i) > 1/(t-i+1)$. The set
$S'= \{y_j \in Y : j\ge i\}$
has size $t-i+1 > k$, and $A(x,y) = b$ for all $y\in S'$, hence by the greedy choice made in step S3, the partition element $S_r$ containing $y_i$ must be at least as large as $S'$, and contain strictly more than $k$ elements. This is a contradiction.

Hence we bound
\begin{equation}\sum_{i=1}^k \Pr_{y\in S_i} \bigl[ A(x,y) = b\bigr] 
= \sum_{i=1}^k \frac{\bigl\{y\in S_i : A(x,y) = b\bigr\}}{|S_i|}
= \sum_{i=1}^t c(y_i) \le \sum_{i=1}^t \frac{1}{i} \le \log|Y| + 1,\end{equation}
and the number of indices $i$ with $\Pr_{y\in S_i} \bigl[ A(x,y) = b\bigr] \ge \delta$ can be at most $(\log|Y| + 1)/\delta$.
\end{proof}

\section{The main argument}

We are now ready to prove our main theorem. Given a matrix $A\in \ZZ^{X\times Y}$ with $\normgamma A \le \gamma$, we wish to express it as a sum of matrices with small block complexity, which in turn gives a bound on the block complexity of $A$. Our strategy shall be to partition the columns $Y$ into subsets $S_i$ using \Cref{lemfirstpartition} and then 
define a new matrix $\tilde A$ by averaging the columns $y$ belonging to each $S_i$. The block complexity of $\tilde A$ can be bounded by invoking \Cref{lemblockcomplexitybound}, and \Cref{lemsubtractaverage} will help us show that $\normgamma{A-\tilde A}^2$ decreases by a constant, making the argument suitable for iteration.

The catch is that subtracting averages takes us outside the realm of integer-valued matrices, so we must consider a slightly wider class of matrices. This motivates the following definition, which is our analogue of the almost integer-valued functions used in~\cite{greensanders}.
Given a matrix $A\in \RR^{X\times Y}$, let $A_\ZZ\in \ZZ^{X\times Y}$ denote the entrywise rounding of $A$ to the nearest integer matrix, where $b+1/2$ is rounded down to $b$ for all $b\in \ZZ$. For any real $\eps > 0$ we say that a real-valued matrix $A\in \RR^{X\times Y}$ is \emph{$\eps$-almost integer-valued} if $\normmax{A-A_\ZZ}\le \eps$.

The following lemma is the heart of our induction, allowing us to decrease the factorization norm.

\begin{lemma}[Key lemma]\label{lemkey}
Let $A\in \RR^{X\times Y}$ be a real-valued matrix with $\normgamma A = \gamma$. Suppose further that $A$ is $\eps$-almost integer-valued for $\eps = 2^{-20\gamma^2}$. If $A_\ZZ$ is not an all-zero matrix, then there exists a $2\eps$-almost integer-valued matrix $A'\in \RR^{X\times Y}$ such that
\begin{equation}\normgamma{A-A'}^2 \le \gamma^2 - \frac{1}{8}\end{equation}
and
\begin{equation}\block(A'_\ZZ) \le 2^{O(\gamma^7)} \bigl(\log |Y|\bigr)^2.\end{equation}
\end{lemma}

\begin{proof}
Let $M = \normmax A$. 
If $A_\ZZ$ is not an all-zero matrix, then $M \ge 1/2$ and we have $\gamma \ge 1/2$ as well. This implies that $\eps \le 2^{-10\gamma} < 1/100$. We fix a $\gamma$-factorization $A = UV$ of $A$, with $\norm{u_x} \le 1$ for all $x\in X$ and $\norm{v_y}\le \gamma$ for all $y\in Y$.

By applying \Cref{lemfirstpartition} to (the nonzero columns of) $A_\ZZ$, we obtain rows $x_1,\ldots,x_k\in X$, integers $b_1,\ldots,b_k\in \ZZ\setminus\{0\}$, and sets $S_1,\ldots,S_k\subseteq Y$
such that for every $1\le i\le k$ and every $y\in S_i$, we have $A_\ZZ(x_i,y) = b_i$. (The second statement of \Cref{lemfirstpartition} will not be used until later, and we defer our choice of $\delta$ until then.)

We now invoke the properties of the $\alpha$-weighted Littlestone dimension. By \Cref{propldimalphabound}, we have $\Ldim_{1/8}(A)\le O(\gamma^4)$, and \textit{a fortiori}, we also have $\Ldim_{1/8}(A_{X\times S_i}) = O(\gamma^4)$ for all $1\le i\le k$. Set $\eps_1 = \eps/(10\gamma)$ and apply \Cref{propalphasubset} to each matrix $A_{X\times S_i}$ with this parameter to obtain subsets $S_i'$ with
\begin{equation} |S_i'| \ge \Bigl( \frac{\eps_1}{\gamma}\Bigr)^{\!O(\gamma^4)}|S_i|
\ge  {\eps_1}^{O(\gamma^5)} |S_i|\end{equation}
and functions $g'_i: X\to [-M,M]$.  Rounding each of these functions $g_i'$ to the nearest integer functions, we obtain functions $g_i : X\to [-M,M] \cap \ZZ$ such that
\begin{equation}\Pr_{y\in S_i'}\bigl[ A_\ZZ(x,y)\ne g_i(x)\bigr] \le
\Pr_{y\in S_i'} \Bigl[ \bigl| A(x,y) - g_i'(x) \bigr| \ge 1/4 \Bigr] \le \eps_1\end{equation} 
for all $1\le i\le k$, where we have applied the fact that $A$ is $\eps$-almost integer-valued for some $0<\eps<1/100$.

For each $i$, let $\hat v_i$ denote the average $\ex_{y\in S_i'} v_y$,
and observe that since $A_\ZZ(x_i, y) = b_i \ne 0$,
\begin{equation}\bigl| \langle u_{x_i}, \hat v_i\rangle \bigr|
= \Bigl| \ex_{y\in S_i'} \langle u_{x_i}, v_y\rangle \Bigr|
= \Bigl| \ex_{y\in S_i'} A(x_i, y)\bigr|
\ge |b_i - \eps| \ge \frac{1}{2},\end{equation}
which in turn gives the bound
$\norm{\hat v_i} \ge 1/2$ by the Cauchy--Schwarz inequality.
We may then apply \Cref{lemsubtractaverage} to obtain subsets $S_i''\subseteq S_i'$ with
\begin{equation}|S_i''| \ge \frac{1}{8\gamma^2} |S_i'|\end{equation}
such that
\begin{equation}\norm{v_y - \hat v_i}^2 \le \norm{v_y}^2 - \frac{1}{8}\le \gamma^2 - \frac{1}{8}\end{equation}
for every $y\in S_i''$.
Let $Y' = \bigcup_{i=1}^k S_i'$ and $\tilde Y = \sum_{i=1}^k S_i''$;
we have
\begin{equation}\label{eqloselog}|\tilde Y| \ge \frac{1}{8\gamma^2} |Y'| \ge {\eps_1}^{O(\gamma^5)} |Y|
\ge 2^{-O(\gamma^7)}|Y|.\end{equation}
We now define a matrix $\tilde A \in \RR^{X\times \tilde Y}$ by setting
$\tilde v_y = v_y - \hat v_i$, so that we have $\norm{\tilde v_y}^2 \le \gamma^2 - 1/8$, and
\begin{equation} \tilde A(x,y) = \ex_{y'\in S_i'} A(x,y') = \langle u_x, \hat v_i\rangle\end{equation}
for every $x\in X$ and $y\in S_i''$.
(Notice that the average is taken over $S_i'$ and not $S_i''$.)
Then for every pair $(x,y)\in X\times S_i''$, we have
\begin{equation}A(x,y) - \tilde A(x,y) = \langle u_x, v_y - \hat v_i\rangle = \langle u_x, \tilde v_y\rangle.\end{equation}

Next, we show that $\tilde A$ is $2\eps$-almost integer-valued and we bound its block complexity. For every $x\in X$, the fact that $A$ is $\eps$-almost integer-valued, combined with our earlier bound $\Pr_{y\in S_i'}\bigl[ A_\ZZ(x,y)\ne g_i(x)\bigr] \le \eps_1$, shows that
\begin{equation}\bigl| \tilde A(x,y) - g_i(x)\bigr|
= \Bigl|\ex_{y'\in S_i'} A(x,y') - g_i(x) \Bigr|\le (1-\eps_1)\eps + \eps_1 (2M+\eps) = \eps + 2\gamma\eps_1\le  2\eps;\end{equation}
that is, $\tilde A$ is a $2\eps$-almost integer-valued matrix, and $\tilde A_\ZZ(x,y) = g_i(x)$ for all $(x,y)\in X\times S_i''$. Define the matrix $G\in \ZZ^{X\times [k]}$ by $G(x,i) = g_i(x)$. Since $\tilde A_\ZZ$ is obtained from $G$ by creating $|S_i''|$ copies of each column $i$, we have $\block(\tilde A_\ZZ) = \block(G)$. Consider a fixed $x\in X$ and integer $b\ne 0$. If $g_i(x) = b$, then since $\Pr_{y\in S_i'}\bigl[ A_\ZZ(x,y) = b\bigr] \ge 1-\eps_1$, we have
\begin{equation}\Pr_{y\in S_i}\bigl[ A_\ZZ(x,y) = b\bigr] \ge   (1-\eps_1)\frac{|S_i'|}{|S_i|} \ge (1-\eps_1){\eps_1}^{O(\gamma^5)}\ge 2^{-O(\gamma^7)}.\end{equation}
Now is the time to apply the second assertion of \Cref{lemfirstpartition}, with $\delta = 2^{-O(\gamma^7)}$. It tells us that there are at most $\bigl(\log|Y| + 1\bigr)/\delta = 2^{O(\gamma^7)} \log |Y|$ such indices $i$ with $\Pr_{y\in S_i} \bigl[A_\ZZ(x,y) = b\bigr]$. In other words, for any $x\in X$, each of the nonzero integers in the range $[-M,M]$ appears in the sum $\sum_{i=1}^k \bigl|g_i(x)\bigr|$ no more than $2^{O(\gamma^7)}\log|Y|$ times. There are no more than $2M$ nonzero integers in this range, and we have
\begin{equation}\sum_{i=1}^k \bigl|g_i(x)\bigr| \le 2M^2 \cdot 2^{O(\gamma^7)} \log|Y| = 2^{O(\gamma^7)}\log|Y|.\end{equation}
By \Cref{lemblockcomplexitybound}, we see that
\begin{equation}\label{eqtildeblockbound}\block(\tilde A_\ZZ) = \block(G) \le 2\max_{x\in X} \sum_{i=1}^k \bigl|g_i(x)\bigr| \le 2^{O(\gamma^7)}\log|Y|.\end{equation}

The key observation at this juncture is that, moving from $A$ to $\tilde A$ in the argument above, we have not changed the vectors $u_x$ for $x\in X$. This allows us to repeatedly apply what we derived above and concatenate all the matrices $\tilde A$ into a single matrix $A'\in \RR^{X\times Y}$ with $\normgamma{A-A'}^2\le \gamma^2 - 1/8$.

In this spirit, starting with $Y_0 = Y$ and $\tilde Y_0 = \emptyset$, we construct a partition $Y = \bigcup_{i=1}^t \tilde Y_i$ and matrices $\tilde A_i \in \RR^{X\times \tilde Y_i}$ by repeatedly applying the argument above to the decreasing sequence $Y_i = Y\setminus \bigcup_{j=0}^{i-1} \tilde Y_j$. Since $|Y_i| \le \bigl( 1-2^{-O(\gamma^7)}\bigr) |Y_{i-1}|$, this process stops after $t \le 2^{O(\gamma^7)} \log |Y|$ steps.

Let $A'\in \RR^{X\times Y}$ be the matrix with $A'_{X\times \tilde Y_i} = \tilde A_i$ for all $1\le i\le t$. We have
\begin{equation}\block(A'_\ZZ) \le \sum_{i=1}^t \block\bigl( (\tilde A_i)_\ZZ\bigr) \le t\cdot 2^{O(\gamma^7)} \log |Y| = 2^{O(\gamma^7)} \bigl(\log|Y|\bigr)^2.\end{equation}
By construction, the difference $A-A'$ may be factorized $A-A' = UV'$ where every column $v'_y$ in $V'$ satisfies $\norm{v'_y}^2\le \gamma^2-1/8$, so $\normgamma{A-A'}^2 \le \gamma^2 - 1/8$.
\end{proof}

Note that after proving the inequality~\eqref{eqtildeblockbound} in the proof above, one is already able to write
\begin{equation}\block(A_\ZZ) \le 2^{O(\gamma^7)}\log|Y|  + 
\block\bigl( (A_{X\times\tilde Y} - \tilde A)_\ZZ\bigr) + \block\bigl( (A_{X\times Y\setminus\tilde Y})_\ZZ\bigr),\end{equation}
where $\bignormgamma{A_{X\times\tilde Y} - \tilde A}^2 \le \gamma^2 - 1/8$ and $|Y\setminus \tilde Y| \le \bigl(1-2^{-O(\gamma^7)}\bigr)n$. We leave it to the reader to perform induction on this inequality and obtain the bound
\[\block(A)\le 2^{O(\gamma^7)}\bigl(\log|Y|\bigr)^{O(\gamma^7)}\]
on the block complexity of a matrix $A$ with bounded $\gamma_2$ norm. While already polylogarithmic, this is significantly worse than the promised bound of \Cref{thmmain}, and we must use the observation that the rows remain unchanged to get an absolute constant in the exponent of $\log|Y|$.

Our main theorem now follows by iterating \Cref{lemkey}. In fact, we prove the following more general statement for almost integer-valued matrices.

\begin{theorem}[Generalized main theorem]\label{thmgeneralmain}
For every finite $\eps$-almost integer-valued matrix $A\in \RR^{X\times Y}$ with $\normgamma A\le \gamma$ and $\eps= 2^{-20\gamma^2}$, the block complexity of $A_\ZZ$ satisfies
\begin{equation}\block(A_\ZZ) \le 2^{O(\gamma^7)} \bigl(\log|Y|\bigr)^2.\end{equation}
\end{theorem}

\begin{proof} The proof is by induction on $\gamma$. If $\gamma < 1/2$, then as observed earlier, we have $\normmax A<1/2$ and $A_\ZZ$ is an all-zero matrix, which has block complexity zero.
Otherwise, by \Cref{lemkey}, there is a $2\eps$-almost integer-valued matrix $A'\in \RR^{X\times Y}$ with
\begin{equation}\normgamma{A-A'}^2 \le \gamma^2 - \frac{1}{8}\end{equation}
and
\begin{equation}\block(A'_\ZZ) \le 2^{C'\gamma^7} \bigl(\log |Y|\bigr)^2\end{equation}
for some absolute constant $C'$. Set $C= \max\{100C', 8^{7/2}\}$. 
The matrix $A-A'$ is $3\eps$-almost integer-valued and
\begin{equation}3\eps \le 3\cdot 2^{-20\gamma^2} \le 2^{-20(\gamma^2 - 1/8)},\end{equation}
so the induction hypothesis provides the bound
\begin{equation}\block\bigl( (A-A')_\ZZ\bigr) \le 2^{C(\gamma^2 - 1/8)^{7/2}}\bigl(\log|Y|\bigr)^2.\end{equation}
This yields
\begin{align}\block(A_\ZZ) &\le \block(A'_\ZZ) + \block\bigl( (A-A')_\ZZ\bigr) \cr
&\le \bigl(2^{C'\gamma^7} + 2^{C(\gamma^2 - 1/8)^{7/2}}\bigr) \bigl(\log |Y|\bigr)^2\cr
&\le  \bigl(2^{C(\gamma^2 - 1/8)^{7/2} + 1}\bigr)\bigl(\log |Y|\bigr)^2\cr
&\le2^{C\gamma^7} \bigl(\log|Y|\bigr)^2,\cr
\end{align}
where our assumption that $\gamma \ge 1/2$ implies
that $C \ge  C'\gamma^7/(\gamma^2-1/8)^{7/2}$.
\end{proof}

\paragraph{Concluding remarks.}\hskip-0.3em
There are two places in which we lose a logarithmic factor, resulting in the factor of $\bigl(\log|Y|\bigr)^2$ in our final theorem. The first is in \Cref{lemfirstpartition}, when we bound the number of indices by $\bigl(\log|Y|+1\bigr)/\delta$, and the second is in~\eqref{eqloselog}, where one discards a constant fraction of the columns. Tightening these bounds (especially the second) appears out of reach of our current methods; we suspect that novel ideas will be necessary to prove \Cref{conjblocky}. 

On the other hand, our polylogarithmic bound is already strong, requiring the full power of our hypothesis on $\eps$. Indeed, M.~G\"o\"os, N.~Harms, and A~Riazanov recently proved~\cite{ghr2025} that for every $\eps > 0$, there exists an $n\times n$ boolean matrix $M$ and a real $\eps$-approximation $\tilde M$ of $M$ such that $\normgamma{\tilde M} \le O_\eps(1)$, while $\norm{M}_{\gamma_2} \ge 2^{\Omega_\eps\bigl(\sqrt{\log n}\bigr)}$ and hence $\block(M) \ge 2^{\Omega_\eps\bigl(\sqrt{\log n}\bigr)}$.

\Cref{thmmain} implies that $\mathrm{D}^{\hbox{\textsc{eq}}}(A)\le 2^{O(\gamma^7)} \log (n)^2$, where $\mathrm{D}^{\hbox{\textsc{eq}}}(A)$ denotes the communication complexity of $A$ with access to an equality oracle (see~\cite[Proposition 3.1]{hhh2023}). Hence any sequence $A_n$ of matrices with $\normgamma{A_n} = O(1)$ is in the complexity class $\mathrm{P}^{\hbox{\textsc{eq}}}$.

\paragraph{Related work.}\hskip-0.3em
A recent paper of I.~Balla, L.~Hambardzumyan, and I.~Tomon approaches \Cref{conjblocky} from a different angle. To state their result, we introduce the following definition.
A \emph{monochromatic rectangle} in an integer matrix $A$ is the product of a subset $S$ of rows
and a subset $T$ of columns such that the entries $A(i,j)$ are all the same
for $(i,j)\in S\times T$.
We shall call a monochromatic rectangle all of whose entries are $b$ a \emph{$b$-rectangle}.

\begin{theorem}[{\rm\cite{bht2025}}, Theorem 1\/]\label{thmbht}
Suppose that $A$ is an $m\times n$ boolean matrix with
$\normgamma A\le \gamma$. There is a monochromatic rectangle $S\times T$ in $A$, where $S\subseteq [m]$ and $T\subseteq [n]$ satisfy
\begin{equation}\frac{|S|\cdot|T|}{mn} \ge 2^{-O(\gamma^3)}.\end{equation}
In particular, if more than half of $A$'s entries are $1$, then $S\times T$ is a $1$-rectangle, and otherwise it is a $0$-rectangle.
\end{theorem}

A proof that \Cref{thmbht} would follow from \Cref{conjblocky} is presented as \cite[Lemma~3.5]{hhh2023}.
A subsequent paper of the authors uses \Cref{thmbht} to show that that for any matrix $A$ with bounded $\gamma_2$ norm, one can find a large blocky matrix containing a constant fraction of the $1$-entries in $A$.

\begin{theorem}[{\rm\cite{blockysubset2025}}, Theorem 1.4\/]
Let $A$ be an $m\times n$ boolean matrix $A$ with $\normgamma A\le \gamma$ in which the number of $1$-entries is $F$. There exists an $m\times n$ blocky matrix $B$ containing at least $F/2^{2^{O(\gamma)}}$ $1$-entries, such that for all $(i,j)\in [m]\times [n]$, we have $B(i,j) = 1$ only if $A(i,j) = 1$. 
\end{theorem}

