\subsection{Completeness for $L_0$}

Let $L_0$ be the language model corresponding to push-pop canonicalization and filtering invalid traces. That is, $L_0(-) = \filter(\pushpop{L(-)})$. To abbreviate notation, let us write $\push{a} \in \Sigma$ simply as $a$, and $\pop{a} \in \Sigma$ as $\bar{a}$.
In this section, we show that the axioms of KA, augmented with the equations $a\bar{a}=1$ and $a\bar{b}=0$ for $a\ne b$ are complete for the equational theory of $L_0$, i.e., $L_0(e_1) = L_0(e_2)$ if $e_1 = e_2$ can be proved from these. % (Theorem \ref{thm:completenessL0}).
%that is, for any expressions $e_1,e_2$, $L_0(e_1)=L_0(e_2)$ iff $e_1=e_2$ is a deductive consequence of the axioms.
%Here and for the rest of this section, ``deductive consequence'' refers to provability in ordinary equational logic from the axioms of KA and the equations $a\bar a=1$ and $a\bar b=0$ for $b\ne a$, $a,b\in\Sigma$.

%Recall that $R:\Exp\to\AAA$ is the standard interpretation of regular expressions over the alphabet $\Sigma\cup\bar\Sigma$ and $L_0:\Exp\to\BB$ with $L_0 = \NF\circ R$. Thus $L_0$ maps $e$ to the set of strings obtained by reducing strings in $L(e)$ to normal form under the rewrite rules $a\bar a\to 1$ and $a\bar b\to 0$, $b\ne a$, discarding those that become $0$.

\smallskip
Recall that the push-pop fragment of \stackat\ is formed by regular expressions over $\Sigma$.
Let $(E,D)$ be the usual Brzozowski derivative on regular expressions~\cite{Brzozowski1964}.
Let $D'$ be like $D$, except it removes symbols from the right instead of the left.
The following two versions of the fundamental theorem for regular expressions can be proved from the laws of KA alone:~\cite{Silva2010}:
\begin{align}
& e = E(e) + \sum_{a\in\Sigma} aD_a(e)
&& e = E(e) + \sum_{a\in\Sigma} D'_a(e)a\label{eq:fundthmZ}
\end{align}
We can straightforwardly extend $D$ and $D'$ to words: for $x\in\Sigma^*$ and $a\in\Sigma$, we define
\begin{align*}
& D_\eps(e) = e
&& D_{xa}(e) = D_{a}(D_{x}(e))
&& D'_\eps(e) = e
&& D'_{xa}(e) = D'_{a}(D'_{x}(e)).
\end{align*}
%Then
%\begin{align*}
%& D_{xy}(e) = D_{y}(D_{x}(e)) && D'_{xy}(e) = D'_{y}(D'_{x}(e)).
%\end{align*}
There are only finitely many derivatives $D_{x}(e)$ and $D'_{x}(e)$ up to KA equivalence~\cite{Brzozowski1964}.
%We will apply $(E,D)$ and $(E,D')$ to both pure push and pure pop expressions below.

A \emph{pure push} (respectively, \emph{pure pop}) \emph{expression} is a regular expression over letters of the form $a \in \Sigma$ (respectively, $\bar{a} \in \Sigma$).
The expressions $1$ and $0$ are both pure pop and pure push expressions.

\begin{theoremEnd}[default]{lemma}%
\label{lem:sumpushpop}
Every expression $e_1\bar e_2$, where $e_1$ is a pure push expression and $\bar e_2$ a pure pop expression, can be provably transformed to a finite sum of pure push expressions of the form $D'_{xa}(e_1)a$, pure pop expressions of the form $\bar aD_{xa}(\bar e_2)$, or $1$, where $x\in\Sigma^*$ and $a\in\Sigma$.
\end{theoremEnd}
\begin{proofEnd}
We use the fundamental theorem \eqref{eq:fundthmZ} with $D$ applied to $e_1$ and $D'$ applied to $\bar{e}_2$: % chktex 2
\begin{align*}
e_1 &= E(e_1) + \sum_{a\in \Sigma} D'_a(e_1)a & \bar e_2 &= E(\bar e_2) + \sum_{a\in \Sigma} \bar aD_{a}(\bar e_2).
\end{align*}
We have
\begin{align*}
e_1\bar e_2 &= \Big(E(e_1) + \sum_{a\in \Sigma} D'_a(e_1)a\Big)\Big(E(\bar e_2) + \sum_{b\in \Sigma} \bar b D_b(\bar e_2)\Big)\\
&= E(e_1)E(\bar e_2) + E(\bar e_2)\sum_{a\in \Sigma} D'_a(e_1)a + E(e_1)\sum_{b\in \Sigma} \bar b D_b(\bar e_2) + \Big(\sum_{a\in \Sigma} D'_a(e_1)a\Big)\Big(\sum_{b\in\Sigma}\bar bD_b(\bar e_2)\Big) \\
&= E(e_1)\bar e_2 + E(\bar e_2)e_1 + \sum_{a\in \Sigma} D'_a(e_1)D_a(\bar e_2).
\end{align*}
In the last step, we have simplified the summation by applying the axioms $\push{a}\pop{a} = 1$ and $\push{a}\pop{b} = 0$ when $a\neq b$.
The same analysis applies to $D'_x(e_1)D_x(\bar e_2)$, giving
\begin{align*}
D'_x(e_1)D_x(\bar e_2) &= E(D'_x(e_1))D_x(\bar e_2) + E(D_x(\bar e_2))D'_x(e_1) + \sum_a D'_{xa}(e_1)D_{xa}(\bar e_2)
\end{align*}
for $x\in\Sigma^*$, or more succinctly,
\begin{align}
\alpha_x &= \phi_x + \sum_a \alpha_{xa}\label{eq:alpha}
\end{align}
for $x\in\Sigma^*$, where
\begin{align*}
\alpha_x &= D'_x(e_1)D_x(\bar e_2) & \phi_x = E(D'_x(e_1))D_x(\bar e_2) + E(D_x(\bar e_2))D'_x(e_1).
\end{align*}
There are actually only finitely many equations \eqref{eq:alpha}, as there are only finitely many derivatives of $e_1$ and $\bar e_2$ up to associativity, commutativity, and idempotence (ACI)~\cite{Brzozowski1964}. This gives rise to a finite linear system % chktex 2
\begin{align}
X_x &= \phi_x + \sum_a X_{xa},\ x\in S\label{eq:system}
\end{align}
where $S\subs\Sigma^*$ is a finite index set large enough that all equations \eqref{eq:alpha} are represented. Then \eqref{eq:system} can be reformulated as a matrix-vector equation $X = \phi + AX$, where $A$ is an $S\times S$ matrix over $\{0,1\}$ and $\phi$ is a vector of sums of pure push or pure pop expressions $\phi_x$. The equations \eqref{eq:alpha} say that $\alpha = \phi + A\alpha$, which says that $X = \alpha$ is a solution of \eqref{eq:system}. % chktex 2

Now let $\psi$ be the vector with
\begin{align*}
\psi_x &= \sum_{y\in\Sigma^*}\phi_{xy},\ x\in S.
\end{align*}
These are essentially finite sums, again because there are only finitely many derivatives up to ACI\@. We claim that the resulting finite vector $\psi$ is also a solution to \eqref{eq:system}, and is in fact the least solution. To see that it is a solution, % chktex 2
\begin{align*}
\psi_x &= \sum_y \phi_{xy}
= \phi_x + \sum_{a} \sum_{y} \phi_{xay}
= \phi_x + \sum_a \psi_{xa}.
\end{align*}
It is also the least, since one can show by induction that for any other solution $X$ and any $x$, $\phi_{xy} \le X_x$ for all $y$:
\begin{align*}
\phi_x &\le \phi_x + \sum_a X_{xa} = X_x
&
\phi_{xay} &\le X_{xa}
\le \phi_x + \sum_a X_{xa} = X_x.
\end{align*}
By Kleene algebra~\cite{Kozen1994}, the least solution $\psi$ can be calculated efficiently as $\psi = A^*\phi$, which is a vector of sums of pure push and pure pop expressions.

Let
\begin{align*}
\psi(e_1\bar e_2) &= \psi_\eps = \sum_{x\in\Sigma^*} E(D'_x(e_1))D_x(\bar e_2) + E(D_x(\bar e_2))D'_x(e_1).
\end{align*}
Since $\alpha$ is a solution of \eqref{eq:system}, we know that $\psi(e_1\bar e_2)\le\alpha_\eps=e_1\bar e_2$. % chktex 2
We claim also that $e_1\bar e_2\le\psi(e_1\bar e_2)$. This will follow from several sublemmas.
\begin{lemma}%
\label{lemma:psi-monotone}
If $f_1 \leq g_1$ and $\bar f_2 \leq \bar g_2$, then $\psi(f_1 \bar f_2) \leq \psi(g_1 \bar g_2)$.
\end{lemma}
\begin{proof}
Using monotonicity of the derivatives,
\begin{align*}
\psi(f_1\bar f_2)
&= \sum_{x\in\Sigma^*} E(D'_x(f_1))D_x(\bar f_2) + E(D_x(\bar f_2))D'_x(f_1)\\
&\le \sum_{x\in\Sigma^*} E(D'_x(g_1))D_x(\bar g_2) + E(D_x(\bar g_2))D'_x(g_1)
= \psi(g_1\bar g_2).
\tag*\qedhere
\end{align*}
\end{proof}

\begin{lemma}%
\label{lemma:insert-left-base}
$a\psi(e_1 \bar e_2) \leq \psi(a e_1 \bar e_2)$.
\end{lemma}
\begin{proof}
We wish to show
\begin{align*}
\sum_{x\in\Sigma^*} E(D'_x(e_1))aD_x(\bar e_2) + E(D_x(\bar e_2))aD'_x(e_1)
\le \sum_{x\in\Sigma^*} E(D'_x(ae_1))D_x(\bar e_2) + E(D_x(\bar e_2))D'_x(ae_1).
\end{align*}
It suffices to show the two inequalities
\begin{align*}
aD'_x(e_1) &\le D'_x(ae_1) &
E(D'_x(e_1))aD_x(\bar e_2)
&\le E(D'_{xa}(ae_1))D_{xa}(\bar e_2) + E(D_x(\bar e_2))D'_x(ae_1).
\end{align*}
The proof of the left-hand inequality is by induction on $x$. The basis is $aD'_\eps(e_1) = ae_1 = D'_\eps(ae_1)$. For the induction step,
\begin{align*}
aD'_{xb}(e_1)
&= aD'_{b}(D'_{x}(e_1))
\le D'_{b}(aD'_{x}(e_1))
\le D'_{b}(D'_{x}(ae_1))
= D'_{xb}(ae_1).
\end{align*}
For the right-hand inequality, if $E(D'_x(e_1))=0$, we are done. Otherwise, $E(D'_x(e_1))=1$, thus $x^R\in e_1$, thus $(xa)^R = ax^R\in ae_1$, thus also $E(D'_{xa}(ae_1))=1$ and $a\le D'_x(ae_1)$. We now must show
\begin{align*}
aD_x(\bar e_2)
&\le D_{xa}(\bar e_2) + E(D_x(\bar e_2))D'_x(ae_1).
\end{align*}
Using the fundamental theorem,
\begin{align*}
aD_x(\bar e_2)
&= a(E(D_x(\bar e_2)) + \sum_b \bar b D_{xb}(\bar e_2))
= E(D_x(\bar e_2))a + D_{xa}(\bar e_2)\\
&\le E(D_x(\bar e_2))D'_x(ae_1) + D_{xa}(\bar e_2).
\tag*\qedhere
\end{align*}
\end{proof}

\begin{lemma}%
\label{lemma:insert-left}
For all pure push expressions $e_1$ and $d$ and all pure pop expressions $\bar e_2$, it is provable that $d \psi(e_1 \bar e_2) \leq \psi(de_1 \bar e_2)$.
\end{lemma}
\begin{proof}
We proceed by induction on $d$. For the basis, the cases $\{0,1\}$ are trivial, and the case $a \in \Sigma$ follows from Lemma~\ref{lemma:insert-left-base}. For the inductive case $d_1 + d_2$,
    \begin{align*}
    (d_1 + d_2)\psi(e_1 \bar e_2)
        &= d_1\psi(e_1 \bar e_2) + d_2\psi(e_1 \bar e_2) \\
        &\leq \psi(d_1e_1 \bar e_2) + \psi(d_2e_1 \bar e_2) && \text{induction hypothesis}\\
        &\leq \psi((d_1 + d_2)e_1 \bar e_2) && \text{\Cref{lemma:psi-monotone}.}
    \end{align*}

The case $d_1d_2$ follows from two applications of the induction hypothesis:
    \begin{align*}
    d_1d_2\psi(e_1 \bar e_2)
        \leq d_1\psi(d_2e_1 \bar e_2)
        \leq \psi(d_1d_2e_1\bar e_2).
    \end{align*}

Finally, for the case $d^*$,
    \begin{align*}
    \psi(e_1 \bar e_2) + d\psi(d^*e_1 \bar e_2)
        &\leq \psi(e_1 \bar e_2) + \psi(dd^* e_1 \bar e_2) && \text{induction hypothesis}\\
        &\leq \psi(d^* e_1 \bar e_2)  && \text{\Cref{lemma:psi-monotone}.}
    \end{align*}
    By an axiom of Kleene algebra, $d^* \psi(e_1 \bar e_2) \leq \psi(d^*e_1 \bar e_2)$.
\end{proof}

\begin{lemma}%
\label{lemma:insert-right}
For all pure push expressions $e_1$ and all pure pop expressions $\bar e_2$ and $\bar d$, it is provable that $\psi(e_1 \bar e_2) \bar d \leq \psi(e_1 \bar e_2 \bar d)$.
\end{lemma}
\begin{proof}
By symmetric arguments to \Cref{lemma:insert-left}.
\end{proof}

\begin{lemma}
For all pure push expressions $e_1$ and all pure pop expressions $\bar e_2$, $e_1 \bar e_2 \leq \psi(e_1 \bar e_2)$.
\end{lemma}
\begin{proof}
Using \Cref{lemma:insert-left,lemma:insert-right} and the fact that $1\leq\psi(1)$,
$e_1\bar e_2 \leq e_1\psi(1)\bar e_2 \leq \psi(e_1 \bar e_2)$.
\end{proof}

We have shown that
\begin{align*}
e_1\bar e_2 &= \sum_{x\in\Sigma^*} E(D'_x(e_1))D_x(\bar e_2) + E(D_x(\bar e_2))D'_x(e_1).
\end{align*}
To obtain the form as specified in the statement of the lemma (Lemma~\ref{lem:sumpushpop}), we can simply write
$D_x(\bar e_2)$ as $E(D_x(\bar e_2)) + \sum_a \bar aD_{xa}(\bar e_2)$ and
$D'_x(e_1)$ as $E(D'_x(e_1)) + \sum_a D_{xa}(e_1)a$ using the fundamental theorem \eqref{eq:fundthmZ}. % chktex 2
\end{proofEnd}

An expression is in \emph{normal form} if it is a sum of expressions of the form $\bar e_1e_2$, where $\bar e_1$ is a pure pop expression and $e_2$ is a pure push expression. Note that $L(e)=L_0(e)$ if $e$ is in normal form.

\begin{theoremEnd}[default]{theorem}%
\label{thm:normalform}
Every expression can be provably transformed to normal form.
\end{theoremEnd}
\begin{proofEnd}
By induction. For the basis, $a$, $\bar a$, $1$, and $0$ are all in normal form.
For $+$, we transform both terms of the sum individually to normal form; clearly, normal forms are preserved by sums.

For a product of expressions with each factor already in normal form, we multiply out the sums using distributivity.
This gives us a big sum of expressions of the form $\bar{e}_1e_2\bar{e}_1'e_2'$, with $\bar{e}_1$ and $\bar{e}_1'$ pure pop expressions, while $\bar{e}_2$ and $\bar{e}_2'$ are pure push expressions.
It now suffices to show how to transform $\bar{e}_1e_2\bar{e}_1'e_2'$ into normal form.
We do this using \Cref{lem:sumpushpop}, which tells us that the inner expression $e_2\bar{e}_1'$ can be written as $\bar{d}_1 + d_2$, with $\bar{d}_1$ a pure pop expression, and $d_2$ a pure push expression.
This lets us achieve the desired normal form, by deriving as follows:
\begin{align*}
\bar e_1e_2\bar e_1'e_2' = \bar e_1(e_2\bar e_1')e_2' = \bar e_1(\bar d_1 + d_2)e_2' = \bar e_1\bar d_1e_2' + \bar e_1d_2e_2'.
\end{align*}

Finally, consider $e^*$, where $e = \bar b_1c_1 + \cdots + \bar b_n c_n$ has already been transformed to normal form.
Let $[\bar b]$ be the vector whose $i$th component is $\bar b_i$ and let $[c]$ be the vector whose $i$th component is $c_i$.
Then $e = [\bar b]^T[c]$, where $^T$ denotes matrix transpose.
Using basic Kleene algebra, we then derive:
\begin{align}
\Big(\sum_i \bar b_i c_i\Big)^* &= ([\bar b]^T[c])^*
= 1 + [\bar b]^T[c]([\bar b]^T[c])^*
= 1 + [\bar b]^T([c][\bar b]^T)^*[c]
= 1 + [\bar b]^T A^*[c],\label{eq:Amatrix}
\end{align}
where $A = [c][\bar b]^T$ is an $n\times n$ matrix with $A_{ij}=c_i\bar b_j$.
By applying \Cref{lem:sumpushpop} to the terms in $A$, we can express this matrix as $B_0 + C_0$, where $(B_0)_{ij}$ contains only pure push terms $D'_{xa}(c_i)a$ (in general different terms for different $j$) or $1$ and $(C_0)_{ij}$ contains only pure pop terms $\bar aD_{xa}(\bar b_j)$ or $1$.

Now consider $B_0C_0$.
Each entry $(B_0C_0)_{ij}$ is a sum of terms of the form either $D'_{xa}(c_i)a$, $\bar aD_{xa}(\bar b_j)$, $D'_{xa}(c_i)a\bar cD_{xc}(\bar b_j)$ or $1$. We can delete $D'_{xa}(c_i)a\bar cD_{xc}(c_j)$ when $a\ne c$.
If $a=c$, we can replace $D'_{xa}(c_i)a\bar aD_{xa}(\bar b_j)$ by $D'_{xa}(c_i)D_{xa}(\bar b_j)$, then replace this by a sum of pure push and pure pop terms according to Lemma~\ref{lem:sumpushpop}.
The new terms will still be of the form $D'_{xa}(c_i)a$ or $\bar aD_{xa}(\bar b_j)$. We add these new terms to $B_0$ and $C_0$ to obtain matrices $B_1$ and $C_1$ respectively.
Then $B_1 + C_1 = B_0 + C_0 + B_0C_0$.

We continue this process, getting $B_0\le B_1\le B_2\le\cdots$ and $C_0\le C_1\le C_2\le\cdots$ as long as there are new terms. Eventually we do not get any new terms because there are only finitely many derivatives up to ACI\@. At that point $B_{n+1}=B_n$ and $C_{n+1}=C_n$, and $B_n C_n\le B_{n+1}+C_{n+1} = B_n+C_n$.

We claim at this point that the original $A$ of \eqref{eq:Amatrix} satisfies % chktex 2
\begin{align*}
A^* &= (B_n + C_n)^* = C_n^*B_n^*,
\end{align*}
where the right-hand side is of the desired form.
For the left-hand equality, surely $A^* = (B_0 + C_0)^* \le (B_n + C_n)^*$, and by induction, $B_{i+1}+C_{i+1} = B_i + C_i + B_i C_i\le A^* + A^* + A^*A^* = A^*$, so $(B_n+C_n)^*\le A^{**} = A^*$. For the right-hand equality, it is clear that $C_n^*B_n^* \le (B_n + C_n)^*$, so it remains to show that $(B_n + C_n)^* \le C_n^*B_n^*$. Since $B_n C_n \le B_n + C_n$, we have
\begin{align*}
B_n + (B_n + C_n^*)C_n = B_n + B_n C_n + C_n^*C_n \le B_n + B_n + C_n + C_n^* \le B_n + C_n^*.
\end{align*}
Applying the left-hand fixpoint rule $b + xa \le x\ \Imp\ ba^* \le x$ of KA with $b = B_n$, $a = C_n$, and $x = B_n + C_n^*$, we have that $B_n C_n^*\le B_n + C_n^*$. Then
\begin{align*}
1 + (B_n + C_n)C_n^*B_n^* &= 1 + B_n C_n^*B_n^* + C_n C_n^*B_n^* \le 1 + (B_n + C_n^*)B_n^* + C_n C_n^*B_n^* \le C_n^*B_n^*.
\end{align*}
Now applying the right-hand fixpoint rule $b + ax \le x\ \Imp\ a^*b \le x$ of KA with $a = B_n + C_n$, $b=1$, and $x = C_n^*B_n^*$, we conclude that $(B_n + C_n)^* \le C_n^*B_n^*$.
\end{proofEnd}

We now have everything we need to state our completeness result for $L_0$.

\begin{theorem}%
\label{thm:completenessL0}
The axioms of KA augmented with the equations $a\bar a=1$ and $a\bar b=0$ for $b\ne a$ are sound and complete for the equational theory of the interpretation $L_0$; that is, for any $e_1,e_2\in\Exp$, $L_0(e_1)=L_0(e_2)$ iff $e_1=e_2$ is a deductive consequence of these axioms.
\end{theorem}
\begin{proof}
Soundness of the axioms is routine; thus if $e_1=e_2$ is provable, then $L_0(e_1)=L_0(e_2)$.
Conversely, suppose $L_0(e_1)=L_0(e_2)$.
Using \Cref{thm:normalform}, we can provably transform $e_1$ and $e_2$ to normal forms $e_1'$ and $e_2'$, respectively.
By soundness, $L_0(e_1')=L_0(e_2')$, and since $L_0(e)=L(e)$ for any $e$ in normal form (by \Cref{lem:sumpushpop}), $L(e_1')=L(e_2')$.
By the completeness of KA w.r.t. $L$~\cite{Kozen1994}, $e_1'=e_2'$ is provable.
In conjunction with the proofs of $e_1=e_1'$ and $e_2=e_2'$, we obtain a proof of $e_1=e_2$.
\end{proof}

\subsection{Completeness for \stackat}

We now turn our attention to proving completeness for the push-pop fragment of \StacKAT with respect to $\bar{L}$.
We continue to assume the axioms for $L_0$, namely the axioms of KA in addition to the equations $a\bar a=1$ and $a\bar b=0$ for $b\ne a$, but $\bar{L}$ (and therefore $\Sem{-}$) also satisfy an additional property:

\begin{theoremEnd}[default]{lemma}%
\label{lem:L0L1}
The axioms for $L_0$ plus $\bar aa \le 1$ (equivalently, $1+\bar aa = 1$) are sound for $\overline{L}$.
\end{theoremEnd}
\begin{proofEnd}
The axioms of KA are sound since $\BB$ is a KA\@. The axioms $a\bar a=1$ and $a\bar b=0$, $b\ne a$, are still sound since equations are preserved under a homomorphism. The axiom $\bar aa \le 1$, equivalently $1+\bar aa = 1$, is also sound under $L_1$:
\begin{align*}
& L_1(1+\bar aa) = \NF(\{\eps,\bar aa\})\dn = \{\eps,\bar aa\}\dn = \set{\bar xx}{x\in\Sigma^*} = \{\eps\}\dn = \NF(\{\eps\})\dn = L_1(1).
\end{align*}
Thus if $e_1=e_2$ is provable, then $L_1(e_1)=L_1(e_2)$.
\end{proofEnd}

Although inspired by this axiom, our axiomatization is rather more complicated, involving an infinite set of rules derived from the fundamental theorem. % \eqref{eq:fundthmA}.
We do not know whether $\bar aa\le 1$ by itself is enough for completeness, but conjecture that it is not.

To properly describe our axiomatization, we need a new operator.
For $B\subs\Sigma^*$, define $B^\dagger = \set{\bar xx}{x\in B}$.
For example, $(a^*)^\dagger = \set{\bar a^n a^n}{n\ge 0}$.
Clearly, ${}^\dagger$ does not preserve regularity, which is not surprising as we are dealing with stacks.
However, we will temper the non-regular aspect of this operator by using the two Brzozowski derivatives $D$ and $D'$ in tandem. %, as we did in the proof of \Cref{lem:sumpushpop}.
Still assuming $a\bar a=1$ and $a\bar b=0$ for $b\ne a$, here are some properties of $^\dagger$ that are not difficult to derive:
%\begin{itemize}
%\item
%$(\bigcup_\alpha B_\alpha)^\dagger = \bigcup_\alpha B_\alpha^\dagger$
%\item
%$B^\dagger B^\dagger = B^\dagger$
%\item
%$(B^\dagger)^* = 1 + B^\dagger$
%\item
%$\bar aB^\dagger a = (Ba)^\dagger$, $a\in\Sigma$
%\end{itemize}
\begin{align}
& \Bigl(\bigcup_\alpha B_\alpha\Bigr)^\dagger = \bigcup_\alpha B_\alpha^\dagger
&& B^\dagger B^\dagger = B^\dagger
&& (B^\dagger)^* = 1 + B^\dagger
&& \bar aB^\dagger a = (Ba)^\dagger,\ a\in\Sigma
\label{eq:sounddaggereqs}
\end{align}
It is also clear that if $B$ is regular, then $B^\dagger$ is context-free. %, as $B^\dagger$ is the intersection of the regular set $\bar\Sigma^*B$ with the context-free language $(\Sigma^*)^\dagger = \set{\bar xx}{x\in\Sigma^*}$.
We furthermore have the following.

%We can also introduce a corresponding syntactic operator $^\dagger$, but for syntactic closure we must also extend the operator $\barnone$ to apply to pop symbols as well as push symbols. For this purpose it makes sense to define $\bar{\bar a}=a$, so that $\barnone$ becomes an involution. On $(\Sigma\cup\bar\Sigma)^*$, $\barnone$ reverses the string and simultaneously complements each symbol. However, this extension introduces more complication than necessary for the completeness of \stackat, as we will only ever need to apply $^\dagger$ to pure push expressions.
%
%With the extended definition of $\barnone$,

\begin{textAtEnd}
We can extend the interpretation $R:\Exp\to 2^{(\Sigma\cup\bar\Sigma)^*}$ to expressions involving $^\dagger$ by adding the clause $\SemR{e^\dagger} = \SemR e^\dagger$ to the inductive definition. The semantic properties \eqref{eq:sounddaggereqs} lead to sound equations % chktex 2
%\begin{itemize}
%\item
%$(e_1+e_2)^\dagger = e_1^\dagger + e_2^\dagger$
%\item
%$e^\dagger e^\dagger = e^{\dagger\dagger} = e^\dagger$
%\item
%$(e^\dagger)^* = 1 + e^\dagger$
%\item
%$\bar ae^\dagger a = (ea)^\dagger$, $a\in\Sigma$
%\end{itemize}
\begin{align*}
& (e_1+e_2)^\dagger = e_1^\dagger + e_2^\dagger
&& e^\dagger e^\dagger = e^{\dagger\dagger} = e^\dagger
&& (e^\dagger)^* = 1 + e^\dagger
&& \bar ae^\dagger a = (ea)^\dagger,\ a\in\Sigma
\end{align*}
The congruence rule $e_1=e_2\Imp e_1^\dagger=e_2^\dagger$ also holds.

From \eqref{eq:fundthmZ}, we have a version of the fundamental theorem that holds in the presence of $^\dagger$: % chktex 2
\begin{align}
\bar e_1e^\dagger e_2
%&= (E(\bar e_1) + \sum_{a\in\Sigma} D'_a(\bar e_1)\bar a)e^\dagger(E(e_2) + \sum_{b\in\Sigma} bD_b(e_2))\nonumber\\
&= E(\bar e_1)e^\dagger E(e_2) + E(\bar e_1)\sum_b e^\dagger bD_{b}(e_2)\nonumber + E(e_2)\sum_a D'_{a}(\bar e_1)\bar ae^\dagger\nonumber\\
&\quad\ + \sum_{a\ne b} D'_{a}(\bar e_1)\bar a e^\dagger bD_{b}(e_2) + \sum_a D'_{a}(\bar e_1)(ea)^\dagger D_{a}(e_2).\label{eq:fundthmA}
\end{align}
We also have $e^\dagger = E(e) + \sum_{a\in\Sigma} \bar aD'_a(e)^\dagger a$.
\end{textAtEnd}

\begin{theoremEnd}[default]{lemma}%
\label{lem:LR}
For pure pop expressions $\bar{e}_1$ and pure push expressions $e_2$,
$\bar{L}(\bar e_1e_2) = L(\bar e_1) \cdot \Ssd \cdot L(e_2)$.
\end{theoremEnd}
\begin{proofEnd}
By definition, $\overline{L}(\bar e_{1}e_{2}) = \poppush{L_0(\bar e_{1}e_{2})} = \poppush{L(\bar e_{1}e_{2})} = L(\bar e_{1}) \cdot \Ssd \cdot L(e_{2})$.
\end{proofEnd}

We can also extend ${}^\dagger$ to regular expressions, interpreting $e^\dagger$ as $L(e)^\dagger$.
The following then holds.

