\begin{theoremEnd}[default]{lemma}%
\label{lem:delimited}
Let $\bar e_1$ be a pure pop expression and $e,e_2$ pure push expressions.
The expression $\bar e_1e^\dagger e_2$ is semantically $L$-equivalent to a sum of expressions of the following forms:
\begin{align}
& \bar d_1\bar ad^\dagger bd_2,\ a\ne b && \bar d_1\bar ad^\dagger && d^\dagger bd_2 && d^\dagger\label{eq:four1}
\end{align}
where $d_1$ is a pure pop expression, $d$ and $d_2$ are pure push expressions, and $a,b\in\Sigma$, $a\ne b$.
\end{theoremEnd}
\begin{proofEnd}
Fix $\bar e_1$, $e$, and $e_2$ as in the statement of the lemma. Define a binary relation on $\Sigma^*$:
\begin{align*}
y\equiv z\ \ \Iff\ \ \SemR{D'_{y}(\bar e_1)} = \SemR{D'_{z}(\bar e_1)}\ \ \text{and}\ \ \SemR{D_{y}(e_2)} = \SemR{D_{z}(e_2)}.
\end{align*}
The relation $\equiv$ is a right-invariant equivalence relation (that is, $y\equiv z$ implies $ya\equiv za$) with only finitely many classes $[z]=\set y{y\equiv z}$, as there are only finitely many derivatives up to KA equivalence. Thus there is a finite-state automaton with states $\Sigma^*/{\equiv}$ and transition function $\delta([x],a)=[xa]$. The equivalence classes $[z]$ are all regular sets and are the strings accepted from the state $[z]$.

One can compute a regular expression $e_z$ for $[z]$ as follows. The single-step transition matrix of this automaton is a $(\Sigma^*/{\equiv})\times(\Sigma^*/{\equiv})$ matrix $A$ of expressions such that $A_{[x][z]} = \sum_{[xa]=[z]} a$. Thus
\begin{align*}
\SemR{A_{[x][z]}} = \set{a\in\Sigma}{[xa]=[z]}.
\end{align*}
It follows by induction that
\begin{align*}
& \SemR{A^n_{[x][z]}} = \set{y\in\Sigma^n}{[xy]=[z]}
&& \SemR{A^*_{[x][z]}} = \set{y\in\Sigma^*}{[xy]=[z]}
\end{align*}
so we can take $e_z = A^*_{[\eps][z]} = [z]$.

Now for $x\in\Sigma^*$, define
\begin{align*}
\tau(x)
&= D'_x(\bar e_1)(ex)^\dagger D_x(e_2)\\
\phi(x)
&= E(D'_x(\bar e_1))(ex)^\dagger E(D_x(e_2)) + E(D'_x(\bar e_1))\sum_b (ex)^\dagger bD_{xb}(e_2)\\
&\quad\ + E(D_x(e_2))\sum_a D'_{xa}(\bar e_1)\bar a(ex)^\dagger + \sum_{a\ne b} D'_{xa}(\bar e_1)\bar a(ex)^\dagger bD_{xb}(e_2).
\end{align*}
Using the fact that $\sum_{y\equiv z}(ey)^\dagger = (ee_z)^\dagger$ and the fact that $D'_{y}(\bar e_1)$ and $D'_{z}(\bar e_1)$ are equivalent and $D_{y}(e_2)$ and $D_{z}(e_2)$ are equivalent for $y\equiv z$, we have
\begin{align}
\sum_{y\equiv z}\phi(y)
&= \sum_{y\equiv z}E(D'_z(\bar e_1))(ey)^\dagger E(D_z(e_2)) + \sum_{y\equiv z}E(D'_z(\bar e_1))\sum_b (ey)^\dagger bD_{zb}(e_2)\nonumber\\
&\quad\ + \sum_{y\equiv z}E(D_z(e_2))\sum_a D'_{za}(\bar e_1)\bar a(ey)^\dagger + \sum_{y\equiv z}\sum_{a\ne b} D'_{za}(\bar e_1)\bar a(ey)^\dagger bD_{zb}(e_2)\nonumber\\
&= E(D'_y(\bar e_1))(ee_z)^\dagger E(D_y(e_2)) + E(D'_y(\bar e_1))\sum_b (ee_z)^\dagger bD_{yb}(e_2)\nonumber\\
&\quad\ + E(D_y(e_2))\sum_a D'_{ya}(\bar e_1)\bar a(ee_z)^\dagger + \sum_{a\ne b} D'_{ya}(\bar e_1)\bar a(ee_z)^\dagger bD_{yb}(e_2).\label{eq:goodform}
\end{align}
This is a finite sum of terms of the desired form as described in the statement of the lemma.

The fundamental theorem \eqref{eq:fundthmA} says that $\tau(x) = \phi(x) + \sum_a \tau(xa)$. Unwinding this inductively, % chktex 2
\begin{align*}
\bar e_1e^\dagger e_2 &= \tau(\eps) = \sum_y \phi(y) = \sum_{[z]} \sum_{y\equiv z} \phi(y),
\end{align*}
which by \eqref{eq:goodform} is equivalent to a finite sum of the desired form. % chktex 2
\end{proofEnd}

Note that the four forms shown in \eqref{eq:four1} represent pairwise disjoint sets under $L$. % chktex 2
For example, every string in $L(\bar d_1\bar ad^\dagger bd_2)$, where $a\ne b$, contains a substring $\bar a\kern1pt\bar xxb$, whereas every string in $L(\bar d_1\bar ad^\dagger)$ has a suffix of the form $\bar a\kern1pt\bar xx$, and no string in normal form can have both.

%For expressions in one of the four forms \eqref{eq:four1},
Let $\#$ be a new delimiter symbol and consider the forms
\begin{align}
& ad_1\#d\#bd_2,\ a\ne b && ad_1\#d\# && \#d\#bd_2 && \#d\#\label{eq:four2}
\end{align}
corresponding to the four forms of \eqref{eq:four1}. % chktex 2
% The $\#$ are used to delimit $d$, and occurrences of $^\dagger$ are removed.
Define the map
\begin{align*}
& K:\Sigma^*\#\Sigma^*\#\Sigma^* \to \bar\Sigma^*\Sigma^* && K(x\#y\#z) = \bar x\bar yyz.
\end{align*}
$K$ is not injective; for example, $K(a\#a\#a) = K(aa\#\#aa)$.
However, $K$ acts bijectively between strings of the form~\eqref{eq:four1} and corresponding strings of the form~\eqref{eq:four2}.
\begin{theoremEnd}[default]{lemma}%
\label{lem:LR2}
Let $e$ be one of the expressions in \eqref{eq:four1} and let $e'$ be the corresponding expression in \eqref{eq:four2}. The map $K$ restricted to $L(e')$ is a bijection $K:L(e')\to L(e)$. % chktex 2
\end{theoremEnd}
\begin{proofEnd}
Consider the first two corresponding expressions $\bar d_1\bar ad^\dagger bd_2$ from \eqref{eq:four1} and $ad_1\#d\#bd_2$ from \eqref{eq:four2}, where $a\ne b$. The image of $L(ad_1\#d\#bd_2)$ under $K$ i % chktex 2
\begin{align*}
\set{K(u)}{u\in L(ad_1\#d\#bd_2)}
&= \set{K(ax\#y\#bz)}{x\in L(d_1),\ y\in L(d),\ z\in L(d_2)}\\
&= \set{\bar x\kern1pt\bar a\kern1pt\bar yybz}{x\in L(d_1),\ y\in L(d),\ z\in L(d_2)}\\
&\subs L(\bar d_1\kern1pt\bar ad^\dagger bd_2).
\end{align*}
But any string of the form $\bar x\kern1pt\bar a\kern1pt\bar yybz\in\bar d_1\kern1pt\bar ad^\dagger bd_2$ is the image under $K$ of exactly one string in $L(ad_1\#d\#bd_2)$, namely $ax\#y\#bz$. The string $y$ is uniquely determined since $\bar yy$ is the longest skew-palindromic substring of $\bar x\kern1pt\bar a\kern1pt\bar yybz$ as it is delimited by $\bar a$ and $b$ and $a\ne b$, and thereafter $x$ and $z$ are also uniquely determined.

A similar argument holds for the other three cases.
\end{proofEnd}

Let $\sum_i\bar e_{i1}e_{i2}$ and $\sum_j\bar d_{j1}d_{j2}$ be two expressions in normal form. Using Lemma~\ref{lem:delimited}, reduce $\sum_i\bar e_{i1}\Ssd e_{i2}$ and $\sum_j\bar d_{j1}\Ssd d_{j2}$ to sums of expressions $\sum_i\bar p_i q_i^\dagger r_i$ and $\sum_j \bar u_j v_j^\dagger w_j$, respectively, of the form \eqref{eq:four1}. Let $\sum_i p_i\#q_i\#r_i$ and $\sum_j u_j\#v_j\#w_j$ be the corresponding sums of expressions of the form \eqref{eq:four2}. % chktex 2

\begin{theoremEnd}[default]{lemma}%
\label{lem:FG5}
$\overline{L}(\sum_i\bar e_{i1}e_{i2})\subs \overline{L}(\sum_j\bar d_{j1}d_{j2})
\ \Iff\ L(\sum_i p_i\#q_i\#r_i)\subs L(\sum_j u_j\#v_j\#w_j)$.
\end{theoremEnd}
\begin{proofEnd}
We show that the following are equivalent:
\begin{enumerate}[(i)]
\item
$L_1(\sum_i\bar e_{i1}e_{i2})\subs L_1(\sum_j\bar d_{j1}d_{j2})$
\item
$L(\sum_i\bar e_{i1}\Ssd e_{i2})\subs L(\sum_j\bar d_{j1}\Ssd d_{j2})$
\item
$L(\sum_i p_i\#q_i\#r_i)\subs L(\sum_j u_j\#v_j\#w_j)$.
\end{enumerate}
Statements (i) and (ii) are equivalent by Lemma~\ref{lem:LR} and (ii) and (iii) are equivalent by Lemma~\ref{lem:LR2}.
\end{proofEnd}

Now consider the rule
\begin{align}
\frac{\sum_i p_i\#q_i\#r_i \le \sum_j u_j\#v_j\#w_j}{\sum_i\bar e_{i1}e_{i2} \le \sum_j\bar d_{j1}d_{j2}},\label{eq:badrule2}
\end{align}
where the expressions are as described in the paragraph above Lemma~\ref{lem:FG5}.

\begin{theorem}%
\label{thm:completenessB}
The rule~\eqref{eq:badrule2}, along with $a\bar a=1$, $a\bar b=0$ for $b\ne a$, and the axioms of KA and equational logic, are sound and complete for the equational theory of the push-pop fragment of \stackat.
\end{theorem}
\begin{proof}
Suppose we want to prove that $e\le d$ under the interpretation $L_1$ or $\Sem-$. By Theorem~\ref{thm:normalform}, we can provably convert $e$ and $d$ to normal form $\sum_i\bar e_{i1}e_{i2}$ and $\sum_j\bar d_{j1}d_{j2}$, respectively. By Lemma~\ref{lem:FG5} and rule~\eqref{eq:badrule2}, to prove that $\sum_i\bar e_{i1}e_{i2} \le \sum_j\bar d_{j1}d_{j2}$ under the interpretation $L_1$, it suffices to prove $\sum_i p_i\#q_i\#r_i\le \sum_j u_j\#v_j\#w_j$ under the interpretation $R$. This is provable, as KA is complete for $R$.
\end{proof}

\section{Related Work}\label{sec:related}

In relating \StacKAT to existing extensions of regular languages it is important to make a few observations. Most importantly, a \StacKAT program does not have a separate input tape. Hence, it does not capture behaviors that require both processing the input and pushing/popping symbols to/from the stack. Using standard pushdown automata, one can model behaviors like ``after every $a$-transition, write symbol $x$ to the stack'' but this is not possible in \StacKAT. If \StacKAT programs were equivalent to automata with both an input tape and a stack, equivalence of \StacKAT languages would clearly be undecidable---e.g., we could then use the stack to parse a context-free grammar on the input tape. Having said that, there are several tractable fragments of context-free languages that are somewhat reminiscent of \StacKAT. The reader might wonder if \StacKAT is a particular instance of one of these previously studied, tractable fragments. To the best of our knowledge this is not the case. Below, we review below the most closely related work and explain the key differences.

\paragraph{Network Reachability Verification of MPLS Networks}
Closely related to our work is the verification of reachability in MPLS networks~\cite{Jensen2020,Jensen2021, Jensen2018}. Since MPLS networks use the packet as a stack, the verification problem can be cast as a reachability problem in a pushdown system. These works can also handle quantitative properties such as failures or latency. Recently, a symbolic decision procedure was developed~\cite{Beckett2022} that can efficiently handle large packet spaces.
In contrast with these works, \StacKAT handles equivalence queries. An interesting question for future work is whether ideas from the above works can be adapted to \StacKAT.


\paragraph{Visibly Pushdown Languages}
% \tobias{On page 21, I am a bit confused about ``StacKAT languages are not a subset of VPLs, as StacKAT becomes undecidable when we have a separate stack and input tape''. It is not clear to me how the former follows from the latter. Like, if this were the case, would it mean that StacKAT languages are a subset of VPLs? Also, what are StacKAT languages?}
%
One important subclass of languages that is particularly relevant for program analysis are visibly pushdown languages (VPLs)~\cite{Alur2004}.  VPLs are accepted by visibly pushdown automata. Whereas in general pushdown automata the stack operations depend on both the input symbol and the current state, in VPAs the input alphabet is partitioned in a way that the type of stack operation (push or pop) is determined by the input symbol itself alone. VPLs are more tractable than general context-free languages as they enjoy several closure and decidability properties. VPLs are closed under union, intersection, and complementation. Moreover, emptiness, membership, and language equality and inclusion are decidable.

We view the relationship between \StacKAT and VPLs as follows.
Naively, one might hope to use equivalence of pushdown automata as a basis for decision procedures.
Unfortunately, that equivalence problem is undecidable.
VPLs address this issue by restricting the pushdown automaton to a specific subclass.
\StacKAT takes a different approach and instead removes the input tape, but keeps the pushdown stack completely unrestricted.
Therefore, VPLs and \StacKAT are incomparable, being two different ways of taming the expressive power of pushdown automata.

% \tobias{I recently heard about operator precedence languages, a different kind of strictly context-free language that does have nice decidability properties (\url{https://doi.org/10.1007/978-3-031-65627-9_19}). I do not know how these compare to StacKAT though\ldots}

\paragraph{Dyck Languages}
% \tobias{The bibliography on Dyck languages is quite extensive, maybe bigger than it needs to be?}
%
VPLs are more general than so-called {\em parentheses languages}, also often referred to as Dyck languages, which are languages consisting of balanced strings of parentheses, with one and multiple types of parentheses~\cite{McNaughton1967,Berstel2002}. However, a language $\poppush{L}$ cannot be viewed as such a language, as not all pop/push actions occur parenthesized: a letter $\pop{v}$ in a word $w$ in $\poppush{L}$ can be seen as an opening bracket in case it occurred because of the $\poppush{-}$ closure, but otherwise it is just a letter, and there is not necessarily a closing bracket ($\push{v}$) in $w$. Thus, the $\poppush{-}$-closure cannot be characterized using Dyck languages.

Another class of related work in which Dyck languages play an important role is language graph reachability analysis, a common way to tackle certain static analyses~\cite{Reps1997}. Informally, the nodes of a graph represent various program segments, while edges capture relationships between those segments, such as program flow or data dependencies. Analysis is then formulated as a reachability question between nodes in the graph, as witnessed by paths whose labels along the edges produce a string that belongs to a language, which is often a visibly pushdown language. This reachability problem, often referred to as Dyck reachability, has been applied in many contexts including interprocedural data-flow analysis~\cite{Horwitz1995}, slicing~\cite{Reps1994}, or type-based flow analysis~\cite{Rehof2001}. %The balanced-parenthesis property of Dyck languages is ideal for expressing sensitivity of the analysis in matching calling contexts, matching field accesses of composite objects, matching pointer references and dereferences.
 Dyck reachability has been generalized to bidirected graphs (with applications in pointer analysis) and has been studied in terms of decidability and complexity~\cite{Kjelstrom2022}.

\paragraph{Interprocedural Analysis and Pushdown Systems}
Precise interprocedural dataflow analyses involve reasoning about the call stack to capture call-return behavior~\cite{Reps1995, Sagiv1996}.
Pushdown Systems are another formalism used for program analysis and dataflow analysis~\cite{Finkel1997,Bouajjani1997}, which model a control state as well as a stack. Dataflow queries are then translated to reachability queries in pushdown systems. This avoids merging data flows from states with the same program point but different calling context, resulting in a more precise analysis. Our work by contrast is focused on program equivalence, in order to enable encoding of verification queries such as slicing, translation validation, loop freedom, etc.~\cite{Foster2015}. Weigthed versions of pushdown systems have also been developed~\cite{Reps2003, Reps2005}. It would be interesting to investigate whether techniques for interprocedural dataflow analysis can be harnessed to answer network verification queries, including weighted variants.

\paragraph{Deterministic Context Free Languages}
%
Another relevant subclass of languages are Deterministic Context Free Languages (DCFLs), the class accepted by deterministic pushdown automata (DPDAs). DCFLs are closed under complementation, but not under union. The equivalence problem for DPDAs is decidable~\cite{Senizergues1997,Senizergues2002,Senizergues2002a}. Like VPLs, and unlike StacKAT, DCFLs have a separate input tape.

\paragraph{Deterministic One-Counter Automata}
%
Another relevant subclass are the languages accepted by deterministic one-counter automata (DOCA)~\cite{Valiant1975}. A DOCA is a special case of a pushdown automaton, with a single stack that can only hold one type of symbol (often interpreted as a counter), and the stack operations are restricted to either pushing or popping this symbol (or leaving the stack unchanged). However, again because \StacKAT becomes undecidable when we have a separate stack and input tape, \StacKAT languages are not the languages captured by one-counter automata.

\paragraph{Valence Automata}
%
A generalization of both DOCA and pushdown automata is given by the notion of \emph{valence automaton}~\cite{Buckheister2013} where transitions are labeled with elements from a monoid. A valence automaton accepts a string depending not only on reaching a final state but also on the accumulated product of the transition labels equaling the zero of the monoid. Valence automata generalize several models and can be used to study languages and automata under algebraic constraints. In particular, a DOCA is a valence automaton for the monoid of natural numbers under addition. Pushdown automata are valence automata under the monoid of stack operations. Transitions push or pop symbols on the stack, accepting if the stack is empty. Decidability and closure properties of valence automata are dependent on the specific monoid used.

For our setting, it is not clear how to adapt valence automata to \StacKAT, because \StacKAT programs can transform the stack, and in fact the way they do so is integral to their semantics, whereas (stacks encoded in) valence automata function as an additional constraint on acceptance.

\paragraph{Generalized Versions of KA}
%
\tobias{The discussion of KA+H is now lumped together with omega-algebras. Maybe it deserves its own paragraph. At the same time, there is a bit of overlap with the discussion section that follows, so maybe it should just be in the discussion section?}
In~\cite{Mathieu2005}, the authors investigate an extension of Kleene algebra called omega algebra with domain to model pushdown automata, and propose axioms to model the stack that are reminiscent of ours. However, they do not discuss decidability or completeness of their algebraic theory. Recent advances in completeness techniques led to the development of the Kleene Algebra with Hypotheses framework~\cite{Doumane2019,Pous2024}, which can yield completeness proofs of several Kleene Algebra extensions. However, some of the axioms we consider in \StacKAT fail the conditions of this framework, which prevents its immediate application. In particular, closure w.r.t.\ the hypotheses $\pop{v}\cdot\push{v}\leq 1$ and $\push{v}\cdot\pop{v}\leq 1$ does not preserve regularity.

\section{Future Work}

\StacKAT is an extension of \NetKAT~\cite{Anderson2014,Foster2015,Smolka2015}, but goes beyond it by adding a stack to the data model. A new symbolic decision procedure was recently developed that can efficiently decide large \NetKAT equivalence queries~\cite{Moeller2024}. We would naturally like to integrate \StacKAT within this symbolic framework. As we can encode dup in \StacKAT, one might wonder if the integration is immediate, which is however not the case. The core of the developments in~\cite{Moeller2024} rely on the fact that during the decision procedure, when trying to determine whether $e_1$ and $e_2$ are equivalent, if a dup action is encountered then the packet state is identical at the corresponding states of $e_1$ and $e_2$.
% Intuitively, it is essential for the decision procedure that the dup action forces logging all fields of the current packet and therefore the procedure only needs to track a single packet that is processed in paralel by $e_1$ and $e_2$.
This is fundamentally different in \StacKAT: if equivalent $e_1$ and $e_2$ push the same symbol onto the stack, that does not imply that the packet state is also the same at that moment. In other words, \StacKAT programs $e_1$ and $e_2$ might be equivalent even though the packet state they are in is different. This behavioral difference makes the integration with the framework of~\cite{Moeller2024} challenging, and is left as future work.
Another promising direction for future work is to determine the \emph{active domain} of a \StacKAT program, similar to APKeep~\cite{Zhang2020}, grouping packet values together into equivalence classes, and then reducing the packet space enumeration to the equivalence classes.


