\section{Constructing knots that share 4-surgeries}\label{sec:construction}
In this section, we use RBG links to construct pairs of knots that share four integral surgeries. RBG links were introduced in \cite{LPshake} and are usually used to produce a pair of knots with a single common surgery.

\begin{defi}
A $3$-component link $L$ in $S^3$ with components $R$, $B$, and $G$, is called \textit{Hopf RBG link} if the following hold:
\begin{enumerate}
	\item $R\cup B$, $R\cup G$, and $B\cup G$ are Hopf links.
	\item The Seifert disks $D_R$, $D_B$, and $D_G$ of $R$, $B$, and $G$ can be isotoped such that the following three conditions hold simultaneously:
	\begin{enumerate}
		\item $D_B$ and $D_G$ intersect in a single clasp singularity,
		\item $D_B$ intersects $D_R$ in a single clasp singularity and finitely many ribbon singularities, and
		\item $D_G$ intersects $D_R$ in a single clasp singularity and finitely many ribbon singularities.
	\end{enumerate}
\end{enumerate}
\end{defi}

\begin{figure}[t] 
	\centering
	\def\svgwidth{0,7\columnwidth}
	\input{RGBabstract.pdf_tex}
	\caption{Two schematic views on a Hopf RBG link.}
	\label{fig:RGBabstract}
\end{figure}

A schematic picture of a Hopf RBG link is shown in Figure~\ref{fig:RGBabstract}. For a concrete simple example of a (non-trivial) Hopf RBG link we refer to Figure~\ref{fig:exampleHopfRBG}. After an isotopy, we can always assume that $D_B$ intersects $D_R$ in a single clasp singularity or that $D_G$ intersects $D_R$ in a single clasp singularity. But in general, both are not possible simultaneously, see for example Figure~\ref{fig:exampleHopfRBG}.

We will show that every Hopf RBG link induces pairs of knots that share four surgeries. For that, we will need the following lemma.

\begin{lem}\label{lem:S3surgeries}
	Surgery on a Hopf link with surgery coefficients $p/q$ and $r/s$ yields $S^3$ if and only if $pr-qs=\pm1$. 
\end{lem}

\begin{proof}
	Any Dehn surgery on the Hopf link yields a lens space. Among lens spaces, we can recognize $S^3$ by the vanishing of its first homology group. Since $|pr-qs|$ yields the order of the first homology of a $(p/q,r/s)$-surgery on a $2$-component link, the claim follows.
\end{proof}

\begin{cor} \label{cor:knots} To any Hopf RBG link $L$, pair of rationals $p/q$ and $r/s$  with $pr-qs=\pm1$, and $C\in\{R,B,G\}$, we can naturally associate a knot $K_C^{p/q,r/s}$ by considering the image of $C$  in the $S^3$ obtained by performing $p/q$ and  $r/s$ surgery on $L\setminus C$. \qed
\end{cor}

In this paper, we will mainly be concerned with the knots $K_G^{0,n}$ and $K_B^{0,n}$.

\noindent By convention, we always choose an orientation of the Hopf RBG link such that
\begin{align*}
	\lk(R,B)=1=\lk(R,G).
\end{align*}
Thus the linking number $\lk(B,G)$ is either $+1$ or $-1$. Then the precise version of our main theorem reads as follows. 

\begin{thm} \label{thm:main_detailed}
	For any Hopf RBG link L and integer $n\in\Z$, the knots $K_G^{0,n}$ and $K_B^{0,n}$ have orientation-preserving diffeomorphic surgeries for the following set of surgery slopes.
	\begin{itemize}
	\item $(n+1,n+2,n+3,2n+2)$, if $\lk(B,G)=-1$, and
	\item $(n-3,n-2,n-1,2n-2)$, if $\lk(B,G)=1$.
	\end{itemize}
\end{thm}

To prove Theorem~\ref{thm:main_detailed}, we first observe that there are distinct fillings of a Hopf RBG link which produce the same manifold. We use the notation $L(r,b,g)$ to denote filling $R,B,G$ with slopes $r,b,g$, respectively. We use $\ast$ to denote no filling.  

\begin{lem}\label{lem:sym_hopf}
	Let $L$ be a Hopf RBG link. Then for any $n,m\in\Z$ and $s\in\{-1,0,1\}$ we have that $L(n,m,s)$ is orientation-preserving diffeomorphic to $L(n,s,m)$. 
\end{lem}

\begin{proof}
	For each $s$, these diffeomorphisms are induced by the sequences of handle slides and slam dunks shown in Figures~\ref{fig:lem1} and~\ref{fig:lem2}.
\end{proof}

\begin{figure}[t] 
	\centering
	\def\svgwidth{0,8\columnwidth}
	\input{lem1.pdf_tex}
	\caption{$L(n,m,0)$ is diffeomorphic to $L(n,0,m)$. Each vertical diffeomorphism is given by a handle slide (indicated with the arrow) followed by a slam dunk.}
	\label{fig:lem1}
\end{figure}

\begin{figure}[htbp] 
	\centering
	\def\svgwidth{0,75\columnwidth}
	\input{lem2.pdf_tex}
	\caption{$L(n,m,\pm1)$ is diffeomorphic to $L(n,\pm1,m)$. Each vertical diffeomorphism is given by a blow down. While the horizontal diffeomorphism is induced by an isotopy.}
	\label{fig:lem2}
\end{figure}
\begin{figure}[htbp] 
	\centering
	\def\svgwidth{0,75\columnwidth}
	\input{RGBtangles.pdf_tex}
	\caption{Kirby moves from a Hopf RBG link to the knots $K_B^{0,n}$ and $K_G^{0,n}$. The sign in the framing $*+n\pm2$ depends on the exact linking numbers of the Hopf RBG link.}
	\label{fig:RGBtangles}
\end{figure}

With this lemma, we are ready to give the proof of Theorem~\ref{thm:main_detailed}.

\begin{proof} [Proof of Theorem~\ref{thm:main_detailed}]
For knots $K_G^{0,n}$ and $K_B^{0,n}$ constructed from a Hopf RBG link $L$ as in Corollary \ref{cor:knots}, the diffeomorphisms from	Lemma~\ref{lem:sym_hopf} readily show that  $K_G^{0,n}$ and $K_B^{0,n}$ share four integer surgeries as follows.
	\begin{align*}
		K_G^{0,n}(s_n)&=L(0,n,n)=K_B^{0,n}(s_n)\\
		K_G^{0,n}(s_0)&=L(0,n,0)=L(0,0,n)=K_B^{0,n}(s_0)\\
		K_G^{0,n}(s_1)&=L(0,n,+1)=L(0,+1,n)=K_B^{0,n}(s_1)\\
		K_G^{0,n}(s_{-1})&=L(0,n,-1)=L(0,-1,n)=K_B^{0,n}(s_{-1})
	\end{align*}
Here we are using $s_i$ to stand in for a not-yet-computed surgery coefficient. To compute the coefficients $(s_n,s_0,s_1,s_{-1})$ we perform the explicit Kirby moves as shown in Figure~\ref{fig:RGBtangles}. A concrete Hopf RBG link is shown in Figure~\ref{fig:exampleHopfRBG}, where $(s_n,s_0,s_1,s_{-1})=(n+1,n+2,n+3,2n+2)$. To get the other set of slopes in the statement of Theorem \ref{thm:main_detailed}, one can switch the sign on the clasp between $B$ and $G$ in the RBG link in Figure~\ref{fig:exampleHopfRBG}.
\end{proof}

\begin{rem}\label{rem:tangles} A few remarks are in order.
	\begin{enumerate}
		\item If the Hopf RBG links are overly simple or symmetric then it might happen that the knots $K_G^{0,n}$ and $K_G^{0,n}$ are isotopic. But in general, there is no reason why these knots should be isotopic, and we will prove in Section~\ref{sec:distinguish} that often they are not. 
  %$K_G^{0,n}$ and $K_G^{0,n}$ are not isotopic.
		\item On the other hand for $n=-1,0,1$, the knots $K_G^{0,n}$ and $K_B^{0,n}$ are always isotopic. Indeed, Lemma~\ref{lem:sym_hopf} implies that
		\begin{align*}
			K_G^{0,0}&=L(0,0,*)=L(0,*,0)=K_B^{0,0},\\
			K_G^{0,+1}&=L(0,+1,*)=L(0,*,+1)=K_B^{0,+1},\\
			K_G^{0,-1}&=L(0,-1,*)=L(0,*,-1)=K_B^{0,-1}.
		\end{align*}
		\item Similarly for all integers $n\in\Z$, the knots $K_G^{n,0}$ and $K_B^{n,0}$ are isotopic.
  \item It follows from Figure~\ref{fig:RGBtangles} that the knots $K_B^{0,n}$ and $K_G^{0,n}$ are related by taking the tangle shown in the lower row of Figure~\ref{fig:RGBtangles} and rotating it by $\pi$. This can be thought of as a generalized mutation. 
	\end{enumerate}
\end{rem}

In Theorem~\ref{thm:main_detailed} we established that the knots $K_G^{0,n}$ and $K_B^{0,n}$ have four common surgeries. Recall that for any $s\in\Z$ we can associate a 4-manifold to a knot $K$ by attaching a $2$-handle with framing $s$ along a knot $K$ in $\partial D^4$. This $4$-manifold is called the $s$-trace, $X_s(K)$. The boundary of $X_s(K)$ is diffeomorphic to the $s$-surgery along $K$. Since the RBG link which induced $K_G^{0,n}$ and $K_B^{0,n}$ had $R=U$ and $r=0$, our Theorem \ref{thm:main_detailed} immediately generalizes to traces by taking the RBG link $L$ to be a handle diagram of a 4-manifold where $R$ is a $1$-handle in dotted circle notation. 

\begin{cor}\label{thm:traces}
	Let $L$ be a Hopf RBG link. For every integer $n\in\Z$ the knots $K_G^{0,n}$ and $K_B^{0,n}$ have orientation-preserving diffeomorphic $s_i$-traces for the following set of surgery slopes.
	\begin{itemize}
	\item $(n+1,n+2,n+3,2n+2)$, if $\lk(B,G)=-1$, and
	\item $(n-3,n-2,n-1,2n-2)$, if $\lk(B,G)=1$.\qed
	\end{itemize}
\end{cor}

\section{Distinguishing knots that share four surgeries}\label{sec:distinguish}
As a concrete example, we consider the Hopf RBG link $L$ shown in Figure~\ref{fig:exampleHopfRBG}. Note that the intersection of the Seifert disk $D_R$ of $R$ intersects the blue and red Seifert disks in two ribbon singularities and two clasp singularities. On the left side, both ribbon intersections are with $D_B$, and on the right, both are with $D_G$. By following the Kirby moves from Figure~\ref{fig:RGBtangles} we obtain the knots $K_B^{0,n}=K_n$ and $K_G^{0,n}=K'_n$ shown in Figure~\ref{fig:example}.

\begin{figure}[t] 
	\centering
	\def\svgwidth{0,75\columnwidth}
	\input{exampleHopfRBG.pdf_tex}
	\caption{Two views on the same Hopf RBG link.}
	\label{fig:exampleHopfRBG}
\end{figure}

In Appendix~\ref{app} we will prove a technical theorem which implies the following.

\begin{thm}\label{thm:distinguish}
 The Hopf RGB link $L$ in Figure~\ref{fig:exampleHopfRBG} induces the knots $K_B^{0,n}$ and $K_G^{0,n}$ in Figure~\ref{fig:example} which, for $n\neq-1,0,+1$, have distinct HOMFLYPT polynomials.
\end{thm}

Together with Theorem \ref{thm:main_detailed}, this finishes the proof of Theorem~\ref{thm:counterex}.

\begin{rem} \label{rem:invariants} We make a few remarks about other ways to distinguish or not distinguish knots that share four surgeries.
	\begin{enumerate}
		\item In all examples of Hopf RBG links that we have inspected, the knots $K_B^{0,n}$ and $K_G^{0,n}$ share many knot invariants. For example, they have isomorphic knot Floer and Khovanov homologies and thus also the same Alexander and Jones polynomial and the same $3$-genus. Moreover, verified computations with SnapPy suggest that such knots always have the same hyperbolic invariants (volume, cusp shape, symmetry group, systole, and short slopes). This is probably explained by the fact that the knots coming from our construction are always related by a generalized mutation, as explained in Remark~\ref{rem:tangles}. 
        \item Knots coming from our construction have the same double branched cover; see Theorem~\ref{thm:covers} below.
		\item We can also distinguish $K_B^{0,n}$ and $K_G^{0,n}$ using the fundamental groups of their complements by looking at the number of conjugacy classes of index $k$ subgroups. Indeed, for the Hopf RBG link $L$ from Figure~\ref{fig:exampleHopfRBG} we have used SnapPy to compute (for small values of $n$) the number of covers of $K_B^{0,n}$ and $K_G^{0,n}$ to be different. For example it turns out that $K_B^{0,2}$ has $32$ covers of degree $8$ while $K_G^{0,2}$ has $33$ covers of degree $8$. 
		\item Another successful and computationally fast way to distinguish such knots is by using canonical triangulations. Here we have used the verified methods in SnapPy~\cite{SnapPy} to construct the canonical triangulations of $K_B^{0,n}$ and $K_G^{0,n}$ for small values of $n$ and show that they are not combinatorial equivalent, cf.~\cite{Weeks_canonical}. With the results and methods from~\cite{canonical_surgery} it should also be possible to distinguish infinitely many $K_B^{0,n}$ and $K_G^{0,n}$ using their canonical triangulations.
		\item There exist also examples of Hopf RBG links where $D_R\cap (D_B\cup D_G)$ consists of a single ribbon and two clasp singularities such that $K_B^{0,n}$ and $K_G^{0,n}$ are non-isotopic, see~\cite{data} for a concrete example. However, then the inductive formula for the HOMFLYPT polynomial yields that for all $n$, the knots $K_B^{0,n}$ and $K_G^{0,n}$ have the same HOMFLYPT polynomial. On the other hand, the canonical triangulations can still distinguish $K_B^{0,n}$ and $K_G^{0,n}$ (for $n\neq-1,0,1$). 
	\end{enumerate}
\end{rem}

We end this section by showing that all knots coming from our construction share the same double branched cover and that the cyclic $k$-fold branched covers have the same volume. We denote by $\Sigma_k(K)$ the cyclic $k$-fold branched cover of $K$. 

\begin{thm}\label{thm:covers} 
    Let $L$ be a Hopf RBG link with associated knots $K_B^{0,n}$ and $K_G^{0,n}$. Then for every $k\geq2$ there exists a $2$-component link $J_k$ consisting of two unknots such that for all $n\in\Z$ 
    \begin{itemize}
        \item $\Sigma_k(K_B^{0,n})$ is orientation-preserving diffeomorphic to $J_k(0,kn)$, and
        \item $\Sigma_k(K_G^{0,n})$ is orientation-preserving diffeomorphic to $J_k(kn,0)$.
    \end{itemize}
    Moreover, there exists a sequence of mutations on $J_k$ interchanging the components of $J_k$, and thus the volumes of $\Sigma_k(K_B^{0,n})$ and $\Sigma_k(K_G^{0,n})$ agree for all $k$ and $n$.
    For $k=2$ there exists an isotopy of $J_2$ interchanging the components and thus for all $n\in\Z$ the double branched covers of $K_B^{0,n}$ and $K_G^{0,n}$ are orientation-preserving diffeomorphic.
    \end{thm}

