\end{rem}

\section{Legendrian knots that share contact \texorpdfstring{$(\pm1)$}{(+-1)}-surgeries}\label{sec:legendrian}
Here we will prove Theorem~\ref{thm:counterex_Legendrian} by a variation of the proof of Theorem~\ref{thm:counterex} in the context of contact manifolds. In this section, we will measure surgery coefficients with respect to the contact longitude. For background on contact geometry and contact surgery, we refer for example  to~\cite{Gompf_Stein,Ding_Geiges_Surgery,Ding_Geiges_Stipsicz,Ozbagci_Stipsicz_book,Geiges_book,Durst_Kegel_rot_surgery,phdthesis,Legendrian_knot_complement,Casals_Etnyre_Kegel,EKS_contact_surgery_numbers}.

\begin{defi}
	A $3$-component Legendrian link $L$ in $(S^3,\xist)$ with components $R$, $B$, and $G$, is called \textit{Legendrian Hopf RBG link} if $L$ is a smooth Hopf RBG link such that $R$, $B$, and $G$ are Legendrian unknots with $\tb=-1$.
\end{defi}

A concrete example is shown in Figure~\ref{fig:LegendrianHopfRBGexample}. Similar as in Section~\ref{sec:construction} any Legendrian Hopf RBG link yields Legendrian knots $K_B$ and $K_G$ in $(S^3,\xist)$ that have contactomorphic contact $(\pm1)$-surgeries.

\begin{lem}\label{lem:pairs_Legendrian}
	If $L$ is a Legendrian Hopf RBG link. Then 
	\begin{align*}
		K_G=&\,L(+1,-1,*) \textrm{ and }
		K_B=\,L(+1,*,-1)
	\end{align*}
	are Legendrian knots in $(S^3,\xist)$.
\end{lem}

\begin{proof}
	The cancellation lemma implies that contact $(-1)$-surgery on a Legendrian knot $K$ followed by contact $(+1)$-surgery on a Legendrian meridian of $K$ with $\tb=-1$ is contactomorphic to $(S^3,\xist)$. In particular, it follows that contact $(+1)$-surgery on $R$ and contact $(-1)$-surgery on $G$ is contactomorphic to $(S^3,\xist)$. Thus the image of $B$ under this contactomorphism is a Legendrian knot $K_B$ in $(S^3,\xist)$. The other knot arises by the same construction with the roles of $B$ and $G$ reversed.
\end{proof}

\begin{lem}\label{lem:sym_hopf_Legendrian}
	Let $L$ be a Legendrian Hopf RBG link. Then $L(+1,+1,-1)$ is contactomorphic to $L(+1,-1,+1)$. 
\end{lem}

\begin{proof}
	We consider the contactomorphism shown in Figure~\ref{fig:LegendrianLemma}. The right and left contactomorphism are given by the indicated contact handle slides and Legendrian Reidemeister moves. That the two surgery diagrams in the middle are contactomorphic can be seen as follows. First, we compute that contact $(+1)$-surgery on a Legendrian knot $K$ followed by contact $(+1)$-surgery on a Legendrian meridian of $K$ with $\tb=-1$ yields the overtwisted contact structure $\xi_1$ on $S^3$ with $\de_3=1$~\cite{Durst_Kegel_rot_surgery}. Then we use smooth Kirby calculus and the formulas for computing $\tb$ and $\rot$ from surgery diagrams~\cite{phdthesis} to show that the green knot in the second surgery diagram and the blue knot in the third surgery diagram are loose Legendrian knots in $(S^3,\xi_1)$ with the same classical invariants. Thus these two Legendrian knots are isotopic~\cite{Etnyre_OT} and then also the surgered manifolds are contactomorphic.
\end{proof}

