We start with a general formula that relates $F$ of knots that differ by twisting $5$ strands, where $3$ of these strands are oriented in one direction and the other $2$ strands are oriented in the other direction.

For all $n\in\N_0$, note that the $K_n$ are outside of a $3$-ball $B$ identical and inside $B$ have $5$ strands performing $n$-full twists, oriented as shown in Figure~\ref{fig:5strands}. For $i=1,\ldots, 10$, let $J_i$ be the links that are outside of $B$ the same as $K_n$ but are inside $B$ as shown in Figure~\ref{fig:Ji}.
\begin{lem}\label{lem:5twist}
For $n\geq1$ and $i\in\{1,\ldots, 10\}$ the $F$ polynomials of $K_n, J_i$, and $K_{n-1}$ are related by
\begin{align*}
	F_{K_n}=\,&v^2\big(F_{J_1} - F_{J_2} +F_{J_3} -F_{J_4} \big) + \big(-F_{J_5} +F_{J_6} -F_{J_7} +F_{J_8} -F_{J_9} \big) - v^{-2} F_{J_{10}} \\&+ v^{-4} F_{K_{n-1}}.
\end{align*}	
\end{lem}

\begin{proof}
		For the crossings $c_1,\ldots, c_{10}$ in $K_n$ as marked in Figure~\ref{fig:5strands} we define for $i=1,\ldots, 10$ the knot $K_n^i$ to be the knot obtained from $K_n$ by changing all crossings $c_j$ for $j\leq i$. We observe that $K_n^{10}=K_{n-1}$ and we set $K_n^0=K_n$.
		Moreover, the links $J_i$ are $2$-component links obtained from $K_n$ by changing all crossings $c_j$ for $j>i$ and resolving the crossing $c_i$.
		By appealing to the Skein tree in Figure \ref{fig:skeintree} 
        we get the claimed formula.
\end{proof}

\begin{rem}\hfill
\begin{enumerate}
    \item The lemma also holds for $K_n', J_i'$, defined analogously. In fact, it holds for any sequence of knots $K_n$ that differ by twisting $5$-strands as shown in Figure~\ref{fig:5strands}.
    \item 	We get a similar formula for negative twists by using the mirror formula for $F_L$, i.e.\ $F_{-L}(v)=F_L(v^{-1})$, where $-L$ denotes the mirror of $L$.
\end{enumerate}
\end{rem}

