\begin{proof}
	Any crossing $c$ in the twist region of $K_n$ is negative. By changing $c$ we get $K_{n-1}$ and its resolution is isotopic to $Z$. Thus the skein relation of $F$ yields
	\begin{align*}
		F_{K_n}=-F_Z+v^{-2}F_{K_{n-1}}
	\end{align*}
	and then induction implies the claimed formula.
\end{proof}

\begin{lem}\label{lem:2twist_all_up}
		For $n\in\N_0$, let $K_n$ be the infinite family of knots that are outside of a $3$-ball $B$ identical and inside $B$ have $2$ strands performing $n$-full twists, oriented in the same direction as shown in Figure~\ref{fig:2strands_all_up}. Let $X\cup Y$ be the $2$-component link with components $X$ and $Y$ that is outside of $B$ the same as $K_n$ but inside $B$ as shown in Figure~\ref{fig:2strands_all_up}.
	For $n\geq1$, their $F$ polynomials are related by
	\begin{align*}
		F_{K_n}=\,& (v^{-2}-1) n v^{2n} v^{2\lk(X,Y)} F_X F_Y+ v^{2n} F_{K_{0}}.
	\end{align*}	
\end{lem}

\begin{figure}[t] 
	\centering
	\def\svgwidth{0,4\columnwidth}
	\input{2strands_all_up.pdf_tex}
	\caption{The knot $K_n$ and the $2$-component link $X\cup Y$.}
	\label{fig:2strands_all_up}
\end{figure}

\begin{proof}
	Any crossing $c$ in the twist region of $K_n$ is positive. By changing $c$ we get $K_{n-1}$ and its resolution is isotopic to the $2$-component link $X\cup Y$ with an additional $(n-1)$-twists between the components $X$ and $Y$. Thus the skein relation of $F$ and the linking number formula yields
	\begin{align*}
		F_{K_n}=(v^{-2}-1)v^{2n}v^{2\lk(X,Y)}F_XF_Y+v^{2}F_{K_{n-1}}
	\end{align*}
	and then induction implies the claimed formula.
\end{proof}

\begin{lem}\label{lem:3twist}
	For $n\in\N_0$, let $K_n$ be the infinite family of knots that are outside of a $3$-ball $B$ identical and inside $B$ have $3$ strands performing $n$-full twists, oriented as shown in Figure~\ref{fig:3strands}. Let $U$, $V$ and $L_{n-1}$ be the links that are outside of $B$ the same as $K_n$ but are inside $B$ as shown in Figure~\ref{fig:3strands}.
	For $n\geq1$, their $F$ polynomials are related by
	\begin{align*}
		F_{K_n}=\,&v^2 F_{L_{n-1}} -v^2 F_U -F_V + v^{-2} F_{K_{n-1}}.
	\end{align*}	
\end{lem}

