	\centering
	\def\svgwidth{0,55\columnwidth}
	\input{3strands.pdf_tex}
	\caption{The knot $K_n$ with three marked crossings $c_1$, $c_2$, and $c_3$ and the $2$-component links $L_{n-1}$, $U$, and $V$.}
	\label{fig:3strands}
\end{figure}

\begin{rem}
	In general, the link $L_{n-1}$ depends again on $n$. But since $L_{n-1}$ is a $2$-component link, we can use the linking number formula to reduce the computation of $F_{L_{n-1}}$ to the computation of $F$ of the components of $L_{n-1}$, which can be done with Lemmas~\ref{lem:2twist_all_up} and~\ref{lem:2twist_one_up_one_down}. We refer to Section~\ref{sec:J1} for examples.
\end{rem}

\begin{proof}[Proof of Lemma~\ref{lem:3twist}]
	For the crossings $c_1$, $c_2$, and $c_{3}$ in $K_n$ as marked in Figure~\ref{fig:3strands} we define for $i=1,2,3$ the knot $K_n^i$ to be the knot obtained from $K_n$ by changing all crossings $c_j$ for $j\leq i$. We observe that $K_n^{3}=K_{n-1}$ and we set $K_n^0=K_n$.
	Moreover, we check similarly as in the proof of Lemma~\ref{lem:5twist} that the resolutions of these crossings yield the links $L_{n-1}$, $U$, and $V$. Then we get by successively applying the skein relation of $F$ to the crossing $c_{i+1}$ in $K_n^i$, the claimed formula.
\end{proof}

\begin{lem}\label{lem:4twist}
	For $n\in\N_0$, let $K_n$ be the infinite family of knots that are outside of a $3$-ball $B$ identical and inside $B$ have $4$ strands performing $n$-full twists, oriented as shown in Figure~\ref{fig:4strands}. For $i=1,\ldots, 6$, let $I_i$ be the links that are outside of $B$ the same as $K_n$ but are inside $B$ as shown in Figure~\ref{fig:4strands}.
	For $n\geq1$, their $F$ polynomials are related by
	\begin{align*}
		F_{K_n}=\,&-F_{I_1} + F_{I_2} -F_{I_3} +F_{I_4}  -F_{I_5}  - v^{-2} F_{I_{6}} + v^{-4} F_{K_{n-1}}.
	\end{align*}	
\end{lem}

