	\centering
	\def\svgwidth{0,9\columnwidth}
	\input{4strands.pdf_tex}
	\caption{The knot $K_n$ with six marked crossings and the $2$-component links $I_1,\ldots ,I_6$.}
	\label{fig:4strands}
\end{figure}

\begin{proof}
	As in the proof of Lemma~\ref{lem:5twist} and~\ref{lem:3twist}, we consider the crossings $c_1,\ldots, c_{6}$ in $K_n$ as marked in Figure~\ref{fig:4strands}. Then we check that with the same notation as there, the links $I_i$ are given by the resolutions and thus the skein relation implies the formula for $F$.
\end{proof}

\subsection{Computation of \texorpdfstring{$J_1$}{J1}}\label{sec:J1}

Using the formulas from Lemmas~\ref{lem:2twist_one_up_one_down}-\ref{lem:4twist} we can compute the $F$ polynomials of the links $J_i$ and $J'_i$. We have suppressed the computations for $i>1$; 
they work analogously. In the rest of this section, $n$ is always a positive number.

\begin{lem}
	The family of links $J_1=J_1^n$ shown in Figure~\ref{fig:J1A1} have 
	{\scriptsize
	\begin{align*}
		F_{J_1}=&\,(v^{-2}-1)\big( 1 + v^{-2n+2} -v^{-2n} -v^{-2n-2} + v^{-2n-4} -(n-2) v^{-4n+6} +(n-3)v^{-4n+4} \\&+(6n-2) v^{-4n+2} -(14n-4) v^{-4n} +11nv^{-4n-2} -(3n+1)v^{-4n-4}  \big).
	\end{align*}}
\end{lem}

\begin{figure}[t] 
	\centering
	\def\svgwidth{0,65\columnwidth}
	\input{J1A1.pdf_tex}
	\caption{Left: the $2$-component link $J_1^n$, consisting of the two components $B^1$ and $A^1_n$. Right: A diagram of $A^1_n$.}
	\label{fig:J1A1}
\end{figure}

\begin{proof}
	In Figure~\ref{fig:J1A1} we see that $J_1^n$ consists of two components: the component $B^1$ which is an unknot and the component $A^1_n$ shown in Figure~\ref{fig:J1A1}. Their linking number is $\lk(A^1_n,B^1)=0$, and thus the linking number formula implies that $F_{J_1^n}=(v^{-2}-1)F_{A^1_n}$. Therefore, the claim follows from the following lemma. 
\end{proof}

\begin{lem}
	The family of knots $A_1^n$ shown in Figure~\ref{fig:J1A1} have 
	{\scriptsize
		\begin{align*}
			F_{A_1^n}=&\,\ 1 + v^{-2n+2} -v^{-2n} -v^{-2n-2} + v^{-2n-4} -(n-2) v^{-4n+6} +(n-3)v^{-4n+4} \\&+(6n-2) v^{-4n+2} -(14n-4) v^{-4n} +11nv^{-4n-2} -(3n+1)v^{-4n-4}  .
	\end{align*}}
\end{lem}

\begin{proof}
	First, we use sage to compute 
	\begin{align*}
		F_{A^1_0}=\,&2v^6-3v^4-v^2+4-v^{-2}.
	\end{align*}	
	Then we can apply Lemma~\ref{lem:4twist} to the family of knots $A_1^n$ to see that
		\begin{align*}
		F_{A^1_n}=\,&-F_{I_1} + F_{I_2} -F_{I_3} +F_{I_4}  -F_{I_5}  - v^{-2} F_{I_{6}} + v^{-4} F_{A^1_{n-1}}.
	\end{align*}	
In Lemmas~\ref{lem:I1}--\ref{lem:I6} we compute $F_{I_i}$. If we plug in the values for $F_{I_i}$ we get 
\begin{align*}
	F_{A^1_n}=\,&X+v^{-2n}Y+v^{-4n}Z + v^{-4} F_{A^1_{n-1}},
\end{align*}	
with polynomials	
	\begin{align*}
		X&=1-v^{-4}\\
		Y&=v^2-2+2v^{-4}-v^{-6}\\
		Z&=-v^6+v^4+6v^2-14+11v^{-2}-3v^{-4}.
\end{align*}
Thus Lemma~\ref{lem:ana1} implies that 
	\begin{align*}
		F_{A^1_n}=1-v^{-4n}+Yv^{-2n}\frac{1-v^{-2n}}{1-v^{-2}}+nZv^{-4n}+v^{-4n}F_{A^1_0}.
\end{align*}
Plugging in the above values yields the claimed formula for $F_{A^1_n}$.	
\end{proof}

\begin{lem} \label{lem:I1}
	Let $I^n_1$ be the family of knots shown in Figure~\ref{fig:Ii} then we have 
		\begin{align*}
			F_{I^n_1}=(v^{-2}-1)v^{-2n-2}\,\big( v^2-1+v^{-2}  \big).
	\end{align*}
\end{lem}

\begin{proof}
	In Figure~\ref{fig:Ii} we see that $I_1$ consists of two knots $X^1$ and $Y^1$, that have linking number $\lk(X^1,Y^1)=-n-1$. It is also straightforward to check that $X^1$ is an unknot and $Y^1$ is the figure eight knot with $F_{Y^1}=v^2-1-v^{-2}$. Thus the linking number formula for $F$ implies the result.
\end{proof}

\begin{lem}
	Let $I^n_2$ be the family of knots shown in Figure~\ref{fig:Ii} then we have 
		\begin{align*}
			F_{I^n_2}=(v^{-2}-1)v^{2-2n}\,\big( 1+v^{-2n}(2v^2-6+6v^{-2}-2v^{-4})\big).
	\end{align*}
\end{lem}

\begin{proof}
	From Figure~\ref{fig:Ii} we deduce that $I^n_2$ consist of an unknot $Y^2$ and a knot $X^2_n$ that have linking number $\lk(X^2_n,Y^2)=1-n$. Thus $F_{I^n_2}=(v^{-2}-1)v^{2-2n}F_{X^2_n}$. The $F$ polynomial of $X_n^2$ can be computed using Lemma~\ref{lem:3twist}. In the notation of that lemma, we see that $L_{n-1}$ is a $2$-component link consisting of two unknots that have vanishing linking numbers and thus, independent of $n$, we have $F_{L_{n-1}}=v^{-2}-1$. Moreover, we compute 
	\begin{align*}
		F_U&=(v^{-2}-1)v^2(v^{-2}+v^{-4}-v^{-6})\\
		F_V&=(v^{-2}-1)v^{-2}.
	\end{align*}
Thus Lemma~\ref{lem:3twist} implies that 
\begin{align*}
	F_{X^2_n}=-(v^{-2}-1)+v^{-2}F_{X_{n-1}^2}
\end{align*}
and induction yields
\begin{align*}
	F_{X^2_n}=1-v^{-2n}+v^{-2n}F_{X_0^2}.
\end{align*}
By computing $F_{X^2_0}=2v^2-5+6v^{-2}-2v^{-4}$ and plugging everything into the formula for $F_{I_2}$ we get the claimed result.
\end{proof}

\begin{lem}
	Let $I^n_3$ be the family of knots shown in Figure~\ref{fig:Ii} then we have 
		\begin{align*}
			F_{I^n_3}=(v^{-2}-1)\,\big( 1+v^{-2n}(v^2-1-v^{-2}+v^{-4})  \big).
	\end{align*}
\end{lem}

\begin{proof}
	In Figure~\ref{fig:Ii} we observe that $I_3$ consists of an unknot $Y^3$ that has vanishing linking number with the other component $X^3_n$ and thus $F_{I_3^n}=(v^{-2}-1)F_{X_n^3}$. We compute $F_{X^3_n}$ with the help of Lemma~\ref{lem:2twist_one_up_one_down}. In the notation of that lemma, we observe that $Z$ is a $2$-component unlink with $F_Z=v^{-2}-1$ and we compute $F_{X_0^3}=v^2-v^{-2}+v^{-4}$. Putting all this together yields the claimed result.
\end{proof}

\begin{lem}
	Let $I^n_4$ be the family of knots shown in Figure~\ref{fig:Ii} then we have 
		\begin{align*}
			F_{I^n_4}=(v^{-2}-1)v^{2-2n}\,\big( (v^{2-2n}-1)(-v^2+v^{-4}-v^{-6})+v^{2-2n}(2v^2-2+v^{-4})  \big).
	\end{align*}
\end{lem}

\begin{proof}
	In Figure~\ref{fig:Ii} we observe that $I^n_4$ consist of an unknot $Y^4$ and a knot $X^4_n$ that have linking number $\lk(X^4_n,Y^4)=1-n$. Thus $F_{I^n_4}=(v^{-2}-1)v^{2-2n}F_{X^4_n}$. The $F$ polynomial of $X_n^4$ can be computed using Lemma~\ref{lem:3twist}. In the notation of that lemma, we see that $L_{n-1}$ is a $2$-component link consisting of two unknots that have linking number $\lk=-1$ and thus independent of $n$, we have $F_{L_{n-1}}=(v^{-2}-1)v^{-2}$. Moreover, we compute 
	\begin{align*}
		F_U&=(v^{-2}-1)v^{-4}(v^{2}-v^{-2}+v^{-4})\\
		F_V&=(v^{-2}-1)v^{2}.
	\end{align*}
	Thus Lemma~\ref{lem:3twist} implies that 
	\begin{align*}
		F_{X^4_n}=(v^{-2}-1)(-v^2+v^{-4}-v^{-6})+v^{-2}F_{X_{n-1}^4}
	\end{align*}
	and induction yields
	\begin{align*}
		F_{X^4_n}=(v^{-2n}-1)(-v^2+v^{-4}-v^{-6})+v^{-2n}F_{X_0^4}.
	\end{align*}
	By computing $F_{X^4_0}=2v^2-2+v^{-4}$ and plugging everything into the formula for $F_{I_4}$ we get the claimed result.
\end{proof}

\begin{lem}
	Let $I^n_5$ be the family of knots shown in Figure~\ref{fig:Ii} then we have 
		\begin{align*}
			F_{I^n_5}=(v^{-2}-1)v^{6-2n}\,\big( v^{-2}+v^{-4}-v^{-6}  \big).
	\end{align*}
\end{lem}

\begin{proof}
	The components $X^5$ and $Y^5$ of the link $I_5^n$ have linking number $\lk(X^5,Y^5)=3-n$. $Y^5$ is an unknot, while $F_{X^5}=v^{-2}+v^{-4}-v^{-6}$ and thus the linking number formula for $F$ implies the lemma.
\end{proof}

\begin{lem} \label{lem:I6}
	Let $I^n_6$ be the family of knots shown in Figure~\ref{fig:Ii} then we have 
		\begin{align*}
			F_{I^n_6}=v^{-2}-1.
	\end{align*}
\end{lem}

\begin{proof}
	$I^n_6$ is a $2$-component unlink and thus $F_{I^n_6}=v^{-2}-1$.
\end{proof}

