\title[Toeplitz factors]{On the minimum number of Toeplitz factors of a matrix}

\author[Garc\'ia-Marco]{Ignacio Garc\'ia-Marco}
\author[M\'arquez-Corbella]{Irene M\'arquez-Corbella}
