\begin{remark}
The reason the structure isomorphisms of the $\op$-monoidal structure having the domain and codomain in a different direction that for the $\ot$-monoidal structure is due to how these inferences are proved in multiplicative linear logic and the graphical language associated with LDCs \cite{Blute_Cockett_Seely_Trimble_1996}. The $\op$-unitors and $\op$-associator arise more ``naturally'' in the direction chosen and are in agreement with the notation introduced in Cockett and Seely's later work with Koslowski on linear bicategories \cite{Cockett_Koslowski_Seely_2000}. 
\end{remark}

\begin{definition}\cite[Sec 3]{Cockett_Seely_1997_LDC}\label{def:SLDC}
A linearly distributive category $(\bX,\ot,\top,\op,\bot)$ is {\bf symmetric} if 
\begin{itemize}
    \item $(\bX, \ot, \top)$ is a symmetric monoidal category with $\ot$-braiding \[ \sigma_\ot\c \ot\Rarr switch_{\bbX,\bbX};\ot \qquad{\sigma_\ot}_{A, B}\c A\ot B\rarr B\ot A \]
    \item $(\bX,\op,\bot)$ is a symmetric monoidal category with $\op$-braiding \[ \sigma_\op\c \op\Rarr switch_{\bbX, \bbX};\op \qquad {\sigma_\op}_{A, B}\c A\op B\rarr B\op A \]
\end{itemize}
such that the linear distributivities interact coherently with the braidings \eqref{cc:lin_dist_braiding}. 
\begin{equation}\begin{gathered}\label{cc:lin_dist_braiding}
\xymatrixrowsep{1.75pc}\xymatrixcolsep{2.75pc}\xymatrix@L=0.5pc{
(A\op B) \ot C\ar[r]^-{\delta^R_{A,B,C}} \ar[d]_-{{\sigma_\ot}_{A\op B, C}} & A\op (B\ot C) \\
C\ot (A\op B)\ar[d]_-{1_{C} \ot {\sigma_\op}_{A,B}} & (B\ot C) \op A\ar[u]_-{{\sigma_\op}_{B\ot C, A}}\\
C\ot (B\op A)\ar[r]_-{\delta^L_{C,B,A}} & (C\ot B)\op A \ar[u]_-{{\sigma_\ot}_{C,B}\op 1_{A}} 
}
\end{gathered}\end{equation}

% \begin{align}\label{eq:lin_dist_braiding}
% \delta^R_{A,B,C} = {\sigma_\ot}_{A\op B, C} ; (1_{C} \ot {\sigma_\op}_{A,B}) ; \delta^L_{C,B,A} ; ( {\sigma_\ot}_{C,B}\op 1_{A}) ; {\sigma_\op}_{B\ot C, A}
% \end{align} 
\end{definition}

Many models of multiplicative linear logic, in particular the ones we are interested in, also satisfy an additional rule: the binary MIX rule $A\ot B \vdash A\op B$. With the cut rule present, satisfying the binary MIX rule is equivalent to satisfying the nullary MIX rule $\bot \vdash \top$. In terms of LDCs, this amounts to the existence of a map $m\c \bot\rarr\top$ such that the two possible induced maps $A\ot B\rarr A\op B$ are equal. This map will be essential to the following discussions.

\begin{definition}{\cite[Def 6.2]{Cockett_Seely_1997}}
A linearly distributive category \bX\ is {\bf mix} if there is a morphism $m\c\bot\rarr\top$ such that 
\begin{equation}\begin{gathered}\label{cc:mix_LDC}
\xymatrixrowsep{1.75pc}\xymatrixcolsep{2.75pc}\xymatrix@L=0.5pc{
A\ot B\ar[r]^-{1_A\ot {u^L_\op}_B^{-1}}\ar[d]_-{{u^R_\op}_A^{-1}\ot 1_B}& A\ot (\bot \op B)\ar[r]^-{1_A\ot(m\op 1_B)} & A\ot (\top \op B)\ar[d]^-{\delta^L_{A, \top, B}} \\
(A\op \bot)\ot B\ar[d]_-{(1_A\op m)\ot 1_B} & & (A\ot \top)\op B \ar[d]^-{{u^R_\ot}_A^{-1}\op 1_B} \\
(A\op \top)\ot B \ar[r]_-{\delta^R_{A,\top,B}} & A\op (\top \ot B)\ar[r]_-{1_A\op {u^L_\ot}_B^{-1}} & A\op B
}
\end{gathered}\end{equation}
\end{definition}

