% & (A^\perp \ot (\bot\op A))\op (B\op A)^\perp \xrightarrow{(1_{A^\perp}\ot {u^L_\op}_A) \op 1_{(B\op A)^\perp}} (A^\perp \ot A)\op (B\op A)^\perp \xrightarrow{{\gamma_\ot}_{A^\perp, A}\op 1_{(B\op A)^\perp}} (A\ot A^\perp)\op (B\op A)^\perp \xrightarrow{\gamma^R_A\op 1_{(B\op A)^\perp}} \\
% &\bot\op(B\op A)^\perp \xrightarrow{{u^L_\op}_{(B\op A)^\perp}} (B\op A)^\perp
% \end{align*}
% \end{lemma}

\begin{theorem}\cite[Thm 4.5]{Cockett_Seely_1997_LDC}\label{thm:SLDC_starauto}
The notions of symmetric linearly distributive categories with negation and $*$-autonomous categories coincide.
\end{theorem}

\begin{example}\label{ex:LDC} Let us list three important class of examples of LDCs.
\begin{enumerate}
    \item Every monoidal category $(\cX, \os, I)$ can be viewed as a linearly distributive category, when taking the tensor and par structures to be equal to the original monoidal structure, i.e. $\ot=\op=\os$ and $\top= \bot = I$. In this case, the linear distributivities are just $\os$-associators. We call such LDCs $(\cX, \os, I, \os, I)$ {\bf degenerate}.

    \item By Theorem \ref{thm:SLDC_starauto}, every $*$-autonomous category $(\cX, \os, I, \star)$ is a linearly distributive category, with the tensor structure given by the original monoidal structure and the par structure given by the de Morgan dual, i.e. $A \op B = (B^\star \os A^\star)^\star$ and $\bot = I^\star$.  Some notable examples of $*$-autonomous categories include the category of finite-dimensional vector spaces, the category of sup-lattices, the category of coherence spaces and the category of finiteness spaces. 

    \item Cockett and Seely introduced a class of examples known as {\bf shifted tensor} LDCs in \cite{Cockett_Seely_1992}. These are the categorical analogue of shift monoids and are defined as follows.

    \begin{definition}\cite[Sec 5.2]{Cockett_Seely_1999}
        Consider a monoidal category $(\bX, \ot, \top)$. An object $\bot\in\bX$ is said to have a {\bf tensor inverse} if there is an object $\bot^{-1}$ equipped with two isomorphisms 
        \[ s^L\c\bot \ot \bot^{-1}\rarr\top \qquad s^R\c \bot^{-1}\ot\bot\rarr\top\]
        such that 

    \begin{equation*}\begin{gathered}
    \xymatrixrowsep{1.75pc}\xymatrixcolsep{2.75pc}\xymatrix@L=0.5pc{
    (\bot^{-1}\ot \bot) \ot \bot^{-1} \ar[rr]^-{{\alpha_\ot}_{\bot^{-1},\bot, \bot{-1}}} \ar[d]_-{s^R\ot 1_{\bot^{-1}}}& &\bot^{-1}\ot(\bot\ot\bot^{-1}) \ar[d]^-{1_{\bot^{-1}}\ot s^L}\\
    \top\ot\bot^{-1}\ar[rd]_-{{u^L_\ot}^{-1}_{\bot^{-1}}} & & \bot^{-1}\ot \top \ar[ld]^-{{u^R_\ot}^{-1}_{\bot^{-1}}}\\
    & \bot^{-1}
    }
    \end{gathered}\end{equation*}

    Suppose there is an object $\bot\in\bX$ with a tensor inverse, then define a monoidal product by $A\op B = A\ot (\bot^{-1}\ot B)$, known as the {\bf $\bot$-shifted tensor}. 
    \end{definition}    

    \begin{proposition}\cite[Prop 5.3, 5.4]{Cockett_Seely_1992}\label{prop:shift_tensor}
        Consider a monoidal category $(\bX, \ot, \top)$ with an object $\bot\in\bX$ with a tensor inverse, then $(\bX, \ot, \top, \op,\bot)$, where $\op$ is the $\bot$-shifted tensor, is a linearly distributive category with invertible linear distributivities. Moreover, every linearly distributive categories with invertible linear distributivities has a tensor inverse for $\bot$ whose shift tensor product is naturally equivalent to the parr product. 
    \end{proposition}

\end{enumerate}
\end{example}

\subsection{Linear Functors and Transformations}  \hfill\

\vspace{0.5\baselineskip}
In the same spirit as the Fox theorem, we will need the appropriate notions of functors and transformations between linearly distributive categories. 

\begin{definition}\cite[Def 1]{Cockett_Seely_1999}
Let \bX\ and \bY\ be linearly distributive categories. A {\bf linear functor} $F = (F_\ot, F_\op)\c\bX\rarr\bY$ consists of:
\begin{itemize}
\item a monoidal functor $(F_\ot, m_\top, m_\ot)\c(\bX,\ot,\top)\rarr(\bY,\ot,\top)$, equipped with
    \begin{itemize}
	\item a morphism $m_\top\c\top\rarr F_\ot(\top)$,
	\item a natural transformation 
    \begin{align*}
    &m_\ot\c (F_\ot\times F_\ot);\ot \Rarr \ot; F_\ot & {m_\ot}_{A, B}\c F_\ot(A)\ot F_\ot(B)\rarr F_\ot(A\ot B)
    \end{align*}
    \end{itemize}
\item a comonoidal functor $(F_\op, n_\bot, n_\op)\c(\bX,\op,\bot)\rarr(\bY,\op,\bot)$, equipped with
    \begin{itemize}
	\item a morphism $n_\bot\c F_\op(\bot)\rarr\bot$,
	\item a natural transformation 
    \begin{align*}
    &n_\op\c \op;F_\op \Rarr (F_\op\times F_\op);\op  & {n_\op}_{A,B}\c F_\op(A\op B)\rarr F_\op(A)\op F_\op(B)
    \end{align*}
    \end{itemize}
\item four natural transformations, known as {\bf linear strengths}, 
\begin{align*}
&v_\ot^R\c \op; F_\ot \Rarr (F_\op \times F_\ot); \op & {v_\ot^R}_{A,B} \c F_\ot(A\op B)\rarr F_\op(A)\op F_\ot(B)\\
&v_\ot^L\c \op; F_\ot \Rarr (F_\ot \times F_\op); \op & {v_\ot^L}_{A,B} \c F_\ot(A\op B)\rarr F_\ot(A)\op F_\op(B)\\
&v_\op^R\c (F_\ot\times F_\op);\ot \Rarr \ot; F_\op & {v_\op^R}_{A,B} \c F_\ot(A)\ot F_\op(B)\rarr F_\op(A\ot B)\\
&v_\op^L\c (F_\op\times F_\ot);\ot \Rarr \ot; F_\op & {v_\op^L}_{A,B} \c F_\op(A)\ot F_\ot(B)\rarr F_\op(A\ot B)
\end{align*}
\end{itemize}
subject to various coherence conditions determining the interaction of the linear strengths with the units \eqref{cc:linear_strength_unit}, with the associativities \eqref{cc:linear_strength_assoc}, with the linear distributivities \eqref{cc:linear_strength_dist}, and with other linear strengths via associators \eqref{cc:linear_stregnth_assoc_linear_strength} and via linear distributivities \eqref{cc:linear_stregnth_dist_linear_strength}.

\begin{equation}\begin{gathered}\label{cc:linear_strength_unit}
\xymatrixrowsep{1.75pc}\xymatrixcolsep{2.75pc}\xymatrix@L=0.5pc{
F_\ot(\bot\op A)\ar[r]^-{F_\ot({u^L_\op}_A)}\ar[d]_-{{\nu^R_\ot}_{\bot, A}} & F_\ot(A) \\
F_\op(\bot) \op F_\ot(A)\ar[r]_-{n_\bot \op 1_{F_\ot(A)}} & \bot \op F_\ot(A)\ar[u]_-{{u^L_\op}_{F_\ot(A)}} 
}
\end{gathered}\end{equation}
\begin{align*}
&{\nu^R_\ot}_{\bot, A}; (n_\bot \op 1_{F_\ot(A)}); {u^L_\op}_{F_\ot(A)} = F_\ot({u^L_\op}_A) \\
&{\nu^L_\ot}_{A, \bot}; (1_{F_\ot(A)}\op n_\bot); {u^R_\op}_{F_\ot(A)} = F_\ot({u^R_\op}_A)\\
&{u^L_\ot}_{F_\op(A)};(m_\top \ot 1_{F_\op(A)}); {\nu^R_\op}_{\top, A} = F_\op({u^L_\ot}_A)\\
&{u^R_\ot}_{F_\op(A)};( 1_{F_\op(A)}\ot m_\top); {\nu^L_\op}_{\top, A} = F_\op({u^R_\ot}_A)
\end{align*}

\begin{equation}\begin{gathered}\label{cc:linear_strength_assoc}
\xymatrixrowsep{1.75pc}\xymatrixcolsep{2.75pc}\xymatrix@L=0.5pc{
F_\ot(A\op (B\op C))\ar[r]^-{F_\ot({\alpha_\op}_{A,B,C})}\ar[d]_-{{\nu^R_\ot}_{A, B\op C}} &F_\ot((A\op B)\op C)\ar[d]^-{{\nu^R_\ot}_{A\op B, C}} \\
F_\op(A)\op F_\ot(B\op C)\ar[d]_-{1_{F_\op(A)}\op {\nu^R_\ot}_{B, C}} & F_\op(A\op B) \op F_\ot(C)\ar[d]^-{{n_\op}_{A,B}\op 1_{F_\ot(C)}}\\
 F_\op(A) \op (F_\op(B) \op F_\ot(C))\ar[r]_*+<1em>{_{{\alpha_\op}_{F_\op(A), F_\op(B), F_\ot(C)}}} & (F_\op(A)\op F_\op(B)) \op F_\ot(C)
}
\end{gathered}\end{equation}
\begin{align*}
&{\nu^R_\ot}_{A,B\op C}; (1_{F_\op(A)}\op {\nu^R_\ot}_{B,C});{\alpha_\op}_{F_\op(A), F_\op(B), F_\ot(C)} = F_\ot({\alpha_\op}_{A,B,C}); {\nu^R_\ot}_{A\op B, C}; ({n_\op}_{A,B}\op 1_{F_\ot(C)}) \\
&{\nu^L_\ot}_{A,B\op C}; (1_{F_\ot(A)}\op {n_\op}_{B, C});{\alpha_\op}_{F_\ot(A), F_\op(B), F_\op(C)} = F_\ot({\alpha_\op}_{A,B,C}); {\nu^L_\ot}_{A\op B, C}; ({\nu^L_\op}_{A,B}\op 1_{F_\op(C)})\\
&{\alpha_\ot}_{F_\ot(A), F_\ot(B), F_\op(C)}; (1_{F_\ot(A)} \ot {\nu^R_\op}_{B,C}); {\nu^R_\op}_{A, B\ot C} = ({m_\ot}_{A,B} \ot 1_{F_\op(C)}); {\nu^R_\op}_{A\ot B, C}; F_\op({\alpha_\ot}_{A, B, C})  \\
& {\alpha_\ot}_{F_\op(A), F_\ot(B), F_\ot(C)};(1_{F_\op(A)}\ot {m_\ot}_{B,C}); {\nu^L_\op}_{A, B\ot C}= ({\nu^L_\op}_{A,B}\ot 1_{F_\ot(C)}); {\nu^R_\op}_{A\ot B, C}; F_\op({\alpha_\ot}_{A,B,C})
\end{align*}

\begin{equation}\begin{gathered}\label{cc:linear_strength_dist}
\xymatrixrowsep{1.75pc}\xymatrixcolsep{2.75pc}\xymatrix@L=0.5pc{
F_\ot(A\op B) \ot F_\ot(C)\ar[d]_-{{\nu^R_\ot}_{A,B} \ot 1_{F_\ot(C)}}\ar[r]^-{{m_\ot}_{A\op B, C}} & F_\ot((A\op B)\ot C)\ar[d]^-{F_\ot(\delta^R_{A,B,C})} \\
(F_\op(A) \op F_\ot(B)) \ot F_\ot(C) \ar[d]_-{\delta^R_{F_\op(A), F_\ot(B), F_\ot(C)}} & F_\ot(A\op (B\ot C)) \ar[d]^-{{\nu^R_\ot}_{A, B\ot C}}\\
F_\op(A) \op (F_\ot(B) \ot F_\ot(C))\ar[r]_-{1_{F_\op(A)}\op {m_\ot}_{B,C}} & F_\op(A) \op F_\ot(B\ot C)
}
\end{gathered}\end{equation}
\begin{align*}
&{m_\ot}_{A\op B, C}; F_\ot(\delta^R_{A,B,C}); {\nu^R_\ot}_{A, B\ot C}  = ({\nu^R_\ot}_{A,B} \ot 1_{F_\ot(C)}); \delta^R_{F_\op(A), F_\ot(B), F_\ot(C)}; (1_{F_\op(A)}\op {m_\ot}_{B,C}) \\
&{m_\ot}_{A, B\op C}; F_\ot(\delta^L_{A,B,C}); {\nu^L_\ot}_{A\ot B, C}  = (1_{F_\ot(A)}\ot {\nu^L_\ot}_{B,C}); \delta^R_{F_\ot(A), F_\ot(B), F_\op(C)}; ({m_\ot}_{A,B}\op 1_{F_\op(C)}) \\
& {\nu^R_\op}_{A, B\op C}; F_\op(\delta^L_{A, B, C}); {n_\op}_{A\ot B, C} = (1_{F_\ot(A)} \ot {n_\op}_{B,C}); \delta^L_{F_\ot(A), F_\op(B), F_\op(C)}; ({\nu^R_\op}_{A,B}\op 1_{F_\op(C)}) \\
& {\nu^L_\op}_{A\op B, C}; F_\op(\delta^R_{A, B, C}); {n_\op}_{A, B\ot C} = ({n_\op}_{A,B}\op 1_{F_\ot(C)}); \delta^R_{F_\op(A), F_\op(B), F_\ot(C)}; (1_{F_\op(A)}\op {\nu^L_\op}_{B,C}) \\
\end{align*}

\begin{equation}\begin{gathered}\label{cc:linear_stregnth_assoc_linear_strength}
\xymatrixrowsep{1.75pc}\xymatrixcolsep{2.75pc}\xymatrix@L=0.5pc{
F_\ot(A\op (B\op C))\ar[r]^-{F_\ot({\alpha_\op}_{A,B,C})}\ar[d]_-{{\nu^R_\ot}_{A, B\op C}} & F_\ot((A\op B)\op C)\ar[d]^-{{\nu^L_\ot}_{A\op B, C}} \\
F_\op(A) \op F_\ot(B\op C)\ar[d]_-{1_{F_\op(A)}\op {\nu^L_\ot}_{B,C}} & F_\ot(A\op B)\op F_\op(C)\ar[d]^-{{\nu^R_\ot}_{A, B} \op 1_{F_\op(C)}}\\
 F_\op(A) \op (F_\ot(B) \op F_\op(C))\ar[r]_*+<1em>{_{{\alpha_\op}_{F_\op(A), F_\ot(B), F_\op(C)}}}& (F_\op(A) \op F_\ot(B))\op F_\op(C)
}
\end{gathered}\end{equation}
\begin{align*}
& {\nu^R_\ot}_{A, B\op C}; (1_{F_\op(A)}\op {\nu^L_\ot}_{B,C});{\alpha_\op}_{F_\op(A), F_\ot(B), F_\op(C)} = F_\ot({\alpha_\op}_{A,B,C});{\nu^L_\ot}_{A\op B, C}; ({\nu^R_\ot}_{A, B} \op 1_{F_\op(C)}) \\
& {\alpha_\ot}_{F_\ot(A),F_\op(B), F_\ot(C)}; (1_{F_\ot(A)}\ot {\nu^L_\op}_{B, C}) ; {\nu^R_\op}_{A, B\ot C} = ({\nu^R_\op}_{A, B} \ot 1_{F_\ot(C)}); {\nu^L_\op}_{A\ot B, C}; F_\op({\alpha_\ot}_{A, B, C})
\end{align*}

\begin{equation}\begin{gathered}\label{cc:linear_stregnth_dist_linear_strength}
\xymatrixrowsep{1.75pc}\xymatrixcolsep{2.75pc}\xymatrix@L=0.5pc{
F_\ot(A) \ot F_\ot (B\op C)\ar[r]^-{1_{F_\ot(A)}\ot {\nu^R_\ot}_{B,C}}\ar[d]_-{{m_\ot}_{A, B
\op C}} & F_\ot(A) \ot (F_\op (B) \op F_\ot(C))\ar[d]^-{\delta^L_{F_\ot(A), F_\op(B), F_\ot(C)}} \\
F_\ot(A\ot (B\op C))\ar[d]_-{F_\ot(\delta^L_{A, B, C})} & (F_\ot(A) \ot F_\op(B)) \op F_\ot(C)\ar[d]^-{{\nu^R_\op}_{A,B} \op 1_{F_\ot(C)}} \\
F_\ot((A\ot B)\op C) \ar[r]_-{{\nu^R_\ot}_{A\ot B, C}}& F_\op(A\ot B) \op F_\ot(C)
}
\end{gathered}\end{equation}
\begin{align*}
& {m_\ot}_{A, B\op C}; F_\ot(\delta^L_{A, B, C}); {\nu^R_\ot}_{A\ot B, C} = (1_{F_\ot(A)}\ot {\nu^R_\ot}_{B,C}); \delta^L_{F_\ot(A), F_\op(B), F_\ot(C)}; ({\nu^R_\op}_{A,B} \op 1_{F_\ot(C)})\\
& {m_\ot}_{A\op B, C}; F_\ot(\delta^R_{A, B, C}); {\nu^L_\ot}_{A, B\ot C} = ({\nu^R_\ot}_{A,B}\ot 1_{F_\ot(C)}); \delta^R_{F_\op(A), F_\ot(B), F_\ot(C)}; ({\nu^L_\op}_{A,B} \op 1_{F_\ot(C)})\\
& {\nu^R_\op}_{A\op B, C}; F_\op(\delta^R_{A, B, C}); {n_\op}_{A, B\ot C} = ({\nu^R_\ot}_{A, B}\ot 1_{F_\op(C)}); \delta^R_{F_\op(A), F_\ot(B), F_\op(C)}; (1_{F_\op(A)}\op {\nu^R_\op}_{B, C}) \\
& {\nu^L_\op}_{A, B\op C}; F_\op(\delta^L_{A, B, C}); {n_\op}_{A\ot B, C} = (1_{F_\op(A)} \ot {\nu^L_\ot}_{B, C}); \delta^L_{F_\op(A), F_\ot(B), F_\op(C)}; ({\nu^L_\op}_{A, B}\op 1_{F_\op(C)})
\end{align*}

\vspace{\baselineskip}
\noindent If \bX\ and \bY\ are symmetric linearly distributive categories, then a linear functor $F=(F_\ot, F_\op)$ is {\bf symmetric} if 
\begin{itemize}
    \item $F_\ot\c (\bX, \ot, \top)\rarr(\bY, \ot, \top)$ is a symmetric monoidal functor,
    \item $F_\op\c (\bX, \op, \bot)\rarr(\bY, \op, \bot)$ is a symmetric comonoidal functor, and
    \item the linear strengths interact coherently with the braidings \eqref{cc:linear_strength_braiding}
\end{itemize}
%
\begin{equation}\begin{gathered}\label{cc:linear_strength_braiding}
\xymatrixrowsep{1.75pc}\xymatrixcolsep{2.75pc}\xymatrix@L=0.5pc{
F_\ot(A\op B) \ar[r]^-{{v_\ot^R}_{A,B}}\ar[d]_-{F_\ot({\sigma_\op}_{A,B})} & F_\op(A)\op F_\ot(B) \ar[d]^-{{\sigma_\op}_{F_\op(A), F_\ot(B)}} \\
F_\ot (B\op A) \ar[r]_-{{v_\ot^L}_{B, A}} & F_\ot(B) \op F_\op(A) \\
F_\ot(A)\ot F_\op(B)\ar[r]^-{{v_\op^R}_{A,B}}\ar[d]_-{{\sigma_\ot}_{F_\ot(A),F_\op(B)}} & F_\op(A\ot B)\ar[d]^-{F_\op({\sigma_\ot}_{A,B})}\\
F_\op(B)\ot F_\ot(A)\ar[r]_-{{v_\op^L}_{B,A}} & F_\op(B\ot A)
}
\end{gathered}\end{equation}

\end{definition}

\begin{remark}
In the symmetric case, we can alternatively drop the requirement that the left (or right) linear strengths exist instead of adding \eqref{cc:linear_strength_braiding}. This remains a linear functor as we can always define the missing pair of linear strengths via the braiding. Therefore, when defining symmetric linear functor, we often only give one pair of linear strengths.
\end{remark}

\begin{definition}\cite[Def 3]{Cockett_Seely_1999}\label{def:linear_trans} 
Let $F, G\c\bX\rarr\bY$ be linear functors between linearly distributive categories. A {\bf linear transformation} $\alpha\c F\Rarr G$ consists of:
\begin{itemize}
\item a monoidal transformation $\alpha_\ot\c (F_\ot, m_{\top}^{F}, m_\ot^{F}) \Rarr (G_\ot, m_{\top}^{G}, m_\ot^{G})$ and
\item a comonoidal transformation $\alpha_\op\c (G_\op, n_{\bot}^{G}, n_\op^{G})\Rarr (F_\op, n_{\bot}^{F}, n_\op^{F})$,
\end{itemize}
which commute coherently with the linear strengths of $F$ and $G$ \eqref{cc:linear_trans_linear strength}.
%
\begin{equation}\begin{gathered}\label{cc:linear_trans_linear strength}
\xymatrixrowsep{1.75pc}\xymatrixcolsep{2.75pc}\xymatrix@L=0.5pc{
F_\ot(A\op B) \ar[r]^-{{\alpha_\ot}_{A\op B}} \ar[dd]_-{{v_\ot^R}^{F}_{A,B}} & G_\ot(A\op B)\ar[d]^-{{v_\ot^R}^{G}_{A,B}} \\
& G_\op (A) \op G_\ot(B) \ar[d]^-{{\alpha_\op}_{A}\op 1_{G_\ot(B)}} \\
F_\op(A)\op F_\ot(B)\ar[r]_-{1_{F_\op(A)} \op {\alpha_\ot}_{B}} & F_\op(A) \op G_\ot(B)
}
\end{gathered}\end{equation}
\begin{align*}
&{\alpha_\ot}_{A\op B} ; {v_\ot^R}^{G}_{A,B} ; ({\alpha_\op}_{A} \op 1_{G_\ot (B)}) = {v_\ot^R}^{F}_{A,B} ; (1_{F_\op(A)} \op {\alpha_\ot}_{B})\\
&{\alpha_\ot}_{A\op B} ; {v_\ot^L}^{G}_{A,B} ;  (1_{G_\ot(A)} \op {\alpha_\op}_{B}) = {v_\ot^L}^{F}_{A,B} ; ({\alpha_\ot}_{A}\op 1_{F_\op(B)}) \\
& (1_{G_\op(A)}\ot {\alpha_\ot}_{B}) ; {v_\op^L}^{G}_{A,B} ; {\alpha_\op}_{A\ot B} = ({\alpha_\op}_{A} \ot 1_{F_\ot(B)}) ; {v_\op^L}^{F}_{A,B}\\
& ({\alpha_\ot}_{A} \ot 1_{G_\op(B)}) ; {v_\op^R}^{G}_{A,B} ; {\alpha_\op}_{A\ot B} = (1_{F_\ot(A)}\ot {\alpha_\op}_{B}) ; {v_\op^R}^{F}_{A,B}
\end{align*}
\end{definition}

\begin{proposition}\cite[Prop 4]{Cockett_Seely_1999}\label{prop:2cat_LDC}
Linearly distributive categories, linear functors, and linear transformations form a 2-category, which is denoted by \LDC. Restricting to symmetric linearly distributive categories and symmetric linear functors equally gives a 2-category, denoted $\mathbf{SLDC}$. Both these 2-categories are closed under products. 
\end{proposition}

While not defined in their paper \cite{Cockett_Seely_1999}, it is immediate that we can extend the notion of strong monoidal functors to the context of linear functors:
\begin{definition}
    A linear functor $F\ = (F_\ot, F_\op)\c \bX\rarr\bY$ is {\bf strong} if 
    \begin{itemize}
        \item $F_\ot\c (\bX, \ot, \top)\rarr(\bY, \ot, \top)$ is a strong monoidal functor, and
        \item $F_\op\c (\bX, \op, \bot)\rarr(\bY, \op, \bot)$ is a strong comonoidal functor.
    \end{itemize}
\end{definition}

We will also consider linear functors whose component functors are equal. These were first defined by \cite{Blute_Panangaden_Slanov_2012} and then further explored by \cite{Cockett_Comfort_Srinivasan_2021}.

\begin{definition}\cite[Def 3.1]{Cockett_Comfort_Srinivasan_2021}
Consider linearly distributive categories \bX\ and \bY, a a linear functor $F=(F_\ot,F_\op)\c \bX\rarr\bY$ is {\bf Frobenius} if
\begin{enumerate}
    \item $F_\ot = F_\op$,
    \item ${\nu^R_\ot}_{A,B} = {\nu^L_\ot}_{A,B} = {n_\op}_{A,B}$, and 
    \item ${\nu^R_\op}_{A,B} = {\nu^L_\op}_{A,B} = {m_\ot}_{A,B}$.
\end{enumerate}
\end{definition}

Given the degeneracy, we can give an alternative characterization of such linear functors.
\begin{proposition}\cite[Lem 3.2]{Cockett_Comfort_Srinivasan_2021}
Consider linearly distributive categories \bX\ and \bY, then the following notions coincide:
\begin{itemize}
    \item Frobenius linear functors $F = (F_\ot, F_\op)\c \bX\rarr\bY$, and 
    \item $\ot$-monoidal-$\op$-comonoidal functors $(F, m_\ot, m_\top, n_\op, n_\bot)\c \bX\rarr\bY$ satisfying \eqref{cc:Frobenius_linear_functor}.
\end{itemize}
\begin{equation}\label{cc:Frobenius_linear_functor}
\begin{gathered}\xymatrixrowsep{1.75pc}\xymatrixcolsep{1.75pc}\xymatrix@L=0.5pc{
F(A)\ot F(B\op C)\ar[r]^-{{m_\ot}_{A,B\op C}}\ar[d]_-{1_{F(A)}\ot {n_\op}_{B,C}} & F(A\ot (B\op C))\ar[r]^-{F(\delta^L_{A,B,C})} & F((A\ot B)\op C)\ar[d]^-{{n_\op}_{A\ot B, C}} \\
F(A) \ot (F(B)\op F(C))\ar[r]_-{\delta^L_{F(A), F(B), F(C)}} & (F(A) \ot F(B))\op F(C)\ar[r]_-{{m_\ot}_{A,B}\op 1_{F(C)}} & F(A\ot B)\op F(C) \\
F(A\op B)\ot F(C)\ar[r]^-{{m_\ot}_{A\op B, C}}\ar[d]_-{{n_\op}_{A,B}\ot 1_{F(C)}} & F((A\op B)\ot C)\ar[r]^-{F(\delta^R_{A, B, C})} & F(A\op (B\ot C))\ar[d]^-{{n_\op}_{A, B\ot C}} \\
(F(A)\op F(B))\ot F(C)\ar[r]_-{\delta^R_{F(A), F(B), F(C)}} & F(A)\op (F(B)\ot F(C))\ar[r]_-{1_{F(A)}\op {m_\ot}_{B, C}} & F(A) \op F(B\ot C) 
}
\end{gathered}\end{equation}
\end{proposition}

If the LDCs are mix, the definition of Frobenius linear functors can be slightly extended to guarantee that they preserve the mix maps.
\begin{definition}\cite[Def 3.4]{Cockett_Comfort_Srinivasan_2021}
Consider mix linearly distributive categories \bX\ and \bY, then a Frobenius linear functor $F=(F,F)\c \bX\rarr\bY$ is {\em mix} if the following diagram commutes.
\begin{equation}\label{cc:mix_Frobenius_linear_functor}
\begin{gathered}\xymatrixrowsep{1.75pc}\xymatrixcolsep{1.75pc}\xymatrix@L=0.3pc{
F(\bot)\ar[r]^-{n_\bot}\ar[d]_-{F(m)} & \bot\ar[d]^-{m} \\
F(\top) & \top\ar[l]^-{m_\top}
}
\end{gathered}\end{equation}
\end{definition}

If we then consider linear transformations between Frobenius linear functors, they often correspond a natural isomorphism paired with its inverse.
\begin{lemma}\cite[Lem 3.6]{Cockett_Comfort_Srinivasan_2021}\label{lem:Frobenius_linear_trans_1}
Suppose $F,G\c \bX\rarr\bY$ are Frobenius linear functors and $\alpha=(\alpha_\ot, \alpha_\op)\c F\Rarr G$, then the following are equivalent:
\begin{enumerate}
    \item One of the diagrams in \eqref{cc:Frobenius_linear_trans_unit} and one of the diagrams in \eqref{cc:Frobenius_linear_trans_product} hold.
    \item $\alpha_\op = \alpha^{-1}_\op$
\end{enumerate}
\begin{equation}\label{cc:Frobenius_linear_trans_unit}
\begin{gathered}\xymatrixrowsep{1.75pc}\xymatrixcolsep{2.75pc}\xymatrix{
\top\ar[r]^-{m^G_\top}\ar[rd]_-{m^F_\top} & G(\top)\ar[d]^-{{\alpha_\op}_\top} & F(\bot)\ar[r]^-{n_\bot^F}\ar[d]_-{{\alpha_\ot}_\top} & \bot\ar[dl]^-{n_\bot^G}\\
& F(\top) & G(\bot)
}
\end{gathered}\end{equation}
\begin{equation}\label{cc:Frobenius_linear_trans_product}
\begin{gathered}\xymatrixrowsep{1.75pc}\xymatrixcolsep{1.5pc}\xymatrix@L=0.5pc{
G(A)\ot F(B)\ar[r]^-{1_{G(A)}\ot {\alpha_\ot}_B}\ar[d]_-{{\alpha_\op}_A\ot 1_{F(B)}} & G(A) \ot G(B)\ar[dd]^-{{m_\ot^G}_{A,B}} & F(A)\ot G(B)\ar[r]^-{{\alpha_\ot}_A\ot 1_{G(B)}}\ar[d]_-{1_{F(A)}\ot {\alpha_\op}_B} & G(A)\ot G(B)\ar[dd]^-{{m_\ot^G}_{A,B}}\\
F(A)\ot F(B)\ar[d]_-{{m_\ot^F}_{A,B}} & & F(A)\ot F(B)\ar[d]_-{{m_\ot^F}_{A,B}} & \\
F(A\ot B)\ar[r]_-{{\alpha_\ot}_{A\ot B}} & G(A\ot B) & F(A\ot B)\ar[r]_-{{\alpha_\ot}_{A\ot B}} & G(A\ot B) \\
G(A\op B)\ar[r]^-{{n_\op^G}_{A,B}}\ar[d]_-{{\alpha_\op}_{A\op B}} & G(A) \op G(B)\ar[dd]^-{1_{G(A)}\op {\alpha_\op}_B} & G(A\op B)\ar[r]^-{{n_\op^G}_{A,B}}\ar[d]_-{{\alpha_\op}_{A\op B}} & G(A)\op G(B)\ar[dd]^-{{\alpha_\op}_A\op 1_{G(B)}} \\
F(A\op B)\ar[d]_-{{n_\op^F}_{A,B}} & & F(A\op B)\ar[d]_-{{n_\op^F}_{A,B}} & & \\
F(A)\op F(B)\ar[r]_-{{\alpha_\ot}_A\op 1_{F(B)}} & G(A)\op F(B) & F(A)\op F(B)\ar[r]_-{1_{F(A)}\op {\alpha_\ot}_B} & F(A)\op G(B) 
}
\end{gathered}\end{equation}
\end{lemma}

\begin{lemma}\cite[Lem 3.10]{Cockett_Comfort_Srinivasan_2021}\label{lem:Frobenius_linear_trans_2}
Suppose  $F,G\c \bX\rarr\bY$ are Frobenius linear functors and $\alpha\c F\Rarr G$ is a $\ot$-monoidal and $\op$-comonoidal natural isomorphism, then $(\alpha, \alpha^{-1})\c F\Rarr G$ is a linear transformation.
\end{lemma}

As Frobenius linear functors compose and identity linear functors are Frobenius, restricting to such 1-cells determines a sub-2-category.
\begin{proposition}
Linearly distributive categories, Frobenius linear functors and linear transformations form a sub-2-category of \LDC, denoted by $\mathbf{FLDC}$
\end{proposition}

\subsection{Cartesian Linearly Distributive Categories}  \hfill\

\vspace{0.5\baselineskip}
We now introduce cartesian LDCs, the subclass we are interested in characterizing via the linearly distributive Fox theorem.

\begin{definition}\cite[Sec 2]{Cockett_Seely_1997_LDC}
A {\bf cartesian linearly distributive category} \bX\ is a symmetric linearly distributive category whose tensor $\ot$ is the categorical product $\times$ in \bX, with top $\top$ the terminal object $\bone$ in \bX, and par $\op$ is the categorical coproduct $+$ in \bX, with $\bot$ the initial object $\bzero$ in \bX. 
\end{definition}

The development of the linearly distributive Fox theorem renewed interest in cartesian LDCs, which were further explored in their own right by the author and co-author Jean-Simon Pacaud Lemay in the article ``Cartesian Linearly Distributive Categories Revisited'' \cite{Kudzman-Blais_Lemay_2025}. This work examines the distinctive structures and properties of cartesian LDCs, discusses key classes of examples, and reassesses previously proposed instances of cartesian LDCs. We recommend reading both articles, as they complement each other, though each is designed to be accessible and valuable independently. \\

Cartesian LDCs themselves form a 2-category with the appropriate notion of linear functor as 1-cells, mirroring the strong monoidal functors in the 2-category of cartesian categories.

\begin{proposition}
There is a sub 2-category of \LDC consisting of cartesian linearly distributive categories, strong symmetric linear functors, known as {\bf cartesian linear functors}, and linear transformations, denoted by \CLDC, closed under products. Moreover, there is a sub 2-category of \LDC consisting of cartesian linearly distributive categories, strong symmetric Frobenius linear functors and linear transformations, denoted by $\mathbf{FCLDC}$.
\end{proposition}

\section{Duoidal Categories}\label{sec:duoidal_categories}

Linearly distributive categories are of course not the only categories with two monoidal structures. Duoidal categories represent another variant, characterized by two monoidal products that interact via additional structure maps, most notably the interchange law. Unlike LDCs, the duoidal structure arises canonically when considering finite products and coproducts. The theory of duoidal categories will play a crucial role in the definitions and results presented in this paper, so we present all the necessary background in this section. \\

The earliest appearance of a form of the interchange law between monoidal structures in the literature is found in Joyal and Street's work on braided monoidal categories \cite{Joyal_Street_1993}. They demonstrate that a duoidal category with structure maps that are isomorphisms corresponds to a braided monoidal category via a categorical Eckmann-Hilton argument. Subsequently, Balteanu, Fiedorowicz, Schwänzl, and Vogt defined 2-fold monoidal categories as monoids in the monoidal category of monoidal categories \cite{Balteanu_Fiedorowicz_Schwaenzl_Vogt_2003}. In their definition, the interchange law is not required to be an isomorphism, but the unit objects of both monoidal structures are assumed to coincide, and the monoidal structures themselves are strict. Building on this foundation, Forcey, Siehler, and Sowers generalized the definition by allowing distinct unit objects and non-strict associators, while retaining equalities for unitors and certain structure maps \cite{Forcey_Siehler_Sowers_2007}. \\

The currently accepted definition of duoidal category was first introduced by Aguiar and Mahajan under the name 2-monoidal categories \cite{Aguiar_Mahajan_2010}\footnote{We will refrain from using the 2-monoidal category terminology introduced by Aguiar and Mahajan to avoid confusion with monoidal 2-categories, which are 2-categories with a coherent monoidal structure.}. The background on duoidal categories presented in this section is almost entirely based on Chapter 6 of their monograph, and readers seeking additional details are encouraged to consult it. The now-standard name for duoidal categories was suggested by Street and first appeared in the literature in \cite{Batanin_Markl_2012} and \cite{Booker_Street_2013}.

\subsection{Definition, Symmetry and Examples}  \hfill\

\begin{definition}\cite[Def 6.1]{Aguiar_Mahajan_2010}\label{def:duoidal_cat}
A {\bf duoidal category} $(\cX, \diamond, I,\star, J)$ is category \cX\ with two monoidal structures $(\cX, \diamond, I, \alpha_\diamond, \rho_\diamond, \lambda_\diamond)$ and $(\cX, \star, J, \alpha_\star, \rho_\star, \lambda_\star)$ equipped with morphisms 
\begin{alignat*}{3}
\Delta_{I}  &\c I\rarr I\star I &\qquad  \mu_{J}& \c J\diamond J\rarr J  &\qquad  \iota  & \c I\rarr J
\end{alignat*}
and an {\bf interchange} natural transformation 
\begin{align*}
&\zeta\c (\star \times \star);\diamond \Rarr s_{\ccX,\ccX,\ccX,\ccX}; (\diamond \times \diamond);\star & \zeta_{A, B, C, D}\c (A\star B)\diamond(C\star D)\rarr(A\diamond C)\star(B\diamond D)
\end{align*}
such that 
\begin{itemize}
    \item $(J, \nabla_{J}, \iota)$ is a $\diamond$-monoid,
    \item $(I, \Delta_{I}, \iota)$ is a $\star$-comonoid,
    \item interchange maps interact coherently with associativities \eqref{cc:assoc_interchange} and with unitors \eqref{cc:unit_interchange}.
\end{itemize}
%
\begin{equation}\begin{gathered}\label{cc:assoc_interchange}
\resizebox{0.9\linewidth}{!}{\xymatrixrowsep{1.75pc}\xymatrixcolsep{1.75pc}\xymatrix@L=0.5pc{
((A\star B) \diamond (C\star D)) \diamond (E\star F)\ar[r]^-{{\alpha_\diamond}_{A\star B, C\star D, E\star F}}\ar[d]_-{\zeta_{A, B, C, D}\diamond 1_{E\star F}} & (A\star B) \diamond ((C\star D) \diamond (E\star F)) \ar[r]^-{1_{A\star B}\diamond \zeta_{C, D, E, F}} & (A\star B) \diamond ((C\diamond E)\star (D\diamond F)) \ar[d]^-{\zeta_{A, B, C\diamond E, D\diamond F}} \\
((A\diamond C)\star (B\diamond D)) \diamond (E\star F)\ar[r]_-{\zeta_{A\diamond C, B\diamond D, E, F}} & ((A\diamond C)\diamond E)\star ((B\diamond D)\diamond F)\ar[r]_-{{\alpha_\diamond}_{A, C, E}\star {\alpha_\diamond}_{B, D, F}} & (A\diamond (C\diamond E))\star (B\diamond (D\diamond F))
}}
\end{gathered}\end{equation}
\begin{align*}
&{\alpha_\diamond}_{A\star B, C\star D, E\star F}; (1_{A\star B}\diamond \zeta_{C, D, E, F}); \zeta_{A, B, C\diamond E, D\diamond F} = (\zeta_{A, B, C, D}\diamond 1_{E\star F}); \zeta_{A\diamond C, B\diamond D, E, F}; ({\alpha_\diamond}_{A, C, E}\star {\alpha_\diamond}_{B, D, F}) \\
&\zeta_{A\star B, C D\star E, F}; (\zeta_{A, B, D, E}\star 1_{C\diamond F}); {\alpha_\star}_{A\diamond D, B\diamond E, C\diamond F} = ({\alpha_\star}_{A,B,C}\diamond{\alpha_\star}_{D, E, F}); \zeta_{A, B\star C, D, E\star F}; (1_{A\diamond D}\star\zeta_{B, C, E, F})
\end{align*}

\begin{equation}\begin{gathered}\label{cc:unit_interchange}
\xymatrixrowsep{1.75pc}\xymatrixcolsep{1.75pc}\xymatrix@L=0.5pc{
A\star B\ar[r]^-{{\lambda_\diamond}_{A\star B}} \ar[d]_-{{\lambda_\diamond}_{A}\star {\lambda_\diamond}_{B}}& I \diamond (A\star B)\ar[d]^-{\Delta_I\diamond 1_{A\star B}} \\
(I\diamond A)\star (I\diamond B) & (I\star I)\diamond (A\star B)\ar[l]^-{\zeta_{I,I,A,B}}
}
\end{gathered}\end{equation}
\begin{align*}
& {\lambda_\diamond}_{A\star B}; (\Delta_I\diamond 1_{A\star B}); \zeta_{I,I,A,B} = {\lambda_\diamond}_{A}\star {\lambda_\diamond}_{B} \quad\quad\quad {\rho_\diamond}_{A\star B}; (1_{A\star B}\diamond \Delta_I); \zeta_{A,B, I, I} = {\rho_\diamond}_{A}\star {\rho_\diamond}_{B} \\
& ({\lambda_\star}_{A}\diamond{\lambda_\star}_{B}); \zeta_{J, A, J, B}; (\mu_J\star 1_{A\diamond B}) = {\lambda_\star}_{A\diamond B} \quad\quad ({\rho_\star}_{A}\diamond{\rho_\star}_{B}); \zeta_{A, J, B, J}; (1_{A\diamond B}\star \mu_J) = {\rho_\star}_{A\diamond B}
\end{align*}
\end{definition}

