\begin{definition}
A duoidal category $(\cX, \diamond, I,\star, J)$ is {\bf normal} if $\iota^{-1}\c I\rarr J$ is invertible, in other words the units are isomorphic. Further, a duoidal category is {\bf strong} if all its structure maps are invertible. 
\end{definition}

\begin{definition}\cite[Def 6.5]{Aguiar_Mahajan_2010}\label{def:braided_duoidal_cat}
A duoidal category $(\cX, \diamond, I,\star, J)$ is {\bf braided} if
\begin{itemize}
\item $(\cX, \diamond, I)$ is a braided monoidal category with $\diamond$-braiding \[ \sigma_\diamond\c\diamond\Rarr switch_{\ccX,\ccX};\diamond \qquad{\sigma_\diamond}_{A, B}\c A\diamond B\rarr B\diamond A \]
\item $(\cX, \star, J)$ is a braided monoidal category with $\op$-braiding \[ \sigma_\star\c \star\Rarr switch_{\ccX,\ccX};\star \qquad {\sigma_\star}_{A, B}\c A\star B\rarr B\star A \]
\end{itemize}
such that 
\begin{itemize}
    \item $(J, \mu_{J},\iota)$ is a braided $\diamond$-monoid and $(I, \Delta_{I}, \iota)$ is a cobraided $\star$-comonoid, i.e. \eqref{cc:braided_monoid_comonoid}
    \item interchange maps interact coherently with the braidings \eqref{cc:interchange_braiding}.
\end{itemize}
%
\begin{equation}\begin{gathered}\label{cc:braided_monoid_comonoid}
\xymatrixrowsep{1.75pc}\xymatrixcolsep{1.75pc}\xymatrix@L=0.5pc{
J\diamond J \ar[r]^-{\mu_J}\ar[d]_-{{\sigma_\diamond}_{J,J}} & J & I\ar[r]^-{\Delta_I}\ar[rd]_-{\Delta_I} & I\star I\ar[d]^-{{\sigma_\star}_{I,I}} \\
J\diamond J \ar[ru]_-{\mu_J} & & & I\star I
}
\end{gathered}\end{equation}

\begin{equation}\begin{gathered}\label{cc:interchange_braiding}
\xymatrixrowsep{1.75pc}\xymatrixcolsep{1.75pc}\xymatrix@L=0.5pc{
(A\star B)\diamond (C\star D)\ar[r]^-{\zeta_{A, B, C, D}}\ar[d]_-{{\sigma_\star}_{A,B} \diamond {\sigma_\star}_{C,D}} & (A\diamond C)\star (B\diamond D)\ar[d]^-{{\sigma_\star}_{A\diamond C, B\diamond D}} \\
(B\star A)\diamond (D\star C)\ar[r]_-{\zeta_{B, A, D, C}} & (B\diamond D)\star (A\diamond C)
}
\end{gathered}\end{equation}
\begin{align*}
& \zeta_{A, B, C, D} ; {\sigma_\star}_{A\diamond C, B\diamond D} = ({\sigma_\star}_{A,B} \diamond {\sigma_\star}_{C,D}); \zeta_{B, A, D, C}\\ 
& \zeta_{A, B, C, D} ; ({\sigma_\diamond}_{A,C} \star {\sigma_\diamond}_{B,D}) = {\sigma_\diamond}_{A\star B, C\star D};\zeta_{C,D,A,B}
\end{align*}
\end{definition}

The notion of symmetric duoidal categories has not yet appeared in the literature as such, since the motivation for duoidal structures is often braided monoidal categories, although it is a trivial extension of braided duoidal categories. Symmetry is essential to the Fox theorem and therefore will be a key component of this work. 

\begin{definition}
A braided duoidal category $(\cX, \diamond, I,\star, J)$ is {\bf symmetric} if 
\begin{itemize}
\item $(\cX, \diamond, I)$ is a symmetric monoidal category, and 
\item $(\cX, \star, J)$ is a symmetric monoidal category.
\end{itemize}
\end{definition}

Given a symmetric duoidal category, there are two canonical flips, one for $\diamond$ and for $\star$. We note here how these canonical flips interact with the duoidal structure maps.

\begin{proposition}
The following diagrams commute in any symmetric duoidal category:
\begin{equation}\begin{gathered}\label{cc:delta_nabla_canonicalflip}
\xymatrixrowsep{1.75pc}\xymatrixcolsep{2.75pc}\xymatrix@L=0.5pc{
I\ar[r]^-{\Delta_I}\ar[dd]_-{\Delta_I} & I\star I \ar[d]^-{\Delta_I \star \Delta_I} & (J\diamond J)\diamond(J\diamond J)\ar[r]^-{\mu_J\diamond \mu_J}\ar[d]_-{\tau^\diamond_{J,J,J,J}} & J\diamond J\ar[dd]^-{\mu_J}\\
& (I\star I)\star (I\star I)\ar[d]^-{\tau^\star_{I,I,I,I}} &  (J\diamond J)\diamond(J\diamond J)\ar[d]_-{\mu_J}\\
I\star I\ar[r]_-{\Delta_I\star \Delta_I} & (I\star I)\star (I\star I) & J\diamond J\ar[r]_-{\mu_J} & J
}
\end{gathered}\end{equation}
\begin{equation}\begin{gathered}\label{cc:medial_canonicalflip}
\resizebox{0.9\linewidth}{!}{\xymatrixrowsep{1.75pc}\xymatrixcolsep{1.75pc}\xymatrix@L=1.5pc{
{\begin{array}{@{}c@{}}((A\star A') \star (B\star B'))\diamond{}\\ ((C\star C')\star(D\star D'))\end{array}}\ar[r]^-{\zeta_{A\star A', B\star B', C\star C', D\star C'}}\ar[d]_-{\tau^\diamond_{A\star A', B\star B', C\star C', D\star D'}} & {\begin{array}{@{}c@{}}((A\star A') \diamond (C\star C'))\star{}\\ ((B\star B')\diamond(D\star D'))\end{array}}\ar[r]^-{\zeta_{A,A',C,C'}\star \zeta_{B,B',D,D'}} & {\begin{array}{@{}c@{}}((A\diamond C)\star (A'\diamond C'))\star{}\\ ((B\diamond D)\star (B'\diamond D'))\end{array}}\ar[d]^-{\tau^\star_{A\diamond C, A'\diamond C', B\diamond D, B'\diamond D'}} \\
{\begin{array}{@{}c@{}}((A\star B)\star(A'\star B'))\diamond{}\\ ((C\star D)\star (C'\star D'))\end{array}}\ar[r]_-{\zeta_{A\star B, A'\star B', C\star D, C'\star D'}} & {\begin{array}{@{}c@{}}((A\star B)\star(C\star D))\star{}\\ ((A'\star B')\star (C'\star D'))\end{array}}\ar[r]_-{\zeta_{A,B,C,D}\star \zeta_{A',B',C',D'}} &
{\begin{array}{@{}c@{}}((A\diamond C)\star(B\diamond D))\star{}\\ ((A'\diamond C')\star(B'\diamond D'))\end{array}}
}}    
\end{gathered}\end{equation}
\begin{align*}
\zeta_{A\star A', B\star B', C\star C', D\star C'};& (\zeta_{A,A',C,C'}\star \zeta_{B,B',D,D'}); \tau^\star_{A\diamond C, A'\diamond C', B\diamond D, B'\diamond D'}\\ &= (\tau^\star_{A,A',B,B'}\diamond \tau^\star_{C, C', D, D'}); \zeta_{A\star B, A'\star B', C\star D, C'\star D'}; (\zeta_{A,B,C,D}\star \zeta_{A',B',C',D'}) \\
\tau^\diamond_{A\star A', B\star B', C\star C', D\star D'};& (\zeta_{A,A',C,C'}\diamond\zeta_{B,B',D,D'}); \zeta_{A\diamond C, A'\diamond C', B\diamond D, B'\diamond D'} = \\
&(\zeta_{A,A',B,B'}\diamond \zeta_{C,C', D, D'});\zeta_{A\diamond B, A'\diamond B', C\diamond D, C'\diamond D'}; (\tau^\diamond_{A,B,C,D}\star \tau^\diamond_{A',B',C',D'})
\end{align*}
\end{proposition}

