\subsection{Duoidal Functors and Transformations}  \hfill\

\vspace{0.5\baselineskip}
Aguiar and Mahajan define two different types of functors between duoidal categories: bilax duoidal functors and double lax duoidal functors. We shall only need the former.

\begin{definition}\cite[Def 6.50]{Aguiar_Mahajan_2010}
Let $(\cX, \diamond, I,\star, J)$ and $(\cY, \diamond, I,\star, J)$ denote duoidal categories. \\
A {\bf bilax duoidal functor} $(F, p_{I},p_\diamond, q_{J},q_\star) \c (\cX, \diamond, I,\star, J)\rarr (\cY, \diamond, I,\star, J)$ is a functor $F\c \cX\rarr \cY$ such that
\begin{itemize}
	\item $(F, p_{I},p_\diamond)\c (\cX,\diamond,I)\rarr(\cY,\diamond, I)$ is a monoidal functor with 
	\begin{itemize}
		\item a morphism $p_{I}\c I\rarr F(I)$, 
		\item a natural transformation
            \[ p_\diamond\c (F\times F);\diamond\Rarr \diamond; F \qquad\qquad {p_\diamond}_{A, B}\c F(A)\diamond F(B)\rarr F(A\diamond B) \]
	\end{itemize}

	\item $(F, q_{J},q_\star)\c (\cX,\star,J)\rarr(\cY,\star, J)$ is a comonoidal functor with
	\begin{itemize}
		\item a morphism $q_{J}\c F(J)\rarr J$, 
		\item a natural transformation
            \[ q_\star\c \star;F \Rarr (F\times F);\star \qquad\qquad {q_\star}_{A, B}\c F(A\star B)\rarr F(A)\star F(B) \]
	\end{itemize}
\end{itemize}
such that \eqref{cc:duoidalfunctor_interchange} and \eqref{cc:duoidalfunctor_unit}. 
%
\begin{equation}\begin{gathered}\label{cc:duoidalfunctor_interchange}
\resizebox{0.9\linewidth}{!}{\xymatrixrowsep{1.75pc}\xymatrixcolsep{1.75pc}\xymatrix@L=0.5pc{
F(A\star B)\diamond F(C\star D)\ar[r]^-{{q_\star}_{A,B}\diamond {q_\star}_{C,D}}\ar[d]_-{{p_\diamond}_{A\star B, C\star D}} & (F(A)\star F(B)) \diamond (F(C)\star F(D))\ar[r]^-{\zeta_{F(A), F(B), F(C), F(D)}} & (F(A)\diamond F(C))\star (F(B)\diamond F(D))\ar[d]^-{{p_\diamond}_{A,C}\star {p_\diamond}_{B,D}} \\
F((A\star B)\diamond (C\star D))\ar[r]_-{F(\zeta_{A,B,C,D})} & F((A\diamond C)\star (B\diamond D))\ar[r]_-{{q_\star}_{A\diamond C, B\diamond D}} & F(A\diamond C)\star F(B\diamond D)
}}
\end{gathered}\end{equation}

\begin{equation}\begin{gathered}\label{cc:duoidalfunctor_unit}
\xymatrixrowsep{1.75pc}\xymatrixcolsep{1.75pc}\xymatrix@L=0.5pc{
I\ar[r]^-{p_{I}}\ar[d]_-{\Delta_{I}} & F(I)\ar[r]^-{F(\Delta_{I})} & F(I\star I)\ar[d]^-{{q_\star}_{I,I}} & I\ar[r]^-{p_I}\ar[d]_-{\iota} & F(I)\ar[d]^-{F(\iota)}\\
I\star I\ar[rr]_-{p_{I}\star p_{I}} && F(I)\star F(I) & J & F(J)\ar[l]^-{q_J}\\
F(J) \diamond F(J)\ar[r]^-{{p_\diamond}_{J,J}}\ar[d]_-{q_{J}\diamond q_{J}} & F(J\diamond J)\ar[r]^-{F(\mu_{J})} & F(J)\ar[d]^-{q_J} \\
J\diamond J\ar[rr]_-{q_J} && J
}
\end{gathered}\end{equation}
% \begin{align}\label{duoidalfunctor_interchange}
% ({q_\star}_{A,B}\diamond {q_\star}_{C,D}); \zeta_{F(A), F(B), F(C), F(D)};({p_\diamond}_{A,C}\star {p_\diamond}_{B,D}) = {p_\diamond}_{A\star B, C\star D}; F(\zeta_{A,B,C,D}); {q_\star}_{A\diamond C, B\diamond D}
% \end{align}
% \begin{align}\label{duoidalfunctor_unit}
% p_{I}; F(\Delta_{I});{q_\star}_{I,I} = \Delta_{I};(p_{I}\star p_{I}) \quad\quad {p_\diamond}_{J,J}; F(\mu_{J}); q_{J} = (q_{J}\diamond q_{J});\mu_{J} \quad\quad p_{I};F(\iota); q_{J} = \iota
% \end{align}
\end{definition}

\begin{definition}\cite[Def 6.51]{Aguiar_Mahajan_2010}
A {\bf bilax duoidal transformation} $\alpha\c (F, p_{I}^{F},p_\diamond^{F}, q_{J}^{F},q_\star^{F}) \Rarr (G, p_{I}^{G},p_\diamond^{G}, q_{J}^{G},q_\star^{G})$ is a natural transformation $\alpha\c F\rarr G$ such that 
\begin{itemize}
	\item $\alpha\c (F, p_{I}^{F},p_\diamond^{F})\Rarr (G,p_{I}^{G}, p_\diamond^{G})$ is a monoidal transformation and
	\item $\alpha\c (F, q_{J}^{F}, q_\star^{F})\Rarr (G, q_{J}^{G},q_\star^{G})$ is a comonoidal transformation.
\end{itemize}
\end{definition}

\begin{proposition}\cite[Prop 6.52]{Aguiar_Mahajan_2010}\label{prop:2cat_duoidalcats}
There is a 2-category of duoidal categories, bilax duoidal functors and bilax duoidal transformations, denoted \DUO.
\end{proposition}

Just as a monoid in a monoidal category \cX\ can be equivalently defined as a monoidal functor from the terminal category to \cX, Aguiar and Mahajan define two types of ``monoid-like'' structures in a duoidal category based upon their two type of functors: duoidal bimonoids and duoidal double monoids. Once more, we only introduce the former.

\begin{definition}\cite[Def 6.25]{Aguiar_Mahajan_2010}
\begin{itemize}
\item A {\bf duoidal bimonoid} in duoidal category \cX\ is a quintuple $\langle A, \nabla_A, u_A, \Delta_A, e_A\rangle$ of an object $A$ in \cX\ equipped with four morphisms
\[ \nabla_A\c A\diamond A \rarr A \qquad u_A\c I\rarr A \qquad \Delta_A\c A\rarr A\star A \qquad e_A\c A\rarr J\]
\begin{itemize}
    \item $\langle A, \nabla_A, u_A\rangle$ is a $\diamond$-monoid,
    \item $\langle A, \Delta_A, e_A\rangle$ is a $\star$-comonoid
\end{itemize} such that the two structures are compatible \eqref{cc:duoidal_bimonoid}.
%
\begin{equation}\begin{gathered}\label{cc:duoidal_bimonoid}
\xymatrixrowsep{1.75pc}\xymatrixcolsep{1.75pc}\xymatrix@L=0.5pc{
A\diamond A\ar[r]^-{\nabla_A}\ar[d]_-{\Delta_A \diamond \Delta_A} & A\ar[r]^-{\Delta_A} & A\star A  & I\ar[r]^-{u_A}\ar[rd]_-{\iota} & A\ar[d]^-{e_A}\\
(A\star A)\diamond (A\star A)\ar[rr]_-{\zeta_{A,A,A,A}} && (A\diamond A)\star (A\diamond A)\ar[u]_-{\nabla_A \star \nabla_A} & & J \\
A\diamond A\ar[r]^-{\nabla_A} \ar[d]_-{e_A\diamond e_A}& A\ar[d]^-{e_A} & I\ar[r]^-{\Delta_I}\ar[d]_-{u_A} & I\star I\ar[d]^-{u_A\star u_A}\\
J \diamond J \ar[r]_-{\mu_J}& J & A\ar[r]_-{\Delta_A} & A\star A
}
\end{gathered}\end{equation}
% \[ (\Delta \diamond \Delta); \zeta_{A, A, A, A} ; (\mu\star\mu) = \mu;\Delta \quad\quad\quad \eta;\epsilon = \iota\] 
% \[ \mu; \epsilon = (\epsilon\diamond\epsilon);\mu_{J} \quad\quad\quad\quad\quad \Delta_{I}; (\eta\star\eta) = \eta;\Delta \]
\item A {\em morphism of duoidal bimonoids} is a morphism of the underlying $\diamond$-monoids and $\star$-comonoid.
\end{itemize}
\end{definition}

\begin{proposition}\cite[Cor 6.53]{Aguiar_Mahajan_2010}\label{prop:duoidal_functor_preserve}
A bilax duoidal functor preserves bimonoids and morphisms between bimonoids.
\end{proposition}

\subsection{Cartesian and Cocartesian Duoidal Categories}  \hfill\

\vspace{0.5\baselineskip}
As previously stated, duoidal structure arises canonically whenever a monoidal category has finite products or finite coproducts. We detail the construction here.

\begin{proposition}\cite[Ex 6.19]{Aguiar_Mahajan_2010}\label{prop:cartesian_duoidal}
    \begin{enumerate}
        \item Consider a monoidal category $(\cX,\os, I)$ with finite products, then $(\cX, \os, I, \times, \bone)$ is a duoidal category with structure maps
    \[ \Delta_I = \langle 1_I, 1_I\rangle\c I\rarr I\times I \qquad \mu_{\bone} =  t_{\bone\os\bone}\c \bone\os\bone\rarr \bone \qquad  \iota = t_{I}\c I\rarr \bone\]
    and interchange natural transformation
    \[\zeta_{A,B,C,D} = \langle \pi^0_{A,B} \os \pi^0_{C,D}, \pi^1_{A,B} \os \pi^1_{C,D}\rangle\c (A\times B)\os(C\times D)\rarr (A\os C)\times (B\os D) \]

    \item Consider a monoidal category $(\cX,\os, I)$ with finite coproducts, then $(\cX, +, \bzero, \os, I)$ is a duoidal category with structure maps
    \[  \Delta_{\bzero} = b_{\bzero\os \bzero}\c \bzero\rarr \bzero\os \bzero \qquad \mu_I =  [1_I, 1_I]\c I+I\rarr I \qquad \iota = b_{I}\c \bzero\rarr I\]
    and interchange natural transformation
    \[\zeta_{A,B,C,D} = [\iota^0_{A,C} \os \iota^0_{B,D}, \iota^1_{A,C} \os \iota^1_{B,D}]\c (A\os B)+(C\os D)\rarr (A+C)\os (B+D) \]

    \item Consider now a category \cX\ with finite products and coproducts, then $(\cX, +, \bzero, \times, \bone)$ is of course a symmetric duoidal category with structure maps
    \begin{align*}
        & \Delta_{\bzero} = b_{\bzero\times \bzero} = \langle 1_\bzero, 1_\bzero\rangle\c \bzero\rarr \bzero\times \bzero & \mu_{\bone} = t_{\bone+\bone} = [1_\bone, 1_\bone]\c\bone+\bone\rarr \bone\\
        &\iota = t_{\bzero}=b_{\bone}\c \bzero\rarr\bone
    \end{align*}
    and interchange natural transformation
    \begin{align*}
    &\zeta_{A,B,C,D} = \langle \pi^0_{A,B} + \pi^0_{C,D}, \pi^1_{A,B} +\pi^1_{C,D}\rangle =\\
    & [\iota^0_{A,C} \times \iota^0_{B,D}, \iota^1_{A,C} \times \iota^1_{B,D}]\c (A\times B)+(C\times D)\rarr (A+C)\times (B+D)
    \end{align*}
    \end{enumerate}
\end{proposition}

This idea extends to monoidal functors between monoidal categories with finite products or finite coproducts as follows. 

\begin{lemma}\label{lem:functor_comon_if_cart}
Given cartesian categories \cX\ and \cY, any functor $F\c \cX\rarr\cY$ becomes a symmetric comonoidal functor with structure maps
\[ q_{\bone}= t_{F(\bone)}\c F(\bone)\rarr \bone\quad\quad {q_{\times}}_{A,B} = \langle F(\pi^0_{A,B}), F(\pi^1_{A, B})\rangle\c F(A\times B)\rarr F(A)\times F(B) \]
Further, any natural transformation $\alpha\c F\Rarr G$ becomes a symmetric comonoidal transformation between the induced symmetric comonoidal functors. \\

Dually, given cocoartesian categories \cX\ and \cY, any functor $G\c \cX\rarr\cY$ becomes a symmetric monoidal functor with structure maps
\[ p_{\bzero}= b_{F(\bzero)}\c \bzero\rarr F(\bzero)\quad\quad {p_+}_{A,B} = [F(\iota^0_{A,B}), F(\iota^1_{A, B})]\c F(A)+ F(B)\rarr F(A+B) \]
Any natural transformation $\alpha\c F\Rarr G$ becomes a symmetric monoidal transformation between the induced symmetric monoidal functors.
\end{lemma}

\begin{proposition}\cite[Ex 6.68]{Aguiar_Mahajan_2010}\label{prop:cartesian_duoidal_functor}
\begin{enumerate}
    \item Consider duoidal categories $(\cX, \os, I, \times, \bone)$ and $(\cY, \os, I, \times, \bone)$ whose second monoidal structures are cartesian as described above. Then, consider a monoidal functor $(F, p_I, p_\os)\c (\cX, \os, I)\rarr (\cY, \os, I)$. By the above Lemma, $(F, q_{\bone}, q_\times)\c (\cX, \times, \bone)\rarr(\cY, \times, \bone)$ is a comonoidal functor. This further determines a bilax duoidal functor 
\[(F, p_I, p_\os, q_{\bone}, q_\times)\c (\cX, \os, I, \times, \bone)\rarr (\cY, \os, I, \times,\bone)\]
    \item Consider duoidal categories $(\cX,+, \bzero, \os, I)$ and $(\cY,+, \bzero, \os, I)$ whose first monoidal structures are cocartesian. Then, any comonoidal functor $(F, q_I, q_\os)\c(\cX, \os, I)\rarr (\cY, \os, I)$ is equally a monoidal functor $(F, p_{\bzero}, p_+)\c (\cX, +, \bzero)\rarr(\cY, +, \bzero)$ by the above Lemma. This determines a bilax duoidal functor 
\[(F, p_{\bzero}, p_+, q_I, q_\os)\c (\cX,+, \bzero, \os, I)\rarr(\cY,+, \bzero, \os, I)\]
    \item If we now consider a categories \cX\ and \cY\ with finite products and coproducts, then every functor $F\c\cX\rarr\cY$ is canonically a bilax duoidal functor.
\end{enumerate}
\end{proposition}

\begin{remark}
Given comonoidal functors $(F, q^{F}_{\bone}, q^{F}_\times)\c (\cX, \times, \bone)\rarr(\cY, \times, \bone)$ induced as described above, the standard composition of comonoidal functors is equal to the induced comonoidal structure of the composed functor $F;G$. Similarly, for the monoidal functors described above.
\end{remark}

\section{Medial Linearly Distributive Categories}\label{sec:MLDC}

We can immediately provide a characterization of cartesian LDCs $(\bX, \times, \bone, +, \bzero)$ by recognizing that $(\bX, \times, \bone)$ is a cartesian monoidal structure and $(\bX, +, \bzero)$ is a cocartesian monoidal structure, therefore Corollary \ref{cor:char_cartesian_cat} applies to the former and its dual applies to the latter. 

\begin{proposition}\label{prop:char_CLDC}
A symmetric linearly distributive category \bX\ is cartesian if and only if there are natural transformations
\[ \Delta_{A}\c A\rarr A\ot A \quad\quad e_{A}\c A\rarr \top \quad\quad \nabla_{A}\c A\op A\rarr A \quad\quad u_{A}:\bot\rarr A \]
such that, $\forall A, B\in\bX$,
\begin{itemize}
	\item $\langle A, \Delta_{A}, e_{A}\rangle$ determines a cocommutative $\ot$-comonoid,
	\item $\langle A, \nabla_{A}, u_{A}\rangle$ determines a commutative $\op$-monoid, and 
\end{itemize}
\[\Delta_{A\ot B} = (\Delta_{A}\ot\Delta_{B}); \tau^\ot_{A, A, B, B} \qquad e_{A\ot B} = (e_{A}\ot e_{B}); {u^{R}_{\ot}}_{\top}^{-1} \]
\[\nabla_{A\op B} = \tau^\op_{A, B, A, B};(\nabla_{A}\op\nabla_{B}) \qquad u_{A\op B} = {u^R_\op}^{-1}_{\bot};(u_{A}\op u_{B}) \]
\[\Delta_{\top} = {u^{R}_{\ot}}_{\top} \qquad e_{\top} = 1_{\top} \qquad  \nabla_{\bot} = {u^{R}_{\op}}_{\bot} \qquad u_{\bot} = 1_{\bot} \]
\end{proposition}

The natural transformations of course have component morphisms for all objects in the symmetric LDC. Therefore, there will be maps \[ e_\bot, u_\top\c \bot\rarr\top \qquad u_{\bot\ot\bot}, \Delta_\bot\c \bot\rarr \bot\ot \bot \qquad e_{\top\op\top}, \nabla_\top\c \top\op\top\rarr\top\] and, given $A, B \in \bX$, there will be a maps \[ \Delta_{A\op B}\c A\op B \rarr (A\op B)\ot (A\op B) \qquad \nabla_{A\ot B}\c (A\ot B)\op (A\ot B)\rarr A\ot B \] 

The conditions of Proposition \ref{prop:char_CLDC} give us additional information about these maps. Indeed, by naturality of $e$ and equation $e_\top = 1_\top$, we see that  \[ e_\bot = u_\top \qquad e_{\top\op\top} = \nabla_\top \qquad e_{A\op B} = (e_A\op e_B) ; \nabla_\top \]
Similarly, by naturality of $u$ and equation $u_\bot = 1_\bot$, 
\[ u_\top = e_\bot \qquad u_{\bot\ot\bot} = \Delta_\bot \qquad u_{A\ot B} = \Delta_\bot; (u_A \ot u_B)\]
%
Furthermore, we can determine a formula for diagonal morphism $\Delta_{A\ot B}$:
%
\begin{equation*}\begin{gathered}
\xymatrixrowsep{2.75pc}\xymatrixcolsep{3.5pc}\xymatrix@L=0.5pc{
A\op B\ar@/_2.0pc/[ddr]_-{1_{A\op B}}\ar[r]^-{\Delta_A\op \Delta_B}\ar@{}[rd]|{\eqref{cc:comonoid_units}} & (A\ot A)\op (B\ot B)\ar[r]^-{\Delta_{(A\ot A)\op (B\ot B)}}\ar[d]^-{(1_A\ot e_A)\op (e_B\ot 1_B)}\ar@{}[rd]|{(\nat)} & ((A\ot A)\op (B\ot B)) \ot ((A\ot A)\op (B\ot B))\ar[d]^-{\hbox{$\scriptsize\begin{array}{@{}c@{}}((1_A\ot e_A)\op (e_B\ot 1_B))\ot {}\\ ((1_A\ot e_A)\op (e_B\ot 1_B))\end{array}$}} \\
& (A\ot\top)\op (\top\ot B)\ar[d]^-{{u^R_\ot}^{-1}_A \op {u^L_\op}^{-1}_B} & ((A\ot\top)\op (\top\ot B))\ot ((A\ot\top)\op (\top\ot B))\ar[d]^-{({u^R_\ot}^{-1}_A \op {u^L_\op}^{-1}_B)\ot ({u^R_\ot}^{-1}_A \op {u^L_\op}^{-1}_B)}\\
& A\op B\ar[r]_-{\Delta_{A\op B}} & (A\op B)\ot (A\op B)
}\end{gathered}\end{equation*}
%
Therefore, \[ \Delta_{A\op B} = A\op B \xrightarrow{\Delta_A\op \Delta_B} (A\ot A)\op (B\ot B) \xrightarrow{\mu^0_{A,A,B,B}} (A\op B)\ot (A\op B)\] for some natural transformation 
\begin{align*}
    &\mu^0_{A,B,C,D} \c (A\ot B)\op (C\ot D) \rarr (A\op C)\ot (B\op D)\\
    &= \Delta_{(A\ot B)\op(C\ot D)}; ( ( (1_A\ot e_B); {u^R_\ot}^{-1}_A \op (1_C\ot e_D); {u^R_\ot}^{-1}_C) \ot ((e_A\ot 1_B); {u^L_\ot}^{-1}_B \op (e_C\ot 1_D); {u^L_\ot}^{-1}_D))\\
\end{align*}
%
Similarly, by naturality of $\nabla$ and monoid coherence conditions \eqref{cc:monoid_units},
%
\begin{equation*}\begin{gathered}
\xymatrixrowsep{2.75pc}\xymatrixcolsep{3.5pc}\xymatrix@L=0.5pc{
(A\ot B)\op (A\ot B)\ar[r]^{\nabla_{A\ot B}}\ar[d]_{({u^R_\op}_A^{-1}\ot{u^R_\op}_B^{-1})\op ({u^L_\op}_A^{-1} \ot {u^L_\op}_B^{-1})} & A\ot B \ar[d]_{{u^R_\op}_A^{-1}\ot{u^R_\op}_B^{-1}}\ar@/^2.0pc/[ddr]^{1_{ A\ot B}}\\
%
(A\op \bot)\ot(B\op\bot))\op((\bot\op A)\ot (\bot\op B))\ar@{}[rd]|{(\nat)}\ar[d]_-{\hbox{$\scriptsize\begin{array}{@{}c@{}}((1_{A}\op u_{A})\ot (1_{B}\op u_{B})) {}\\ ((u_{A}\op 1_{ A})\ot (u_{B}\op 1_{B}))\end{array}$}} & (A\op \bot)\ot (B\op \bot)\ar[d]_{(1_{A}\op u_{A})\ot (1_{B}\op u_{B})} \ar@{}[rd]|{\eqref{cc:monoid_units}} \\
%
(A\op A)\ot (B\op B))\op ((A\op A)\ot (B\op B))\ar[r]_-{\nabla_{(A\op A)\ot (B\op B)}}& (A\op A)\ot (B\op B)\ar[r]_-{\nabla_{A}\ot \nabla_{B}} & A\ot B
}\end{gathered}\end{equation*}
%
This determines that \[ \nabla_{A\ot B} = (A\ot B)\op (A\ot B) \xrightarrow{\mu^1_{A,B,A,B}} (A\op A)\ot (B\op B) \xrightarrow{\nabla_A\ot \nabla_B} A\ot B \]

where $\mu^1_{A,B,A,B}$ is the natural transformation
\begin{align*}
    &\mu^1_{A,B,C,D} \c (A\ot B)\op (C\ot D) \rarr (A\op C)\ot (B\op D)\\
    &= ( ( {u^R_\op}^{-1}_A;(1_A\ot e_B)\op {u^R_\op}^{-1}_C;(1_C\ot e_D)) \ot ( {u^L_\op}^{-1}_B; (e_A\ot 1_B) \op {u^L_\op}^{-1}_D;(e_C\ot 1_D)); \nabla_{(A\op C)\ot (B\op D)}
\end{align*}
We can then demonstrate that $\mu^0_{A,B,C,D} = \mu^1_{A,B,C,D}$, though the detailed computations are omitted here due to their length.

\begin{corollary}\label{cor:char_CLDC_naive}
Consider a symmetric linearly distributive category \bX\ satisfying the conditions of Proposition \ref{prop:char_CLDC}, then there are maps
\[ m \c \bot\rarr\top \qquad \Delta_\bot\c \bot\rarr\bot\ot\bot \qquad \nabla_\top\c \top\op\top\rarr\top\]
and a natural transformation 
\[ \mu\c (\ot \times \ot);\op \Rarr s_{\bbX, \bbX, \bbX, \bbX}; (\op \times \op);\ot \qquad \mu_{A, B, C, D}\c (A\ot B)\op(C\ot D)\rarr(A\op C)\ot(B\op D) \]
such that 
\[ \Delta_{A\op B} = (\Delta_A \op\Delta_B) ; \mu_{A,A,B,B} \qquad e_{A\op B} = (e_A\op e_B);\Delta_\bot \]
\[ \nabla_{A\ot B} = \mu_{A,B,A,B}; (\nabla_A \ot \nabla_B) \qquad u_{A\ot B} = \nabla_\top; (u_A\ot u_B) \]
\[ e_\bot = u_\top = m \]
\end{corollary}

The maps indicated above will be central to our main definition and therefore we take the time to discuss their meaning in the following section.

\subsection{Medial Rule and Main Definition}  \hfill\

\vspace{0.5\baselineskip}
Considering that linearly distributive categories (LDCs) provide the categorical semantics for multiplicative linear logic, it is important to examine the logical significance of the map $(A\ot B)\op (C\ot D) \rarr (A\op C)\ot (B\op D)$. If we consider, for example, Boolean logic and take $\ot=\wedge$ and $\op=\vee$, then $(A\wedge B) \vee (C\wedge D) \vdash (A\vee C)\wedge (B\vee D)$ is a valid implication.\\

This implication appears prominently as an inference rule in multiple deductive systems based on deep inference. Deep inference, more specifically the calculus of structures, is a proof formalism first developed by Guglielmi to generalize Gentzen's sequent calculus, inspired by key concepts from linear logic \cite{Guglielmi_2007}. \\

This rule was first introduced as an inference rule by Br\"{u}nnler and Tiu \cite{Brunnler_Tiu_2001} for a local system of classical logic, SKS, and was named the {\bf medial rule}. In this context, locality refers to the idea that rules do not require a global view of formulae of potentially unbounded size, such as contraction within Gentzen’s system for classical logic \cite{Brunnler_2003_1}. Locality in SKS is achieved by ensuring that non-local rules, including contraction, are presented in atomic form. However, the general form of contraction must still be admissible in SKS, which necessitates the medial rule. The medial rule also appears in Stra\ss burger’s local system of linear logic, SLLS, to ensure that contraction and co-contraction remain atomic \cite{Strassburger_2002}, and similarly in Tiu’s local system for intuitionistic logic, SISgq \cite{Tiu_2006}. Following its introduction in deep inference, the medial rule has also been studied as a term-rewriting rule, both in isolation \cite{Strassburger_2007_2} and alongside the linear distributivity and mix rules \cite{Das_Strassburger_2016, Bruscoli_Strassburger_2017}.\\

In categorical logic, the medial rule has been examined in the study of categorical semantics for classical logic. Unlike intuitionistic logic, which is modeled by cartesian closed categories, and linear logic, which is modeled by $*$-autonomous or linearly distributive categories, the categorical semantics for classical logic remain unresolved. A naive definition of cartesian $*$-autonomous categories leads only to Boolean algebras as models due to Joyal’s paradox. Consequently, the appropriate categorical framework for classical logic remains an active area of research. The medial rule plays a key role in Stra\ss burger’s Boolean categories \cite{Strassburger_2007_1} and in Lamarche’s $*$-autonomous categories with finitary medial and the absorption law \cite{Lamarche_2007}. In both cases, the authors begin with $*$-autonomous categories and introduce medial maps alongside the $\bot$ contraction map $\bot\rarr \bot\ot \bot$ and the $\top$ co-contraction map $\top\op\top\rarr\top$ to construct categorical models of classical logic. Furthermore, in both constructions, the categories include the nullary mix map $\bot\rarr\top$. In particular, Lamarche’s categories, which will be shown to be related to our main definition in Section \ref{sec:adding_negation}, were a major inspiration for the present work.\\ 

From a categorical perspective, the medial map can be recognized as an instance of the well-known interchange law in duoidal categories, taking $\diamond = \op$, $J=\bot$, $\star = \op$ and $I = \bot$. When combined with  $\bot$ contraction, $\top$ co-contraction and the nullary mix map $\bot\rarr\top$, they provide all the necessary structures maps for a duoidal category, beyond the standard maps for monoidal structures.\\

To establish a linearly distributive Fox theorem, we cannot begin with the 2-category of symmetric LDCs alone. Instead, we must consider symmetric LDCs that include additional medial maps, including nullary mix, $\bot$ contraction and $\top$ co-contraction. This necessity aligns with the role of the medial rule in SLLS, where it enables the atomic contraction and co-contraction rules to extend to all formulae. Therefore, we must first define what it means for a linearly distributive category to have coherent medial maps. 

\begin{definition}
A {\bf medial linearly distributive category} $(\bX,\ot,\top,\op,\bot)$ consists of:
\begin{itemize}
\item a category $(\bX, ;, 1_A)$,
\item a {\bf tensor} monoidal structure $(\bX, \ot, \top)$.
\item a {\bf par} monoidal structure $(\bX, \op, \bot)$,
\item {\bf $\bot$-contraction}, {\bf $\top$-cocontraction} and {\bf nullary mix} morphisms,
\[ \Delta_{\bot}\c\bot\rarr\bot\ot\bot \qquad \nabla_{\top}\c \top\op\top\rarr\top \qquad m\c\bot\rarr\top\]
\item a {\bf medial} natural transformation, and 
\[ \mu\c (\ot \times \ot);\op \Rarr s_{\bbX, \bbX, \bbX, \bbX}; (\op \times \op);\ot \qquad \mu_{A, B, C, D}\c (A\ot B)\op(C\ot D)\rarr(A\op C)\ot(B\op D) \]
\item left and right {\bf linear distributivity} natural transformations
	\begin{align*}
	& \delta^R\c (\op \times 1_{\tiny\bX});\ot \Rarr a_{\bbX, \bbX, \bbX};(1_{\bbX}\times\ot);\op & \delta^R_{A,B,C}\c (A\op B)\ot C\rarr A\op (B\ot C), \\
	& \delta^L\c (1_{\bbX}\times\op);\ot \Rarr a_{\bbX, \bbX, \bbX};(\ot\times1_{\bbX});\op & \delta^L_{A,B,C}\c A\ot(B\op C)\rarr (A\ot B)\op C,
	\end{align*}
\end{itemize}
such that 
\begin{itemize}
\item $(\bX,\ot,\top,\op,\bot)$ is a mix linearly distributive category,
\item $(\bX,\op,\bot,\ot,\top)$ is a duoidal category, and
\item the {\bf medial maps} interact coherently with the linear distributivities \eqref{cc:medial_lindist}.
\end{itemize}

\begin{equation}\begin{gathered}\label{cc:medial_lindist}
\xymatrixrowsep{1.75pc}\xymatrixcolsep{2.75pc}\xymatrix@L=0.5pc{
((A\ot B)\op (C\ot D))\ot X\ar[r]^-{\mu_{A,B,C,D} \ot 1_{X}}\ar[d]_-{\delta^R_{A\ot B, C\ot D, X}} & ((A\op C)\ot(B\op D))\ot X\ar[d]^-{{\alpha_\ot}_{A\op C, B\op D, X}} \\
(A\ot B)\op ((C\ot D)\ot X)\ar[d]_-{1_{A\ot B} \op {\alpha_\ot}_{C, D, X}} &(A\op C)\ot((B\op D)\ot X) \ar[d]^-{1_{A\op C} \ot \delta^R_{B,D,X}} \\
(A\ot B)\op (C\ot(D\ot X))\ar[r]_-{\mu_{A, B, C, D\ot X}} & (A\op C) \ot (B\op (D\ot X))
}
\end{gathered}\end{equation}
\begin{align*}
(\mu_{A,B,C,D} \ot 1_{X}); &{\alpha_\ot}_{A\op C, B\op D, X}; (1_{A\op C} \ot \delta^R_{B,D,X})= \delta^R_{A\ot B, C\ot D, X} ; (1_{A\ot B} \op {\alpha_\ot}_{C, D, X}); \mu_{A, B, C, D\ot X} \\ 
(1_{X} \ot \mu_{A,B,C,D}); &{\alpha_\ot}^{-1}_{X, A\op C, B\op D} ; (\delta^L_{X,A,C}\ot 1_{B\op D})= \delta^L_{X,A\ot B, C\ot D} ; ({\alpha_\ot}^{-1}_{X, A, B}\op 1_{C\ot D}); \mu_{X\ot A, B, C, D} \\
(\delta^R_{X,A,B} \op 1_{C\ot D}); &{\alpha_\op}^{-1}_{X, A\ot B, C\ot D}; (1_{X} \op \mu_{A,B,C,D}) = \mu_{X\op A, B, C, D}; ({\alpha_\op}^{-1}_{X, A, C}\ot 1_{B\op D}); \delta^R_{X, A\op C, B\op D} \\
(1_{A\ot B}\op \delta^L_{C,D,X}); &{\alpha_\op}_{A\ot B, C\ot D, X}; (\mu_{A,B,C,D}\op 1_{X})  = \mu_{A,B,C,D\op X}; (1_{A\op C}\ot {\alpha_\op}_{B,D,X}); \delta^L_{A\op C, B\op D, X}\\
\end{align*}
\end{definition}

\begin{remark}
In the above definition, $(\bX,\op,\bot,\ot,\top)$ being a duoidal category corresponds to
\begin{itemize}
    \item $(\bot, \Delta_{\bot}, m)$ is a $\ot$-comonoid and $(\top, \nabla_{\top}, m)$ is a $\op$-monoid \eqref{cc:bot_top_comonoid_monoid}, 
    \item the medial maps interact coherently with the associators \eqref{cc:medial_assoc} and with the unitors \eqref{cc:absorption_law}.
\end{itemize} 
%
\begin{equation}\label{cc:bot_top_comonoid_monoid}
\begin{aligned}
&\Delta_{\bot}; (1_{\bot}\ot \Delta_{\bot})=\Delta_{\bot}; (\Delta_{\bot}\ot 1_{\bot});{\alpha_\ot}_{\bot,\bot,\bot} \\
& (1_{\top}\op\nabla_{\top});\nabla_{\top} = {\alpha_\op}_{\top,\top,\top};(\nabla_{\top} \op 1_{\top});\nabla_{\top} \\\\
&\Delta_{\bot};(1_{\bot}\ot m) = {u^R_\ot}_{\bot} \qquad\qquad (1_{\top}\op m);\nabla_{\top} = {u^R_\op}_{\top} \\
&\Delta_{\bot};(m\ot 1_{\bot}) = {u^L_\ot}_{\bot} \qquad\qquad (m \op1_{\top});\nabla_{\top} = {u^L_\op}_{\top} 
\end{aligned}
\end{equation}

\begin{align}\label{cc:medial_assoc}
\begin{split}
&\mu_{A\ot B, C, D\ot E, F} ;(\mu_{A, B, D, E}\ot 1_{C\op F}); {\alpha_\ot}_{A\op D, B\op E, C\op F} \\
&= ({\alpha_\ot}_{A,B,C}\op{\alpha_\ot}_{D,E,F}); \mu_{A, B\ot C, D,E\ot F} ; (1_{A\op D}\ot \mu_{B,C,E,F}) \\ \\
&{\alpha_\op}_{A\ot B, C\ot D, E\ot F}; (\mu_{A,B,C,D}\op 1_{E\ot F}); \mu_{A\op C, B\op D, E, F} \\
&= (1_{A\ot B}\op \mu_{C,D,E,F}); \mu_{A,B,C\op E, D\op F}; ({\alpha_\op}_{A,C,E}\ot {\alpha_\op}_{B,D,F})\\
\end{split}
\end{align}

\begin{align}\label{cc:absorption_law}
\begin{split}
&(\Delta_{\bot}\op 1_{A\ot B}); \mu_{\bot,\bot,A,B};({u_\op^L}_{A} \ot {u_\op^L}_{B}) = {u_\op^L}_{A\ot B} \\
&(1_{A\ot B}\op\Delta_{\bot});\mu_{A,B,\bot,\bot}; ({u_\op^R}_{A} \ot {u_\op^R}_{B}) = {u_\op^R}_{A\ot B}\\
&({u_\ot^L}_{A} \op {u_\ot^L}_{B}); \mu_{\top,A,\top,B}; (\nabla_{\top}\ot 1_{A\op B}) = {u_\ot^L}_{A\op B} \\
&({u_\ot^R}_{A} \op {u_\ot^R}_{B}); \mu_{A,\top,B,\top}; (1_{A\op B}\ot \nabla_{\top}) = {u_\ot^R}_{A\op B} 
\end{split}
\end{align}
\end{remark}

We will refrain from giving examples at this point and first continue developing the theory of MLDCs. Examples will be the focus of Section \ref{sec:examples}.\\

As discussed in the introduction, medial LDCs provide a suitable framework for categories that are both independently linearly distributive and duoidal in a coherent manner. We use the term independently to emphasize that, while certain duoidal categories can inherit a linearly distributive structure from their interchange maps (this construction will be reviewed in Section \ref{sec:properties}), this is what we intend. We are concerned with categories where the duoidal and linearly distributive structures do not imply one another, yet nonetheless interact coherently.  This perspective will be particularly useful, as it allows us to leverage the well-developed theory of duoidal categories, which was be introduced in Section \ref{sec:duoidal_categories}.\\

Alternatively, medial LDCs can be viewed as providing categorical semantics for the logical system MLL+Medial, an extension of multiplicative linear logic with MIX, enriched by the addition of the medial rule. This variant may be incompatible with standard sequent calculus, as the medial rule is rather unconventional: its premise is a disjunction of formulae, while its conclusion is a conjunction. However, MLL+Medial is likely expressible within the calculus of structures, where linear distributivity and medial maps play a central role in several systems within the deep inference paradigm. Overall, the logical study of MLL+Medial remains an open area for furture research. 

\begin{remark}
This is perhaps a similar situation to that of pomset logic and BV. Pomset logic is a non-commutative variant of MLL which includes a non-commutative connective $\lhd$ introduced by Retor\'e motivated by Girard's categorical model for linear logic, coherence spaces, and the study of proof nets \cite{Retore_2021}. While pomset logic was expressible with proof nets, it did not seem to be properly expressible in a sequent calculus. In an attempt remedy the situation, Guglielmi determined it could not be done and that lead to the development to of the calculus of structures, as an alternative to sequent calculus based on the idea of deep inference, along with the logic BV \cite{Guglielmi_2007}. It was conjectured in said paper that BV and pomset logic were one and the same. It was determined that, like pomset logic, BV was inexpressible in the sequent calculus \cite{Tiu_2006_BV}, although recent work has conclusively showed that these two logics are in fact different, while detailing exactly why there are difficulties expressing these logics in sequent calculus \cite{Nguyen_Strassburger_2023}. 
\end{remark}

\subsection{Symmetry}  \hfill\

\vspace{0.5\baselineskip}
If we revisit Proposition \ref{prop:char_CLDC}, which provides a preliminary characterization of cartesian LDCs, we observe that for any objects $A$ and $B$ in a CLDC, the diagonal $\Delta_{A\ot B}$ and the multiplication $\nabla_{A\op B}$ are constructed using the canonical flip maps associated with the symmetric $\ot$ and $\op$ monoidal structures. By the same reasoning that led us to define medial LDCs to ensure the presence of the necessary medial maps, we now define symmetric medial LDCs to guarantee the existence of these canonical flip maps.

\begin{definition}\label{def:symm_MLDC}
A {\bf symmetric medial linearly distributive category} $(\bX,\ot,\top,\op,\bot)$ is a medial linearly distributive category such that  
\begin{itemize}
	\item $(\bX,\ot,\top,\op,\bot)$ is a symmetric linearly distributive category, and  
	\item $(\bX,\op,\bot,\ot,\top)$ is a symmetric duoidal category.
\end{itemize}

In other words, a medial linear distributive category is symmetric if $(\bX,\ot,\top)$ and $(\bX,\op,\bot)$ are symmetric monoidal categories such that \eqref{cc:lin_dist_braiding}, \eqref{cc:braided_monoid_comonoid} and \eqref{cc:interchange_braiding}.
\end{definition}

There is however an equivalent definition for symmetric medial LDCs which does not introduce the nullary mix map $m\c\bot\rarr\top$ nor asks for it to be mix. Indeed, in the presence of the braidings, we can define it in terms of the other structure maps and get the mix structure. \\

It is well-known that given a duoidal category $(\bX, \op,\bot,\ot,\top)$, $m\c\bot\rarr\top$ is defined by the rest of the structure.

\begin{proposition}\cite[Prop 6.9]{Aguiar_Mahajan_2010}\label{prop:iota_defined_by_zeta}
The structure map $m\c\bot\rarr\top$ is equal to
\begin{equation}
\begin{gathered}\xymatrixrowsep{1.75pc}\xymatrixcolsep{1pc}\xymatrix@L=0.5pc{
&&& (\bot\ot\top)\op(\top\ot\bot)\ar[r]^-{\mu_{\bot,\top,\top\,\bot}}& (\bot\op\top)\ot(\top\op\bot)\ar[rrd]^-{{u^L_\op}_\top \ot {u^R_\op}_\top} \\
\bot\ar[r]^-{{u_\op}_\bot^{-1}} & \bot\op\bot\ar[rru]^-{{u^R_\ot}_\bot \op {u^L_\ot}_\bot}\ar[rrd]_-{{u^L_\ot}_\bot \op {u^R_\ot}_\bot}&&&&& \top\ot\top\ar[r]^-{{u_\ot}^{-1}_\top} & \top \\
&&& (\top\ot\bot)\op(\bot\ot\top)\ar[r]_-{\mu_{\top,\bot,\bot,\top}} & (\top\op\bot)\ot(\bot\op\top)\ar[urr]_-{{u^R_\op}_\top \ot {u^L_\op}_\top}
}
\end{gathered}\end{equation}
\end{proposition}

The proof that both these composites are equivalent, and themselves equal to $m$ follows from the conditions that $(\top, \nabla_\top, m)$ is a $\op$-monoid and $(\bot, \Delta_\bot, m)$ is a $\ot$-comonoid. Therefore, the definition of an arbitrary duoidal category must include the nullary mix map. \\

However, in the presence of braidings, it can be excluded. It was first noticed by Lamarche in Proposition 2.11 of \cite{Lamarche_2007} that, given a category with two symmetric monoidal structures $(\bX, \ot, \top)$ and $(\bX, \op, \bot)$, and a coherent medial natural transformation $\mu_{A,B,C,D}$, i.e. \eqref{cc:interchange_braiding} holds, the above composites are equal. \\

Further, in the presence of $\bot$-contraction $\Delta_\bot\c \bot\rarr\bot\ot\bot$ such that $\bot$ is a cocommutative $\ot$-cosemigroup and $\top$-cocontraction map $\nabla_\top\c \top\op\top\rarr\top$ such that $\top$ with commutative $\op$-semigroup, which interact coherently with the medial maps, i.e. \eqref{cc:unit_interchange} holds, then the equivalent composites $\bot\rarr\top$ further endow $\bot$ and $\top$ with $\ot$-comonoid and $\op$-monoid structures respectively, as shown in Proposition 2.19 \cite{Lamarche_2007}. \\

Then, as $\bot$ is endowed with a $\ot$-comonoid structure and $\top$ is endowed with a $\op$-monoid structure in a symmetric LDC, Fuhrmann and Pym's theorem in \cite{Fuhrmann_Pym_2007} implies their counit and unit, which are equal in this instances, induce a mix structure.  \\

Altogether, these observations allows us to provide an alternative definition of symmetric medial LDCs which excludes the nullary mix map and defines it entirely based on the rest of the structure:

\begin{proposition}\label{prop:alternative_SMLDC}
A symmetric medial linearly distributive category $(\bX,\ot,\top,\op,\bot)$ is equivalently defined as a symmetric linearly distributive category, equipped with 
\begin{itemize}
\item $\bot$-contraction and $\top$-cocontraction morphisms,
\[ \Delta_{\bot}\c\bot\rarr\bot\ot\bot \qquad \nabla_{\top}\c \top\op\top\rarr\top\]
\item a medial natural transformation, and 
\[ \mu\c (\ot \times \ot);\op \Rarr s_{\bbX, \bbX, \bbX, \bbX}; (\op \times \op);\ot \qquad \mu_{A, B, C, D}\c (A\ot B)\op(C\ot D)\rarr(A\op C)\ot(B\op D) \]
\end{itemize}
such that 
\begin{itemize}
\item $(\bot, \Delta_\bot)$ is a cocommutative $\ot$-cosemigroup and $(\top, \nabla_\top)$ is commutative $\op$-semigroup \eqref{cc:bot_top_comm_semigroups}, 
\item the medial maps interact coherently with the braidings \eqref{cc:sym_medial_braiding}, the associators \eqref{cc:sym_medial_assoc} and with the unitors \eqref{cc:sym_medial_lindist},
\item the medial maps interact coherently with the linear distributivities \eqref{cc:sym_medial_lindist}, and
\item the medial maps, the linear distributivities and the braidings interact coherently together \eqref{cc:sym_medial_lindist_braiding}.
\end{itemize}

\begin{align}\label{cc:bot_top_comm_semigroups}
\begin{split}
&\Delta_{\bot} = \Delta_{\bot}; {\sigma_\ot}_{\bot,\bot} \qquad \Delta_{\bot}; (1_{\bot}\ot \Delta_{\bot}) = \Delta_{\bot}; (\Delta_{\bot}\ot 1_{\bot}); {\alpha_\ot}_{\bot,\bot,\bot} \\
&\nabla_{\top} = {\sigma_\op}_{\top,\top}; \nabla_{\top} \qquad (1_{\top}\op\nabla_{\top});\nabla_{\top} = {\alpha_\op}_{\top,\top,\top};(\nabla_{\top} \op 1_{\top});\nabla_{\top} 
\end{split}
\end{align}

\begin{align}\label{cc:sym_medial_braiding}
\begin{split}
& \mu_{A, B, C, D} ; {\sigma_\ot}_{A\op C, B\op D} = ({\sigma_\ot}_{A,B} \op {\sigma_\ot}_{C,D}); \mu_{B, A, D, C}\\ 
& \mu_{A, B, C, D} ; ({\sigma_\op}_{A,C} \ot {\sigma_\op}_{B,D}) = {\sigma_\op}_{A\ot B, C\ot D};\mu_{C,D,A,B}
\end{split}
\end{align}

\begin{align}\label{cc:sym_medial_assoc}
\begin{split}
&\mu_{A\ot B, C, D\ot E, F} ; (\mu_{A, B, D, E}\ot 1_{C\op F}); {\alpha_\ot}_{A\op D, B\op E, C\op F} = \\
&({\alpha_\ot}_{A,B,C}\op{\alpha_\ot}_{D,E,F}); \mu_{A, B\ot C, D,E\ot F} ; (1_{A\op D}\ot \mu_{B,C,E,F}) \\ \\
&{\alpha_\op}_{A\ot B, C\ot D, E\ot F};(\mu_{A,B,C,D}\op 1_{E\ot F}); \mu_{A\op C, B\op D, E, F} \\
&= (1_{A\ot B}\op \mu_{C,D,E,F}); \mu_{A,B,C\op E, D\op F}; ({\alpha_\op}_{A,C,E}\ot {\alpha_\op}_{B,D,F})
\end{split}
\end{align}

\begin{align}\label{cc:sym_absorption_law}
\begin{split}
&(1_{A\ot B}\op\Delta_{\bot});\mu_{A,B,\bot,\bot}; ({u_\op^R}_{A} \ot {u_\op^R}_{B}) = {u_\op^R}_{A\ot B}\\
&({u_\ot^R}_{A} \op {u_\ot^R}_{B}); \mu_{A,\top,B,\top}; (1_{A\op B}\ot \nabla_{\top}) = {u_\ot^R}_{A\op B} 
\end{split}
\end{align}

\begin{align}\label{cc:sym_medial_lindist}
\begin{split}
&(1_{X} \ot \mu_{A,B,C,D}); {\alpha_\ot}^{-1}_{X, A\op C, B\op D} ; (\delta^L_{X,A,C}\ot 1_{B\op D})= \\
&\delta^L_{X,A\ot B, C\ot D} ; ({\alpha_\ot}^{-1}_{X, A, B}\op 1_{C\ot D}); \mu_{X\ot A, B, C, D} \\ \\
&(1_{A\ot B}\op \delta^L_{C,D,X}); {\alpha_\op}_{A\ot B, C\ot D, X}; (\mu_{A,B,C,D}\op 1_{X})  \\
&= \mu_{A,B,C,D\op X}; (1_{A\op C}\ot {\alpha_\op}_{B,D,X}); \delta^L_{A\op C, B\op D, X}
\end{split}
\end{align}

\begin{align}\label{cc:sym_medial_lindist_braiding}
\begin{split}
&(1_{X} \ot \mu_{A,B,C,D}); {\alpha_\ot}^{-1}_{X, A\op C, B\op D} ; ({\sigma_\ot}_{X,A\op C}\ot 1_{B\op D}); {\alpha_\ot}_{A\op C, X, B\op D}; (1_{A\op C}\ot \delta^L_{X,B,D}) =\\
&\delta^L_{X,A\ot B, C\ot D} ; ({\alpha_\ot}^{-1}_{X, A, B}\op 1_{C\ot D}); (({\sigma_\ot}_{X,A}\ot 1_B)\op 1_{C\ot D}); ({\alpha_\ot}_{A,X,B}\op 1_{C\ot D}); \mu_{X\ot A, B, C, D} \\ \\
&(\delta^L_{A,B,X}\op 1_{C\ot D}); {\alpha_\op^{-1}}_{A\ot B, X, C\ot D}; (1_{A\ot B}\op {\sigma_\op}_{X, C\ot D}); {\alpha_\op}_{A\ot B, C\ot D, X}; (\mu_{A,B,C,D}\op 1_X)= \\
&\mu_{A,B\op X, C, D}; (1_{A\op C}\ot {\alpha_\op^{-1}}_{B,X,D}); (1_{A\op C}\ot (1_B\op {\sigma_\op}_{X,D})); (1_{A\op C}\ot {\alpha_\op}_{B,D,X}); \delta^L_{A\op C, B\op D, X}
\end{split}
\end{align}

\end{proposition}
\begin{proof}
It is immediate that Definition \ref{def:symm_MLDC} implies the definition presented in the Proposition, since the former is a version of the latter with more structures and conditions. Coherence condition \eqref{cc:sym_medial_lindist_braiding} is obtained by replacing the right linear distribution in \eqref{cc:medial_lindist} by its definition as a composite of braidings and the linear distributions, and simplifying using \eqref{cc:braided_monoidal_cat_asso_hexagon} and \eqref{cc:sym_medial_braiding}.\\

Now, consider a symmetric LDC $(\bX,\ot,\top,\op,\bot)$ as outlined in the Proposition. Then, the following diagram commutes:
\begin{equation*}
\begin{gathered}\xymatrixrowsep{1.75pc}\xymatrixcolsep{2.75pc}\xymatrix@L=0.5pc{
&& (\bot\ot\top)\op(\top\ot\bot)\ar[r]^-{\mu_{\bot,\top,\top\,\bot}}\ar[dd]_-{{\sigma_\ot}_{\bot,\top}\op {\sigma_\ot}_{\top,\bot}} \ar@{}[rdd]|{\eqref{cc:sym_medial_braiding}} & (\bot\op\top)\ot(\top\op\bot)\ar[dd]^-{{\sigma_\ot}_{\bot\op\top, \top\op\bot}}\ar[rrd]^-{{u^L_\op}_\top \ot {u^R_\op}_\top} \\
\bot\op\bot\ar[rru]^-{{u^R_\ot}_\bot \op {u^L_\ot}_\bot}\ar[rrd]_-{{u^L_\ot}_\bot \op {u^R_\ot}_\bot} \ar@{}[rr] | {\eqref{cc:braided_monoidal_cat_unit_triangle}} &&&&& \top\ot\top \ar@{}[ll] | {\eqref{cc:braided_monoidal_cat_unit_triangle}}\\
&& (\top\ot\bot)\op(\bot\ot\top)\ar[r]_-{\mu_{\top,\bot,\bot,\top}} & (\top\op\bot)\ot(\bot\op\top)\ar[urr]_-{{u^R_\op}_\top \ot {u^L_\op}_\top}
}
\end{gathered}\end{equation*}

As such, we can define $m\c\bot\rarr\top$ to be the equivalent composites in Proposition \ref{prop:iota_defined_by_zeta}. \\

$(\bot, \Delta_\bot, m)$ is a cocommutative $\ot$-comonoid as $\Delta_\bot; (1_\bot \ot m) = {u^R_\ot}_\bot$ holds as follows:\\
\resizebox{\linewidth}{!}{\xymatrixrowsep{1.75pc}\xymatrixcolsep{1.75pc}\xymatrix@L=0.5pc{
\bot\ot\bot \ar[r]^-{1_\bot \ot {u_\op}_\bot^{-1}} & \bot\ot(\bot\op\bot)\ar[r]^-{1_\bot \ot({u^L_\ot}_\bot \op {u^R_\ot}_\bot)} & \bot\ot((\top\ot\bot)\op(\bot\ot\top))\ar@{}[rdd]|{\eqref{cc:sym_medial_lindist}} \ar[r]^-{1_{\bot}\ot\,\mu_{\top,\bot,\bot,\top}} \ar[d]_-{\delta^L_{\bot,\top\ot\bot,\bot\ot\top}} & \bot\ot((\top\op\bot)\ot(\bot\op\top))\ar[r]^-{1_\bot \ot({u^R_\op}_\top^{-1} \ot {u^R_\op}_\top^{-1})} \ar[d]^-{{\alpha_\ot}_{\bot, \top\op\bot, \bot\op\top}^{-1}} & \bot\ot(\top \ot \top)\ar[dd]^-{1_\bot \ot {u_\ot}_\top^{-1}}\\
%
&& (\bot\ot(\top\ot\bot))\op(\bot\ot\top)\ar[d]_-{{\alpha_\ot}^{-1}_{\bot,\top,\bot}\op 1_{\bot\ot\top}} & (\bot\ot(\top\op\bot))\ot (\bot\op \top)\ar[d]^{\delta^L_{\bot,\top,\bot}\ot1_{\bot\op\top}} \\
%
\bot\ar[uu]^{\Delta_{\bot}}\ar[dd]_-{{u^R_\ot}_\bot} &&((\bot\ot\top)\ot \bot)\op(\bot\ot\top)\ar[d]_-{({u^R_\ot}^{-1}_\bot \ot 1_\bot)\op 1_{\bot\ot\top}} \ar[r]^-{\mu_{\bot\ot\top,\bot,\bot,\top}} \ar@{}[rd]|{(\nat)}&((\bot\ot\top)\op\bot)\ot(\bot\op\top)\ar[d]^-{({u^R_\ot}^{-1}_\bot \op 1_\bot)\ot 1_{\bot\op\top}} & \bot\ot\top\\
%
&& (\bot\ot\bot)\op(\bot\ot\top)\ar[d]_-{{\sigma_\op}_{\bot\ot\bot,\bot\ot\top}} \ar[r]^-{\mu_{\bot,\bot,\bot,\top}} \ar@{}[rd]|{\eqref{cc:sym_medial_braiding}}&(\bot\op\bot)\ot(\bot\op\top)\ar[d]^{{\sigma_\op}_{\bot,\bot}\ot {\sigma_\op}_{\bot,\top}} \\
%
\bot\ot\top \ar[r]_-{{u^R_\op}^{-1}_{\bot\ot\top}}& (\bot\ot\top)\op\bot \ar[r]_{1_{\bot\ot\top}\op\Delta_{\bot}} & (\bot\ot\top)\op(\bot\ot\bot)\ar[r]_{\mu_{\bot,\top,\bot,\bot}} & (\bot\op\bot)\ot(\top\op\bot)\ar[r]_-{{u_\op}_\bot \ot {u^R_\op}_\top} & \bot\ot\top \ar@{=}[uu]
}}
\\

\noindent where the left-hand and right-hand diagrams pentagons commute by the interaction between $\delta^L$ and the unitors \eqref{cc:unit_lineardist}, by the naturality of $\delta^L$ and by various coherence conditions for the structure maps of the symmetric monoidal categories $(\bX,\ot,\top)$ and $(\bX, \op, \bot)$. \\

The upper composite in the diagram is equal to $\Delta_{\bot};(1_{\bot}\ot m)$, while the lower composite
\[ {u^R_\ot}_{\bot}; {u^R_\op}^{-1}_{\bot\ot\top}; (1_{\bot\ot \top}\op\Delta_{\bot});\mu_{\bot,\top,\bot,\bot}; ({u_\op^R}_{\bot} \ot {u_\op^R}_{\top}) = {u^R_\ot}_{\bot}; {u^R_\op}^{-1}_{\bot\ot\top};{u_\op^R}_{\bot\ot \top} = {u^R_\ot}_{\bot} \] by \eqref{cc:sym_absorption_law}. Thus,  $\Delta_{\bot};(1_{\bot}\ot m) = {u^R_\ot}_{\bot}$ as promised. \\

Similarly, we can show that $m\c\bot\rarr\top$ endows $\top$ with a commutative $\op$-monoid structure. Then, by Theorem \ref{thm:prove_mix}, the symmetric LDC is mix. \\

Finally, it straightforward to prove the symmetric versions of \eqref{cc:sym_medial_assoc},  \eqref{cc:sym_absorption_law} using the braidings. The only technical computation is showing that the coherence conditions \eqref{cc:sym_medial_braiding}, \eqref{cc:sym_medial_lindist} and \eqref{cc:sym_medial_lindist_braiding} imply the right linear distribution, defined as the composite of the left linear distribution and braidings, interacts coherently with the medial maps, in \eqref{cc:medial_lindist}, completing the proof.
\end{proof}

This alternative definition is of particular use because it involves fewer coherence conditions to check when looking at examples and it will be helpful in showing that symmetric medial LDCs with negation are equivalent to Lamarche's definition detailed in \cite{Lamarche_2007} in the following section

\subsection{Adding Negation}\label{sec:adding_negation}  \hfill\

\vspace{0.5\baselineskip}
As linear negation is central to linear logic and a component of many models of multiplicative linear logic, it was essential when developing LDCs that Cockett and Seely demonstrate how to include negation in their categorical framework to recover $*$-autonomous categories. Indeed, many of the key examples of LDCs are $*$-autonomous. The same holds true in our extension to medial LDCs. It is important we describe how the duoidal structure interacts with linear negation and recover Lamarche's definition of $*$-autonomous categories with finitary (binary and nullary) medial, and with the absorption law \cite{Lamarche_2007}.

\begin{definition}
A symmetric medial linearly distributive category $(\bX, \ot, \top, \op, \bot)$ {\bf has negation} if
\begin{itemize}
    \item it has negation as a symmetric linearly distributive category (Definition \ref{def:SLDC_negation}),
    \item $\bot$-contraction $\Delta_\bot\c\bot\rarr\bot\ot\bot$ and $\top$-cocontraction $\nabla_\top\c\top\op\top\rarr\top$ are dual to one another \eqref{cc:delta_nabla_dual}, and 
    \item the medial maps are self-dual \eqref{cc:medial_selfdual}.
\end{itemize}   

\begin{equation}\begin{gathered}\label{cc:delta_nabla_dual}
\xymatrixrowsep{1.75pc}\xymatrixcolsep{1.75pc}\xymatrix{
(\bot\ot\bot)^\perp\ar[d]_-{(\Delta_\bot)^\perp} & \bot^\perp\op\bot^\perp\ar[l]_-{\phi_{\bot,\bot}}\ar[r]^-{\beta_\top\op \beta_\top} & \top\op\top\ar[d]^-{\nabla_\top} \\
\bot^\perp\ar[rr]_-{\beta_\top} && \top
}
\end{gathered}\end{equation}
\begin{equation}\begin{gathered}\label{cc:medial_selfdual}
\xymatrixrowsep{1.75pc}\xymatrixcolsep{2.75pc}\xymatrix{
(A^\perp \ot B^\perp) \op (C^\perp \op D^\perp)\ar[d]_-{\mu_{A^\perp, B^\perp, C^\perp, D^\perp}} \ar[r]^-{\epsilon_{B,A}^{-1}\op \epsilon_{D,C}^{-1}} & (B\op A)^\perp \op (D\op C)^\perp \ar[d]^-{\phi_{B\op A, D\op C}}\\
(A^\perp \op C^\perp) \ot (B^\perp \op D^\perp)\ar[d]_-{\phi_{A,C}\ot \phi_{B,D}} & ((D\op C) \ot (B\op A))^\perp \ar[d]^-{\mu_{D,B,C,A}^\perp} \\
 (C\ot A)^\perp \ot (D\ot B)^\perp\ar[r]_-{\epsilon_{D\ot B, C\ot A}^{-1}} & ((D\ot B)\op (C\ot A))^\perp
}
\end{gathered}\end{equation}
