\end{definition}

\begin{lemma}
A symmetric medial linearly distributive category with negation $(\bX, \ot, \top, \op, \bot)$  has a self-dual nullary mix map $m\c \bot\rarr\top$, i.e.
\begin{equation}\begin{gathered}\label{cc:m_dual}
\xymatrixrowsep{1.75pc}\xymatrixcolsep{1.75pc}\xymatrix{
\bot\ar[d]_-{m}\ar[r]^-{\chi_\top} & \top^\perp\ar[d]^-{(m)^\perp} \\
\top\ar[r]_-{\beta^{-1}_\top} & \bot^\perp
}
\end{gathered}\end{equation}
\end{lemma}
\begin{proof}
This follows from the definition of $m\c \bot\rarr\top$ as a composite of unitors and the medial map, i.e. Proposition \ref{prop:iota_defined_by_zeta}, and the fact that the medial maps are self-dual themselves.  
\end{proof}

By Theorem \ref{thm:SLDC_starauto}, which states the correspondence between symmetric LDCs with negation and $*$-autonomous categories, and by comparing Lamarche's definition to the alternative definition of a symmetric medial LDC in Proposition \ref{prop:alternative_SMLDC}, it is immediate that: 

\begin{proposition}
The notions of symmetric medial linearly distributive categories with negation and of with that $*$-autonomous categories with finitary medial, and with the absorption law, as defined in \cite{Lamarche_2007}, coincide.
\end{proposition}

We will however also be particularly invested in symmetric medial LDCs which do not have a notion of negation. This is due to the ultimate goal of providing a 2-functor which maps symmetric medial LDCs to cartesian LDCs as part of the linearly distributive Fox theorem. If this construction preserves the negation of symmetric medial LDCs, then by Joyal's paradox, the resulting cartesian LDCs would necessarily be posets. This will be discussed in greater detail in Section \ref{sec:medial_bimonoids}. 

\subsection{Examples}\label{sec:examples}  \hfill\ 

\vspace{0.5\baselineskip}
The most important class example of a MLDC is of course the CLDCs, as the former were defined precisely to be an appropriate generalization of the latter. \\

The canonical duoidal structure of a CLDC was discussed by this author and co-author Lemay. It is precisely the one for cartesian and co-cartesian categories as described in Proposition \ref{prop:cartesian_duoidal}.

\begin{proposition}\cite[Prop 3.19]{Kudzman-Blais_Lemay_2025}
A cartesian linearly distributive category $(\bX, \times, \top, +, \bot)$ is a duoidal category, with structure maps
\begin{align*}
    &\Delta_{\bot} = b_{\bot\times \bot} = \langle 1_\bot, 1_\bot\rangle\c \bot\rarr \bot\times \bot\qquad \nabla_{\top} = t_{\top+\top} = [1_\top, 1_\top]\c\top+\top\rarr \top \\
    &m = t_{\bot}=b_{\top}\c \bot\rarr\top
\end{align*}
and interchange natural transformation
\begin{align*}
&\mu_{A,B,C,D}\c (A\times B)+(C\times D)\rarr (A+C)\times (B+D)\\
&=\langle \pi^0_{A,B} + \pi^0_{C,D}, \pi^1_{A,B} +\pi^1_{C,D}\rangle = [\iota^0_{A,C} \times \iota^0_{B,D}, \iota^1_{A,C} \times \iota^1_{B,D}]
\end{align*}
\end{proposition}

Moreover, Proposition 3.20 in \cite{Kudzman-Blais_Lemay_2025} details the how this duoidal structure interacts with the linear distributivities. The resulting commuting diagrams imply that:

\begin{theorem}\label{thm:CLDC_is_SMLDC}
Every cartesian linearly distributive category $(\cX, \times, \bone, +, \bzero)$ is canonically a symmetric medial linearly distributive category.
\end{theorem}

Another immediate class of examples are the braided monoidal categories, as every monoidal category is a degenerate LDC and every braided category is a strong duoidal category.

\begin{proposition}
Consider a braided monoidal category $(\cX, \os, I)$, then it is a medial linearly distributive category $(\cX, \os, I, \os, I)$ with
\[ \nabla_I = {u^{-1}_\os}_I \c I\os I \rarr I \qquad\qquad \Delta_I = {u_\os}_I \c I\rarr I\os I \qquad \qquad m = 1_I\c I\rarr I\]
\[ \mu_{A,B,C,D} = \tau^\os_{A,B,C,D}\c (A\os B)\os (C\os D) \rarr (A\os C)\os (B\os D)\]
\[ \delta^L_{A,B,C} = {\alpha_\os^{-1}}_{A,B,C}\c A\os (B\os C) \rarr (A\os B)\os C\] \[\delta^R_{A,B,C} = {\alpha_\os}_{A,B,C}\c (A\os B)\os C \rarr A\os (B\os C) \]
\end{proposition}
\begin{proof}
By Example \ref{ex:LDC}, every monoidal category is a degenerate LDC with associators for linear distributivities. By Example \ref{ex:duoidal} and Proposition \ref{prop:strong_duoidal}, we know ever braided monoidal category is a strong duoidal category with the canonical flip as its interchange map. Therefore, it only remains to verify \eqref{cc:medial_lindist}, which follow immediately by the coherence theorem for braided monoidal categories. 
\end{proof}

% Another possible source of examples would be to consider duoidal categories whose monoidal products are equal, but they are not strong, i.e. their interchange maps are not the canonical flips. These would immediately be degenerate LDCs. It would only remain to check \eqref{cc:medial_lindist} holds.

% \begin{example}
% Consider the category of vector spaces $\mathrm{Vec}$ with the duoidal structure $(\mathrm{Vec}, \odot, 0, \odot, 0)$ as described in Example \ref{ex:duoidal}.
% \end{example}

Our final source of examples stems from generalizing $Q$-coherences to the linearly distributive context, as first introduced by Lamarche \cite{Lamarche_1995} to capture Girard's coherence spaces and Ehrhard's hypercoherences, and later investigated in the context of $*$-autonomous categories with finitary (binary and nullary) medial, and with the absorption law \cite{Lamarche_2007}.  \\

Firstly, let $(\bP, \ot, \top, \op, \bot)$ be a posetal symmetric MLDC. In other words, $\bP$ is a poset with two commutative, associative and unital operations $\ot$ and $\op$, equipped with units $\top$ and $\bot$ respectively, such that the following inequalities hold $\forall a, b, c, d\in \bP$.
\[ \top\op\top\leq \top \qquad \bot\leq \bot\ot\bot \qquad \bot\leq \top \]
\[ (a\ot b)\op (c\ot d) \leq (a\op c)\ot (b\op d) \]
\[ (a\op b)\ot c \leq a\op (b\ot c) \qquad a\ot (b\op c) \leq (a\ot b)\op c\]

While this may seem at first glance to be an involved definition, one can quickly see that every bounded distributive lattice is such a poset with $\ot = \wedge$ and $\op = \vee$. Indeed, as proved in \cite{Kudzman-Blais_Lemay_2025}, a CLDC is a poset if and only if it is a bounded distributive lattice, and a posetal CLDC is of course a posetal symmetric MLDC as previously discussed. 

\begin{definition}\cite[Def 4.5]{Lamarche_2007}
\begin{itemize}
    \item A {\em \bP-coherence} $A = (|A|, \rho_A)$ consists of a pair of a poset $(|A|, \sqsubseteq)$ and a symmetric monotone function $\rho_A\c |A|\times|A|\rarr \bP$.   
    \item A {\em \bP-coherence map} $f\c A\rarr B$ is a relation $f\c |A|\nrightarrow |B|$ which is 
    \begin{enumerate}
        \item down-closed in the source: $(a,b)\in f \wedge a' \sqsubseteq a \implies (a',b)\in f$,
        \item up-closed in the target: $(a,b)\in f \wedge b\sqsubseteq b' \implies (a,b')\in f$, and 
        \item compatible with the monotone functions: $(a,b)\in f \wedge (a',b')\in f \implies \rho_A(a,a')\leq \rho_B(b,b')$
    \end{enumerate}
\end{itemize} 
\end{definition}

\begin{definition}\cite[Def 4.5]{Lamarche_2007}
Let \PCOH\ be denote the following structure:
\begin{itemize}
    \item Objects: \bP-coherences $A= (|A|, \rho_A)$
    \item Morphisms: \bP-coherence maps $f\c A\rarr B$
    \item Composition: standard composition of relations, i.e. given $f\c A\rarr B$ and $g\c B\rarr C$, $f;g\c A\rarr C$ is the relation $f;g\c |A|\nrightarrow|C|$ defined as \[ (a,c)\in f;g \iff \exists b\in B, (a,b)\in f \wedge (b,c)\in g\]
    \item Identities: given \bP-coherence $A= (|A|, \rho_A)$, $1_A\c A\rarr A$ is defined by
    \[ (a,a')\in 1_A \iff a \sqsubseteq\ a' \in |A| \]
    \item Tensor product: $\ot\c \PCOH\times \PCOH\rarr \PCOH$ is defined by 
    \[ (A = (|A|, \rho_A), B=(|B|, \rho_B))\mapsto A\ot B = (|A|\times |B|, \rho_{A\ot B})\]
    \[ (f\c A\rarr A', g\c B\rarr B')\mapsto (f\ot g\c A\ot B\rarr A'\ot B')\] 
    where the monotone function $\rho_{A\ot B}\c (|A|\times |B|)\times ((|A|\times |B|)\rarr \bP$ is given by 
    \[ \rho_{A\ot B}((a,b),(a',b')) = \rho_A(a,a')\ot \rho_B(b,b')\]
    and where $f\ot g$ is given by the relation $f\times g \c |A|\times |B| \nrightarrow |A'|\times |B'|$, i.e. 
    \[ ((a,b), (a',b))\in f\times g \iff (a,a')\in f\wedge (b,b')\in g\]
    \item Tensor unit: \bP-coherence $\top = (\{*\}, \rho_\top)$ where $\rho_\top(*,*) = \top \in \bP$
    \item Par product: $\op\c \PCOH\times \PCOH\rarr \PCOH$ is defined by 
    \[ (A = (|A|, \rho_A), B=(|B|, \rho_B))\mapsto A\op B = (|A|\times |B|, \rho_{A\op B})\]
    \[ (f\c A\rarr A', g\c B\rarr B')\mapsto (f\op g\c A\op B\rarr A'\op B')\] 
    where the monotone function $\rho_{A\op B}\c (|A|\times |B|)\times ((|A|\times |B|)\rarr \bP$ is given by 
    \[ \rho_{A\op B}((a,b),(a',b')) = \rho_A(a,a')\op \rho_B(b,b')\]
    and where $f\op g$ is given by the relation $f\times g \c |A|\times |B| \nrightarrow |A'|\times |B'|$, i.e. 
    \[ ((a,b), (a',b))\in f\times g \iff (a,a')\in f\wedge (b,b')\in g\]
    \item Par unit: \bP-coherence $\top = (\{*\}, \rho_\bot)$ where $\rho_\bot(*,*) = \bot\in \bP$
    \item Bottom-contraction map: $\Delta_\bot\c \bot\rarr \bot\ot \bot$ is relation $|\bot|\nrightarrow |\bot|\times|\bot|$  given by \[ (*,(*,*))\in \nabla_\top \]
    \item Top-cocontraction map: $\nabla_\top\c \top\op\top\rarr\top$ $|\top|\times |\top|\nrightarrow |\top|$ given by \[ ((*,*),*)\in \nabla_\top \]
    \item Nullary mix map: $m\c \bot \rarr\top$ is the relation $|\bot|\nrightarrow|\top|$ given by \[ (*,*)\in m\]
     \item Medial maps: $\mu_{A,B,C,D}\c (A\ot B)\op (C\ot D)\rarr (A\op D)\ot (C\op D)$ is relation $(|A|\times |B|)\times (|C|\times |D|)\nrightarrow (|A|\times |C|)\times (|B|\times |D|)$ given by
    \[ (((a,b),(c,d)), ((a',c'),(b',d')))\in \delta^L_{A,B,C} \iff a\sqsubseteq a' \wedge b\sqsubseteq b' \wedge c\sqsubseteq c' \wedge d\sqsubseteq s'\]
    \item Left linear distributivity: $\delta^L_{A,B,C}\c A\ot (B\op C)\rarr (A\ot B)\op C$ is relation $|A|\times(|B|\times |C|)\nrightarrow (|A|\times|B|)\times |C|$ given by 
    \[ (((a,(b,c)), ((a',b'),c'))\in \delta^L_{A,B,C} \iff a\sqsubseteq a' \wedge b\sqsubseteq b' \wedge c\sqsubseteq c'\]
\end{itemize}
\end{definition}

\begin{proposition}
\PCOH\ is a symmetric medial linearly distributive category.   
\end{proposition}
As the above construction is simply a small generalization of Lamarche's work, we shall not include the proof in this paper.

\subsection{Properties}\label{sec:properties} \hfill\

\vspace{0.5\baselineskip}
Notice that in a symmetric medial LDC, we have the canonical flip maps for the symmetric $\ot$-monoidal product and symmetric $\op$-monoidal product. The interaction between the medial maps, the linear distributivities and the canonical flip maps are given below.

\begin{proposition}\label{prop:interaction_canonical_flip_medial_maps_linear_dist}
The following diagrams commute in any symmetric medial linearly distributive category:
\begin{equation}\begin{gathered}\label{cc:interaction_canonical_flip_medial_maps_linear_dist}
\xymatrixrowsep{1.75pc}\xymatrixcolsep{2.75pc}\xymatrix@L=0.5pc{
(A\ot B)\ot((C\ot D)\op (E\ot F))\ar[r]^-{\delta^L_{A\ot B, C\ot D, E\ot F}}\ar[d]_-{1_{A\ot B}\ot \mu_{C,D,E,F}} & ((A\ot B)\ot (C\ot D))\op (E\ot F)\ar[d]^-{\tau^\ot_{A,B,C,D}\op 1_{E\ot F}} \\
(A\ot B)\ot ((C\op E)\ot(D\op F))\ar[d]_-{\tau^\ot_{A,B,C\op E, D\op F}} & ((A\ot C)\ot(B\ot D))\op (E\ot F)\ar[d]^-{\mu_{A\ot C, B\ot D, E,F} } \\
(A\ot (C\op E))\ot (B\ot (D\op F))\ar[r]_-{\delta^L_{A,C,E}\ot \delta^L_{B,D,F}} & ((A\ot C)\op E) \ot ((B\ot D)\op F)
}
\end{gathered}\end{equation}
\begin{align*}
&\delta^L_{A\ot B, C\ot D, E\ot F};(\tau^\ot_{A,B,C,D}\op 1_{E\ot F});\mu_{A\ot C, B\ot D, E,F} \\
&= (1_{A\ot B}\ot \mu_{C,D,E,F}); \tau^\ot_{A,B,C\op E, D\op F}; (\delta^L_{A,C,E}\ot \delta^L_{B,D,F}) \\ \\
&\mu_{A, B\op C, D, E\op F}; (1_{A\op D}\ot \tau^\op_{B,C,E,F}); \delta^L_{A\op D, B\op E, C\op F}= \\
&(\delta^L_{A,B,C}\op \delta^L_{D, E, F}); \tau^\op_{A\ot B, C, D\ot E, F}; (\mu_{A,B,D,E}\op 1_{C\op F})
\end{align*}
\end{proposition}

\begin{proof}
The proof of the first equality is given by the commuting diagram in Figure \ref{fig:interaction_canonical_flip_medial_maps_linear_dist}, in the Appendix \ref{app:commuting_diagrams} due to its size, and the other equality follows similarly. 
\end{proof}

The above proposition allows us to show that the medial maps are in some sense the canonical flip maps ``modulo'' the mix maps.

\begin{proposition}\label{prop:interchange_canonicalflip_mix}
Given a symmetric medial linearly distributive category, the following diagram commutes
\begin{equation}\label{diag:interchange_canonicalflip_mix}
\begin{gathered}\xymatrixrowsep{1.75pc}\xymatrixcolsep{2pc}\xymatrix@L=0.5pc{
(A\ot B)\op(C\ot D)\ar[r]^-{\mu_{A,B,C,D}}\ar[d]_-{\mix_{A,B}\op\mix_{C,D}} & (A\op C)\ot (B\op D)\ar[d]^-{\mix_{A\op C, B\op D}} \\
(A\op B)\op(C\op D)\ar[r]_-{\tau^\op_{A, B, C, D}} & (A\op C)\op(B\op D) \\
(A\ot B)\ot (C\ot D)\ar[r]^-{\tau^\ot_{A,B,C,D}}\ar[d]_-{\mix_{A\ot B, C\ot D}} & (A\ot C)\ot (B\ot D)\ar[d]^-{\mix_{A,C}\ot \mix_{B\ot D}} \\
(A\ot B)\op(C\ot D)\ar[r]_-{\mu_{A,B,C,D}} & (A\op C)\ot(B\op D) 
}
\end{gathered}\end{equation}  
\end{proposition}
\begin{proof}
The proof of the first equality is given by the commuting diagram in Figure \ref{fig:interaction_canonical_flip_medial_maps_mix} in the Appendix \ref{app:commuting_diagrams} due to its size, and the other equality follows similarly. 
\end{proof}

\vspace{0.5\baselineskip}
If we consider a MLDC with invertible linear distributivities, we know it must know the $\op$-monoidal product must be equivalent to the $\bot$-shifted tensor, but in the presence of medial structure, we can say even more:

\begin{proposition}
Consider a medial linearly distributive category $(\bX, \ot, \top,\op,\bot)$ with invertible linear distributivities, then its linearly distributive structure is compact.    
\end{proposition}
\begin{proof}
Consider a MLDC $(\bX, \ot, \top,\op,\bot)$ whose linear distributivities $\delta^L_{A,B,C}$ and $\delta^R_{A,B,C}$ have inverses. By Proposition \ref{prop:shift_tensor} and the details of the proof in \cite{Cockett_Seely_1997_LDC}, $\top\op\top$ is the tensor inverse of $\bot$ with isomorphisms
\[ s^L= \bot\ot(\top\op\top)\xrightarrow{\delta^L_{\bot,\top,\top}} (\bot\ot\top)\op\top \xrightarrow{{u^R_\ot}^{-1}_\bot\op1_\top} \bot\op\top \xrightarrow{{u^L_\op}_\top} \top \]  
\[s^R=(\top\op\top)\ot\bot\xrightarrow{\delta^R_{\top, \top,\bot}} \top\op(\top\ot\bot) \xrightarrow{1_\top\op{u^L_\ot}^{-1}_\bot} \top\op\bot \xrightarrow{{u^R_\op}_\top} \top \]

This implies that the MLDC is isomix as $m\c \bot\rarr\top$ has inverse defined by
\[ m^{-1} = \top \xrightarrow{{s^L}^{-1}} \bot\ot(\top\op\top) \xrightarrow{1_\bot\ot \nabla_\top} \bot\ot \top \xrightarrow{{u^R_\ot}_\bot^{-1}} \bot\]

$m^{-1}; m = 1_\top$ holds by the following commuting diagram
\begin{equation*}\begin{gathered}
\xymatrixrowsep{2.25pc}\xymatrixcolsep{3.75pc}\xymatrix@L=0.3pc{
\top\ar[rr]^-{{u^L_\op}^{-1}_\top}\ar@{=}[dddd]\ar@{}[rd]|{\eqref{cc:bot_top_comonoid_monoid}} && \bot\op \top\ar[r]^-{{u^R_\ot}_\bot}\ar[ld]_-{m\op 1_\top}\ar@{}[d]|{(\nat)} & (\bot\ot\top)\op\top\ar[dd]^-{{\delta^L_{\bot,\top,\top}}^{-1}}\ar[dl]_-{(m\ot 1_\top)\op 1_\top} \\
& \top\op\top\ar[dddl]_-{\nabla_\top}\ar[r]^-{{u_\ot}_\top \op 1_\top}\ar[rd]_-{{u^L_\ot}_{\top\op\top}}^{\eqref{cc:unit_lineardist}}& (\top\ot\top)\op \top\ar[d]^-{{\delta^L_{\top,\top,\top}}^{-1}} & \\
&\ar@{}[rd]|{(\nat)} & \top\ot(\top\op\top)\ar[d]^-{1_\top\ot \nabla_\top} \ar@{}[r]|{(\nat)} & \bot\ot(\top\op\top)\ar[dd]^-{1_\bot\ot \nabla_\top}\\
&&\top\ot \top\ar[lld]_-{{u_\ot}_\top^{-1}}\ar@{}[d]|{(\nat)}  \\
\top && \bot\ar[ll]^-{m} & \bot\ot\top\ar[l]^-{{u^R_\ot}_\bot^{-1}}\ar[ul]_-{m\ot 1_\top}
}
\end{gathered}\end{equation*}
Similarly, for $m; m^{-1} = 1_\bot$. \\

As the linear distributivities are isomorphisms and $m\c \bot\rarr\top$ is invertible, $\mix_{A,B}\c A\ot B\rarr A\op B$ is an isomorphism.
\end{proof}

Given a normal duoidal category, there is a construction providing a linearly distributive structure. Indeed, let $(\cX, \diamond, I, \star, J)$ be a duoidal category where $\iota\c I\rarr J$ is an isomorphism, we can define the following linear distributivities:
\begin{align*}
&\partial^L_{A,B,C}= A\diamond (B\star C) \cong (A\star J)\diamond (B\star C) \xrightarrow{\zeta_{A,J,B,C}} (A\diamond B)\star (J\diamond C) \cong (A\diamond B)\star C \\
&\partial^R_{A,B,C} = (A\star B)\diamond C \cong (A\star B)\diamond (J\star C) \xrightarrow{\zeta_{A,B,J,C}} (A\diamond J) \star (B\diamond C) \cong A\star (B\diamond C)
\end{align*}
Then, $(\cX, \diamond, I, \star, J)$ is an isomix LDC \cite{Spivak_Srinivasan_2024}. \\

Consider now an isomix MLDC $(\bX, \ot, \top,\op,\bot)$ with linear distributivities 
\[ \delta^L_{A,B,C}\c A\ot (B\op C)\rarr (A\ot B)\op C \qquad\qquad \delta^R_{A,B,C}\c (A\op B)\ot C\rarr A\op (B\op C)\]
Then, it is in particular a normal duoidal category $(\bX, \op, \bot,\ot,\top)$. By above, we know that $(\bX, \op, \bot, \ot, \top)$ is an isomix LDC with linear distributivities 
\[ \partial^L_{A,B,C}\c A\op(B\ot C) \rarr (A\op B)\ot C\ \qquad\qquad \partial^R_{A,B,C}\c (A\ot B)\op C\rarr 
A\ot (B\op C) \]
Notice the direction of the latter linear distributivities is opposite to the former. It turns out they are inverses of each other and, therefore, when isomix, the linearly distributive structure is compact.

\begin{proposition}\label{prop:isomix_MLDC}
Consider an isomix medial linearly distributive category $(\bX, \ot, \top,\op,\bot)$, then its linearly distributive structure is compact. 
\end{proposition}
\begin{proof}
Consider an isomix MLDC $(\bX, \ot, \top,\op,\bot)$ and define the natural transformations $\partial^L$ and $\partial^R$ as follows.
\begin{align*}
\partial^L_{A,B,C}= &A\op (B\ot C) \xrightarrow{{u^R_\ot}_A\op 1_{B\ot C}} (A\ot \top)\ot (B\ot C) \xrightarrow{\mu_{A,\top,B,C}} (A\op B)\ot (\top\op C) \\
&\xrightarrow{1_{A\op B}\ot (m^{-1}\op 1_C)} (A\op B)\ot (\bot \op C) \xrightarrow{1_{A\op B}\ot {u^L_\op}_C} (A\op B)\ot C \\
\partial^R_{A,B,C} =& (A\ot B)\op C \xrightarrow{1_{A\ot B}\op {u^R_\ot}_C} (A\ot B)\op (\top\ot C) \xrightarrow{\mu_{A,B,\top,C}} (A\op \top) \ot (B\op C)\\
&\xrightarrow{(1_A\op m^{-1})\ot 1_{B\op C}} (A\op \bot)\ot (B\op C) \xrightarrow{{u^R_\op}_A\ot 1_{B\op C}} A\ot (B\op C)
\end{align*}
Then, $\partial^R_{A,B,C}$ is the inverse of $\delta^L_{A,B,C}$ and $\partial^L_{A,B,C}$ is the inverse of $\delta^R_{A,B,C}$. The proof that $\delta^L_{A,B,C}; \partial^R_{A,B,C} = 1_{A\ot (B\op C)}$ follows from the commuting diagram in Figure \ref{fig:partial_R_inverse_delta_L} in the Appendix \ref{app:commuting_diagrams} due to its size. The other equalities follow similarly. \\

As the linear distributivities are isomorphisms and $m\c \bot\rarr\top$ is invertible, $\mix_{A,B}\c A\ot B\rarr A\op B$ is an isomorphism.
\end{proof}

\begin{remark}\label{rem:compact_not_strong}
The fact that the linearly distributive structure of a MLDC is compact does not mean however mean that the duoidal structure is strong, in other words that the structure maps are all invertible and the medial maps are in particular the canonical flip. We shall see an example of such a MLDC in Section \ref{sec:examples}.
\end{remark}

\section{Medial Linear Functors and Transformations}\label{sec:medial_linear_functor}

With the definition of medial LDCs well established, we now turn to the appropriate functors between these categories and the transformations between such functors. Similar to the 2-category of cartesian LDCs \CLDC, the corresponding 2-category would form a sub-2-category of \LDC. \\

As such, these ``medial linear functors'' are linear functors that also interact coherently with the duoidal structure. Given that there are two established definitions of duoidal functors, there are naturally at least two distinct types of ``medial linear functors''. However, we shall define only the specific class required for the linearly distributive Fox theorem. These functors are symmetric and strong, paralleling the strong symmetric monoidal functors found between symmetric monoidal categories. It is important to emphasize that these should not be regarded as the only valid choices for 1-cells between medial LDCs. Rather, they are the appropriate ones within the specific context of our work.

\begin{definition}
    Let $\bX$ and $\bY$ be symmetric linearly distributive categories. A {\bf strong symmetric medial linear functor} $F = (F_\ot, F_\op)\c \bX\rarr\bY$ consists of:

\begin{itemize}
    \item a functor $F_\ot\c \bX\rarr \bY$, equipped with 
    \begin{itemize}
        \item an invertible morphism $m_{\top}\c\top\xrightarrow{\sim} F_\ot(\top)$,
        \item a natural isomorphism 
        \begin{align*}
            &m_\ot\c (F_\ot\times F_\ot);\ot \Rarr \ot; F_\ot & {m_\ot}_{A, B}\c F_\ot(A)\ot F_\ot(B)\xrightarrow{\sim} F_\ot(A\ot B)
        \end{align*}
        \item a morphism $m_{\bot}\c\bot\rarr F_\ot(\bot)$, 
        \item a natural transformation 
        \begin{align*}
            &m_\op\c (F_\ot\times F_\ot);\op \Rarr \ot; F_\op  & {m_\op}_{A, B}\c F_\ot(A)\op F_\ot(B)\rarr F_\ot(A\op B)
        \end{align*}
    \end{itemize}
    such that
     \begin{itemize}
         \item $(F_\ot, m_{\top},m_\ot)\c (\bX, \ot, \top)\rarr(\bY,\ot,\top)$ is a strong symmetric monoidal functor,
         \item $(F_\ot, m_{\bot}, m_\op)\c(\bX, \op, \bot)\rarr(\bY,\op,\bot)$ is a symmetric monoidal functor, 
    \end{itemize}     

    \item a functor $F_\op\c \bX\rarr \bY$, equipped with 
    \begin{itemize}
        \item an invertible morphism $n_{\bot}\c F_\op(\bot)\xrightarrow{\sim} \bot$,
        \item a natural isomorphism
        \begin{align*}
            & n_\op\c \op;F_\op \Rarr (F_\op\times F_\op);\op  & {n_\op}_{A,B}\c F_\op(A\op B)\xrightarrow{\sim} F_\op(A)\op F_\op(B)
        \end{align*}
        \item a morphism $n_{\top}\c F_\op(\top)\rarr\top$,
        \item a natural transformation 
        \begin{align*}
            & n_\op\c \ot;F_\op \Rarr (F_\op\times F_\op);\ot & {n_\ot}_{A,B}\c F_\op(A\ot B)\rarr F_\op(A)\ot F_\op(B)
        \end{align*}
    \end{itemize}
    such that 
    \begin{itemize}
         \item \((F_\op, n_{\bot}, n_\op)\c(\bX, \op, \bot)\rarr(\bY,\op,\bot)\) is a strong symmetric comonoidal functor,
         \item \((F_\op, n_{\top}, n_\ot)\c(\bX, \op, \bot)\rarr(\bY,\op,\bot)\) is a symmetric comonoidal functor,
    \end{itemize}

    \item linear strength natural transformations
    \begin{align*}
        &v_\ot^R\c \op; F_\ot \Rarr (F_\op \times F_\ot); \op & {v_\ot^R}_{A,B} \c F_\ot(A\op B)\rarr F_\op(A)\op F_\ot(B)\\
        &v_\ot^R\c (F_\ot\times F_\op);\ot \Rarr \ot; F_\op & {v_\op^R}_{A,B} \c F_\ot(A)\ot F_\op(B)\rarr F_\op(A\ot B)\\
    \end{align*}
    satisfying the coherence conditions ensuring that
    \begin{itemize}
        \item $(F_\ot, m_{\bot},m_\op, m_{\top}^{-1}, m_\ot^{-1})\c(\bX, \op,\bot,\ot, \top)\rarr(\bY,\op,\bot,\ot,\top)$ is a bilax duoidal functor, i.e. \eqref{cc:F_ot_bilax} holds, 
        \item $(F_\op, n_{\bot}^{-1}, n_\op^{-1}, n_{\top}, n_\ot)\c(\bX, \op,\bot,\ot, \top)\rarr(\bY,\op,\bot,\ot,\top)$ is a bilax duoidal functor, i.e.  \eqref{cc:F_op_bilax} holds, 
        \item $F  = (F_\ot, F_\op)\c\bX\rarr\bY$ is a symmetric linear functor, and
        \item the linear strengths interact coherently with the $\bot$-contraction and $\top$-cocontraction maps \eqref{cc:linear_strength_nabla_delta}, with the medial transformation \eqref{cc:linear_strength_medial}, and $m_\op$ and $n_\ot$ \eqref{cc:linear_strength_m_op_n_ot}.
    \end{itemize}
\end{itemize}   
%
\begin{equation}\label{cc:F_ot_bilax}
\begin{gathered}
\begin{aligned}
&\Delta_{\bot};(m_{\bot}\ot m_{\bot});{m_\ot}_{\bot,\bot} = m_{\bot};F_\ot(\Delta_{\bot}) \\
&(m_{\top}\op m_{\top}); {m_\op}_{\top,\top}; F_{\ot}(\nabla_{\top}) = \nabla_{\top};m_{\top} \\ 
& m;m_{\top} = m_{\bot};F_\ot(m)\\ \\
&({m_\ot}_{A,B}\op {m_\ot}_{C,D}); {m_\op}_{A\ot B, C\ot D}; F_\ot(\mu_{A,B,C,D}) \\
&= \mu_{F_\ot(A), F_\ot(B), F_\ot(C), F_\ot(D)}; ({m_\op}_{A,C}\ot {m_\op}_{B, D}); {m_\ot}_{A\op C,B\op D}
\end{aligned}
\end{gathered}
