\end{proof}

Now, we turn to the discussion of transformations. As there are several potential notions of medial linear functors, there are multiple definitions of ``medial linear transformations''. However, we will introduce only the specific definition relevant to our treatment of medial LDCs.

\begin{definition}
Let $F, G\c\bX\rarr\bY$ be strong symmetric medial linear functors. A {\bf strong medial linear transformation} $\alpha = (\alpha_\ot, \alpha_\op)\c F\Rarr G$ consists of:
\begin{itemize}
	\item a natural transformation 
        \[ \alpha_\ot\c F_\ot\Rarr G_\ot \qquad\qquad {\alpha_\ot}_A\c F_\ot(A) \rarr G_\ot(A)\]
        such that 
        \begin{itemize}
            \item $\alpha_\ot\c (F_\ot, m_{\top}^{F}, m_\ot^{F}) \Rarr (G_\ot, m_{\top}^{G}, m_\ot^{G})$ is a monoidal transformation,
            \item  $\alpha_\ot\c (F_\ot, m_{\bot}^{F},m_\op^{F})\Rarr (G_\ot,m_{\bot}^{G}, m_\op^{G})$ is a monoidal transformation,
        \end{itemize}

	\item a natural transformation 
        \[ \alpha_\op\c G_\op\Rarr F_\op \qquad\qquad {\alpha_\op}_A\c G_\op(A)\rarr F_\op(A)\]
        such that 
        \begin{itemize}
            \item $\alpha_\op\c(G_\op, n_{\bot}^{G}, n_\op^{G}) \Rarr (F_\op, n_{\bot}^{F}, n_\op^{F})$ is a comonoidal transformation,
            \item $\alpha_\op\c (G_\op, {n_{\top}}^{G}, {n_\ot}^{G})\Rarr(F_\op, {n_\top^F}, {n_\ot}^{F})$ is a comonoidal transformation,
        \end{itemize}
\end{itemize}		
satisfying the coherence conditions ensuring that $\alpha = (\alpha_\ot, \alpha_\op)$ is a linear transformation, i.e. \eqref{cc:linear_trans_linear strength} holds. 
\end{definition}

\begin{remark}
Notice that the conditions that $\alpha_\ot\c F_\ot \Rarr G_\ot$ satisfies in the above definition are equivalent to asking that
\[\alpha_\ot\c (F_\ot, m_{\bot}^{F}, {m_\op}^{F}, {m_{\top}^{-1}}^{F},  {m_\ot^{-1}}^{F})\Rarr(G_\ot, m_{\bot}^{G}, {m_\op}^{G}, {m_{\top}^{-1}}^{G},{m_\ot^{-1}}^{G})\]
is a bilax duoidal transformation and, similarly, the conditions that $\alpha_\op\c G_\op\Rarr F_\op$ satisfies is equivalent to
\[\alpha_\op\c (G_\op, {n_{\bot}^{-1}}^{G},{n_\op^{-1}}^{G}, {n_\op}^{G},{n_{\top}}^{G})\Rarr(F_\op,{n_{\bot}^{-1}}^{F},{n_\op^{-1}}^{F}, {n_\op}^{F}, {n_{\top}}^{F})\]
being a  bilax duoidal transformation.
\end{remark}

\subsection{Frobenius Medial Linear Functors and Transformations} \hfill\

\vspace{0.5\baselineskip}
As in the case of Frobenius linear functors, we can consider strong symmetric medial linear functors whose pair of functors $F_\ot$ and $F_\op$ are equal.
\begin{definition}
A strong symmetric medial linear functor $F=(F_\ot,F_\op)\c \bX\rarr\bY$ is {\bf Frobenius} if
\begin{enumerate}
    \item $F_\ot = F_\op$,
    \item $m_\bot = n_\bot^{-1}$, ${m_\op}_{A,B} = {n_\op^{-1}}_{A,B}$, $n_\top = m_\top^{-1}$, and ${n_\ot}_{A,B} = {m_\ot^{-1}}_{A,B}$,
    \item ${\nu^R_\ot}_{A,B} = {n_\op}_{A,B}$, and ${\nu^R_\op}_{A,B} = {m_\ot}_{A,B}$.
\end{enumerate}
\end{definition}

Given the degeneracy, we can once more give an alternative characterization of such linear functors.
\begin{proposition}
Consider $\bX$ and $\bY$ be symmetric linearly distributive categories, then the following notions coincide:
\begin{itemize}
    \item Frobenius strong symmetric medial linear functors $F = (F_\ot, F_\op)\c \bX\rarr\bY$, and 
    \item strong symmetric $\ot$-monoidal and strong symmetric $\op$-comonoidal functors \\
    $(F, m_\top,m_\ot, n_\bot, n_\op)\c \bX\rarr\bY$ satisfying \eqref{cc:Frobenius_linear_functor}, \eqref{cc:mix_Frobenius_linear_functor} and \eqref{cc:Frobenius_medial_linear_functor_nabla_delta}.
\end{itemize}
\begin{equation}\begin{gathered}\label{cc:Frobenius_medial_linear_functor_nabla_delta}
\xymatrixrowsep{1.75pc}\xymatrixcolsep{1.25pc}\xymatrix{
F(\bot)\ar[r]^-{n_\bot}\ar[d]_-{F(\Delta_\bot)} & \bot\ar[r]^-{\Delta_\bot} & \bot\ot\bot\ar[d]^-{n_\bot^{-1}\ot n_\bot^{-1}} & F(\top\op\top)\ar[d]_-{F(\nabla_\top)}\ar[rr]^-{{n_\op}_{\top,\top}} & & F(\top) \op F(\top)\ar[d]^-{m_\top^{-1} \op m_\top^{-1}}\\
F(\bot\ot\bot) & & F(\bot)\ot F(\bot) \ar[ll]^-{{m_\ot}_{\bot,\bot}} & F(\top) & \top \ar[l]^-{m_\top}& \top \op \top \ar[l]^-{\nabla_\top} 
}\\
\xymatrixrowsep{1.75pc}\xymatrixcolsep{4.75pc}\xymatrix@L=0.5pc{
F((A\ot B)\op (C\ot D))\ar[r]^-{F(\mu_{A,B,C,D})} \ar[d]_-{{n_\op}_{A\ot B, C\ot D}} & F ((A\op C)\ot (B\op D)) \ar[d]^-{{m_\ot^{-1}}_{A\op C, B\op D}} \\
F(A\ot B)\op F(C\ot D)\ar[d]_-{{m_\ot^{-1}}_{A,B}\op {m^{-1}_\ot}_{C,D}} & F(A\op C)\ot F(B\op D)\ar[d]^-{{n_\op}_{A,C}\ot {n_\op}_{B,D}} \\
(F(A)\ot F(B))\op (F(C)\ot F(D)) \ar[r]_-{\mu_{F(A), F(B), F(C), F(D)}} &  (F(A)\op F(C))\ot (F(B)\op F(D)) \\
}
\end{gathered}\end{equation}
\end{proposition}

\begin{remark}
Recall that \eqref{cc:Frobenius_linear_functor} is equivalent to asking that $(F, m_\ot, m_\top, n_\op, n_\bot)\c \bX\rarr\bY$ is a Frobenius linear functor. Moreover, \eqref{cc:mix_Frobenius_linear_functor} and \eqref{cc:Frobenius_medial_linear_functor_nabla_delta} are equivalent to asking that \\$(F, n_\bot^{-1}, n_\op^{-1}, m_\top^{-1}, m_\ot^{-1})\c (\bX, \op, \bot, \ot, \top)\rarr(\bY, \op, \bot, \ot, \top)$ is a bilax duoidal functor. As Frobenius linear functors and bilax duoidal functors compose, we know Frobenius strong symmetric medial linear functors compose as well. 
\end{remark}

If we then consider strong medial linear transformations between such linear functors, we can see that the paired transformations must in fact be a section-retraction pair.
\begin{proposition}
Consider Frobenius strong symmetric medial linear functors $F, G\c \bX\rarr\bY$, then 
\begin{itemize}
    \item $\alpha_\ot\c F\Rarr G$ and $\alpha_\op\c G\Rarr F$ are a $\ot$-monoidal and $\op$-comonoidal transformations, and 
    \item for each object $A\in \bX$, ${\alpha_\ot}_A\c F(A)\rarr G(A)$ is a section of ${\alpha_\op}_A\c G(A)\rarr F(A)$, i.e. ${\alpha_\ot}; \alpha_\op = 1_{F}$.
\end{itemize}
\end{proposition}
\begin{proof}
Let $\alpha = (\alpha_\ot, \alpha_\op)\c F\Rarr G$ be a strong medial linear transformation between Frobenius strong symmetric medial linear functors. This means in particular that:
\begin{itemize}
    \item $\alpha_\ot\c (F, m_\top^F, m_\ot^F)\Rarr (G, m_\top^F, m_\ot^G)$ is a $\ot$-monoidal transformation
    \item $\alpha_\ot\c (F, {n_\bot^F}^{-1}, {n_\op^F}^{-1})\Rarr (G, {n_\bot^G}^{-1}, {n_\op^G}^{-1})$ is a $\op$-monoidal transformation, meaning $\alpha_\ot\c (F, n_\bot^F, n_\op^F)\Rarr (G, n_\bot^G, n_\op^G)$ 
\end{itemize}
Similarly, for $\alpha_\op$. Further, as $\alpha=(\alpha_\ot, \alpha_\op)\c F\Rarr G$ is a linear transformation, the diagrams in \eqref{cc:linear_trans_linear strength} holds, the first of which is as follows in the context of Frobenius linear functors:
\[ {\alpha_\ot}_{A\op B}; {n_\op^G}_{A,B}; ({\alpha_\op}_A\op 1_{G(B)}) = {n_\op^F}_{A,B}; (1_{F(A)}\op {\alpha_\ot}_B)\qquad (*)\]
Letting $B=\bot$ implies that $\alpha_\ot; \alpha_\op = 1_{F(A)}$ by the following commuting diagram.
\begin{equation*}
\xymatrixrowsep{2.75pc}\xymatrixcolsep{3.25pc}\xymatrix{
& G(A)\ar[rd]^-{G({u^R_\op}_A^{-1})}\ar@{}[d]|{(\nat)} & & \\
%
F(A)\ar[ru]^-{{\alpha_\ot}_A}\ar[r]_-{F({u^R_\op}_A^{-1})}\ar[dd]_-{{u^R_\op}^{-1}_{F(A)}}\ar@{}[rdd]|{\eqref{cc:mon_trans}} & F(A\op \bot)\ar@{}[rdd]|{(*)}\ar[dd]_-{{n_\op^F}_{A,\bot}}\ar[r]_-{{\alpha_{A\op \bot}}} & G(A\op \bot)\ar[r]^-{G({u^R_\op}_A)}\ar[d]_-{{n_\op^G}_{A,\bot}}\ar@{}[rd]|{\eqref{cc:mon_trans}} & G(A)\ar[rd]^-{{\alpha_\op}_A}\ar[d]^-{{u^R_\op}^{-1}_{G(A)}} \\
%
& & G(A)\op G(\bot)\ar[d]_-{{\alpha_\op}_A\op 1_{G(\bot)}}\ar[r]^-{1_{G(A)}\op {n^G_\bot}^{-1}}\ar@{}[rd]|{(\exch)} & G(A)\op\bot\ar[d]^-{{\alpha_\op}_A\op 1_\bot}\ar@{}[r]|{(\nat)} & F(A) \\
%
F(A)\op\bot\ar[r]_-{1_{F(A)}\op {n_\bot^F}^{-1}}&F(A)\op F(\bot)\ar[r]_-{1_{F(A)}\op {\alpha_\op}_\bot} & F(A)\op G(\bot)\ar[r]_-{1_{F(A)}\op n^G_\bot} & F(A)\op\bot\ar[ru]_-{{u^R_\op}_{F(A)}}
}
\end{equation*}
The top composite is $\alpha_\ot; \alpha_\op$, while the bottom composite is $1_{F(A)}$ since $\alpha_\op$ is $\op$-comonoidal.
\end{proof}

An immediate situation where one gets such a linear transformation is when considering an invertible $\ot$-monoidal and $\op$-comonoidal natural transformation.
\begin{proposition}
Given an invertible $\ot$-monoidal and $\op$-comonoidal natural transformations $\alpha\c F\Rarr G$ between strong symmetric Frobenius medial linear functors, the pair $(\alpha, \alpha^{-1})\c F\Rarr G$ is a strong medial linear transformation. 
\end{proposition}
\begin{proof}
Consider an invertible $\ot$-monoidal and $\op$-comonoidal natural transformations $\alpha\c F\Rarr G$, then by Lemma \ref{lem:Frobenius_linear_trans_2}, $(\alpha, \alpha^{-1})\c F\Rarr G$ is a linear transformation. To be a strong medial linear transformation, it remains to show $\alpha\c (F_\ot, m_\bot^F, m_\op^F)\Rarr (G_\ot, m_\bot^G, m_\op^G)$ is a $\op$-monoidal transformation and $\alpha^{-1}\c (G_\op, n_\top^G, n_\ot^G)\Rarr (F_\op, n_\top^F, n_\ot^F)$ is a $\ot$-comonoidal transformation.\\

Since $F$ and $G$ are Frobenius, this is in fact requiring that $\alpha\c (F, {n_\bot^F}^{-1}, {n_\op^F}^{-1})\Rarr (G, {n_\bot^G}^{-1}, {n_\op^G}^{-1})$ is a $\op$-monoidal transformation and $\alpha^{-1}\c (G, {m_\top^G}^{-1}, {m_\ot^G}^{-1})\Rarr(F, {m_\top^F}^{-1}, {m_\ot^F}^{-1})$ is a $\ot$-comonoidal transformation, which is true as $\alpha\c (F, n_\bot^F, n_\op^F)\Rarr (G, n_\bot^G, n_\op^G)$ is a $\op$-comonoidal transformation and $\alpha\c (F, m_\top^F, m_\ot^F)\Rarr (G, m_\top^G, m_\ot^G)$ is a $\ot$-monoidal transformation respectively.
\end{proof}

\subsection{2-Category \SMLDC} \hfill\

\vspace{0.5\baselineskip}
We now prove that these functors and transformations as 1-cells and 2-cells, with symmetric medial LDCs as 0-cells, form a 2-category.
\begin{theorem}
Symmetric medial linearly distributive categories, strong symmetric medial linear functors, and strong medial linear transformations form a 2-category, which is denoted by \SMLDC.  
\end{theorem}
\begin{proof}
Consider symmetric medial LDCs \bX, \bY\ and \bZ. Let $F=(F_\ot,F_\op)\c \bX\rarr\bY$ and $G=(G_\ot, G_\op)\c \bY\rarr\bZ$ be strong symmetric medial linear functor. Then, their horizontal composite $F; G = (F_\ot; G_\ot, F_\op; G_\op)\c \bX\rarr \bY$ is given by:

\begin{itemize}
    \item functor $F_\ot; G_\ot \c \bX\rarr \bZ$, equipped with 
    \begin{align*}
        &m^G_{\top}; G_\ot(m^F_\top)\c \top\rarr G_\ot(F_\ot(\top)) \\
        &{m_\ot}^G_{F_\ot(A), F_\ot(B)}; G_\ot({m^F_\ot}_{A,B})\c G_\ot(F_\ot(A)) \ot G_\ot(F_\ot(B)) \rarr G_\ot(F_\ot(A\ot B)) \\ \\
        &m^G_{\bot}; G_\ot(m^F_\bot)\c \bot\rarr G_\ot(F_\ot(\bot)) \\
        &{m^G_\op}_{F_\ot(A), F_\ot(B)}; G_\ot({m^F_\op}_{A, B})\c G_\ot(F_\ot(A)) \op G_\ot(F_\ot(B)) \rarr G_\ot(F_\ot(A\op B))
    \end{align*}   

    \item a functor $F_\op; G_\op\c \bX\rarr \bZ$, equipped with 
    \begin{align*}
        &G_\op(n^F_\bot); n^G_{\bot}\c G_\op(F_\op(\bot))\rarr \bot\\
        &G_\ot({n^F_\op}_{A,B}); {n^G_\op}_{F_\op(A),F_\op(B)}\c G_\op(F_\op(A\op B))\rarr G_\op(F_\op(A))\op G_\op(F_\op(B)) \\ \\
        &G_\op(n^F_\top); n^G_{\top}\c G_\op(F_\op(\top))\rarr \top \\
        &G_\ot({n^F_\ot}_{A,B}); {n^G_\ot}_{F_\op(A),F_\op(B)}\c G_\op(F_\op(A\ot B))\rarr G_\op(F_\op(A))\ot G_\op(F_\op(B)) 
    \end{align*} 

    \item linear strength natural transformations
    \begin{align*}
        &G_\ot({v_\ot^R}_{A,B}^F); {\nu^R_\ot}^G_{F_\op(A), F_\ot(B)} \c G_\ot(F_\ot(A\op B))\rarr G_\op(F_\op(A))\op G_\ot(F_\ot(B))\\
        & {\nu_\op^R}_{F_\ot(A),F_\op(B)}^{G};G_\op({\nu_\op^R}_{A,B}^{F})\c G_\ot(F_\ot(A))\ot G_\op(F_\op(B))\rarr G_\op(F_\op(A\ot B))
    \end{align*}
\end{itemize}
It is immediate that $F;G\c\bX\rarr\bZ$ is a strong symmetric linear functor,  and that $F_\ot; G_\ot \c \bX\rarr \bZ$ and $F_\op; G_\op\c \bX\rarr \bZ$ are bilax duoidal functors, as the composition is inherited from \LDC and \DUO in the appropriate ways. It remains only to show the additional coherence conditions also hold for $F;G\c\bX\rarr\bZ$. \\

The first diagram of \eqref{cc:linear_strength_nabla_delta} holds by the following commuting diagram and the second diagram holds similarly.\\
\begin{equation*}\begin{gathered}
\xymatrixrowsep{1.75pc}\xymatrixcolsep{1.75pc}\xymatrix@L=0.5pc{
G_\op(F_\op(\bot))\ar[r]^-{G_\op(n^F_\bot)}\ar[dd]_-{G_\op(F_\op(\Delta_\bot))} & G_\op(\bot)\ar[rd]_-{G_\op(\Delta_\bot)}\ar[r]^-{n^G_\bot} & \bot\ar[r]^-{\Delta_\bot} & \bot\ot \bot\ar[d]^-{m^G_\bot \ot {n^G_\bot}^{-1}} \ar@{}[dll]|{\eqref{cc:linear_strength_nabla_delta}\,\text{for}\,G}\\
\ar@{}[r]|{\eqref{cc:linear_strength_nabla_delta}\,\text{for}\,F} && G_\op(\bot\ot\bot)\ar[d]_-{G_\op(m^F_\bot \ot {n^F_\bot}^{-1})} & G_\ot(\bot)\ot G_\op(\bot)\ar[d]^-{G_\ot(m^F_\bot)\ot G_\op({n^F_\bot}^{-1})} \ar[l]_-{{\nu^R_\op}^G_{\bot,\bot}} \\
G_\op(F_\op(\bot\ot\bot)) & & G_\op(F_\ot(\bot)\ot F_\op(\bot))\ar[ll]^-{G_\op({\nu^R_\op}^F_{A,B})}\ar@{}[ru]|{(\nat)} & G_\ot(F_\ot(\bot))\ot G_\op(F_\op(\bot)) \ar[l]^-{{\nu^R_\op}^G_{F_\ot(\bot),F_\op(\bot)}}
}
\end{gathered}\end{equation*}
%
The first diagram \eqref{cc:linear_strength_medial} holds by the following commuting diagram, \\
\begin{equation*}
