%
{\begin{array}{@{}c@{}}G_\op(F_\op(A)\ot F_\op(B)) \op{}\\  G_\ot(F_\ot(C)\ot F_\ot(D))\end{array}} \ar[d]_-{\hbox{$\tiny\begin{array}{@{}c@{}} {n^G_\ot}_{F_\op(A),F_\ot(B)} \op{}\\ {m^G_\ot}^{-1}_{F_\ot(C),F_\op(D)} \end{array}$}}\ar@{}[rrrd]|{\eqref{cc:linear_strength_medial}} &&& {\begin{array}{@{}c@{}} G_\ot(F_\op(A)\op F_\ot(C))\ot{}\\ G_\ot(F_\op(B) \op F_\ot(D))\end{array}} \ar[d]^-{\hbox{$\tiny\begin{array}{@{}c@{}} {\nu^R_\ot}^G_{F_\op(A),F_\ot(C)} \op{}\\ {\nu^R_\ot}^{G}_{F_\op(B),F_\op(D)} \end{array}$}} \\
