{\begin{array}{@{}c@{}}(G_\op(F_\op(A)) \ot G_\op(F_\op(B))) \op{}\\ (G_\ot(F_\ot(C))\ot G_\ot(F_\ot(D)))\end{array}}\ar[rrr]_-{\mu_{G_\op(F_\op(A)), G_\op(F_\op(B)), G_\ot(F_\ot(C)), G_\ot(F_\ot(D))}} &&& {\begin{array}{@{}c@{}} (G_\op(F_\op(A)) \op G_\ot(F_\ot(C))) \ot{}\\ (G_\op(F_\op(B))\op G_\ot(F_\ot(D)))\end{array}}
}}
\end{equation*}

The first diagram of \eqref{cc:linear_strength_m_op_n_ot} holds by the following commuting diagram,\\
