Finally, it is immediate to show that the identity linear functors and the identity linear transformations are inherited by \SMLDC and that strong medial linear transformations are closed under the standard vertical and horizontal composition of linear transformations.
\end{proof}

\begin{proposition}\label{prop:inclusion_CLDC_SMLDC}
The inclusion map $\inc\c \CLDC\rarr\SMLDC$ determines a 2-functor.
\end{proposition}
\begin{proof}
By Theorem \ref{thm:CLDC_is_SMLDC}, every cartesian LDC has a canonical symmetric medial LDC structure. \\

Consider a cartesian linear functor
\[ F=(F_\times, F_+)\c (\bX, \times, \bone, +, \bzero)\rarr (\bY, \times, \bone, +, \bzero) \]  Then, in particular, $(F_\times, m_\bone^{-1}, m^{-1}_\times)\c (\bX,\times, \bone)\rarr (\bY, \times, \bone)$ and $(F_+, n^{-1}_\bzero, n^{-1}_+)\c (\bX, +,\bzero)\rarr (\bY, +, \bzero)$ are respectively comonoidal and monoidal functors. Then, by Proposition \ref{prop:cartesian_duoidal_functor}, the following are bilax duoidal functors, \[ (F_\times, p_\bzero, p_+, m_\bone^{-1}, m^{-1}_\times)\c (\bX, +,\bzero, \times, \bone)\rarr (\bY, +,\bzero, \times, \bone)\]\[ (F_+, n_\bzero^{-1}, n_+^{-1}, q_\bone, q_\times)\c (\bX, +,\bzero, \times, \bone)\rarr (\bY, +,\bzero, \times, \bone)\] where $p_\bzero, p_\times, q_\bone$ and $q_\times$ are defined in Lemma \label{functor_comon_if_cart}. In order to prove $F=(F_\times, F_+)$ is a strong symmetric medial linear functor, it remains to show the additional coherence conditions. \\

\eqref{cc:linear_strength_nabla_delta} holds by the universal property of initial and terminal objects:
\begin{align*}
\bzero \xrightarrow{b_{F_+(\bzero\times\bzero)}} F_+(\bzero\times\bzero) &=\bzero \xrightarrow{\Delta_\bzero} \bzero\times\bzero \xrightarrow{p_{\bzero}\times n_{\bzero}^{-1}} F_\times(\bzero)\times F_\times(\bzero) \xrightarrow{{\nu_+^R}_{\bzero,\bzero} } F_+(\bzero\times\bzero) \\
& = \bzero \xrightarrow{n_\bzero^{-1}} F_+(\bzero) \xrightarrow{F_+(\Delta_\bzero)} F_+(\bzero\times\bzero) \\ \\
F_\times(\bone+\bone) \xrightarrow{t_{F_\times(\bone+\bone)}} \bone&=F_\times(\bone+\bone) \xrightarrow{{\nu_\times^R}_{\bone,\bone}} F_+(\bone)+F_\times(\bone) \xrightarrow{q_{\bone}+ m^{-1}_{\bone}} \bone+\bone \xrightarrow{\nabla_\bone} \bone \\
&=F_\times(\bone+\bone) \xrightarrow{F_\times(\nabla_{\bone})} F_\times(\bone)\xrightarrow{m_{\bone}^{-1}} \bone
\end{align*}

The first coherence condition of \eqref{cc:linear_strength_medial} is 
\begin{align*}
&F_\times(\mu_{A,B,C,D}); {m_\times^{-1}}_{A+ C, B+ D}; ({\nu_\times^R}_{A,C}\times {\nu_\times^R}_{B,D})  \\
&={\nu_\times^R}_{A\times B, C\times D}; ({q_\times}_{A,B}+ {m^{-1}_\times}_{C,D}); \mu_{F_+(A), F_+(B), F_\times(C), F_\times(D)}
\end{align*}
and it holds as follows. The left-hand side and right-hand sides composed with the $0^{th}$ projection are given by
\begin{align*}
&F_\times(\mu_{A,B,C,D}); {m_\times^{-1}}_{A+ C, B+ D}; ({\nu_\times^R}_{A,C}\times {\nu_\times^R}_{B,D}); \pi^0_{F_+(A)+F_\times(C), F_+(B)+ F_\times(D)} \\
&= F_\times(\mu_{A,B,C,D}); {m_\times^{-1}}_{A+ C, B+ D}; \pi^0_{F_\times(A+C), F_\times(B+D)}; {\nu_\times^R}_{A,C} \\
&= F_\times(\mu_{A,B,C,D}); F_\times(\pi^0_{A+C, B+D}); {\nu_\times^R}_{A,C} = F_\times(\pi^0_{A,B}+\pi^0_{C,D}); {\nu_\times^R}_{A,C} \\
\\
&{\nu_\times^R}_{A\times B, C\times D}; ({q_\times}_{A,B}+ {m^{-1}_\times}_{C,D}); \mu_{F_+(A), F_+(B), F_\times(C), F_\times(D)}; \pi^0_{F_+(A)+F_\times(C), F_+(B)+ F_\times(D)} \\
&= {\nu_\times^R}_{A\times B, C\times D}; ({q_\times}_{A,B}+ {m^{-1}_\times}_{C,D}); (\pi^0_{F_+(A), F+(B)}+\pi^0_{F_\times(C), F_\times(D)}) \\
&=  {\nu_\times^R}_{A\times B, C\times D}; (F_+(\pi^0_{A, B})+F_\times(\pi^0_{C,D})) = F_\times(\pi^0_{A,B}+\pi^0_{C,D}); {\nu_\times^R}_{A,C}
\end{align*}
Similarly, when composed with the $1^{st}$ projection, 
\begin{align*}
&F_\times(\mu_{A,B,C,D}); {m_\times^{-1}}_{A+ C, B+ D}; ({\nu_\times^R}_{A,C}\times {\nu_\times^R}_{B,D}); \pi^0_{F_+(A)+F_\times(C), F_+(B)+ F_\times(D)} \\
& = F_\times(\pi^1_{A,B}+\pi^1_{C,D}); {\nu_\times^R}_{B,D}\\ 
\\
&{\nu_\times^R}_{A\times B, C\times D}; ({q_\times}_{A,B}+ {m^{-1}_\times}_{C,D}); \mu_{F_+(A), F_+(B), F_\times(C), F_\times(D)}; \pi^1_{F_+(A)+F_\times(C), F_+(B)+ F_\times(D)} \\
& = F_\times(\pi^1_{A,B}+\pi^1_{C,D}); {\nu_\times^R}_{B,D}\\ 
\end{align*}
Then, by the universal properties of products, the  first coherence condition of \eqref{cc:linear_strength_medial} holds. The second condition similarly by the universal properties of coproducts. \\

The first condition of \eqref{cc:linear_strength_m_op_n_ot} is
\begin{align*}
&{\nu_+^R}_{A, B\times C}; F_+({\alpha_\times^{-1}}_{A,B,C}); {q_\times}_{A\times B, C}\\
&= (1_{F_\times(A)}\times {q_\times}_{B,C}); {\alpha_\times^{-1}}_{F_\times(A), F_+(B), F+(C)}; ({\nu^R_+}_{A, B}\times 1_{F_+(C)})
\end{align*}
The left-hand side and right-hand sides composed with the projections are given by
\begin{align*}
&{\nu_+^R}_{A, B\times C};F_+({\alpha_\times^{-1}}_{A,B,C}); {q_\times}_{A\times B, C}; \pi^0_{F_+(A\times B), F_+(C)} = {\nu_+^R}_{A, B\times C}; F_+({\alpha_\times^{-1}}_{A,B,C}); F_+(\pi^0_{A\times B, C}) \\
&= {\nu_+^R}_{A, B\times C}; F_+(1_{A}\times \pi^0_{B,C}) = (1_{F_\times(A)}\times F_+(\pi^0_{B,C})); {\nu_+^R}_{A, B} \\ \\
&(1_{F_\times(A)}\times {q_\times}_{B,C}); {\alpha_\times^{-1}}_{F_\times(A), F_+(B), F+(C)}; ({\nu^R_+}_{A, B}\times 1_{F_+(C)}); \pi^0_{F_+(A\times B), F_+(C)} \\
&= (1_{F_\times(A)}\times {q_\times}_{B,C}); {\alpha_\times^{-1}}_{F_\times(A), F_+(B), F+(C)}; \pi^0_{F_\times(A)\times F_+(B), F_+(C)}; {\nu^R_+}_{A, B} \\
&= (1_{F_\times(A)}\times {q_\times}_{B,C}); (1_{F_\times(A)}\times \pi^0_{F_+(B), F_+(C)}); {\nu^R_+}_{A, B} = (1_{F_\times(A)}\times F_+(\pi^0_{B,C})); {\nu_+^R}_{A, B} \\ \\
&{\nu_+^R}_{A, B\times C}; F_+({\alpha_\times^{-1}}_{A,B,C}); {q_\times}_{A\times B, C}; \pi^1_{F_+(A\times B), F_+(C)} = {\nu_+^R}_{A, B\times C}; F_+({\alpha_\times^{-1}}_{A,B,C}); F_+(\pi^1_{A\times B, C}) \\
&= {\nu_+^R}_{A, B\times C}; F_+(\pi^1_{A, B\times C}); F_+(\pi^1_{B,C}) = {\nu_+^R}_{A, B\times C}; F_+(!_{A}\times 1_{B\times C}); F_+({u^L_\times}_{B\times C}^{-1});F_+(\pi^1_{B,C}) \\
&=(F_\times(!_{A})\times F_+(1_{B\times C})); {\nu_+^R}_{\bone, B\times C};F_+({u^L_\times}_{B\times C}^{-1});F_+(\pi^1_{B,C})\\
&=(F_\times(!_{A})\times F_+(1_{B\times C})); (m_{\bone}^{-1}\times 1_{F_+(B\times C)}); {u^L_\times}_{F_+(B\times C)}^{-1}; F_+(\pi^1_{B,C}) =\pi^1_{F_\times(A), F_+(B\times C)}; F_+(\pi^1_{B,C}) \\ \\
&(1_{F_\times(A)}\times {q_\times}_{B,C}); {\alpha_\times^{-1}}_{F_\times(A), F_+(B), F+(C)}; ({\nu^R_+}_{A, B}\times 1_{F_+(C)}); \pi^1_{F_+(A\times B), F_+(C)} \\
&= (1_{F_\times(A)}\times {q_\times}_{B,C}); {\alpha_\times^{-1}}_{F_\times(A), F_+(B), F+(C)}; \pi^{1}_{F_\times(A)\times F_+(B), F_+(C)} \\
&= (1_{F_\times(A)}\times {q_\times}_{B,C}); \pi^{1}_{F_\times(A), F+(B)\times F_+(C)}; \pi^1_{F_+(B), F_+(C)} \\
&=  \pi^1_{F_\times(A), F_+(B\times C)}; {q_\times}_{B,C}; \pi^1_{F_+(B), F_+(C)} = \pi^1_{F_\times(A), F_+(B\times C)}; F_+(\pi^1_{B,C}) 
\end{align*}
Then, by the universal property of products, the first condition of \eqref{cc:linear_strength_m_op_n_ot} holds. The second condition of \eqref{cc:linear_strength_m_op_n_ot} follows by the universal properties of coproducts for the same reasons as its counterpart.\\

Consider a linear transformation $\alpha = (\alpha_\times,\alpha_+)\c F\Rarr G\c\bX\rarr\bY$ between strong symmetric linear functors between cartesian LDCs. In particular, it is a pair consisting of a monoidal transformation $\alpha_\times\colon (F_\times, m^{F}_{\bone}, m^{F}_\times)\Rarr (G_\times, m^{G}_{\bone}, m^{G}_\times)$ and $\alpha_+\colon (F_+, n^{F}_{\bzero}, n^{F}_+)\Rarr (G_+, n^{G}_{\bzero}, n^{G}_+)$. By Proposition \ref{functor_comon_if_cart}, $\alpha_\times\colon(F, p^{F}_{\bzero}, p^{F}_+)\Rarr(G, p^{G}_{\bzero}, p^{G}_+)$ is a monoidal transformation and $\alpha_+\colon (F_+, q^{F}_{\bone}, q^{F}_\times)\Rarr (G_+, q^{G}_{\bone}, q^{G}_\times)$ is a comonoidal transformation. As such, $\alpha$ is a strong medial linear transformation.\\

Therefore, the inclusion map $\inc\c\CLDC\rarr\SMLDC$ is well-defined. The proof that it is moreover a 2-functor follows by examining that canonical medial linear functor structure of a cartesian linear functor described above respects composition and identities. 
\end{proof}

It is fairly immediate to see that the above results can restricted to Frobenius linear functors.
\begin{corollary}
Symmetric medial linearly distributive categories, strong symmetric Frobenius medial linear functors and strong medial linear transformations form a sub 2-category of \SMLDC, denoted by $\mathbf{SFMLDC}$. Further, the inclusion map $\inc\c \CLDC\rarr\SMLDC$ restricts to an inclusion 2-functor $\inc\c\mathbf{FCLDC}\rarr\mathbf{SFMLDC}$
\end{corollary}
\begin{proof}
The only technicality to verify is that given a Frobenius cartesian linear functor $F=(F_\times,F_+)\c \bX\rarr \bY$, the induced strong symmetric medial linear functor is Frobenius, in other words that the canonical $+$-monoidal structure on $(F_\times,p_\bzero, p_+)\c (\bX, \bzero, +)\rarr (\bY, \bzero, +)$ corresponds to $(F_+, n_\bzero^{-1}, n_+^{-1})\c (\bX, \bzero, +)\rarr (\bY, \bzero, +)$ and similarly for the canonical $\times$-comonoidal structure on $F_+$. This is immediate however as $F_+ = F_\times$. While the structure maps $n_\bzero$ and ${n_+}_{A,B}$ are not guaranteed to have inverses, if they do, they must be the canonical ones $p_\bzero$ and ${p_+}_{A,B}$. Similarly, $q_\bone = {m_\bone}^{-1}$ and ${q_\times}_{A,B} = {m_\times^{-1}}_{A,B}$.
\end{proof}

\section{Linearly Distributive Fox Theorem}\label{sec:LD_Fox}

It is now time to discuss the construction on a symmetric medial LDCs which will yield a cartesian LDCs, mirroring the category of cocommutative comonoids of a symmetric monoidal category to create a cartesian category in the standard Fox theorem. \\

If we review our earlier characterization of cartesian LDCs in Proposition \ref{prop:char_CLDC}, which followed as a direct consequence of the Fox theorem and its dual, we see that a cartesian LDC \bX\ is in particular a symmetric LDC, where each object $A\in\bX$ is equipped with four morphisms
\[\Delta_A\c A\rarr A\ot A \qquad e_A\c A\rarr\top \qquad \nabla_A\c A\op A\rarr A \qquad u_A\c \bot\rarr A\]
such that $\langle A, \Delta_A, e_A\rangle$ is a cocommutative $\ot$-comonoid and $\langle A, \nabla_A, u_A\rangle$ is a commutative $\op$-monoid. \\

To someone well-versed in duoidal category theory, this structure will be familiar. Indeed, these are the same maps and structures of a duoidal bimonoid in a duoidal category. This is the key to the theorem and why the duoidal structure of the medial LDCs is essential.

\subsection{Medial Bimonoids}\label{sec:medial_bimonoids}  \hfill\

\begin{definition}
Let \bX\ be a symmetric medial linearly distributive category. 
\begin{itemize}
    \item A {\bf medial bimonoid} in \bX\ is a quintuple $\langle A, \Delta_{A}, u_{A}, \nabla_{A}, e_{ A}\rangle$ consisting of an object $A$ and four morphisms 
    \[\Delta_A\c A\rarr A\ot A \qquad e_A\c A\rarr\top \qquad \nabla_A\c A\op A\rarr A \qquad u_A\c \bot\rarr A\] in \bX\ such that 
\begin{itemize}
	\item $\langle A, \Delta_{A}, e_{A}\rangle$ is a $\ot$-comonoid,
	\item $\langle A, \nabla_{A}, u_{A}\rangle$ is a $\op$-monoid, 
\end{itemize}
satisfying coherence conditions between $\ot$-comonoid and $\op$-monoid structure maps \eqref{cc:medial_bimonoid}.
%
\begin{equation}\begin{gathered}\label{cc:medial_bimonoid}
\xymatrixrowsep{1.75pc}\xymatrixcolsep{1.75pc}\xymatrix@L=0.5pc{
A\op A\ar[r]^-{\nabla_A}\ar[d]_-{\Delta_A\op\Delta_A} & A\ar[r]^-{\Delta_A} & A\ot A  & \bot\ar[r]^-{m}\ar[d]_-{u_A} & \top\\
(A\ot A)\op (A\ot A)\ar[rr]_-{\mu_{A,A,A,A}} && (A\op A)\ot (A\op A)\ar[u]_-{\nabla_A\ot\nabla_A} & A\ar[ru]_-{e_A} \\
A\op A\ar[r]^{\nabla_A}\ar[d]_-{e_A\op e_A} & A\ar[d]^-{e_A} & \bot\ar[r]^-{u_A}\ar[d]_-{\Delta_\bot} & A\ar[d]^-{\Delta_A} \\
\top \op \top \ar[r]_-{\nabla_\top}& \top & \bot\ot \bot\ar[r]_-{u_A\ot u_A} & A\ot A
}
\end{gathered}\end{equation}

Alternatively, a medial bimonoid in \bX\ is a duoidal bimonoid in the duoidal category $(\bX, \op, \bot, \ot, \top)$. 

\item A medial bimonoid $\langle A, \Delta_{A}, e_{A}, \nabla_{A}, u_{A}\rangle$ is {\bf bicommutative} if $\langle A, \Delta_{A}, e_{A}\rangle$ is cocommutative $\ot$-comonoid and $\langle A, \nabla_{A}, u_{A}\rangle$ is a commutative $\op$-monoid.

\item A {\bf bimonoid morphism} $f\c\langle A, \Delta_{A}, u_{A}, \nabla_{A}, e_{A}\rangle\rarr\langle B, \Delta_{B}, u_{B}, \nabla_{B}, e_{B}\rangle$ is a morphism $f\c A\rarr B$ in \bX\ such that 
\begin{itemize}
	\item $f\c\langle A, \Delta_{A}, e_{A}\rangle\rarr\langle B, \Delta_{B}, e_{B}\rangle$ is a $\ot$-comonoid morphism, and 
	\item $f\c\langle A, \nabla_{A}, u_{A}\rangle\rarr\langle B, \nabla_{B}, u_{B}\rangle$ is a $\op$-monoid morphism
\end{itemize}

\end{itemize}
\end{definition}

It is immediate that the $\ot$ and $\op$ units in a symmetric medial LDC have canonical medial bimonoid structures given by the duoidal structure maps, as the $\ot$-comonoid structure of $\bot$ and $\op$-monoid structure for $\top$ are part of the definition of a medial LDC, and the other coherence conditions follow easily. 

\begin{proposition}\label{prop:top_bottom_medial_bimonoids}
Given a symmetric medial linearly distributive category \bX, the following
\[\langle \top, {u_\ot}_\top\c \top\rarr\top\ot\top, 1_\top\c\top\rarr\top, \nabla_\top\c\top\op\top\rarr\top, m\c \bot\rarr\top \rangle\]
\[ \langle \bot, \Delta_\bot\c\bot\rarr\bot\ot\bot, m\c\bot\rarr\top, {u_\op}_\bot\c\bot\op\bot\rarr\bot, 1_\bot\c\bot\rarr\bot\rangle\]
 are bicommutative bimonoids. 
\end{proposition}

Furthermore, medial bimonoids combine together via the tensor and par monoidal products to produce new medial bimonoids as follows. 

\begin{proposition}\label{prop:constructing_medial_bimonoids}
Consider a pair of bicommutative medial bimonoids $\langle A, \Delta_A, e_A, \nabla_A, u_A\rangle $ and  $\langle B, \Delta_B, e_B, \nabla_B, u_B\rangle$ in a symmetric medial linearly distributive category \bX. Then, the object $A\ot B$ equipped with morphisms 
\begin{align*}
& \Delta_{A\ot B} = A\ot B \xrightarrow{\Delta_A\ot\Delta_B} (A\ot A)\ot (B\ot B) \xrightarrow{\tau^\ot_{A,A,B,B}} (A\ot B)\ot(A\ot B) \\
&t_{A\ot B} = A\ot B\xrightarrow{e_A\ot e_B} \top\ot \top \xrightarrow{{u_\ot}_\top^{-1}} \top \\
&\nabla_{A \ot B} = (A\ot B)\op(A\ot B)\xrightarrow{\mu_{A,B,A,B}} (A\op A)\ot (B\op B) \xrightarrow{\nabla_A\ot \nabla_B} A\ot B \\
&u_{A\ot B}= \bot\xrightarrow{\Delta_\bot} \bot\ot\bot \xrightarrow{u_A\ot u_B} A\ot B
\end{align*}
and the object $A\op B$ equipped with morphisms 
\begin{align*}
& \Delta_{A\op B} = A\op B \xrightarrow{\Delta_A\op\Delta_B} (A\ot A)\op (B\ot B) \xrightarrow{\mu_{A,A,B,B}} (A\op B)\ot(A\op B) \\
&t_{A\op B} = A\op B\xrightarrow{e_A\op e_B} \top\op\top \xrightarrow{\nabla_\top} \top \\
&\nabla_{A\op B} = (A\op B)\op(A\op B)\xrightarrow{\tau^\op_{A,B,A,B}} (A\op A)\op (B\op B) \xrightarrow{\nabla_A\op \nabla_B} A\op B \\
&u_{A\op B}= \bot\xrightarrow{{u_\op}_\bot^{-1}} \bot\op\bot \xrightarrow{u_A\op u_B} A\op B
\end{align*}
are bicommutative medial bimonoids. 
\end{proposition}
\begin{proof}
It follows immediately, by Lemma \ref{lem:constructing_comonoids} that $\langle A\ot B, \Delta_{A\ot B}, t_{A\ot B}\rangle$ is a cocommutative $\ot$-comonoid. $\langle A\ot B, \nabla_{A\ot B}, e_{A\ot B}\rangle$ is a commutative $\op$-monoid as follows:\\

$\nabla_{A\ot B}$ satisfies the associativity coherence condition in \eqref{cc:monoid_assoc} by the commuting diagram below.
\begin{equation*}
\resizebox{\linewidth}{!}{
\xymatrixrowsep{1.75pc}\xymatrixcolsep{1.75pc}\xymatrix@L=1pc{
{\begin{array}{@{}c@{}}(A\ot B) \op{}\\  ((A\ot B)\op (A\ot B))\end{array}}\ar[r]^-{{\alpha_\op}_{A\ot B, A\ot B, A\ot B}}\ar[d]_-{1_{A\ot B}\op \mu_{A,B,A,B}}\ar@{}[rrd]|{\eqref{cc:medial_assoc}}& 
{\begin{array}{@{}c@{}}((A\ot B)\op (A\ot B))\op{}\\  (A\ot B)\end{array}}\ar[r]^-{\mu_{A,B,A,B}\op 1_{A\ot B}} &{\begin{array}{@{}c@{}}((A\op A)\ot (B\op B)) \op{}\\ (A\ot B)\end{array}}\ar[r]^-{(\nabla_A\ot \nabla_B)\op 1_{A\ot B}}\ar[d]_-{\mu_{A\op A, B\op B, A, B}} \ar@{}[rd]|{(\nat)} & (A\ot B)\op (A\ot B)\ar[d]^-{\mu_{A,B,A,B}}\\
%
{\begin{array}{@{}c@{}}(A\ot B) \op{}\\  ((A\op A)\ot (B\op B))\end{array}}\ar[d]_-{1_{A\ot B}\op (\nabla_A\ot\nabla_B)}\ar[r]^-{\mu_{A,B,A\op A, B\op B}}\ar@{}[rd]|{(\nat)}  & {\begin{array}{@{}c@{}}(A\op (A\op A))\ot{}\\ (B\op (B\op B))\end{array}}\ar[d]^-{(1_A\op \nabla_A)\ot (1_B\op \nabla_B)}\ar[r]_-{{\alpha_\op}_{A,A,A}\ot {\alpha_\op}_{B,B,B}} \ar@{}[rrd]|{\eqref{cc:monoid_assoc}} &{\begin{array}{@{}c@{}}((A\op A)\op A)\ot {}\\  ((B\op B)\op B)\end{array}}\ar[r]_-{(\nabla_A\op 1_A)\ot (\nabla_B\op 1_B)}& (A\op A)\ot (B\op B)\ar[d]^-{\nabla_A\ot \nabla_B}\\
%
(A\ot B)\op (A\ot B)\ar[r]_-{\mu_{A,B,A,B}} & (A\op A)\ot (B\op B) \ar[rr]_-{\nabla_A\ot \nabla_B} && A\ot B
}}
\end{equation*}
%
$\nabla_{A\ot B}$ and $e_{A\ot B}$ satisfy the unitality coherence condition in \eqref{cc:monoid_units} by the commuting diagram below.
\begin{equation*}
\xymatrixrowsep{2.75pc}\xymatrixcolsep{2.75pc}\xymatrix@L=0.5pc{
(A\ot B)\op \bot\ar[d]_-{{u^R_\op}_{A\ot B}}\ar[r]^-{1_{A\ot B}\op \Delta_\bot}\ar@{}[rd]|{\eqref{cc:absorption_law}} & (A\ot B)\op (\bot\ot\bot)\ar[r]^-{1_{A\ot B}\op (u_A\ot u_B)}\ar[d]_-{\mu_{A,B,\bot,\bot}}\ar@{}[rd]|{(\nat)} & (A\ot B)\op (A\ot B)\ar[d]^-{\mu_{A,B,A,B}} \\
(A\ot B)A\ot B\ar[r]_-{{u^R_\op}_A^{-1}\ot{u^R_\op}_B^{-1}} &(A\op\bot)\ot(B\op\bot)\ar[r]^-{(1_A\op u_A)\ot(1_B\op u_B)}\ar@/_2.0pc/[rd]_-{{u^R_\op}_A\ot {u^R_\op}_B} & (A\op A)\ot (B\op B)\ar[d]^-{\nabla_A\ot \nabla_B} \\
&\ar@{}[ru]|{\eqref{cc:monoid_units}}& A\ot B
}
\end{equation*}

Finally, $\nabla_{A\ot B}$ satisfies the commutativity condition \eqref{cc:commutative_monoid} by the commuting diagram below.
\begin{equation*}
\xymatrixrowsep{2.75pc}\xymatrixcolsep{3.75pc}\xymatrix@L=0.5pc{
(A\ot B)\op (A\ot B)\ar[r]^-{\mu_{A,B,A,B}}\ar[d]_-{{\sigma_\op}_{A\ot B, A\ot B}}\ar@{}[rd]|{\eqref{cc:sym_medial_braiding}} & (A\op A)\ot (B\op B)\ar[r]^-{\nabla_A\ot \nabla_B}\ar[d]_-{{\sigma_\op}_{A,A}\ot {\sigma_\op}_{B,B}} \ar@{}[rd]|{\eqref{cc:commutative_monoid}} & A\ot B\\
(A\ot B)\op (A\ot B)\ar[r]_-{\mu_{A,B,A,B}} & (A\op A)\ot (B\op B)\ar@/_2pc/[ru]_-{\nabla_A\ot \nabla_B} &
}
\end{equation*}

It remains to show the four coherence conditions in \eqref{cc:medial_bimonoid} hold. \\

$\Delta_{A\ot B}$ and $\nabla_{A\ot B}$ satisfy the first diagram in \eqref{cc:medial_bimonoid} by the following commuting diagram:
\begin{equation*}
\resizebox{\linewidth}{!}{\xymatrixrowsep{2.75pc}\xymatrixcolsep{1.75pc}\xymatrix@L=0.5pc{
