{\begin{array}{@{}c@{}}((A\ot A)\op (A\ot A))\ot{}\\ ((B\ot B)\op (B\ot B))\end{array}}\ar[rr]_-{\mu_{A,A,A,A}\ot \mu_{B,B,B,B}} &&
{\begin{array}{@{}c@{}}((A\op A)\ot (A\op A)) \ot{}\\ ((B\op B)\ot (B\op B))\end{array}} \ar[r]_*!/_6pt/{\tau^\ot_{A\op A, A\op A, B\op B, B\op B}}\ar[u]_-{(\nabla_A\ot \nabla_A)\ot (\nabla_B\ot \nabla_B)} & {\begin{array}{@{}c@{}}((A\op A)\ot (B\op B)) \ot{}\\ ((A\op A)\ot (B\op B))\end{array}}\ar[u]_-{(\nabla_A\ot \nabla_B)\ot (\nabla_A\ot \nabla_B)}^-{(\nat)\quad}\\
{\begin{array}{@{}c@{}}((A\ot B)\ot (A\ot B)) \op{}\\ ((A\ot B)\ot (A\ot B)) \end{array}}\ar[rrrr]_-{\mu_{A\ot B, A\ot B, A\ot B, A\ot B}} &&&& {\begin{array}{@{}c@{}}(A\ot B)\op (A\ot B)) \ot{}\\ ((A\ot B)\op (A\ot B)) \end{array}} \ar[u]_-{\mu_{A,A,B,B}\ot \mu_{A,A,B,B}}
}}
\end{equation*}

$u_{A\ot B}$ and $e_{A\ot B}$ satisfy the second diagram in \eqref{cc:medial_bimonoid} by the following commuting diagram:
\begin{equation*}
\xymatrixrowsep{2.75pc}\xymatrixcolsep{3.75pc}\xymatrix@L=0.5pc{
\bot\ar[r]^-{m}\ar[d]_-{\Delta_\bot}\ar@{}[rd]|{\eqref{cc:bot_top_comonoid_monoid}} & \top \\
\bot\ot\bot\ar[r]^-{m\ot m}\ar[d]_-{u_A\ot u_B}\ar@{}[rd]|{\eqref{cc:medial_bimonoid}} & \top\ot\top\ar[u]_-{{u_\ot}^{-1}_\top} \\
A\ot B\ar@/_2pc/[ru]_-{e_A\ot e_B}&
}
\end{equation*}

$\nabla_{A\ot B}$ and $e_{A\ot B}$ satisfy the third diagram in \eqref{cc:medial_bimonoid} by the following commuting diagram:
\begin{equation*}
\xymatrixrowsep{2.75pc}\xymatrixcolsep{3.75pc}\xymatrix@L=0.5pc{
