(\top\ot\top)\op (\top\ot\top)\ar[d]_-{{u_\ot}^{-1}_\top \op {u_\ot}^{-1}_\top}\ar[r]_-{\mu_{\top,\top,\top,\top}}\ar@{}[rrd]|{\eqref{cc:absorption_law}} & (\top\op\top)\ot(\top\op\top)\ar[r]_-{\nabla_\top\op\nabla_\top} & \top\ot\top \ar[d]^-{{u_\ot}^{-1}_\top}\\
\top\op\top\ar[rr]_-{\nabla_\top} && \top
}
\end{equation*}

Finally, $\Delta_{A\ot B}$ and $u_{A\ot B}$ satisfy the fourth diagram in \eqref{cc:medial_bimonoid} by the following commuting diagram: 
\begin{equation*}
\xymatrixrowsep{2.75pc}\xymatrixcolsep{3.75pc}\xymatrix@L=0.5pc{
\bot\ar[r]^-{\Delta_\bot}\ar[dd]_-{\Delta_\bot}\ar@{}[rdd]|{\eqref{cc:delta_nabla_canonicalflip}\quad} & \bot\ot\bot\ar[r]^-{u_A\ot u_B}\ar[d]_-{\Delta_\bot \ot \Delta_\bot}\ar@{}[rd]|{\eqref{cc:medial_bimonoid}} & A\ot B\ar[d]^-{\Delta_A\ot \Delta_B} \\
& (\bot\ot\bot)\ot(\bot\ot\bot)\ar[r]_-{(u_A\ot u_A)\ot (u_B\ot u_B)}\ar[d]_-{\tau^\ot_{\bot,\bot,\bot,\bot}}\ar@{}[rd]|{(\nat)} & (A\ot A)\ot (B\ot B)\ar[d]^-{\tau^\ot_{A,A,B,B}} \\
\bot\ot\bot\ar[r]_-{\Delta_\bot\ot \Delta_\bot} & (\bot\ot\bot)\ot(\bot\ot\bot)\ar[r]_-{(u_A\ot u_B)\ot (u_A\ot u_B)}& (A\ot B)\ot (A\ot B) 
}
