\title{Oobleck: Low-Compromise Design for Fault Tolerant Accelerators}

\author{\IEEEauthorblockN{Guy Wilks}
\IEEEauthorblockA{Carnegie Mellon University} 
\and
\IEEEauthorblockN{Brian Li}
