\title{Normalization of 
Quaternionic Polynomials in Coordinate-Free Quaternionic Variables
in Conjugate-Alternating Order}

\author[1]{Hongbo Li\thanks{hli@mmrc.iss.ac.cn}}
\author[1]{Zhengyang Wang\thanks{wangzhengyang22@mails.ucas.ac.cn}}
