\subsection{A General  Theory of Standard Model (GSM)}

The action for the general theory of standard model is explicitly constructed  in a spin-related intrinsic gravigauge spacetime as follows: 
\be \label{GSMaction0}
& & \cS_{GSM}  = \int [\dbar \zeta^{c}]  \sum_{s=\mp}  \frac{1}{2} \{  \sum_{\Psi=l,q}  \bs{\zeta} [ \frac{1}{2} \bar{\Psi}_{s}^{i} \Sigma_{s}^{c}  i \bshcD_{c}^{(\Psi s)}\, \Psi_{s}^{i}  + H.c. 
 \nn \\
& & + \bar{\Psi}_{s}^{i} \hPhi_{s} ( \tilde{\Gamma}_{s} \tilde{\lambda}^{\Psi}_{ij}  +  \hGa_{s}  \hat{\lambda}^{\Psi}_{ij} ) \, \Psi_{s}^{j} ] + \frac{1}{8} \eta^{cd} \Tr (\hcD_{c}\hPhi_{s} )^{\dagger} \hcD_{d}\hPhi_{s} \nn \\
& & -  \frac{1}{4} \eta^{cc'}\eta^{dd'} ( \frac{1}{2g_1^2} \Tr \hF_{cd}^{(l_{s})} \hF_{c'd'}^{(l_{s})}  + \frac{1}{2g_2^2} \Tr \hF_{cd}^{(L_{s})} \hF_{c'd'}^{(L_{s})} )   \} \nn \\
& & -\frac{1}{4}\eta^{cc'}\eta^{dd'} [ \frac{4}{g_3^2} \Tr \hF_{cd}^{(C)} \hF_{c'd'}^{(C)} + \frac{1}{g_w^2} \hcW_{cd}\hcW_{c'd'}  \nn \\
& & +\frac{1}{2g_4^2} \Tr (\bshcF_{cd}^{-} \bshcF_{c'd'}^{-} + \bshcF_{cd}^{+} \bshcF_{c'd'}^{+}   \nn \\ 
& & -  \frac{1}{2\bs{\zeta}^{2}} \bshcF_{cd}^{(W-)} \bshcF_{c'd'}^{(W+)} + \frac{2}{\gamma_c^2} \hcF_{cd}^{(-)} \hcF_{c'd'}^{(+)}  ) ]\nn \\
& & +  \frac{1}{4} \Phi_{\kappa}^2  \etat^{cdc'd'}_{aa'} \bshsF_{cd}^{a}\bshsF_{c'd'}^{a'}    - \frac{1}{8} \beta_w^2 \hphi_w^2   \eta^{cd}  \Tr \bshcW_{c}^{(-)}  \bshcW_{d}^{(+)}  \nn \\
& & +   \frac{1}{2}  (  \gamma_{\kappa}^2 \Phi_{\kappa}^2  + \beta_e \hphi_{e}^2 )  \eta^{cd}  \Tr \bshcA_{c}\bshcA_{d} + \frac{1}{2}\beta_{\kappa}^2 \eta^{cd}\cD_{c}\Phi_{\kappa} \cD_{d}\Phi_{\kappa}  \nn \\
& & +\frac{1}{2}  \eta^{cd} [ \hcD_{c}(\bs{\zeta}\hphi_{w})\hcD_{d}(\bs{\zeta}\hphi_{w})   +  \gamma_{w}^2  \hphi_w^2\hcD_{c}\bs{\zeta} \hcD_{d}\bs{\zeta} + \cD_{c}\hphi_{e} \cD_{d}\hphi_{e}] \nn \\
& & - \hPhi_{\kappa}^4\, \hcV_{S}( \hPhi/\hPhi_{\kappa}, \bs{\zeta} \hphi_w/\hPhi_{\kappa}, \hphi_{e}/\hPhi_{\kappa}) ,
\ee
with Latin indices ($a,b,c,d=0,1,2,3$) representing spin-related vectors, raised and lowered, and contracted by metric matrices, $\eta^{ab}$($\eta_{ab}$)=$\diag.$(1,-1,-1,-1). Here, the summations over $s=\mp$ and $\Psi=l,q$ are in respective to the chiral duality representations and spinor fields of leptons and quarks. We have defined gauge covariant derivatives,
\be
& & i\bshcD_{c}^{(\Psi \mp)} \equiv i \eth_{c}+ \hA_{c}^{(\Psi \mp)} + \bshcA_{c}^{\mp} + i 3\hcW_{c}/2, \nn \\
& & \hA_{c}^{(\Psi \mp)}\equiv  \hB_{c} \Sigma_{Y \mp}^{(\Psi)} + \hW_{c}^{i} \Sigma_{L \mp}^i  + \hA_{c}^{\alpha} T_{\alpha}^{(\Psi)}, \nn \\
& & \bshcA_{c}^{\mp} \equiv \hcB_{c}\Sigma_{\mp} + \hcW_{c}^{a}\Sigma_{a \mp} + \hcA_{c}^{ab}\Sigma_{ab}/2 , 
\ee
where $\hB_{c}$, $\hW_{c}^{i}$, and $\hA_{c}^{\alpha}$ correspond to the electroweak and strong gauge fields in SM, $\hcB_{c}$, $\hcW_{c}^{a}$ and $\hcA_{c}^{ab}$ are chiral conformal-spin, chirality boost-spin and spin gauge fields introduced via gauge symmetry WS$_c$(1,3), and $\hcW_{c}$ is Weyl scaling gauge field. We have defined the gauge covariant fields, 
\be \label{GCGF}
