\be
& & [\Sigma^{ab}, \Sigma^{cd}] =  i (\Sigma^{ad}\eta^{bc} -\Sigma^{bd}  \eta^{ac} - \Sigma^{ac} \eta^{bd} + \Sigma^{bc} \eta^{ad}) , \nn \\
