& &  [\Sigma^{ab}, \Sigma_{\mp} ]  = 0,  \quad [\Sigma_{\mp}, \Sigma_{\mp} ]=0, \quad [\Sigma_{\mp}^{a}, \Sigma_{\mp}^{b}] = 0 .
