& &  \hcF_{cd} \equiv (\hat{\eth}_{c} \hcA_{d}^{ab} - \hat{\eth}_{d}\hcA_{c}^{ab} -i [\hA_{c}, \hA_{d}]^{ab} + \bshsF_{cd}^{a'} \hcA_{a'}^{ab} ) \Sigma^{ab}/2 , \nn \\
