The covariant derivative over $\hPhi_{\mp}$ is defined as follows:
\be
& & \hcD_{c}\hPhi_{\mp} \equiv (\hat{\eth}_{c} - i \hB_{c} \tGa_{\pm}/2  - i \hW_{c}^{i}\Sigma_{L \mp}^{i} ) \hPhi_{\mp}  ,  \nn \\
& &  \eta^{cd} \Tr (\hcD_{c}\hPhi_{\mp} )^{\dagger} \hcD_{d}\hPhi_{\mp} = 8\eta^{cd} (\hcD_{c}\hH)^{\dagger} \hcD_{d}\hH .
\ee




\subsection{ Gravitization Equation of GSM in spin-related Gravigauge Spacetime}


The matrices $\bscM_{cda}^{\; c'd'a'}$ and $\widehat{\bscF}_{cda}$ in the gravitization equation are explicitly  defined as follows: 
\be
& & \bscM_{cda}^{\; c'd'a'}  \equiv (\eta_{c}^{\, c'} \eta_{d}^{\, d'} -\eta_{d}^{\, c'} \eta_{c}^{\, d'} )/2 ( \eta_{a}^{\, a'} \hat{\cS}_{+}^2   - \widehat{\cV}_{a b} \eta^{b a'} ) \nn \\
& & +  [ ( \eta_{c}^{\, c'}  \eta_{d}^{\, a'}  - \eta_{d}^{\, c'} \eta_{c}^{\, a'} ) \eta_{a}^{\, d'} +  (\eta_{d}^{\, d'} \eta_{c}^{\, a'} - \eta_{c}^{\, d'} \eta_{d}^{\, a'} )\eta_{a}^{\, c'} ] \hat{\cS}_{-}^{2}/2 \nn \\
& & -  [ \eta_{ca} (\eta_{d}^{\, d'}  \eta^{c'a'} - \eta_{d}^{\, c'}  \eta^{d'a'}) -  \eta_{da}( \eta_{c}^{\, d'}  \eta^{c'a'} -\eta_{c}^{\, c'}  \eta^{d'a'} ) ] \Phi^2_{\kappa} , \nn \\
& & \widehat{\cV}_{a b}  \equiv   \hcB_{a} \hcB_{b} - \hcW_{a c} \hcW_{b}^{c} + \hcA_{a a'b'}\hcA_{b}^{a'b'}   + \hcW_{a} \hcW_{b} \nn \\
& & \qquad + \hB_{a}\hB_{b}  + \hW_{a}^{i} \hW_{b}^{i} + \hA_{a}^{\alpha} \hA_{b}^{\alpha } = \widehat{\cV}_{ba} , 
\ee
with $\hat{\cS}_{\pm}^2  =   \Phi_{\kappa}^2 + \frac{1}{2} (\gamma_{\kappa}^2\Phi^2_{\kappa} + \beta_{e}\hphi_{e}^2)  \pm  (\gamma_{\kappa}^2\Phi^2_{\kappa} + \beta_{e}\hphi_{e}^2)$, and 
\be
\widehat{\bscF}_{cda}  & \equiv &   \cF_{cd}\hcB_{a} -  \cF_{cd}^{b} \hcW_{a b}  + \cF_{cd}^{a'b'}\hcA_{a a'b'}    \nn \\
& + &  \cW_{cd} \hcW_{a} + F_{cd} \hB_{a} +  F_{cd}^{i} \hW_{a}^{i} + F_{cd}^{\alpha}\hA_{a}^{\alpha} \nn \\
& - &  (\gamma_{\kappa}^2\Phi^2_{\kappa} + \beta_{e}\hphi_{e}^2) g_4( 2\hcA_{cda}-2\hcA_{dca} +\hcA_{acd} )  \nn \\
& + & [ 4\Phi_{\kappa}^2 - 3(\gamma_{\kappa}^2\Phi^2_{\kappa} + \beta_{e}\hphi_{e}^2) ] \hcS_{[cd]a}  =  - \widehat{\bscF}_{dc a}  ,
\ee
where $\bscM_{cda}^{\; c'd'a'}$ is regarded as a $24\times 24$ matrix, antisymmetric under exchanges of $c, d$ and $c', d'$, and $\widehat{\bscM}_{cda}^{\; c'd'a'}$ is the inverse matrix. Note that the gauge fields are rescaled as, $\hcA_{c}^{A} \to g_A \hcA_{c}^{A}$, in order to normalize their kinetic terms.

\subsection{Gravitational Equations of GSM within Gravitational Quantum Field Theory(GQFT)}


In obtaining the action within the framework of GQFT, we have used the following relation,
\be \label{Relation}
& &  \eta^{cd} ( \cA_{c}^{ab}-\mOm_{c}^{ab}/g_4 )  ( \cA_{d ab}-\mOm_{d ab}/g_4) \equiv  \frac{1}{2 g_4^2} \bchi^{\mu\nu \mu' \nu'}_{aa'}\cG_{\mu\nu}^{a}\cG_{\mu'\nu'}^{a'}, \nn \\
& & \cG_{\mu\nu}^{a} \equiv \p_{\mu} \chi_{\nu}^{\; a}  - \p_{\nu} \chi_{\mu}^{\; a} + g_4(\cA_{\mu b}^{a} \chi_{\nu}^{\; b}  - \cA_{\nu b}^{a} \chi_{\mu}^{\; b} ),  
\ee
with the definitions,
\be \label{Tensor}
& & \etab^{c d c' d'}_{a a'} \equiv  \frac{3}{2} \eta^{c c'} \eta^{d d'} \eta_{a a'}  - \frac{1}{2} ( \eta^{c c'} \eta_{a'}^{d} \eta_{a}^{d'}  +  \eta^{d d'} \eta_{a'}^{c} \eta_{a}^{c'} ), \nn \\
& & \chib_{aa'}^{\mu\nu \mu'\nu'} \equiv \chih_{c}^{\;\, \mu}\chih_{d}^{\;\, \nu} \chih_{c'}^{\;\, \mu'} \chih_{d'}^{\;\, \nu'}  \etab^{c d c' d'}_{a a'}.
\ee

The current $\whmJ_{a}^{\;\mu}$ in the gauge-type gravitational equation can be expressed into the following explicit forms: 
\be \label{CC}
& & \whmJ_{a}^{\;\mu}\equiv \gamma_W \hcG_{a}^{\;\mu}  + \hsF_{a}^{\;\mu} -16\pi G_{\kappa} \hmJ_{a}^{\;\mu} , \nn \\
& & \hcG_{a}^{\;\mu} = - \cD_{\nu}(\chi_{\kappa}^2 \widehat{\cG}_{a}^{\mu\nu} ) + \chi_{\kappa}^2  (\eta_{\sigma}^{\; \mu}\chih_{a}^{\; \rho} -  \frac{1}{4} \chih_{a}^{\; \mu} \eta_{\sigma}^{\; \rho} ) \cG_{\rho\nu}^{b} \widehat{\cG}^{\sigma\nu}_{b} ] , \nn \\
& & \hsF_{a}^{\;\mu} =  (\eta_{\sigma}^{\; \mu}\chih_{a}^{\; \rho} -  \frac{1}{4} \chih_{a}^{\; \mu} \eta_{\sigma}^{\; \rho} ) \sF_{\rho\nu}^{b} \whsF^{\sigma\nu}_{b},
\ee
and
\be \label{CC1}
& & \hmJ_{a}^{\;\mu} =  \chi \1 \{  \sum_{\Psi=l,q} \frac{1}{2} [  (   \chih_{a}^{\; \; \mu} \chih_{b}^{\; \nu} -\chih_{b}^{\; \mu}  \chih_{a}^{\;\nu} )  \bar{\Psi}_{L}^{i} \gamma^{b} i\cD_{\nu}^{(\Psi_L)} \Psi_{L}^{i}  \nn \\
& &\, + \chih_{a}^{\;\;\mu}( \bar{\Psi}_{L}^{i} H \lambda^{\Psi^{(-)}}_{ij} \Psi_{R}^{(-)j} +  \bar{\Psi}_{L}^{i} \tilde{H} \lambda^{\Psi^{(+)}}_{ij} \Psi_{R}^{(+)j} + H.c. ) ] \nn \\
& & \, + ( \chih^{\mu\sigma} \chih_{a}^{\; \; \rho} - \frac{1}{4} \chih_{a}^{\; \; \mu}  \chih^{\rho\sigma} ) ( \sum_{\cF^A} \bscF_{\rho\nu}^{A} \bscF_{\sigma\nu'}^{A} - \cF_{\rho\nu}^{b} \cF_{\sigma\nu' b}) \chih^{\nu\nu'} \nn \\
& &\,  - ( \chih^{\mu\sigma} \chih_{a}^{\; \; \rho} - \frac{1}{2} \chih_{a}^{\; \; \mu}  \chih^{\rho\sigma} ) [\cD_{\rho}\phi_{w} \cD_{\sigma}\phi_{w} + \cD_{\rho}\phi_{e} \cD_{\sigma}\phi_{e} \nn \\
& &\,   + \beta_{\kappa}^2 g_w^2 \bM_{\kappa}^2 \cW_{\rho}\cW_{\sigma} + g_4^2  \phi_w^2 ( \gamma_w^2 \cB_{\rho} \cB_{\sigma} - \beta_{w}^2 \cW_{\rho}^{a}  \cW_{\sigma a}) \nn \\
& & \, + 2(\cD_{\rho}H)^{\dagger} \cD_{\sigma}H ] -  \chih_{a}^{\; \; \mu} \cV_{S}(H, \phi_w, \phi_{e}) \},
\ee
where we have used the following definitions,
\be
 \whcG_a^{\mu\nu} & \equiv & \chi\, \bchi^{[\mu\nu]\mu'\nu'}_{a a'}  \cG_{\mu'\nu' }^{a'}, \nn \\
 \chi_{\kappa}^{2} & \equiv & 1 + g_4^2\beta_e (\phi_e^2-v_e^2)/M_{\cA}^2 , \nn \\
 \gamma_W & \equiv & M_{\cA}^2/(g_4^2 \bM_{\kappa}^2), \quad 16\pi G_{\kappa} = 1/\bM_{\kappa}^2 ,
\ee
with $M_{\cA}$ being the mass of spin gauge boson. 

In the action of GSM, all covariant field strengths $\bscF_{\mu\nu}^{A}$ in Minkowski spacetime are related to those $\bscF_{cd}^{A}$ in spin-related gravigauge spacetime via the projections, ($F_{\mu\nu}$, $ F_{\mu\nu}^{i}$, $F_{\mu\nu}^{\alpha}$, $\cW_{\mu\nu}$, $\cF_{\mu\nu}$, $\cF_{\mu\nu}^{a}$,$\cF_{\mu\nu}^{ab}$) $\equiv$ $\chi_{\mu}^{\; c}\chi_{\nu}^{\; d}$($F_{cd}$, $F_{cd}^{i}$, $F_{cd}^{\alpha}$, $\cW_{cd}$, $\cF_{cd}$, $\cF_{cd}^{a}$, $\cF_{cd}^{ab}$).
Here the covariant field strengths in Minkowski spacetime become the standard ones, 
\be
& & F_{\mu\nu} = \p_{\mu} B_{\nu} - \p_{\nu}B_{\mu} , \nn \\
& & F_{\mu\nu}^i = \p_{\mu} W_{\nu}^i - \p_{\nu}W_{\mu}^i + g\epsilon^{ijk}W_{\mu}^{j}  W_{\nu}^{k}, \nn \\
& & F_{\mu\nu}^{\alpha} = \p_{\mu} A_{\nu}^{\alpha}- \p_{\nu}A_{\mu}^{\alpha} 
- g_3 i [A_{\mu}, A_{\nu}]^{\alpha} , 
\ee
for the gauge fields in SM, and
\be
& &  \cW_{\mu\nu} = \p_{\mu} \cW_{\nu} - \p_{\nu}\cW_{\mu},\nn \\
& & \cF_{\mu\nu} = \p_{\mu} \cB_{\nu} - \p_{\nu}\cB_{\mu},  \nn \\
& & \cF_{\mu\nu}^{a} = (\p_{\mu} + g_c\cB_{\mu}) \cW_{\nu}^{\; a}  - (\p_{\nu} + g_cB_{\nu}) \cW_{\mu}^{\; a} \nn \\
& & \quad \quad + g_4(\cA_{\mu b}^{a} \cW_{\nu}^{\; b}  - \cA_{\nu b}^{a} \cW_{\mu}^{\; b} ),  \nn \\
& &  \cF_{\mu}^{ab} =\p_{\mu} \cA_{\nu}^{ab} - \p_{\nu}\cA_{\mu}^{ab}+ g_4 (\cA_{\mu c}^{a} \cA_{\nu}^{cb} - \cA_{\mu c}^{b} \cA_{\nu}^{ca}) ,
\ee
for the additional gauge fields in GSM.

To understand the geometric-type gravitational equation, it is useful to check that the action term for the gravigauge field strength $\sF_{\mu\nu}^{a}$ is equivalent to the Einstein-Hilbert action up to a total derivative, 
\be
\frac{1}{4} \chi\, \tchi_{aa'}^{\mu\nu \mu'\nu'} \sF_{\mu\nu}^{a} \sF_{\mu'\nu'}^{a'} = \chi\, R
- 2 \p_{\mu} (\chi \chih^{\mu\rho} \chih_{a}^{\;\sigma} \sF_{\rho\sigma}^{a} ), 
\ee
with $R$ being the Ricci curvature scalar. 

The symmetric tensor $\mT_{(\mu\nu)}$ and antisymmetric tensor $\mT_{[\mu\nu]}$ are derived from the current $\hmJ_{a}^{\mu}$ in Eq.(\ref{CC1}),
\be
 \mT_{\mu\nu}  & \equiv & \chih  \chi_{\mu}^{\; a} \hmJ_{a}^{\; \rho} \chi_{\rho\nu}  \equiv \mT_{(\mu\nu)} + \mT_{[\mu\nu]}, \nn \\
\mT_{(\mu\nu)}  & \equiv &  \frac{1}{2} (\mT_{\mu\nu} + \mT_{\nu\mu} ), \nn \\
 \mT_{[\mu\nu]}  & \equiv  & \frac{1}{2} (\mT_{\mu\nu} - \mT_{\nu\mu} ) .
\ee 
The tensors $\cG_{(\mu\nu)}$ and $\cG_{[\mu\nu]}$ are obtained from the current $\hcG_{a}^{\;\mu}$ in Eq.(\ref{CC}) as follows:
\be
\cG_{\mu\nu}  &  \equiv & \frac{1}{2} \chih  \chi_{\mu}^{\; a} \hcG_{a}^{\; \rho}  \chi_{\rho\nu} \equiv \cG_{(\mu\nu)} + \cG_{[\mu\nu]}, \nn \\
\cG_{(\mu\nu)} & \equiv & \frac{1}{2} (\cG_{\mu\nu}  + \cG_{\nu\mu}  ) , \; \cG_{[\mu\nu]} \equiv  \frac{1}{2} (\cG_{\mu\nu}  - \cG_{\nu\mu}  ).
\ee




