%\begin{equation}
%    \label{eq:voting_position}
%    x_{m,\ell}=\begin{cases}
%  1, & \text{if } \ell=\ell_m^\star, \\
%  0,  & \text{otherwise},
%\end{cases}
%\end{equation}
%where
%\begin{equation}
%    \label{eq:compute_ell_MU}
%    \ell_m^\star = \arg\max_{\ell\in\mathcal{L}_m}\,r_{m,\ell},
%\end{equation}
%Notice that if there exists a tie in \eqref{eq:compute_ell_MU}, then we break it randomly. (In other words, if more than one $x_{m,\ell}$'s receives the most votes, then choose any one of them randomly.) We summarize the above process in Algorithm \ref{alg:MV}. The visualization of the Algorithm \ref{alg:MV} is shown in Fig.~\ref{fig:voting}.

%We point out that the above voting procedures can be alternatively interpreted as maximizing the number of satisfied actuators rather than directly maximizing the worst SNR among actuators. As we can see in Section \ref{sec:simulation}, adopting this new objective can also bring a significant improvement in the worst-case SNR. Regarding the computational complexity, observe that the main workload of the majority-voting algorithm lies in performing the optimal placement algorithm for each individual actuator. Since the optimal placement algorithm runs in $O(ML^2\log(ML^2))$ times, the overall time complexity of the proposed majority-voting algorithm is $O(UML^2\log(ML^2))$.

\begin{algorithm}[t]
\caption{MTS placement for multi-user broadcast}
\label{alg:MV}
\begin{algorithmic}[1]
    \For{$u=1,2,\ldots,U$}
    \State Run Algorithm \ref{alg:OP} for actuator $u$.
    \EndFor
    \For{$m\in\mathcal{M}$}
    \State Compute each $\ell_m^\star$ according to \eqref{eq:compute_ell_MU}.
    \State Compute each $\bx_m$ according to \eqref{eq:voting_position}.
    \EndFor
    \State Output the optimized $\bX$.
\end{algorithmic}
\end{algorithm}


\section{Numerical Results}
\label{sec:simulation}

We now numerically evaluate the performance of the proposed algorithms. Consider a $100 \times 20$ ceiling area in meters, which is divided into $M=M_x\times M_y$ equal rectangular cells as shown in Fig. \ref{fig:IRS_system}. Each cell provides $L$ candidate positions for its MTS. The ceiling height is $5$ meters. The actuator(s) are randomly distributed on the ground. We set $M=6\times 5=30$, $L=6$, and $N=100$ by default.

We then specify the channel model in our simulations. Each of the channels $\{h_0,f_{m,n,\ell}, g_{m,n, \ell}\}$ is modeled as Rician fading:
\begin{equation}
h=\sqrt{\gamma}\left(\sqrt{\frac{\delta}{1+\delta}}\overline{h}+\sqrt{\frac{1}{1+\delta}}\widetilde{h}\right), 
\end{equation}
where $0<\gamma<1$ is the pathloss factor, $
\delta>0$ is the Rician factor, $\overline{h}\in\mathbb C$ is the normalized line-of-sight (LoS) component, and the fading component $\widetilde{h}$ is a random variable drawn from the complex Gaussian distribution $\mathcal{CN}(0,1)$. The parameter of the pathloss follow \cite{ren2022configuring, Xu2024Coordinating,2021JiangtJSAC}, which is generated according to
\begin{equation}
    \gamma = 10^{-(30+22\log_{10}(d))/10},
\end{equation}
where $d$ is the corresponding distance in meters. The LoS components are generated according to $\overline{h}=\exp(-\mathrm{j}2\pi d/\lambda)$ where $\lambda\approx10$ cm is the wavelength when the carrier frequency equals 2.6 GHz. Regarding the Rician factor, we set $\delta=15$ for all channels.

