\begin{theorem}
\label{MI_traceout_theorem}
    The expected R\'enyi-2 extended measurement-unconditioned QMI of a Bell initial state in the quantum dynamics of $2$-design unitaries with mid-circuit measurements and reset at time $t$ is
    \begin{align}
        &\E_{\rm Haar} I_2(R:A_t)\nonumber\\
        &\simeq \log_2 \left(\frac{\left(d_A^2-1\right) d_B \left(\frac{\left(d_A^2-1\right) d_B}{d_A^2 d_B^2-1}\right)^t+d_B+1}{d_A^2 d_B+1}\right)\nonumber\\
        &\quad - \log_2 \left(\frac{d_A^2 (d_B+1)-\left(d_A^2-1\right) \left(\frac{\left(d_A^2-1\right) d_B}{d_A^2 d_B^2-1}\right)^t}{d_A^3 d_B+d_A}\right)+N_A.
        \label{eq:MI_traceout}
    \end{align}
In the asymptotic limit $d_A, d_B \gg 1$, when $t \ll 2N_A/N_B$, 
\begin{align}
    \E_{\rm Haar}I_2(R:A_t) \simeq 2N_A - t N_B,
    \label{eq:MI_traceout_asymp}
\end{align}
while for $t \gg 2N_A/N_B$, 
\be 
\E_{\rm Haar} I_2(R:A_t) \simeq  d_A^2 d_B^{-t}.
\label{eq:MI_traceout_asymp_late}
\ee 
\end{theorem}
At early time, Eq.~\eqref{eq:MI_traceout_asymp} indicates a linear decay of quantum information; while at late time, Eq.~\eqref{eq:MI_traceout_asymp_late} indicates an exponential decay of quantum information.



