    temporal input $\ket{\phi_\bfz}$. Here we show an example for $t=3$.}
    \label{fig:cond_diagram}
\end{figure}

Via the bath equivalent expansion in Fig.~\ref{fig:cond_diagram}, we can first write out the linear map $E$ (blue box) as
\be
    E = \sum_{\bm a, \bm b} \prod_{k=0}^{t-1} \braket{a_{k+1} b_{2k+1}|U_k|a_k b_{2k}} \ket{a_t}_{A_t}\bra{a_0}_{A_0} \otimes_{k=0}^{t-1} \bra{b_{2k+1}}\bra{b_{2k}},
    \label{eq:E_cond_def}
\ee
where $\bm a = (a_0, \cdots, a_t)$ and $\bm b = (b_0, b_1, \cdots, b_{2t-2}, b_{2t-1})$ are vector representations of indices.
By applying the linear map $E$ on the maximally entangled state $\ket{\Phi}_{RA_0}$, we have 
\begin{align}
    E' \equiv (\mathbb{I}_R \otimes E) \ket{\Phi}_{RA_0} = \frac{1}{\sqrt{d_A}} \sum_{\bm a, \bm b} \prod_{k=0}^{t-1} \braket{a_{k+1} b_{2k+1}|U_k|a_k b_{2k}} \ket{a_0}_{R} \ket{a_t}_{A_t} \otimes_{k=0}^{t-1} \bra{b_{2k+1}}\bra{b_{2k}},
\end{align}
which is a linear map from the expanded bath including input and measurement to the output conditional state in system $R A_t$. The same formalism is also adopted in Ref.~\cite{ippoliti2022solvable, zhang2024holographic}. From Fig.~\ref{fig:cond_diagram}, the temporal input generated from the green dashed box is $\ket{\phi_\bfz} = \otimes_{k=0}^{t-1} \ket{z_t} \ket{0}$, and therefore we can obtain the output conditional state and measurement probability as
\begin{align}
    \begin{cases}
        \ket{\psi_\bfz}_{RA_t} &= E'\ket{\phi_\bfz}/\sqrt{P(\bfz)}\\
        P(\bfz) &= \braket{\phi_\bfz|E'^\dagger E' |\phi_\bfz}.
    \end{cases}
\end{align}
The corresponding density operator is $\state{\psi_\bfz}_{R A_t} = P(\bfz)^{-1} E'\state{\phi_\bfz}E'^\dagger$, and the reduced state $\rho_{A_t|\bfz}$ is
\be
    \rho_{A_t|\bfz} = P(\bfz)^{-1} \tr_R(E'\state{\phi_\bfz}E'^\dagger).
\ee
The measured-conditioned purity of $\rho_{A_t|\bfz}$ is thus
\begin{align}
    \overline{\gamma} &\equiv \E_\bfz \tr(\rho_{A_t|bfz}^2) = \sum_{\bfz} P(\bfz) \tr(\rho_{A_t|\bfz}^2)\\
    &= \sum_{\bfz} P(\bfz) P(\bfz)^{-2} \tr(\tr_R(E'\state{\phi_\bfz}E'^\dagger)^2)\\
    &= \sum_{\bfz} P(\bfz)^{-1} \tr(E'^{\otimes 2}\state{\phi_\bfz}^{\otimes 2} E'^\dagger{}^{\otimes 2} (\mathbb{I}_R \otimes \mathbb{S}_{A_t}))\\
    &= \sum_{\bfz} \braket{\phi_\bfz|E'^\dagger E'|\phi_\bfz}^{-1} \tr(E'^{\otimes 2}\state{\phi_\bfz}^{\otimes 2} E'^\dagger{}^{\otimes 2} (\mathbb{I}_R \otimes \mathbb{S}_{A_t})),
\end{align}
where $\mathbb{S}_{A_t}$ is the swap operator over two replicas in system $A_t$. To evaluate it analytically, we introduce the pseudo measurement-conditioned purity from replica trick as
\begin{align}
    \overline{\gamma}^{(m)} &= \sum_{\bfz} \braket{\phi_\bfz|E'^\dagger E'|\phi_\bfz}^{m} \tr(E'^{\otimes 2}\state{\phi_\bfz}^{\otimes 2} E'^\dagger{}^{\otimes 2} (\mathbb{I}_R \otimes \mathbb{S}_{A_t}))\\
    &= \sum_{\bfz} \tr(E'\state{\phi_\bfz}E'^\dagger)^m \tr(E'^{\otimes 2}\state{\phi_\bfz}^{\otimes 2} E'^\dagger{}^{\otimes 2} (\mathbb{I}_R \otimes \mathbb{S}_{A_t}))\\
    &= \sum_{\bfz} \tr(E'^{\otimes m}\state{\phi_\bfz}^{\otimes m} E'^\dagger{}^{\otimes m}) \tr(E'^{\otimes 2}\state{\phi_\bfz}^{\otimes 2} E'^\dagger{}^{\otimes 2} (\mathbb{I}_R \otimes \mathbb{S}_{A_t}))\\
    &= \sum_{\bfz} \tr(E'^{\otimes (m+2)}\state{\phi_\bfz}^{\otimes (m+2)} E'^\dagger{}^{\otimes (m+2)} (\mathbb{I}_R \otimes (\mathbb{I}_m \otimes \mathbb{S}_{A_t})))\\
    &= \tr\left(E'^{\otimes (m+2)} \left(\sum_{\bfz}\state{\phi_\bfz}^{\otimes (m+2)}\right) E'^\dagger{}^{\otimes (m+2)} (\mathbb{I}_R \otimes (\mathbb{I}_m \otimes \mathbb{S}_{A_t}))\right),
    \label{eq:pseudo_purity1}
\end{align}
where in the last step $\mathbb{I}_R$ is changed to the identity operator on $m+2$ replicas and $\mathbb{I}_m \otimes \mathbb{S}_{A_t}$ is the swap operator on $A_t$ with trivial identity on first $m$ replicas. Note that
\begin{align}
    \sum_\bfz \state{\phi_\bfz}^{\otimes (m+2)} &= \sum_\bfz \otimes_{k=0}^{t-1} \state{z_k}^{\otimes (m+2)} \otimes \state{0}^{\otimes (m+2)}\\
    &= \otimes_{k=0}^{t-1} \left(\sum_{z_k} \state{z_k}^{\otimes (m+2)} \otimes \state{0}^{\otimes (m+2)}\right)\\
    &\equiv \otimes_{k=0}^{t-1} \left(D_{m+2} \otimes \state{0}^{\otimes (m+2)}\right),
\end{align}
where we define $D_{m+2} = \sum_{z} \state{z}^{\otimes (m+2)}$. Then we can evaluate $E^{\otimes (m+2)} \left(\sum_{\bfz}\state{\phi_\bfz}^{\otimes (m+2)}\right) E^\dagger{}^{\otimes (m+2)}$ as
\begin{align}
    &E'^{\otimes (m+2)} \left(\sum_{\bfz}\state{\phi_\bfz}^{\otimes (m+2)}\right) E'^\dagger{}^{\otimes (m+2)} \nonumber\\
    &= d_A^{-(m+2)} \sum_{\substack{\bm \alpha, \bm \beta,\\ \bm \alpha', \bm \beta'}} \prod_{k=0}^{t-1} \braket{\alpha_{k+1} \beta_{2k+1}|U_k^{\otimes (m+2)}|\alpha_k \beta_{2k}} \braket{\alpha_k' \beta_{2k}'|U_k^\dagger{}^{\otimes (m+2)}|\alpha_{k+1}' \beta_{2k+1}'} \ketbra{\alpha_0}{\alpha_0'}_R \ketbra{\alpha_t}{\alpha_t'}_{A_t} \nonumber\\
    &\qquad \qquad \qquad \times \otimes_{k=0}^{t-1} \braket{\beta_{2k+1}|D_{m+2}|\beta_{2k+1}'} \braket{\beta_{2k}|0^{m+2}}\braket{0^{m+2}|\beta_{2k}'},
\end{align}
where $\ket{\alpha_k} = \otimes_{j=1}^{m+2}\ket{a_k^{(j)}}, \ket{\beta_k} = \otimes_{j=1}^{m+2}\ket{b_k^{(j)}}, \ket{\alpha_k'} = \otimes_{j=1}^{m+2}\ket{a_k'^{(j)}}, \ket{\beta_k'} = \otimes_{j=1}^{m+2}\ket{b_k'^{(j)}}$ are the simplified notation for $m+2$ replicas of basis. $\bm \alpha = (\alpha_0, \cdots, \alpha_{t-1})$, $\bm \beta = (\beta_0, \beta_1, \cdots, \beta_{2k-2}, \beta_{2k-1})$ are the vector representations and so as the others $\bm \alpha', \bm \beta'$. Utilizing the facts 
\begin{align}
    &\braket{\beta_{2k+1}|D_{m+2}|\beta_{2k+1}'} = \sum_{z_k} \braket{\beta_{2k+1}|z_k^{\otimes (m+2)}}\braket{z_k^{\otimes (m+2)}|\beta_{2k+1}'} = \sum_{z_k} \delta_{\beta_{2k+1}, z_k} \delta_{\beta_{2k+1}', z_k},\\
    &\braket{\beta_{2k}|0^{m+2}}\braket{0^{m+2}|\beta_{2k}'}  = \delta_{\beta_{2k}, 0} \delta_{\beta_{2k}', 0},
\end{align}
where $\delta_{\beta, z} = \prod_{j=1}^{m+2} \delta_{b^{(j)}, z}$ is a simplified notation of Kronecker deltas on each replicas. Then we have
\begin{align}
    &E'^{\otimes (m+2)} \left(\sum_{\bfz}\state{\phi_\bfz}^{\otimes (m+2)}\right) E'^\dagger{}^{\otimes (m+2)} \nonumber\\
    &= d_A^{-(m+2)} \sum_{\bm \alpha, \bm \alpha'} \sum_{\bfz} \prod_{k=0}^{t-1} \braket{\alpha_{k+1} z_k^{\otimes (m+2)}|U_k^{\otimes (m+2)}|\alpha_k 0^{\otimes (m+2)}} \braket{\alpha_k' 0^{\otimes (m+2)}|U_k^\dagger{}^{\otimes (m+2)}|\alpha_{k+1}' z_k^{\otimes (m+2)}} \ketbra{\alpha_0}{\alpha_0'}_R \ketbra{\alpha_t}{\alpha_t'}_{A_t} \\
    &= d_A^{-(m+2)} \sum_{\bm \alpha, \bm \alpha'} \sum_{\bfz} \prod_{k=0}^{t-1} \tr\left(U_k^{\otimes (m+2)}\left(\ketbra{\alpha_k}{\alpha_k'}\otimes \state{0}^{\otimes (m+2)}\right)U_k^\dagger{}^{\otimes (m+2)} \left(\ketbra{\alpha_{k+1}'}{\alpha_{k+1}}\otimes \state{z_k}^{\otimes (m+2)}\right)\right) \ketbra{\alpha_0}{\alpha_0'}_R \ketbra{\alpha_t}{\alpha_t'}_{A_t}.
\end{align}
The pseudo measurement-conditioned purity (Eq.~\eqref{eq:pseudo_purity1}) then becomes
\begin{align}
    &\overline{\gamma}^{(m)} = \tr\left(E'^{\otimes (m+2)} \left(\sum_{\bfz}\state{\phi_\bfz}^{\otimes (m+2)}\right) E'^\dagger{}^{\otimes (m+2)} (\mathbb{I}_R \otimes (\mathbb{I}_m \otimes \mathbb{S}_{A_t}))\right) \\
    &= d_A^{-(m+2)} \sum_{\bm \alpha, \bm \alpha'} \sum_{\bfz} \prod_{k=0}^{t-1} \tr\left(U_k^{\otimes (m+2)}\left(\ketbra{\alpha_k}{\alpha_k'}\otimes \state{0}^{\otimes (m+2)}\right)U_k^\dagger{}^{\otimes (m+2)} \left(\ketbra{\alpha_{k+1}'}{\alpha_{k+1}}\otimes \state{z_k}^{\otimes (m+2)}\right)\right) \nonumber\\
    &\qquad \qquad \qquad \times \braket{\alpha_0'|\alpha_0}_R \braket{\alpha_t'|\mathbb{I}_m \otimes \mathbb{S}_{A_t}|\alpha_t}_{A_t}\\
    &= d_A^{-(m+2)} \sum_{\bm \alpha, \bm \alpha'} \prod_{k=0}^{t-1} \tr\left(U_k^{\otimes (m+2)}\left(\ketbra{\alpha_k}{\alpha_k'}\otimes \state{0}^{\otimes (m+2)}\right)U_k^\dagger{}^{\otimes (m+2)} \left(\ketbra{\alpha_{k+1}'}{\alpha_{k+1}}\otimes D_{m+2}\right)\right) \nonumber\\
    & \qquad \qquad \qquad \times \prod_{j=1}^{m+2}\delta_{a_0^{(j)}, a_0'^{(j)}} \prod_{j=1}^{m}\delta_{a_t^{(j)}, a_t'^{(j)}} 
    \delta_{a_t'^{(m+1)}, a_t^{(m+2)}} \delta_{a_t'^{(m+2)}, a_t^{(m+1)}}.
    \label{eq:pseudo_purity2}
\end{align}

Next, we evaluate Haar ensemble average on the pseudo measurement-conditioned purity $\overline{\gamma}^{(m)}$. For Haar unitary twirling, it is known that
\begin{align}
    &\E_{\rm Haar}\left[U^{\otimes (m+2)} \otimes U^*{}^{\otimes (m+2)}\right] = \sum_{\sigma, \pi \in S_{m+2}} {\rm Wg}(\sigma^{-1}\pi, m+2) |\hat{\sigma})(\hat{\pi}| \\
    &= {\rm Wg}(e, m+2)\sum_{\pi} |\hat{\pi})(\hat{\pi}| + \sum_{\sigma \neq \pi} {\rm Wg}(\sigma^{-1}\pi, m+2) |\hat{\sigma})(\hat{\pi}|,
\end{align}
where $S_{m+2}$ is the permutation group of $m+2$ replicas, and $\hat{\pi}$ is the operator representation of permutation $\pi$. ${\rm Wg}(\sigma^{-1}\pi, m+2) = (d^{|\sigma^{-1}\pi|})^{-1}$ is the Weingarten coefficient with $|\sigma^{-1}\pi|$ to be the number of cycles of permutation $\sigma^{-1}\pi$.

\begin{figure}[t]
    \centering
    \includegraphics[width=0.2\textwidth]{Fig14_cond_twirling.pdf}
    \caption{Tensor network representation of Haar-averaged  pseudo measurement-conditioned purity of $\rho_{A_t|\bfz}$ with time steps $t=3$. Here $\tau_2 = \mathbb{I}_m \otimes \mathbb{S}$ is the swap operator on the last two replicas.}
    \label{fig:cond_purity_diagram}
\end{figure}

We start from the unitary twirling on the last step boundary condition,
\begin{align}
    & \E_{\rm Haar}\left[U_{t-1}^{\otimes (m+2)} \otimes U_{t-1}^*{}^{\otimes (m+2)}\right] |\tau_2)_A |D_{m+2})_B \nonumber\\
    &= {\rm Wg}(e, m+2)\sum_{\pi} |\hat{\pi})_{AB}(\hat{\pi}|\tau_2)_A (\hat{\pi}|D_{m+2})_B + \sum_{\sigma \neq \pi} {\rm Wg}(\sigma^{-1}\pi, m+2) |\hat{\sigma})_{AB} (\hat{\pi}|\tau_2)_A (\hat{\pi}|D_{m+2})_B.
    \label{eq:twirling_expansion}
\end{align}
In the following, we evaluate the two terms above separately. For the first term, note that $(\hat{\pi}|D_{m+2})_B = \tr(\hat{\pi}^\dagger \sum_z \state{z}^{\otimes (m+2)}) = \sum_z \braket{z^{\otimes (m+2)}|\hat{\pi}^\dagger|z^{\otimes (m+2)}} = d_B$, we then have
\be
    {\rm Wg}(e, m+2)\sum_{\pi} |\hat{\pi})_{AB}(\hat{\pi}|\tau_2)_A (\hat{\pi}|D_{m+2})_B =  {\rm Wg}(e, m+2) d_B \sum_{\pi} d_A^{|\pi^\dagger \tau_2|} |\hat{\pi})_{AB},
\ee
and further connecting $|D_{m+2})(0|_B$ on the bath system, we have
\begin{align}
    & |D_{m+2})(0|_B {\rm Wg}(e, m+2) \sum_{\pi} |\hat{\pi})_{AB} (\hat{\pi}|\tau_2)_A (\hat{\pi}|D_{m+2})_B \nonumber\\
    & = {\rm Wg}(e, m+2) d_B \sum_{\pi} d_A^{|\pi^\dagger \tau_2|} |\hat{\pi})_A |D_{m+2})_B \\
    & \simeq {\rm Wg}(e, m+2) d_B \left( d_A^{m+2}|\tau_2)_A + d_A^{m+1} |e)_A \right) |D_{m+2})_B,
\end{align}
where we keep the leading order terms $\pi = \tau_2, \mathbb{I}$ in the last step give large system size $d_A \gg 1$. Similarly, for the second term in Eq.~\eqref{eq:twirling_expansion}, we have
\begin{align}
    & |D_{m+2})(0|_B  \sum_{\sigma \neq \pi} {\rm Wg}(\sigma^{-1}\pi, m+2) |\hat{\sigma})_{AB} (\hat{\pi}|\tau_2)_A (\hat{\pi}|D_{m+2})_B \nonumber\\
    &\simeq d_B \left[{\rm Wg}(e\tau_2, m+2) d_A^{m+2} |e)_A |D_{m+2})_B + {\rm Wg}(\tau_2^{-1}e, m+2) d_A^{m+1} |\tau_2)_A |D_{m+2})_B \right]\\
    &= {\rm Wg}(e\tau_2, m+2) d_A^{m+1} d_B \left(d_A |e)_A + |\tau_2)_A\right) |D_{m+2})_B,
\end{align}
where in the second line we still focus on the leading order $(\sigma, \pi) = (\tau_2, e), (e, \tau_2)$.
Combining these two terms together, we have
\begin{align}
    &|D_{m+2})(0|_B \E_{\rm Haar}\left[U_{t-1}^{\otimes (m+2)} \otimes U_{t-1}^*{}^{\otimes (m+2)}\right] |\tau_2)_A |D_{m+2})_B \nonumber\\
    &\simeq {\rm Wg}(e, m+2) d_A^{m+1} d_B \left( d_A|\tau_2)_A + |e)_A \right) |D_{m+2})_B + {\rm Wg}(e\tau_2, m+2) d_A^{m+1} d_B \left(d_A |e)_A + |\tau_2)_A\right) |D_{m+2})_B\\
    &\simeq \frac{d_A^{m+1} d_B}{d_A^{m+2} d_B^{m+2}} \left( d_A|\tau_2)_A + |e)_A \right) |D_{m+2})_B - \frac{d_A^{m+1} d_B}{d_A^{m+3} d_B^{m+3}} \left(d_A |e)_A + |\tau_2)_A\right) |D_{m+2})_B\\
    &= d_B^{-(m+1)}\left(1 - d_A^{-2}d_B^{-1}\right)|\tau_2)_A |D_{m+2})_B + d_A^{-1}d_B^{-(m+1)}\left(1 - d_B^{-1}\right)|e)_A |D_{m+2})_B,
    \label{eq:twirling_taud}
\end{align}
where in the third line we approximate it by ${\rm Wg}(e, m+2) \simeq d_A^{-(m+2)}d_B^{-(m+2)}$ and ${\rm Wg}(e\tau_2, m+2) \simeq -d_A^{-(m+3)}d_B^{-(m+3)}$ given $d_A \gg 1$. Let's move to the next twirling of $U_{t-2}$ and bath operation $|D_{m+2})(0|_B$. For the boundary condition $|e)_A |D_{m+2})_B$, we have
\begin{align}
    & |D_{m+2})(0|_B \E_{\rm Haar}\left[U_{t-2}^{\otimes (m+2)} \otimes U_{t-2}^*{}^{\otimes (m+2)}\right] |e)_A |D_{m+2})_B \nonumber \\
    &= |D_{m+2})(0|_B \sum_{\sigma, \pi} {\rm Wg}(\sigma^{-1}\pi, m+2) |\hat{\sigma})_{AB} (\hat{\pi}|e)_A (\hat{\pi}|D_{m+2})_B\\
    &= d_B \sum_{\sigma, \pi} {\rm Wg}(\sigma^{-1}\pi, m+2) d_A^{|\pi^\dagger|} |\hat{\sigma})_{A} |D_{m+2})_{B}\\
    &= d_B \left[{\rm Wg}(e, m+2)\sum_{\pi} d_A^{|\pi^\dagger|} |\hat{\pi})_A + \sum_{\sigma \neq \pi} {\rm Wg}(\sigma^{-1}\pi, m+2) d_A^{|\pi^\dagger|} |\hat{\sigma})_{A} \right] |D_{m+2})_{B}\\
    &\simeq d_B \left[{\rm Wg}(e, m+2)\left(d_A^{m+2} |e)_A + d_A^{m+1} |\tau_2)_A\right) + {\rm Wg}(\tau_2^{-1}e, m+2) d_A^{m+2} |\tau_2)_{A} + {\rm Wg}(e\tau_2, m+2) d_A^{m+1} |e)_{A}\right] |D_{m+2})_{B} \\
    &= d_A^{m+1} d_B \left[\left({\rm Wg}(e, m+2) + {\rm Wg}(\tau_2^{-1}e, m+2) d_A\right)|\tau_2)_A +\left({\rm Wg}(e, m+2) d_A + {\rm Wg}(e\tau_2, m+2)\right)|e)_{A}\right] |D_{m+2})_{B} \\
    &\simeq d_A^{m+1} d_B \left[\left(d_A^{-(m+2)}d_B^{-(m+2)} - d_A^{-(m+3)}d_B^{-(m+3)} d_A\right)|\tau_2)_A \left(d_A^{-(m+2)}d_B^{-(m+2)} d_A - d_A^{-(m+3)}d_B^{-(m+3)}\right)|e)_{A}\right] |D_{m+2})_{B} \\
    &= d_A^{-1} d_B^{-(m+1)}\left(1 - d_B^{-1}\right)|\tau_2)_A |D_{m+2})_{B} + d_B^{-(m+1)} \left(1 - d_A^{-2}d_B^{-1}\right)|e)_{A}|D_{m+2})_{B},
    \label{eq:twirling_ed}
\end{align}
where we make the same approximations as we utilized above. To summarize, we have the following linear transformation on boundary conditions in every step from Eqs.~\eqref{eq:twirling_taue},~\eqref{eq:twirling_ed}
\begin{align}
    \begin{cases}
        |\tau_2)_A |D_{n+2})_B \to q_\tau |\tau_2)_A |D_{m+2})_B + q_e |e)_A |D_{m+2})_B \\
        |e)_A |D_{n+2})_B \to q_e |\tau_2)_A |D_{m+2})_B + q_\tau |e)_A |D_{m+2})_B
    \end{cases},
\end{align}
where $q_\tau = d_B^{-(m+1)}\left(1 - d_A^{-2}d_B^{-1}\right)$ and $q_e = d_A^{-1}d_B^{-(m+1)}\left(1 - d_B^{-1}\right)$ are two coefficients. We can thus write the linear transformation in the form of a two-by-two matrix
\be
    Q = 
    \begin{pmatrix}
        q_\tau & q_e \\
        q_e & q_\tau
    \end{pmatrix},
\ee
with bases $|\tau_2)_A |D_{m+2})_B \to (1, 0)^T, |e)_A |D_{m+2})_B \to (0, 1)^T$. Via diagonalization, we can write out $Q^t$ explicitly as
\be
    Q^t = \frac{1}{2}
    \begin{pmatrix}
        \nu_+^t + \nu_-^t & \nu_+^t - \nu_-^t \\
        \nu_+^t - \nu_-^t & \nu_+^t + \nu_-^t
    \end{pmatrix},
\ee
where $\nu_{\pm} = q_{\tau} \pm q_e$ are eigenvalues of $Q$. Considering the initial boundary condition at step $t$ in Fig.~\ref{fig:cond_purity_diagram}, we obtain the boundary condition at step $0$ as
\begin{align}
    Q^t (1, 0)^T \to \frac{1}{2}\left[(q_\tau + q_e)^t + (q_\tau - q_e)^t\right] |\tau_2)_A |D_{m+2})_B + \frac{1}{2}\left[(q_\tau + q_e)^t - (q_\tau - q_e)^t\right] |e)_A |D_{m+2})_B,
\end{align}
and thus we have the dynamical solution for pseudo measurement-conditioned purity
\begin{align}
    \E_{\rm Haar}\overline{\gamma}^{(m)} &\simeq d_A^{-(m+2)} (e|_A (0|_B \left(\frac{1}{2}\left[(q_\tau + q_e)^t + (q_\tau - q_e)^t\right] |\tau_2)_A |D_{m+2})_B + \frac{1}{2}\left[(q_\tau + q_e)^t - (q_\tau - q_e)^t\right] |e)_A |D_{m+2})_B\right)\\
    &= \frac{1}{2} d_A^{-(m+2)}  \left(\left[(q_\tau + q_e)^t + (q_\tau - q_e)^t\right] d_A^{m+1}  + \left[(q_\tau + q_e)^t - (q_\tau - q_e)^t\right] d_A^{m+2} \right)\\
    &= \frac{1}{2d_A} \left[(1+d_A) (q_\tau + q_e)^t + (1-d_A) (q_\tau - q_e)^t\right]\\
    &= \frac{1}{2d_A} \left[(1+d_A) \left(d_A^{-2}d_B^{-(m+2)}(d_A + 1)(d_A d_B - 1)\right)^t + (1-d_A) \left(d_A^{-2}d_B^{-(m+2)}(d_A - 1)(d_A d_B + 1)\right)^t\right] \\
    &= \frac{1}{2d_A} d_A^{-2t}d_B^{-(m+2) t} \left[(d_A + 1)^{t+1}(d_A d_B - 1)^t - (d_A-1)^{t+1} (d_A d_B + 1)^t\right],
\end{align}
where we utilize the definition of $q_\tau, q_e$ defined above in the second to last line.
Via taking the limit $m \to -1$, we solve the Haar-averaged dynamical solution for the measurement-conditioned purity of $\rho_{A_t|\bfz}$ as
\begin{align}
    \E_{\rm Haar}\E_{\bfz} \tr(\rho_{A_t|\bfz}^2) = \E_{\rm Haar} \overline{\gamma} &= \lim_{m \to -1} \E_{\rm Haar}\overline{\gamma}^{(m)} \\
    &\simeq \frac{1}{2} d_A^{-(2t+1)}d_B^{-t} \left[(d_A + 1)^{t+1}(d_A d_B - 1)^t - (d_A-1)^{t+1} (d_A d_B + 1)^t\right].
    \label{eq:cond_purity_sol}
\end{align}
Finally, we have the asymptotic lower bound for Haar-averaged measurement-conditioned QMI from Eq.~\eqref{eq:avgMI_lb}
\begin{align}
    &\E_{\rm Haar} \overline{I(R:A_t|\bfz)} \ge -2\log_2\left(\E_{\rm Haar}\E_{\bfz} \tr(\rho_{A_t|\bfz}^2)\right) \\
    &\gtrsim  -2\log_2\left( \frac{1}{2} d_A^{-(2t+1)}d_B^{-t} \left[(d_A + 1)^{t+1}(d_A d_B - 1)^t - (d_A-1)^{t+1} (d_A d_B + 1)^t\right]\right)\\
    &= 2 + 2(2t+1)N_A + 2 t N_B - 2\log_2\left[(d_A + 1)^{t+1}(d_A d_B - 1)^t - (d_A-1)^{t+1} (d_A d_B + 1)^t\right]\\
    &= 2 + 2(2t+1)N_A + 2 t N_B - 2\log_2\left[(d_A d_B + 1)^t (d_A + 1)^{t+1} \right] - 2\log_2\left[\left(\frac{d_A d_B - 1}{d_A d_B + 1}\right)^t - \left(\frac{d_A - 1}{d_A + 1}\right)^{t+1}\right],
    \label{eq:avgMI_sol_sm}
\end{align}
which is the solution of Eq.~\eqref{eq:avgMI_lb} of Theorem.~\ref{theorem_avgMI} in the main text. 

At the end of this section, we perform an asymptotic analysis on the scaling of above result in the limit of large system size $d_A \gg 1$.
\begin{align}
    &\E_{\rm Haar} \overline{I(R:A_t|\bfz)} \nonumber\\
    &= 2 + 2(2t+1)N_A + 2 t N_B - 2t \log_2(d_A d_B + 1) - 2(t+1)\log_2(d_A + 1) - 2\log_2\left[\left(1-\frac{2}{d_A d_B +1}\right)^t - \left(1-\frac{2}{d_A + 1}\right)^{t+1}\right] \\
    &\simeq 2 + 2(2t+1)N_A + 2 t N_B - 2t (N_A+N_B) - 2(t+1)N_A - 2\log_2\left[1-\frac{2t}{d_A d_B +1} - \left(1-\frac{2(t+1)}{d_A + 1}\right)\right]\\
    &= 2 - 2\log_2\left(\frac{2(t+1)}{d_A + 1} -\frac{2t}{d_A d_B +1}\right)\\
    &\simeq 2 - 2\log_2\left(\frac{2(t+1)}{d_A} -\frac{2t}{d_A d_B}\right)\\
    & = 2 - 2\log_2\left(\frac{2}{d_A}(t+1 -t/d_B)\right)\\
    &= 2N_A - \log_2\left((1-1/d_B)t + 1\right).
    \label{eq:cond_lb_asymp_sm}
\end{align}












\section{Derivation for measurement-unconditioned QMI (Theorems~\ref{MI_traceout_theorem} and \ref{MI_traceout_id_theorem})}
\label{app:thereom23}

In this section, we provide the proof on the dynamics for measurement-unconditioned QMI with pure and mixed state reset strategy. As we point out in the main text, for computation convenience, we focus on the R\'enyi-extended QMI defined by
\be
    I_2(R:A_t) = S_2(\rho_R) + S_2(\rho_{A_t}) - S_2(\rho_{R A_t}),
    \label{eq:renyi_qmi}
\ee
where $S_2(\cdot)$ is the R\'enyi-2 entropy. 


In the following, Theorem~\ref{MI_traceout_theorem} is proven in Section~\ref{app:pure_reset} and Theorem~\ref{MI_traceout_id_theorem} is proven in Section~\ref{app:mixed_reset}.

\subsection{Pure-state reset strategy}
\label{app:pure_reset}
\begin{figure}[t]
    \centering
    \includegraphics[width=0.5\textwidth]{Fig15_uncond_diag.pdf}
    \caption{Equivalent relation on the quantum dynamics with mid-circuit measurements and $\ket
    {0}_B$ reset via expanding the bath. The linear map $E$ (blue box) is applied on the initial maximally entangled state. The dashed lines indicate that those outputs do not interact with the unitaries to be passed through. Here we show an example for $t=3$.}
    \label{fig:uncond_diagram}
\end{figure}

For pure-state reset strategy, without loosing generality, we simply assume in every step, the bath system is reset to the trivial product state $\ket{0}$.
From the equivalence relation in Fig.~\ref{fig:uncond_diagram}, we can write out the linear map $E$ as
\be
    E = \sum_{\bm a, \bm b} \prod_{k=0}^{t-1} \braket{a_{k+1} b_{k+1}|U_k|a_{k} 0} \ket{a_t}_{A_t} \otimes_{k=0}^{t-1} \ket{b_{k+1}}_{B_{k+1}} \bra{a_0}_{A_0},
    \label{eq:E_def_uncond}
\ee
where $\bm a = (a_0, \cdots, a_t)$ and $\bm b = (b_1, \cdots, b_t)$ are vector representation of the corresponding indices on data and bath system. Given the initial maximally-entangled state $\ket{\Phi}_{RA_0} = \frac{1}{\sqrt{d_A}} \sum_j \ket{j}_R \ket{j}_{A_0}$, then we have the output state on $R A_t \bm B$ to be
\begin{align}
    &\ket{\psi}_{R A_t \bm B} = (\mathbb{I}_R \otimes E) \ket{\Phi}_{RA_0}\\
    &= \sum_{\bm a, \bm b} \prod_{k=0}^{t-1} \braket{a_{k+1} b_{k+1}|U_k|a_{k} 0} \ket{a_t}_{A_t} \otimes_{k=0}^{t-1} \ket{b_{k+1}}_{B_{k+1}} \left(\bI_R \otimes \bra{a_0}_{A_0}\right) \ket{\Phi}_{RA_0} \\
    &= \frac{1}{\sqrt{d_A}} \sum_{\bm a, \bm b} \prod_{k=0}^{t-1} \braket{a_{k+1} b_{k+1}|U_k|a_{k} 0} \ket{a_0}_R \ket{a_t}_{A_t} \otimes_{k=0}^{t-1} \ket{b_{k+1}}_{B_{k+1}}. 
\end{align}
With one more step, we can write out the corresponding density operator of $\ket{\psi}_{R A_t \bm B}$ as
\begin{align}
    \rho_{R A_t \bm B} = \frac{1}{d_A} \sum_{\substack{\bm a, \bm a'\\ \bm b, \bm b'}}  \prod_{k=0}^{t-1} \braket{a_{k+1} b_{k+1}|U_k|a_{k} 0} \braket{a_k' 0|U_k^\dagger|a_{k+1}' b_{k+1}'} \ketbra{a_0}{a_0'}_R \ketbra{a_t}{a_t'}_{A_t} \otimes_{k=0}^{t-1} \ketbra{b_{k+1}}{b_{k+1}'}_{B_{k+1}}.
    \label{eq:rho_uncond}
\end{align}

Recall the definition of R\'enyi-extended QMI in Eq.~\eqref{eq:renyi_qmi}, now we evluate the corresponding reduced states and their R\'enyi-2 entropy. We begin with $\rho_R$.
\begin{align}
    &\rho_R = \tr_{A_t \bm B}(\rho_{R A_t \bm B})\\
    &= \frac{1}{d_A} \sum_{\substack{\bm a, \bm a'\\ \bm b, \bm b'}}  \prod_{k=0}^{t-1} \braket{a_{k+1} b_{k+1}|U_k|a_{k} 0} \braket{a_k' 0|U_k^\dagger|a_{k+1}' b_{k+1}'} \ketbra{a_0}{a_0'}_R \delta_{a_t, a_t'} \prod_{k=0}^{t-1} \delta_{b_{k+1}, b_{k+1}'}\\
    &= \frac{1}{d_A} \sum_{\substack{\bm a, \bm a'\\ \bm b, \bm b'}}  \prod_{k=0}^{t-1} \tr\left(U_k \left(\ketbra{a_k}{a_k'}\otimes\ketbra{0}{0}\right) U_k^\dagger \left(\ketbra{a_{k+1}'}{a_{k+1}} \otimes \ketbra{b_{k+1}'}{b_{k+1}}\right) \right) \ketbra{a_0}{a_0'}_R \delta_{a_t, a_t'} \prod_{k=0}^{t-1} \delta_{b_{k+1}, b_{k+1}'}.
\end{align}
The purity of $\rho_R$ then becomes
\begin{align}
    &\tr(\rho_R^2) \nonumber\\
    &= \frac{1}{d_A^2} \sum_{\substack{\bm a, \bm a'\\ \bm b, \bm b'}}  \prod_{k=0}^{t-1} \tr\left(U_k \left(\ketbra{a_k}{a_k'}\otimes\ketbra{0}{0}\right) U_k^\dagger \left(\ketbra{a_{k+1}'}{a_{k+1}} \otimes \ketbra{b_{k+1}'}{b_{k+1}}\right) \right) \delta_{a_t, a_t'} \prod_{k=0}^{t-1} \delta_{b_{k+1}, b_{k+1}'} \nonumber\\
    &\qquad \quad \times \sum_{\substack{\bm \alpha, \bm \alpha'\\ \bm \beta, \bm \beta'}}  \prod_{k=0}^{t-1} \tr\left(U_k \left(\ketbra{\alpha_k}{\alpha_k'}\otimes\ketbra{0}{0}\right) U_k^\dagger \left(\ketbra{\alpha_{k+1}'}{\alpha_{k+1}} \otimes \ketbra{\beta_{k+1}'}{\beta_{k+1}}\right) \right)  \delta_{\alpha_t, \alpha_t'} \prod_{k=0}^{t-1} \delta_{\beta_{k+1}, \beta_{k+1}'} \delta_{a_0, \alpha_0'} \delta_{a_0', \alpha_0}\\
    &= \frac{1}{d_A^2} \sum_{\substack{\bm a, \bm a'\\ \bm b, \bm b'}} \sum_{\substack{\bm \alpha, \bm \alpha'\\ \bm \beta, \bm \beta'}} \prod_{k=0}^{t-1} \tr\left(U_k^{\otimes 2} \left(\ketbra{a_k \alpha_k}{a_k' \alpha_k'}\otimes\ketbra{0}{0}^{\otimes 2}\right) U_k^\dagger{}^{\otimes 2} \left(\ketbra{a_{k+1}' \alpha_{k+1}'}{a_{k+1} \alpha_{k+1}} \otimes \ketbra{b_{k+1}' \beta_{k+1}'}{b_{k+1} \beta_{k+1}}\right)\right)\nonumber\\
    &\qquad \qquad \qquad \times \delta_{a_0, \alpha_0'} \delta_{a_0', \alpha_0} \delta_{a_t, a_t'} \delta_{\alpha_t, \alpha_t'} \prod_{k=0}^{t-1} \delta_{b_{k+1}, b_{k+1}'} \delta_{\beta_{k+1}, \beta_{k+1}'},
    \label{eq:rhoR_purity}
\end{align}
which can be equivalently expressed in the diagram shown in Fig.~\ref{fig:uncond_purity_diagram}a with a choice of $t=3$.

\begin{figure}[t]
    \centering
    \includegraphics[width=0.5\textwidth]{Fig16_uncond_twirling.pdf}
    \caption{Tensor network representation of Haar-averaged purity for reduced states (a) $\rho_R$, (b) $\rho_{A_t}$ and (c) $\rho_{R A_t}$ with zero-state reset and time steps $t=3$.}
    \label{fig:uncond_purity_diagram}
\end{figure}

For Haar ensemble average of unitary twirling over two replicas, we have
\be
    \E_{\rm Haar}\left[U^{\otimes 2} \otimes U^*{}^{\otimes 2}\right] = \frac{1}{d^2-1} \left[|e)(e| - \frac{1}{d}|e)(\tau| + |\tau)(\tau| - \frac{1}{d}|\tau)(e|\right],
    \label{eq:haar_2design}
\ee
where $|e)$ and $|\tau)$ are the vectorized operator for identity and transposition between two replicas, following the convention of Ref.~\cite{ippoliti2022solvable, zhang2024holographic}. The inner product of any two operator thus can be conveniently represented as $\tr(A^\dagger B) = (A|B)$. The unitary twirling on the step $t$ becomes
\begin{align}
    &\E_{\rm Haar}\left[U_{t-1}^{\otimes 2} \otimes U_{t-1}^*{}^{\otimes 2}\right]|e)_{A}|e)_{B} \nonumber\\
    &=\frac{1}{d_A^2d_B^2-1} \left[d_A^2d_B^2|e)_{AB} - |e)_{AB} + d_A d_B|\tau)_{AB} - d_A d_B|\tau)_{AB}\right]\\
    &= |e)_{AB},
    \label{eq:twirling_ee}
\end{align}
where we utilize $(e|e)_A = d_A^2, (\tau|e)_A = d_A$ in the second line.
Via the reseting with $(0|_B$ and replacing it to $|e)_B$ in the $t-1$ step, we reobtain the initial boundary condition $|e)_A |e)_B$. Therefore, the Haar-averaged purity becomes
\be
\E_{\rm Haar} \tr(\rho_R^2) = \frac{1}{d_A^2} (\tau|_A (0|_B |e)_{A} |e)_B = \frac{1}{d_A}.
\label{eq:rhoR_purity_sol}
\ee

Next, we move to the reduced state $\rho_{A_t}$. Following Eq.~\eqref{eq:rho_uncond}, we have
\begin{align}
    &\rho_{A_t} = \tr_{R \bm B}(\rho_{R A_t \bm B})\\
    &= \frac{1}{d_A} \sum_{\substack{\bm a, \bm a'\\ \bm b, \bm b'}}  \prod_{k=0}^{t-1} \tr\left(U_k \left(\ketbra{a_k}{a_k'}\otimes\ketbra{0}{0}\right) U_k^\dagger \left(\ketbra{a_{k+1}'}{a_{k+1}} \otimes \ketbra{b_{k+1}'}{b_{k+1}}\right) \right) \delta_{a_0, a_0'} \ketbra{a_t}{a_t'}_{A_t} \prod_{k=0}^{t-1} \delta_{b_{k+1},b_{k+1}'},
\end{align}
and the purity becomes
\begin{align}
    &\tr(\rho_{A_t}^2) \nonumber\\
    &= \frac{1}{d_A^2} \sum_{\substack{\bm a, \bm a'\\ \bm b, \bm b'}} \sum_{\substack{\bm \alpha, \bm \alpha'\\ \bm \beta, \bm \beta'}} \prod_{k=0}^{t-1} \tr\left(U_k^{\otimes 2} \left(\ketbra{a_k \alpha_k}{a_k' \alpha_k'}\otimes\ketbra{0}{0}^{\otimes 2}\right) U_k^\dagger{}^{\otimes 2} \left(\ketbra{a_{k+1}' \alpha_{k+1}'}{a_{k+1} \alpha_{k+1}} \otimes \ketbra{b_{k+1}' \beta_{k+1}'}{b_{k+1} \beta_{k+1}}\right)\right) \nonumber\\
    &\qquad \qquad \qquad \times \delta_{a_0, a_0'} \delta_{\alpha_0, \alpha_0'} \delta_{a_t, \alpha_t'}\delta_{a_t', \alpha_t} \prod_{k=0}^{t-1} \delta_{b_{k+1},b_{k+1}'}\delta_{\beta_{k+1},\beta_{k+1}'},
\end{align}
which is equivalently expressed in the diagram shown in Fig.~\ref{fig:uncond_purity_diagram}b.
The Haar ensemble average from step $t$ is 
\begin{align}
    &\E_{\rm Haar}\left[U_{t-1}^{\otimes 2} \otimes U_{t-1}^*{}^{\otimes 2}\right]|\tau)_{A}|e)_{B}  \nonumber \\
    &= \frac{1}{d_A^2d_B^2-1} \left[d_A d_B^2|e) - \frac{d_A^2 d_B}{d_A d_B}|e) + d_A^2 d_B|\tau) - \frac{d_A d_B^2}{d_A d_B}|\tau)\right]\\
    &= \frac{d_A(d_B^2-1)}{d_A^2d_B^2-1} |e)_{AB} + \frac{d_B(d_A^2 - 1)}{d_A^2d_B^2-1} |\tau)_{AB},
    \label{eq:twirling_taue}
\end{align}
where in the second line we utilize the fact $(\tau|\tau)_A = d_A^2$.
Catenating with $|e)(0|_B$ results in
\be
    |e)(0|_B \E_{\rm Haar}\left[U_{t-1}^{\otimes 2} \otimes U_{t-1}^*{}^{\otimes 2}\right]|\tau)_{A}|e)_{B} = \frac{d_A(d_B^2-1)}{d_A^2d_B^2-1} |e)_A|e)_B + \frac{d_B(d_A^2 - 1)}{d_A^2 d_B^2-1} |\tau)_A|e)_B.
\ee
We can find that the second term shares the same boundary condition $|\tau)_A|e)_B$ as the step $t$ we have evaluated, and from the calculation in Eq.~\eqref{eq:twirling_ee} we know that the boundary $|e)_A |e)_B$ remains the same through unitary twirling. Therefore, we can separately evaluate the contribution from $|\tau)_A|e)_B$ and $|e)_A |e)_B$ as follows.
\begin{itemize}
    \item $|\tau)_A|e)_B$: 
    \be
        \frac{1}{d_A^2}\left(\frac{d_B(d_A^2 - 1)}{d_A^2 d_B^2-1}\right)^t (e|\tau)_A (0|e)_B = \frac{1}{d_A}\left(\frac{d_B(d_A^2 - 1)}{d_A^2 d_B^2-1}\right)^t.
    \ee
    \item $|e)_A|e)_B$: 
    \be
        \frac{1}{d_A^2} \frac{d_A(d_B^2-1)}{d_A^2 d_B^2-1} \sum_{k=0}^{t-1} \left(\frac{d_B(d_A^2 - 1)}{d_A^2 d_B^2-1}\right)^k (e|e)_A (0|e)_B = \frac{d_A(d_B+1)}{d_A^2 d_B + 1} \left(1 - \left(\frac{d_B(d_A^2 - 1)}{d_A^2 d_B^2-1}\right)^t\right).
    \ee
\end{itemize}
Combining the above two terms together, we obtain the dynamical solution of Haar-averaged purity for $\rho_{A_t}$
\begin{align}
    \E_{\rm Haar} \tr(\rho_{A_t}^2) &= \frac{1}{d_A}\left(\frac{d_B(d_A^2 - 1)}{d_A^2 d_B^2-1}\right)^t + \frac{d_A(d_B+1)}{d_A^2 d_B + 1} \left(1 - \left(\frac{d_B(d_A^2 - 1)}{d_A^2 d_B^2-1}\right)^t\right)\\
    &= \frac{d_A (1+d_B)}{1 + d_A^2 d_B} + \frac{1-d_A^2}{d_A(1 + d_A^2 d_B)} \left(\frac{d_B(d_A^2 - 1)}{d_A^2 d_B^2-1}\right)^t.
    \label{eq:rhoA_purity_sol}
\end{align}

Finally, we move to the reduced state $\rho_{R A_t}$.
\begin{align}
    &\rho_{R A_t} = \tr_{\bm B}(\rho_{R A_t \bm B})\\
    &= \frac{1}{d_A} \sum_{\substack{\bm a, \bm a'\\ \bm b, \bm b'}}  \prod_{k=0}^{t-1} \tr\left(U_k \left(\ketbra{a_k}{a_k'}\otimes\ketbra{0}{0}\right) U_k^\dagger \left(\ketbra{a_{k+1}'}{a_{k+1}} \otimes \ketbra{b_{k+1}'}{b_{k+1}}\right) \right) \left(\ketbra{a_0}{a_0'}_R \otimes \ketbra{a_t}{a_t'}_{A_t}\right) \prod_{k=0}^{t-1} \delta_{b_{k+1},b_{k+1}'},
\end{align}
and the purity becomes
\begin{align}
    &\tr(\rho_{R A_t}^2) \nonumber\\
    &= \frac{1}{d_A^2} \sum_{\substack{\bm a, \bm a'\\ \bm b, \bm b'}} \sum_{\substack{\bm \alpha, \bm \alpha'\\ \bm \beta, \bm \beta'}} \prod_{k=0}^{t-1} \tr\left(U_k^{\otimes 2} \left(\ketbra{a_k \alpha_k}{a_k' \alpha_k'}\otimes\ketbra{0}{0}^{\otimes 2}\right) U_k^\dagger{}^{\otimes 2} \left(\ketbra{a_{k+1}' \alpha_{k+1}'}{a_{k+1} \alpha_{k+1}} \otimes \ketbra{b_{k+1}' \beta_{k+1}'}{b_{k+1} \beta_{k+1}}\right)\right) \nonumber\\
    &\qquad \qquad \qquad \times \delta_{a_0, \alpha_0'} \delta_{a_0', \alpha_0} \delta_{a_t, \alpha_t'}\delta_{a_t', \alpha_t} \prod_{k=0}^{t-1} \delta_{b_{k+1},b_{k+1}'}\delta_{\beta_{k+1},\beta_{k+1}'},
\end{align}
which is equivalently expressed in the diagram shown in Fig.~\ref{fig:uncond_purity_diagram}c.
Since it shares the same boundary condition as in Fig.~\ref{fig:uncond_purity_diagram}b, we thus can directly write out the contributions from $|\tau)_A|e)_B$ and $|e)_A |e)_B$ as
\begin{itemize}
    \item $|\tau)_A|e)_B$: 
    \be
        \frac{1}{d_A^2}\left(\frac{d_B(d_A^2 - 1)}{d_A^2 d_B^2-1}\right)^t (\tau|\tau)_A (0|e)_B = \left(\frac{d_B(d_A^2 - 1)}{d_A^2 d_B^2-1}\right)^t.
    \ee
    \item $|e)_A|e)_B$: 
    \be
        \frac{1}{d_A^2} \frac{d_A(d_B^2-1)}{d_A^2 d_B^2-1} \sum_{k=0}^{t-1} \left(\frac{d_B(d_A^2 - 1)}{d_A^2 d_B^2-1}\right)^k (\tau|e)_A (0|e)_B = \frac{d_B+1}{d_A^2 d_B + 1} \left(1 - \left(\frac{d_B(d_A^2 - 1)}{d_A^2 d_B^2-1}\right)^t\right).
    \ee
\end{itemize}
The dynamical solution of Haar-averaged purity for $\rho_{R A_t}$ becomes
\begin{align}
    \E_{\rm Haar} \tr(\rho_{R A_t}^2) &= \left(\frac{d_B(d_A^2 - 1)}{d_A^2 d_B^2-1}\right)^t + \frac{d_B+1}{d_A^2 d_B + 1} \left(1 - \left(\frac{d_B(d_A^2 - 1)}{d_A^2 d_B^2-1}\right)^t\right)\\
    &= \frac{1+d_B}{1 + d_A^2 d_B} + \frac{d_B(d_A^2-1)}{1 + d_A^2 d_B} \left(\frac{d_B(d_A^2 - 1)}{d_A^2 d_B^2-1}\right)^t.
    \label{eq:rhoRA_purity_sol}
\end{align}

To evaluate the Haar-averaged of measurement-uncondioned R\'enyi-extended QMI in Eq.~\eqref{eq:uncond_MI}, we switch the order of ensemble average and logarithmic, which does not change the final result as long as the fluctuation of entropy is small. Combining the results in Eqs.~\eqref{eq:rhoR_purity_sol},~\eqref{eq:rhoA_purity_sol} and~\eqref{eq:rhoRA_purity_sol}, we have
\begin{align}
    &\E_{\rm Haar} I_2(R:A_t) \simeq -\log_2 \E_{\rm Haar}\tr(\rho_R^2) - \log_2 \E_{\rm Haar}\tr(\rho_{A_t}^2) + \log_2 \E_{\rm Haar}\tr(\rho_{R A_t}^2) \\
    &= N_A - \log_2 \left[\frac{d_A (1+d_B)}{1 + d_A^2 d_B} + \frac{1-d_A^2}{d_A(1 + d_A^2 d_B)} \left(\frac{d_B(d_A^2 - 1)}{d_A^2 d_B^2-1}\right)^t\right] + \log_2\left[\frac{1+d_B}{1 + d_A^2 d_B} + \frac{d_B(d_A^2-1)}{1 + d_A^2 d_B} \left(\frac{d_B(d_A^2 - 1)}{d_A^2 d_B^2-1}\right)^t\right],
\end{align}
which is the result of Eq.~\eqref{eq:MI_traceout} in the main text. Assuming large system size $d_A, d_B \gg 1$, we can perform asymptotic analysis, 
\begin{align}
    &\E_{\rm Haar} I_2(R:A_t) = N_A - \log_2 \left[\frac{d_A^2 (1+d_B) + (1-d_A^2)\left(\frac{d_B(d_A^2 - 1)}{d_A^2 d_B^2-1}\right)^t}{d_A(1 + d_A^2 d_B)} \right] + \log_2\left[\frac{1+d_B + d_B(d_A^2-1)\left(\frac{d_B(d_A^2 - 1)}{d_A^2 d_B^2-1}\right)^t}{1 + d_A^2 d_B}\right] \nonumber\\
    &\simeq N_A - \log_2\left(\frac{1}{d_A} - \frac{1}{d_A d_B} \frac{1}{d_B^t}\right) + \log_2\left(\frac{1}{d_A^2} + \frac{1}{d_B^t}\right)\\
    &= N_A - \log_2 \frac{1}{d_A}\left( 1 - \frac{1}{d_B^{t+1}}\right) + \log_2\left(\frac{1}{d_A^2} + \frac{1}{d_B^t}\right)\\
    &\simeq 2N_A - d_B^{-(t+1)} + \log_2\left(d_A^{-2} + d_B^{-t}\right).
\end{align}
For early time $t \ll 2N_A/N_B$, we can further approximate the QMI as
\begin{align}
    \E_{\rm Haar} I_2(R:A_t) &\simeq 2N_A - d_B^{-(t+1)} + \log_2\left(d_A^{-2} + d_B^{-t}\right)\nonumber\\
    &= 2N_A - d_B^{-(t+1)} + \log_2 d_B^{-t}\left(1 + d_A^{-2} d_B^t \right)\\
    &\simeq 2N_A - d_B^{-(t+1)} -t N_B + d_A^{-2} d_B^t\\
    &\simeq 2N_A - tN_B + \mathcal{O}(d_B^{t}/d_A^2),
\end{align}
which recovers the linear scaling in the main text.
On the other hand for late time $t \gg 2N_A/N_B$, with similar approximation method, we have
\begin{align}
    \E_{\rm Haar} I_2(R:A_t) &\simeq 2N_A - d_B^{-(t+1)} + \log_2\left(d_A^{-2} + d_B^{-t}\right)\nonumber\\
    &= 2N_A - d_B^{-(t+1)} + \log_2 d_A^{-2}\left(1 + d_A^{2} d_B^{-t} \right)\\
    &\simeq  2N_A - d_B^{-(t+1)} -2 N_A + d_A^{2} d_B^{-t}\\
    &= d_A^2 d_B^{-t} + \mathcal{O}(d_B^{-(t+1)}).
\end{align}

\subsection{Fully-mixed state reset strategy}
\label{app:mixed_reset}

In this part, we focus on a different reset strategy, the bath system is initialized with a fully-mixed state $\omega = \bI_B/d_B$ starting from the second step.

\begin{figure}[t]
    \centering
    \includegraphics[width=0.5\textwidth]{Fig17_uncond_mix_diag.pdf}
    \caption{Equivalent relation on the quantum dynamics with mid-circuit measurements and diagonal-mixed-state reset via expanding the bath. Here $\omega = \bI_B/d_B$ represents the fully-mixed state. The linear map $E$ (blue box) is applied on the initial maximally entangled state. The dashed lines indicate that those outputs do not interact with the unitaries to be passed through. Here we show an example for $t=3$.}
    \label{fig:uncond_mix_diagram}
\end{figure}

Similar to the derivation in pure-state reset strategy, we first write out the linear map $E$ (shown by blue box in Fig.~\ref{fig:uncond_mix_diagram}) as
\be
    E = \sum_{\bm a, \bm b} \prod_{k=0}^{t-1} \braket{a_{k+1} b_{2k+1}|U_k|a_k b_{2k}} \ket{a_t}_{A_t}\bra{a_0}_{A_0} \otimes_{k=0}^{t-1} \ketbra{b_{2k+1}}{b_{2k}},
    \label{eq:E_def_uncond_mix}
\ee
where different from above we define the vector representation $\bm b = (b_0, b_1, \cdots, b_{2t-2}, b_{2t-1})$. Via applying the linear map $E$ on maximally entangled state $\ket{\Phi}_{RA_0}$ and the expanded bath system (shown in Fig.~\ref{fig:uncond_mix_diagram}), we have the output state over the whole system as
\begin{align}
    &\rho_{R A_t \bm B} = (\mathbb{I}_R \otimes E) \left(\ketbra{\Phi}{\Phi}_{RA_0} \left(\otimes_{k=0}^{t-1} \omega\right) \otimes \ketbra{0}{0}\right) (\mathbb{I}_R \otimes E)^\dagger\\
    &= \frac{1}{d_A} \sum_{\substack{\bm a, \bm b,\\ \bm a', \bm b'}}\prod_{k=0}^{t-1} \braket{a_{k+1} b_{2k+1}|U_k|a_k b_{2k}} \braket{a_k' b_{2k}'|U_k^\dagger|a_{k+1}' b_{2k+1}'} \ketbra{a_0}{a_0'}_R \ketbra{a_t}{a_t'}_{A_t} \left(\otimes_{k=0}^{t-1} \ketbra{b_{2k+1}}{b_{2k+1}'}\right) \braket{b_0|0}\braket{0|b_0'}\otimes_{k=1}^{t-1} \braket{b_{2k}|\omega|b_{2k}'}\\
    &= \frac{1}{d_A} \frac{1}{d_B^{t-1}}\sum_{\substack{\bm a, \bm b,\\ \bm a', \bm b'}}\prod_{k=0}^{t-1} \braket{a_{k+1} b_{2k+1}|U_k|a_k b_{2k}} \braket{a_k' b_{2k}'|U_k^\dagger|a_{k+1}' b_{2k+1}'} \ketbra{a_0}{a_0'}_R \ketbra{a_t}{a_t'}_{A_t} \left(\otimes_{k=0}^{t-1} \ketbra{b_{2k+1}}{b_{2k+1}'}\right) \delta_{b_0, 0}\delta_{b_0',0} \prod_{k=1}^{t-1} \delta_{b_{2k},b_{2k}'}. 
\end{align}



For the reduced state $\rho_R$, we have
\begin{align}
    &\rho_R = \tr_{A_t \bm B}(\rho_{R A_t \bm B})\\
    &= \frac{1}{d_A} \frac{1}{d_B^{t-1}}\sum_{\substack{\bm a, \bm b,\\ \bm a', \bm b'}}\prod_{k=0}^{t-1} \braket{a_{k+1} b_{2k+1}|U_k|a_k b_{2k}} \braket{a_k' b_{2k}'|U_k^\dagger|a_{k+1}' b_{2k+1}'} \ketbra{a_0}{a_0'}_R \delta_{a_t, a_t'} \prod_{k=0}^{t-1} \delta_{b_{2k+1},b_{2k+1}'} \delta_{b_0, 0}\delta_{b_0',0} \prod_{k=1}^{t-1} \delta_{b_{2k},b_{2k}'}\\
    &= \frac{1}{d_A} \frac{1}{d_B^{t-1}} \sum_{\bm a, \bm a'}  \prod_{k=1}^{t-1} \tr\left(U_k \left(\ketbra{a_k}{a_k'}\otimes \bI\right) U_k^\dagger \left(\ketbra{a_{k+1}'}{a_{k+1}}\otimes \bI\right)\right) \tr\left(U_0 \left(\ketbra{a_0}{a_0'}\otimes \ketbra{0}{0}\right) U_0^\dagger \left(\ketbra{a_1'}{a_1}\otimes \bI\right)\right) \ketbra{a_0}{a_0'}_R \delta_{a_t, a_t'}.
\end{align}
The purity of $\rho_R$ then can be evaluated as
\begin{align}
    &\tr(\rho_R^2)\nonumber\\
    &= \frac{1}{d_A^2} \frac{1}{d_B^{2t-2}} \sum_{\bm a, \bm a'}  \prod_{k=1}^{t-1} \tr\left(U_k \left(\ketbra{a_k}{a_k'}\otimes \bI\right) U_k^\dagger \left(\ketbra{a_{k+1}'}{a_{k+1}}\otimes \bI\right)\right) \tr\left(U_0 \left(\ketbra{a_0}{a_0'}\otimes \ketbra{0}{0}\right) U_0^\dagger \left(\ketbra{a_1'}{a_1}\otimes \bI\right)\right) \delta_{a_t, a_t'} \nonumber\\
    & \qquad \quad \times\sum_{\bm \alpha, \bm \alpha'}  \prod_{k=1}^{t-1} \tr\left(U_k \left(\ketbra{\alpha_k}{\alpha_k'}\otimes \bI \right) U_k^\dagger \left(\ketbra{\alpha_{k+1}'}{\alpha_{k+1}}\otimes \bI\right)\right) \tr\left(U_0 \left(\ketbra{\alpha_0}{\alpha_0'}\otimes \ketbra{0}{0}\right) U_0^\dagger \left(\ketbra{\alpha_1'}{\alpha_1}\otimes \bI\right)\right) \delta_{\alpha_t, \alpha_t'} \delta_{a_0, \alpha_0'}\delta_{a_0',\alpha_0} \\
    &= \frac{1}{d_A^2} \frac{1}{d_B^{2t-2}} \sum_{\substack{\bm a, \bm a', \\ \bm \alpha, \bm \alpha'}} \prod_{k=1}^{t-1} \tr\left(U_k^{\otimes 2} \left(\ketbra{a_k \alpha_k}{a_k'\alpha_k'}\otimes \bI^{\otimes 2}\right) U_k^\dagger{}^{\otimes 2} \left(\ketbra{a_{k+1}' \alpha_{k+1}'}{a_{k+1} \alpha_{k+1}}\otimes \bI^{\otimes 2}\right)\right) \nonumber\\
    &\qquad \qquad \qquad \times \tr\left(U_0^{\otimes 2} \left(\ketbra{a_0 \alpha_0}{a_0' \alpha_0'}\otimes \ketbra{0}{0}^{\otimes 2}\right) U_0^\dagger{}^{\otimes 2} \left(\ketbra{a_1' \alpha_1'}{a_1 \alpha_1}\otimes \bI^{\otimes 2}\right)\right) \delta_{a_t, a_t'} \delta_{\alpha_t, \alpha_t'} \delta_{a_0, \alpha_0'}\delta_{a_0',\alpha_0},
\end{align}
which is represented in tensor network in Fig.~\ref{fig:uncond_purity_mix_diagram}a.

Recall that $\E_{\rm Haar}\left[U_{t-1}^{\otimes 2} \otimes U_{t-1}^*{}^{\otimes 2}\right]|e)_A |e)_B = |e)_{AB}$ from Eq.~\eqref{eq:twirling_ee}, the following concatenation with $|e)(e|_B$ results in
\be
    |e)(e|_B\E_{\rm Haar}\left[U_{t-1}^{\otimes 2} \otimes U_{t-1}^*{}^{\otimes 2}\right]|e)_A |e)_B = d_B^2 |e)_A |e)_B,
\ee
As the boundary condition is exactly reproduced in the following step with an extra coefficient $d_B^2$, then we can directly obtain the solution of purity as
\be
    \E_{\rm Haar} \tr(\rho_R^2) = \frac{1}{d_A^2} \frac{1}{d_B^{2t-2}} d_B^{2(t-1)} (\tau|_A (0|_B |e)_{A} |e)_B = \frac{1}{d_A}.
    \label{eq:rhoR_purity_mix_sol}
\ee

\begin{figure}[t]
    \centering
    \includegraphics[width=0.5\textwidth]{Fig18_uncond_mix_twirling.pdf}
    \caption{Tensor network representation of Haar-averaged purity for reduced states (a) $\rho_R$, (b) $\rho_{A_t}$ and (c) $\rho_{R A_t}$ with fully-mixed state reset and time steps $t=3$.}
    \label{fig:uncond_purity_mix_diagram}
\end{figure}


Next, we move to the reduced state $\rho_{A_t}$.
\begin{align}
    &\rho_{A_t} = \tr_{R \bm B}(\rho_{R A_t \bm B})\\
    &= \frac{1}{d_A}\frac{1}{d_B^{t-1}} \sum_{\substack{\bm a, \bm b,\\ \bm a', \bm b'}}\prod_{k=0}^{t-1} \braket{a_{k+1} b_{2k+1}|U_k|a_k b_{2k}} \braket{a_k' b_{2k}'|U_k^\dagger|a_{k+1}' b_{2k+1}'} \delta_{a_0, a_0'} \ketbra{a_t}{a_t'}_{A_t} \prod_{k=0}^{t-1} \delta_{b_{2k+1},b_{2k+1}'} \delta_{b_0, 0}\delta_{b_0',0} \prod_{k=1}^{t-1} \delta_{b_{2k},b_{2k}'}\\
    &= \frac{1}{d_A} \frac{1}{d_B^{t-1}} \sum_{\bm a, \bm a'}  \prod_{k=1}^{t-1} \tr\left(U_k \left(\ketbra{a_k}{a_k'}\otimes \bI\right) U_k^\dagger \left(\ketbra{a_{k+1}'}{a_{k+1}}\otimes \bI\right)\right) \tr\left(U_0 \left(\ketbra{a_0}{a_0'}\otimes \ketbra{0}{0}\right) U_0^\dagger \left(\ketbra{a_1'}{a_1}\otimes \bI\right)\right) \delta_{a_0, a_0'} \ketbra{a_t}{a_t'}_{A_t},
\end{align}
and the purity is
\begin{align}
    &\tr(\rho_{A_t}^2)\nonumber\\
    &= \frac{1}{d_A^2} \frac{1}{d_B^{2t-2}} \sum_{\bm a, \bm a'}  \prod_{k=1}^{t-1} \tr\left(U_k \left(\ketbra{a_k}{a_k'}\otimes \bI\right) U_k^\dagger \left(\ketbra{a_{k+1}'}{a_{k+1}}\otimes \bI\right)\right) \tr\left(U_0 \left(\ketbra{a_0}{a_0'}\otimes \ketbra{0}{0}\right) U_0^\dagger \left(\ketbra{a_1'}{a_1}\otimes \bI\right)\right) \delta_{a_0, a_0'} \nonumber\\
    & \qquad \quad \times \sum_{\bm \alpha, \bm \alpha'}  \prod_{k=1}^{t-1} \tr\left(U_k \left(\ketbra{\alpha_k}{\alpha_k'}\otimes \bI\right) U_k^\dagger \left(\ketbra{\alpha_{k+1}'}{\alpha_{k+1}}\otimes \bI\right)\right) \tr\left(U_0 \left(\ketbra{\alpha_0}{\alpha_0'}\otimes \ketbra{0}{0}\right) U_0^\dagger \left(\ketbra{\alpha_1'}{\alpha_1}\otimes \bI\right)\right) \delta_{\alpha_0, \alpha_0'} \delta_{a_t, \alpha_t'}\delta_{a_t',\alpha_t}\\
    &= \frac{1}{d_A^2}\frac{1}{d_B^{2t-2}} \sum_{\substack{\bm a, \bm a', \\ \bm \alpha, \bm \alpha'}} \prod_{k=1}^{t-1} \tr\left(U_k^{\otimes 2} \left(\ketbra{a_k \alpha_k}{a_k'\alpha_k'}\otimes \bI^{\otimes 2}\right) U_k^\dagger{}^{\otimes 2} \left(\ketbra{a_{k+1}' \alpha_{k+1}'}{a_{k+1} \alpha_{k+1}}\otimes \bI^{\otimes 2}\right)\right) \nonumber\\
    &\qquad \qquad \qquad \times \tr\left(U_0^{\otimes 2} \left(\ketbra{a_0 \alpha_0}{a_0' \alpha_0'}\otimes \ketbra{0}{0}^{\otimes 2}\right) U_0^\dagger{}^{\otimes 2} \left(\ketbra{a_1' \alpha_1'}{a_1 \alpha_1}\otimes \bI^{\otimes 2}\right)\right) \delta_{a_0, a_0'} \delta_{\alpha_0, \alpha_0'} \delta_{a_t, \alpha_t'}\delta_{a_t',\alpha_t},
\end{align}
which is shown in Fig.~\ref{fig:uncond_purity_mix_diagram}b.

Recall from Eq.~\eqref{eq:twirling_taue} $\E_{\rm Haar}\left[U_{t-1}^{\otimes 2} \otimes U_{t-1}^*{}^{\otimes 2}\right]|\tau)_{A}|e)_{B} = \frac{d_A(d_B^2-1)}{d_A^2d_B^2-1} |e)_{AB} + \frac{d_B(d_A^2 - 1)}{d_A^2d_B^2-1} |\tau)_{AB}$, we next apply $|e)(e|_B$ and have
\be
    |e)(e|_B \E_{\rm Haar}\left[U_{t-1}^{\otimes 2} \otimes U_{t-1}^*{}^{\otimes 2}\right]|\tau)_{A}|e)_{B} = \frac{d_A d_B^2(d_B^2-1)}{d_A^2 d_B^2-1} |e)_A |e)_B + \frac{d_B^2(d_A^2 - 1)}{d_A^2d_B^2-1} |\tau)_A |e)_B,
\ee
Moving downward in Fig.~\ref{fig:uncond_purity_mix_diagram}b up to $U_1$, we have the contribution from the two boundary conditions above as
\begin{itemize}
    \item $|\tau)_A|e)_B$: $\left(\frac{d_B^2(d_A^2 - 1)}{d_A^2 d_B^2-1}\right)^{t-1} |\tau)_A |e)_B$.

    \item $|e)_A|e)_B$: $\frac{d_A d_B^2(d_B^2-1)}{d_A^2 d_B^2-1} \sum_{k=0}^{t-2} \left(\frac{d_B^2 (d_A^2 - 1)}{d_A^2 d_B^2-1}\right)^k d_B^{2(t-2-k)} |e)_A |e)_B$.
\end{itemize}
After finishing the twirling over $U_0$, we have the dynamical solution for purity of $\rho_{A_t}$
\begin{align}
    &\E_{\rm Haar} \tr(\rho_{A_t}^2)\nonumber\\
    &= \frac{1}{d_A^2} \frac{1}{d_B^{2(t-1)}}\left[\left(\frac{d_B^2(d_A^2 - 1)}{d_A^2 d_B^2-1}\right)^{t-1} \frac{d_B(d_A^2 - 1)}{d_A^2d_B^2-1} d_A + \left(\frac{d_B^2(d_A^2 - 1)}{d_A^2 d_B^2-1}\right)^{t-1} \frac{d_A(d_B^2-1)}{d_A^2d_B^2-1} d_A^2 \nonumber \right.\\
    &\left. \qquad \qquad \qquad + \frac{d_A d_B^2(d_B^2-1)}{d_A^2 d_B^2-1} \sum_{k=0}^{t-2} \left(\frac{d_B^2 (d_A^2 - 1)}{d_A^2 d_B^2-1}\right)^k d_B^{2(t-2-k)} d_A^2\right]\\
    &= \frac{1}{d_A^2} \frac{1}{d_B^{2(t-1)}} \left[\frac{d_A}{d_B}\left(\frac{d_B^2(d_A^2 - 1)}{d_A^2 d_B^2-1}\right)^{t} + \frac{d_A^3 (d_B^2-1)}{(d_A^2-1)d_B^2}\left(\frac{d_B^2(d_A^2 - 1)}{d_A^2 d_B^2-1}\right)^{t} + \frac{d_A d_B^{2(t-1)}}{d_A^2 - 1}\left(d_A^2-1-(d_A^2 d_B^2-1) \left(\frac{d_A^2 - 1}{d_A^2 d_B^2 - 1}\right)^t \right)   \right] \\
    &= \frac{d_B}{d_A}\left(\frac{d_A^2 - 1}{d_A^2 d_B^2-1}\right)^{t} + \frac{d_A (d_B^2-1)}{d_A^2-1}\left(\frac{d_A^2 - 1}{d_A^2 d_B^2-1}\right)^{t} + \frac{1}{d_A(d_A^2 - 1)}\left(d_A^2-1-(d_A^2 d_B^2-1) \left(\frac{d_A^2 - 1}{d_A^2 d_B^2 - 1}\right)^t \right)\\
    &= \frac{d_B-1}{d_A} \left(\frac{d_A^2 - 1}{d_A^2 d_B^2-1}\right)^{t} + \frac{1}{d_A}.
    \label{eq:rhoA_purity_mix_sol}
\end{align}


Last, the reduce state $\rho_{R A_t}$ is
\begin{align}
    &\rho_{R A_t} = \tr_{\bm B}(\rho_{R A_t \bm B})\\
    &= \frac{1}{d_A} \frac{1}{d_B^{t-1}}\sum_{\substack{\bm a, \bm b,\\ \bm a', \bm b'}}\prod_{k=0}^{t-1} \braket{a_{k+1} b_{2k+1}|U_k|a_k b_{2k}} \braket{a_k' b_{2k}'|U_k^\dagger|a_{k+1}' b_{2k+1}'} \ketbra{a_0}{a_0'}_R \ketbra{a_t}{ a_t'}_{A_t} \prod_{k=0}^{t-1} \delta_{b_{2k+1},b_{2k+1}'} \delta_{b_0, 0} \delta_{b_0',0} \prod_{k=1}^{t-1} \delta_{b_{2k},b_{2k}'}\\
    &= \frac{1}{d_A} \frac{1}{d_B^{t-1}} \sum_{\bm a, \bm a'}  \prod_{k=1}^{t-1} \tr\left(U_k \left(\ketbra{a_k}{a_k'}\otimes \bI \right) U_k^\dagger \left(\ketbra{a_{k+1}'}{a_{k+1}}\otimes \bI\right)\right) \tr\left(U_0 \left(\ketbra{a_0}{a_0'}\otimes \ketbra{0}{0}\right) U_0^\dagger \left(\ketbra{a_1'}{a_1}\otimes \bI\right)\right) \ketbra{a_0}{a_0'}_R \ketbra{a_t}{ a_t'}_{A_t},
\end{align}
and the purity is
\begin{align}
    &\tr(\rho_{R A_t}^2)\nonumber\\
    &= \frac{1}{d_A^2} \frac{1}{d_B^{2t-2}} \sum_{\bm a, \bm a'}  \prod_{k=1}^{t-1} \tr\left(U_k \left(\ketbra{a_k}{a_k'}\otimes \bI \right) U_k^\dagger \left(\ketbra{a_{k+1}'}{a_{k+1}}\otimes \bI\right)\right) \tr\left(U_0 \left(\ketbra{a_0}{a_0'}\otimes \ketbra{0}{0}\right) U_0^\dagger \left(\ketbra{a_1'}{a_1}\otimes \bI\right)\right) \delta_{a_0, \alpha_0'} \delta_{a_0', \alpha_0} \nonumber\\
    & \qquad \quad \times \sum_{\bm \alpha, \bm \alpha'}  \prod_{k=1}^{t-1} \tr\left(U_k \left(\ketbra{\alpha_k}{\alpha_k'}\otimes \bI \right) U_k^\dagger \left(\ketbra{\alpha_{k+1}'}{\alpha_{k+1}}\otimes \bI\right)\right) \tr\left(U_0 \left(\ketbra{\alpha_0}{\alpha_0'}\otimes \ketbra{0}{0}\right) U_0^\dagger \left(\ketbra{\alpha_1'}{\alpha_1}\otimes \bI\right)\right) \delta_{a_t, \alpha_t'} \delta_{a_t', \alpha_t}\\
    &= \frac{1}{d_A^2} \frac{1}{d_B^{2t-2}} \sum_{\substack{\bm a, \bm a', \\ \bm \alpha, \bm \alpha'}} \prod_{k=1}^{t-1} \tr\left(U_k^{\otimes 2} \left(\ketbra{a_k \alpha_k}{a_k'\alpha_k'}\otimes \bI^{\otimes 2}\right) U_k^\dagger{}^{\otimes 2} \left(\ketbra{a_{k+1}' \alpha_{k+1}'}{a_{k+1} \alpha_{k+1}}\otimes \bI^{\otimes 2}\right)\right) \nonumber\\
    &\qquad \qquad \qquad \times \tr\left(U_0^{\otimes 2} \left(\ketbra{a_0 \alpha_0}{a_0' \alpha_0'}\otimes \ketbra{0}{0}^{\otimes 2}\right) U_0^\dagger{}^{\otimes 2} \left(\ketbra{a_1' \alpha_1'}{a_1 \alpha_1}\otimes \bI^{\otimes 2}\right)\right) \delta_{a_0, \alpha_0'} \delta_{a_0', \alpha_0} \delta_{a_t, \alpha_t'} \delta_{a_t', \alpha_t},
\end{align}
which is represented as tensor network as in Fig.~\ref{fig:uncond_purity_mix_diagram}c. Since it shares the same boundary condition as in Fig.~\ref{fig:uncond_purity_mix_diagram}b, the contribution toward $U_1$ remains the same as in $\tr(\rho_{A_t}^2)$.
The dynamical solution for the purity of $\rho_{RA_t}$ is
\begin{align}
    &\E_{\rm Haar} \tr(\rho_{R A_t}^2) \nonumber\\
    &= \frac{1}{d_A^2} \frac{1}{d_B^{2(t-1)}}\left[\left(\frac{d_B^2(d_A^2 - 1)}{d_A^2 d_B^2-1}\right)^{t-1} \frac{d_B(d_A^2 - 1)}{d_A^2d_B^2-1} d_A^2 + \left(\frac{d_B^2(d_A^2 - 1)}{d_A^2 d_B^2-1}\right)^{t-1} \frac{d_A(d_B^2-1)}{d_A^2d_B^2-1} d_A \nonumber \right.\\
    &\left. \qquad \qquad \qquad + \frac{d_A (d_B^2-1)}{d_A^2 d_B^2-1} d_B^{2(t-1)}\sum_{k=0}^{t-2} \left(\frac{d_B^2 (d_A^2 - 1)}{d_A^2 d_B^2-1}\right)^k d_B^{-2k} d_A\right]\\
    &= \frac{1}{d_A^2} \frac{1}{d_B^{2(t-1)}} \left[\frac{d_A^2}{d_B}\left(\frac{d_B^2(d_A^2 - 1)}{d_A^2 d_B^2-1}\right)^{t} + \frac{d_A^2 (d_B^2-1)}{(d_A^2-1)d_B^2}\left(\frac{d_B^2(d_A^2 - 1)}{d_A^2 d_B^2-1}\right)^{t} + \frac{d_B^{2(t-1)}}{d_A^2 - 1}\left(d_A^2-1-(d_A^2 d_B^2-1) \left(\frac{d_A^2 - 1}{d_A^2 d_B^2 - 1}\right)^t \right)   \right] \\
    &= \left(d_B - \frac{1}{d_A^2}\right) \left(\frac{d_A^2 - 1}{d_A^2 d_B^2-1}\right)^{t} + \frac{1}{d_A^2}.
    \label{eq:rhoRA_purity_mix_sol}
\end{align}

We again switch the order of ensemble average and logarithmic, and combine the results in Eqs.~\eqref{eq:rhoR_purity_mix_sol},~\eqref{eq:rhoA_purity_mix_sol} and~\eqref{eq:rhoRA_purity_mix_sol}.
\begin{align}
    &\E_{\rm Haar} I_2(R:A_t) \simeq -\log_2 \E_{\rm Haar}\tr(\rho_R^2) - \log_2 \E_{\rm Haar}\tr(\rho_{A_t}^2) + \log_2 \E_{\rm Haar}\tr(\rho_{R A_t}^2) \\
    &= N_A - \log_2 \left[\frac{d_B-1}{d_A} \left(\frac{d_A^2 - 1}{d_A^2 d_B^2-1}\right)^{t} + \frac{1}{d_A}\right] + \log_2\left[\left(d_B - \frac{1}{d_A^2}\right) \left(\frac{d_A^2 - 1}{d_A^2 d_B^2-1}\right)^{t} + \frac{1}{d_A^2}\right],
\end{align}
which is the result of Eq.~\eqref{eq:MI_traceout_id} in the main text. In the large limit of system $d_A, d_B \gg 1$, we perform the asymptotic analysis as
\begin{align}
    \E_{\rm Haar} I_2(R:A_t) &\simeq N_A - \log_2 \left(\frac{1}{d_A} d_B^{1-2t} + \frac{1}{d_A}\right) + \log_2\left(d_B^{1-2t} + \frac{1}{d_A^2}\right) \\
    &\simeq 2N_A - d_B^{1-2t} + \log_2 \left(d_A^{-2} + d_B^{1-2t}\right).
\end{align}
In the early time $t \ll N_A/N_B + 1/2$, we can further approximate it as
\begin{align}
    \E_{\rm Haar} I_2(R:A_t) &\simeq 2N_A - d_B^{1-2t} + \log_2 d_B^{1-2t} \left(d_A^{-2}d_B^{2t-1} + 1\right)\\
    &\simeq 2N_A - d_B^{1-2t} + (1-2t)N_B + d_A^{-2}d_B^{2t-1}\\
    &\simeq 2N_A + N_B - 2t N_B + \mathcal{O}(d_B^{1-2t}). 
\end{align}
While for the late time $t \gg N_A/N_B + 1/2$, we can further approximate it as
\begin{align}
    \E_{\rm Haar} I_2(R:A_t) &\simeq 2N_A - d_B^{1-2t} + \log_2 d_A^{-2} \left(1 + d_A^{2}d_B^{1-2t}\right)\\
    &\simeq 2N_A - d_B^{1-2t} -2 N_A + d_A^2 d_B^{1-2t}\\
    & \simeq d_A^2 d_B^{1-2t}.
\end{align}


