\subsection{Stability}
\label{subsection:robustness-diffusion-models}
In view of \cref{subsubsection:issues-with-globally-defined-measures}, the stability of zero-noise limits is now studied on stable manifolds of a gradient system of a Morse function and then globally, enabled by structural stability. On stable manifolds, these zero-noise limits are physical measures. First, it is known that zero-noise limits are closely related to the \textit{stochastic stability} of Borel probability measures (\cite{cowieson2005srb}). 

\begin{definition}[Stochastic stability]
\label{definition:stochastic-stability}
    Let $(M,g)$ be a Riemannian manifold and $\mathcal{M}$ the set of Borel probability measures on $M$ with the weak topology. A probability measure $\mu \in \mathcal{M}$ is \textbf{\textit{stochastically stable}} with respect to small random perturbations from a class of Markov chains $\mathcal{F}$ if for every family of small random perturbations $\{\mathcal{X}^{\epsilon}\}_{\epsilon>0}$ of $f$, with $\mathcal{X}^{\epsilon} \in \mathcal{F}$, the collection of stationary measures $\{\mu^{\epsilon}\}_{\epsilon>0}$ converges weakly to $\mu$ as $\epsilon \rightarrow 0$.
\end{definition}

The following corollary is a consequence of \Cref{definition:stochastic-stability}. It says that zero-noise limits for small random perturbations of generic associative memory models are stochastically stable with respect to white-noise perturbations.
\begin{corollary}[Stochastic stability of zero-noise limits]
\label{corollary:stochastically-stable}
    Let $(M,g)$ be a Riemannian manifold and $X=-\nabla_g V$ be a gradient field with $V \in C^r(M, \mathbb{R}), r\geq 2$ a Morse function. Let $\mathcal{F}$ be the collection of Markov diffusion processes generated by Brownian motion, and $\{\mathcal{X}^{\epsilon}\}_{\epsilon>0}$ be a family of small random perturbations of the gradient flow $\phi_t^X$ with $\mathcal{X}^{\epsilon}\in \mathcal{F}$. Then the zero-noise limit $\mu$ of $\{\mathcal{X}^{\epsilon}\}_{\epsilon>0}$ is stochastically stable.
\end{corollary}
\begin{proof}
    The small random perturbations $\{\mathcal{X}^{\epsilon}\}_{\epsilon>0}$ are arbitrary in \Cref{proposition:zero-noise-limit-MS}. Apply the definition of stochastic stability.
\end{proof}

The following proposition is motivated by \cite{bowen1975ergodic}, Proposition 5.4 and details the stability, or dependence, of zero-noise limits on stable manifolds to $C^{r+1}$ perturbations to Morse functions. The proof follows from the Stable Manifold Theorem for a Morse function (\Cref{theorem:stable-manifold-theorem-morse}) combined with \Cref{proposition:zero-noise-limit-MS}. 

\begin{proposition}
[Continuous dependence of zero-noise limits]
\label{lemma:zero-noise-continuous-dependence}
    Let $\phi^X_t$ be a Morse gradient flow generated by $X = -\nabla_g V$ for $V \in C^{r+1}(M,\mathbb{R}), r\geq1$ a Morse function. Denote the set of critical elements of $X$ by $\{ \beta_i,...,\beta_n\}$ and let $W^s(\beta_a)$ be a stable manifold for $\beta_a$, $a \in 1,...,n$; let $\{\mathcal{X}^{\epsilon}\}_{\epsilon>0}$ be a family of small random perturbations of $X$. Then the zero noise limit of $\{\mathcal{X}^{\epsilon}\}_{\epsilon>0}$ on $W^s(\beta_a)$ depends continuously on the $C^r$ flow $\phi^X_t$ for the weak topology on measures and the compact-open $C^{r+1}$ topology on real-valued functions.
\end{proposition}

\begin{proof}
    Let $\mu$, and $\mu'$ be zero-noise limits for small random perturbations $\{ \mathcal{X^{\epsilon}}\}_{\epsilon >0}$ and $\{ \mathcal{X'^{\epsilon}}\}_{\epsilon >0}$ of the gradient flows $\phi_t^X$ and $\phi_t^{X'}$, respectively, with $X' \in \text{Grad}^r(M)$. We have to show that the sequence $\{\mu'\}$ converges to $\mu$ weakly on $W^s(\beta_a)$ when $V' \rightarrow V$ in the $C^{r+1}$ sense, where $X' = -\nabla_g V'$. Let $(U_1,\psi_1),...,(U_k,\psi_k)$ be a finite covering of $M$ (by compactness). Choose compact sets $K_i \subset U_i$ such that $\bigcup_i K_i$ covers $M$. From \Cref{lemma:good-critical-points-milnor}, there exists an $\alpha>0$ so that all 
    functions $V' \in C^{r+1}(M,\mathbb{R})$ with
    \begin{equation*}
        || D^j (V \circ \psi^{-1})(x) - D^j(V' \circ \psi^{-1})(x)|| < \alpha
    \end{equation*}
    have non-degenerate critical elements on $M$, where $x \in \psi(K)$ with $K = K_i$ for some $i$ and $j = 0,...,r+1$. This $\alpha$-neighborhood of $V$ induces a neighborhood of $\nabla_gV$ in $C^r(M,TM)$ and similarly on flows by the uniqueness of the solutions to \eqref{equation:vector-field-ode-definition}. That is, for $V'$ within $\alpha$ of $V$ in the $C^{r+1}$ sense above, the flows $\phi_t^X$ and $\phi_t^{X'}$ are within some $\eta >0$. For any $\delta \leq \eta$, non-degeneracy of critical points is preserved since $V'$ is within $\alpha$ of $V$. Call this neighborhood $\mathcal{U}$. Convergence in the compact-open $C^r$ topology is uniform. Therefore for any $\delta>0$, there exists an $N \in \mathbb{Z}^{+}$, such that for all $n \geq N$, it holds that 
    \begin{equation*}
        || D^l (\psi \circ \phi_t^{X'_{n}} \circ \psi^{-1})(x) - D^l (\psi \circ \phi_t^{X} \circ \psi^{-1})(x) || < \delta
    \end{equation*}
    for $x \in \psi(K_i)$ for some $K_i$ and $l=0,...,r$. Call this $\delta$-neighborhood $\mathcal{V}$. Let $\mathcal{N = \mathcal{U} \, \cap \, \mathcal{V}}$. Then for any $\phi_t^{X'_{n}}\in \mathcal{N}$, the stable manifolds of its critical elements are well-defined, since the set $\text{Crit}(V'_{n})$ contains no degenerate critical points, and by \Cref{proposition:zero-noise-limit-MS}, the zero-noise limit $\mu_n'$ takes the form of a weighted sum of Dirac delta functions. By the Stable Manifold Theorem for a Morse function (\Cref{theorem:stable-manifold-theorem-morse}), $\delta$ can be chosen sufficiently small so the stable manifold $W^s(\beta_a^{'n})$ is $\epsilon$-$C^r$ close to $W^s(\beta_a)$ for any $\epsilon > 0$. That is,
    $W^s(\beta_a^{'n}) \rightarrow W^s(\beta_a)$ in the $C^r$ sense as $V'_n \rightarrow V$ in the $C^{r+1}$ sense, and $\beta_a^{'n} \rightarrow \beta_a$. On $W^s(\beta_a)$, $\mu$ is written $\mu = \int_{W^s(\beta_a)} w_a \delta_{\beta_{a}} \left(d\text{vol}_g(x)\right)$ subject to the constraint $\mu(W^s(\beta_a))=1$. Simply, $w_a=1$. The result follows immediately since $\beta_a^{'n} \rightarrow \beta_a$ and by \Cref{proposition:zero-noise-limit-MS}, $\mu'_n$ is similarly written $\mu'_n = \int_{W^s(\beta^{'n}_a)} w^{'n}_a \delta_{\beta^{'n}_{a}} \left(d\text{vol}_g(x)\right)$ with $w'_a=1$. We have that for any $f \in C^0_b(M)$,
    \begin{equation*}
        \int_{W^s(\beta_a^{'n})} f \,d\mu'_{n} = w_a^{'n} f(\beta_a^{'n}) \rightarrow w_a f(\beta_a) = \int_{W^s(\beta_a)} f \,d\mu.
    \end{equation*}
    Therefore, the subsequence $\{\mu'_{n}\}$ converges weakly to $\mu$. To show that $\{\mu'\}$ converges weakly to $\mu$, proceed by contradiction. Suppose that $\{\mu'\}$ does not converge weakly to $\mu$. Then there exists a $g\in C^0_b(W^s(\beta_a))$, a number $\delta > 0$, and a subsequence $\{\mu'_{k}\}$ for which 
    \begin{equation*}
        \left|\int_{W^s(\beta_a)} g \,d\mu - \int_{W^s(\beta_a^{'k})} g \,d\mu'_{k} \right| \geq \delta
    \end{equation*}
    for all $k \geq 1$. Therefore no subsequence converges, which is a contradiction.
\end{proof}

If $X$ is Morse-Smale, the invariant measures of randomly perturbed and deterministic systems can be studied globally. Since $X$ is structurally stable, there is a neighborhood $\mathcal{N} \subset \chi^1(M)$ of $X$ where each $Y \in \mathcal{N}$ is topologically equivalent to $X$. For each $Y$ there is a homeomorphism $h_Y:M \rightarrow M$ taking orbits of $Y$ to orbits of $X$ preserving orientation.

Any homeomorphism $h:M \rightarrow M$ is an automorphism of the measurable space $(M,\mathcal{B})$ as it is a measurable bijection with a measurable inverse. When $(M,\mathcal{B})$ is equipped with a probability measure $\mu_Y \in \mathcal{M}$, it becomes a Borel probability space $(M,\mathcal{B},\mu_Y)$. The image or \textit{pushforward} of $\mu_Y$ under $h$ is given by $h_{\#}\mu_Y(A) = \mu_Y(h^{-1}(A))$ for $A\in \mathcal{B}$. Similarly, an isomorphism $\psi: (M_X,\mathcal{B}_X,\mu_X) \rightarrow (M_Y,\mathcal{B}_Y,\mu_Y)$ between measure spaces is a measurable bijection with measurable inverse for which the measures agree: $\mu_X(A) = \mu_Y(\psi(A))$ for all $A \in \mathcal{B}_X$. If $h: M \rightarrow M$ is a homeomorphism, then $h: (M,\mathcal{B},\mu_Y) \rightarrow (M,\mathcal{B},h_{\#}\mu_Y)$ is an isomorphism of measure spaces, since it is an isomorphism of measurable spaces and $h_{\#}\mu_X(h(A)) = \mu_X(h^{-1}(h(A)))= \mu_X(A)$ for $A \in \mathcal{B}_X$.

Recall that a $\phi_t^X$-invariant measure $\mu$ is a measure for which $\phi_{t{\#}}^X \mu = \mu$. A flow $\phi_t^X$ equipped with a $\phi_t^X$-invariant measure $\mu$ defines a flow over the measure space $(M, \mathcal{B}, \mu)$; see \cite{sinai1989dynamical}, Definition 1.4 for a definition of flows over measure spaces. We focus on generalizations of measure space isomorphisms to such flows.

\begin{definition}[Metrically isomorphic\footnote{\Cref{definition:metrically-isomorphic} adapts \cite{sinai1989dynamical}, Definition 1.6, where metrically conjugate flows are called metrically isomorphic. "Conjugate" and "equivalent" are distinguished to agree with topologically conjugate and equivalent deterministic flows.}]
\label{definition:metrically-isomorphic}
    Two flows on $\phi_t^X$ and $\phi_t^Y$ on $(M,\mathcal{B})$ with invariant measures $\mu_X$ and $\mu_Y$, are called \textbf{\textit{metrically conjugate}} if there exists invariant subsets $M_1 \subset M$ and $M_2 \subset M$ with $\mu_X(M_X) = \mu_Y(M_Y) = 1$ and an isomorphism of measure spaces $h:(M_X,\mathcal{B}_X, \mu_X)\rightarrow (M_Y,\mathcal{B}_Y, \mu_Y)$ so that $\phi_t^Y(h(x)) = h(\phi_t^X(x))$ for all $t \in \mathbb{R}$ and $x \in M_X$. If there are times $t_1,t_2$ so that $h(\phi_{t_1}^X(x)) = \phi_{t_2}^Y(h(x))$ for all $t \in \mathbb{R}$ and $x \in M_X$, then $\phi_t^X$ and $\phi_t^Y$ are \textbf{\textit{metrically equivalent}}.
\end{definition}

If a flow $\phi_t^X$ on $(M, \mathcal{B}, \mu)$ is topologically conjugate (resp. equivalent) to $\phi_t^Y$, then it is metrically conjugate (resp. equivalent) to $\phi_t^Y$ as a flow on $(M, \mathcal{B}, h_{\#}\mu_X)$\footnote{See the proof of \Cref{lemma:metric-equivalence-Morse-Smale} in \Cref{appendix:strict-isomorphism-weak-convergence} that shows that topological equivalence implies metric equivalence.}. Zero-noise limits are now globally described using structural stability inherited by the Morse-Smale condition. Two lemmas, proven in \Cref{appendix:strict-isomorphism-weak-convergence}, are needed to prove \Cref{proposition:triangle-commutativity-zero-noise}.

\begin{lemma}[Homeomorphisms preserve weak convergence]
\label{lemma:strict-isomorphism-preserve-weak-convergence}
Suppose that $\mu$ and $\nu$ are Borel probability measures on $(M,\mathcal{B})$ and let $\{\mu_n\}$ be a sequence converging weakly to $\mu$. If $h: M \rightarrow M$ is a homeomorphism and $h_{\#}\mu = \nu$, then $h_{\#}\mu_n$ converges weakly to $\nu$. 
\end{lemma}

\begin{lemma}[Topological equivalence implies metric equivalence]
\label{lemma:metric-equivalence-Morse-Smale}
Let $(M,g)$ be a compact Riemannian manifold, $X$ a $C^r$ vector field on $M$, and $\mu$ an invariant Borel probability measure under the flow generated by $X$. If $Y$ is topologically equivalent to $X$ under an orientation preserving homeomorphism $h:M \rightarrow M$, then $h_{\#}\mu$ is invariant under the flow generated by $Y$ and $h: (M, \mathcal{B}, \mu) \rightarrow (M, \mathcal{B}, h_{\#}\mu)$ is a metric equivalence between them as flows over measure spaces. 
\end{lemma}

\begin{proposition}[Continuous dependence of region of convergence]
\label{proposition:triangle-commutativity-zero-noise}
    Let $\phi^X_t$ be a Morse-Smale gradient flow on a Riemannian manifold $(M,g)$ and $\{\mathcal{X}^{\epsilon}\}_{\epsilon>0}$ small random perturbations of $\phi^X_t$ with zero-noise limit $\mu$. A region of convergence of invariant measures $\{\mu^{\epsilon}\}$ to the zero-noise limit of $\{\mathcal{X}^{\epsilon}\}_{\epsilon>0}$ depends continuously on the $C^r$ flow $\phi^X_t, r\geq1$ for the weak topology on measures and the compact-open $C^1$ topology on flows.
\end{proposition}

\begin{proof}
    Let $\mu$ be the (zero-noise) invariant measure of $\phi^{X}_t$. We aim to show that if $\phi^{X'}_t \rightarrow \phi^X_t$ in the $C^1$ sense, a region of convergence of the sequence $\{\mu^{\epsilon}\}$ to $\mu$ varies continuously in the weak topology on measures and the $C^1$ topology on flows. That is, we aim to show that if $\phi^{X'}_t \rightarrow \phi^X_t$, and the sequence of invariant measures $\{\mu^{\epsilon}\}_{\epsilon >0}$ converges weakly to $\mu$ as $\epsilon \rightarrow 0$, then a sequence $\{\nu^{\epsilon}\}$ converges weakly to a $\phi^{X'}_t$-invariant measure $\nu$. 

    Since $\phi^X_t$ is Morse-Smale, it is structurally stable. Then there exists a neighborhood $\mathcal{V}$ of $\phi^X_t$ so that any $\phi^Y_t \in \mathcal{V}$ is topologically equivalent to $\phi_t^X$. Since $\phi^{X'}_t \rightarrow \phi^X_t$ uniformly, for any neighborhood $\mathcal{U}$ of $\phi^X_t$ there exists an $N$ so that for all $n \geq N$ the flow $\phi_t^{X'_{n}}$ is in $\mathcal{U}$. Set $\mathcal{N} = \mathcal{U} \cap \mathcal{V}$. Then each $\phi_t^{X'_{m}} \in \mathcal{N}$ is topologically equivalent to $\phi_t^X$. Therefore, each $\phi_t^{X'_{m}} \in \mathcal{N}$ can be equipped with a homeomorphism $h_{m}:M \rightarrow M$ so that for times $t$ and $t_m$, the following holds: $h_m(\phi_t^{X}(x)) = \phi_{t_m}^{X'_{m}}(h_m(x))$. Since $h_m$ is a topological equivalence, and $\mu$ is $\phi_t^X$-invariant, \Cref{lemma:metric-equivalence-Morse-Smale} implies that the image of $\mu$ under $h_m$, denoted $\nu_{m} = h_{m\#}\mu$, is invariant under $\phi_{t_m}^{X'_{m}}$ so that $h_m$ establishes a metric equivalence on flows over the measure spaces $(M,\mathcal{B},\mu)$ and $(M,\mathcal{B},\nu_m)$. Since $\mu$ is the zero-noise limit of $\{\mathcal{X}^{\epsilon}\}_{\epsilon >0}$, the sequence $\{\mu^{\epsilon}\}$ converges to $\mu$ weakly, by definition. Given a convergent subsequence $\{\mu^{\epsilon_{k}}\}$, define $\nu_m^{\epsilon_{k}} = h_{m\#}\mu^{\epsilon_{k}}$. By \Cref{lemma:strict-isomorphism-preserve-weak-convergence}, for each $\nu_m$, we have that $\nu_m^{\epsilon_{k}} \rightarrow \nu_m$. Application of the subsequence principle from \Cref{lemma:zero-noise-continuous-dependence} gives that $\nu_m^{\epsilon} \rightarrow \nu_{m}$ for each $\nu_m$.
\end{proof}

Let $X = -\nabla_g V$ be a Morse-Smale gradient field and $\{ \mathcal{X}^{\epsilon}\}$ be a family of small random perturbations of $\phi_t^X$ with zero-noise limit $\mu$. \Cref{proposition:triangle-commutativity-zero-noise} says that there exists a neighborhood $\mathcal{N}$ of $\phi_t^X$ were each $\phi_t^Y \in \mathcal{N}$ is topologically equivalent to $\phi_t^X$ and can be equipped with a homeomorphism that induces a commutative diagram on probability measures:

\begin{equation*}
    \begin{tikzcd}[column sep=6.5em, row sep=3.em]
    \mu^{\epsilon} \arrow[r, "w", "\epsilon \rightarrow 0" swap] \arrow[d, "h_{\#}"]
    & \mu \arrow[d, "h_{\#}"]  \\
    h_{\#}\mu^{\epsilon}  \arrow[r, "w"]
    & \nu
    \end{tikzcd} 
\end{equation*}
where horizontal arrows $\xrightarrow{w}$ indicate weak convergence in the limit of vanishing noise.

\begin{remark}
    The image of $\mu^{\epsilon}$ under $h$, that is, $\nu^{\epsilon} = h_{\#}\mu^{\epsilon}$, at a given noise-level $\epsilon>0$, may not be a Boltzmann-Gibbs distribution or even absolutely continuous with respect to Lebesgue measure on $(M,g)$.
\end{remark}

The properties of $\nu$ in \Cref{proposition:triangle-commutativity-zero-noise} and whether it is a zero-noise limiting measure are given as follows. Since $M$ is compact and $V$ is Morse, the non-wandering set $\Omega(X)$ is a finite number of hyperbolic critical points $\{\beta_1,...,\beta_n\}$. By \Cref{proposition:zero-noise-limit-MS}, the zero-noise limit $\mu$ is a finite sum of delta functions: $\mu = \sum_{i=1}^n w_i \delta_{\beta_i}$, with $\sum_{i=1}^n w_i = 1$. Since $\phi_t^X$ and $\phi_t^Y$ are topologically equivalent, the restriction of $h$ to $\Omega(X)$ gives $h|_{\Omega(X)} = {\Omega(Y)}$ where $\Omega(Y)$ is a union of a finite number of hyperbolic critical elements. That is, $\Omega(Y) =  \bigcup_{i=1}^n\{ \beta'_i\} =  \bigcup_{i=1}^n h(\{\beta_i\})$. Since $\Omega(Y)$ is a finite union of hyperbolic critical elements, $Y = -\nabla_{g'}V'$ for a Riemannian metric $g'$ on $M$ and a Morse function $V'$.

Generically, $V$ is an excellent Morse function, so the critical points of $X$ can be ordered by their critical values: $V(\beta_1) > V(\beta_2) > ... > V(\beta_n)$. By definition of the pushforward measure, $h_{\#}\mu = \mu(h^{-1}(A))$ for $A \in \mathcal{B}$. Consequently, $h_{\#}\mu = \sum_{i=1}w'_i\delta_{h(\beta_i)}$ where $w'_i$ is equal to the coefficient $w_i$ for which $h^{-1}(\beta'_i) = \beta_i$. We obtain the following:
\begin{enumerate}[itemsep=0pt]
    \item $\nu$ is the zero-noise limit for small random perturbations $\{\mathcal{Y}^{\epsilon} \}_{\epsilon>0}$ of the flow $\phi_t^Y$ if and only if $\beta_n = \text{inf}_{\beta_i}V'(h(\beta_i))$. That is, if and only if the critical element with uniformly minimal energy for the gradient system $X$ is that with minimal energy for $Y$.
    \item On a stable manifold $W^s(\beta_i)$ of $X$ with $i = 1,...n$, the limiting measure $\nu$ coincides with the zero-noise limit $\mu$ of the family of small random perturbations $\{ \mathcal{X}^{\epsilon}\}_{\epsilon>0}$.
\end{enumerate}


