\subsection{Proof of Proposition \ref{prop_results}}
\begin{proof}
\label{proof_prop_main}

We begin by proving the first part of the proposition. By the canonical representation \citep[page 26]{Vaart2023} and the almost-sure representation theorem \citep[Theorem 1.10.3]{Vaart2023}, we may assume that the sequence of random variables is defined in the same probability space, and that, almost surely:

\begin{equation}\lim_{s\to \infty} \max_{i=1,\ldots, N_1} |\hat{M}_{i} -{M}_{i}| = 0\, ,\end{equation}
\begin{equation}
\label{uniform_as}
\lim_{s \to \infty}\max_{e \in \mathcal{E}} | \Psi_s(e|\boldsymbol{X}; \hat{\delta}_s) - \Psi_s(e|\boldsymbol{X}; \delta_s)|  = 0\, .\end{equation}


Fix $l < \nu$, and take $u \in \{\gamma/2,1-\gamma/2\}$. Item (a) of Lemma 21.1 of \cite{Vaart_1998} yields the following implications:

\begin{enumerate}
    \item[i]If $\Psi_s(q_s(u + l|\boldsymbol{X})|\boldsymbol{X}; \hat{\delta}_s) > u$, then $q_s(u + l|\boldsymbol{X}) \geq {q}_s(u|\boldsymbol{X};\hat{\delta}_s)$.
\item[ii] If $\Psi_s(q_s(u - l|\boldsymbol{X})|\boldsymbol{X}; \hat{\delta}_s) < u$, then  $q_s(u -l|\boldsymbol{X}) \leq {q}_s(u|\boldsymbol{X};\hat{\delta}_s)$.
\end{enumerate}

Combining the above with \eqref{uniform_as}, and using that $\Psi_s(q_s(u)|\boldsymbol{X})|\boldsymbol{X}; {\delta}_s) =u$ by continuity of the true distribution, we arrive at:
$$\limsup_{s \to \infty} {q}_s(u -l|\boldsymbol{X}) \leq \limsup_{s\to \infty} {q}_s(u|\boldsymbol{X};\hat{\delta}_s)  \leq \limsup_{s \to \infty} {q}_s(u +l|\boldsymbol{X})  $$

$$ \liminf_{s\to \infty} {q}_s(u-l|\boldsymbol{X})  
 \leq \liminf_{s\to \infty} {q}_s(u|\boldsymbol{X};\hat{\delta}_s)  \leq \liminf_{s \to \infty} {q}_s(u+l|\boldsymbol{X})  $$

Using the first of these inequalities, we obtain, by the conditional Fatou inequality \citep[page 88]{Williams_1991}

\begin{equation*}
\tiny
    \begin{aligned} 1-\gamma - 2l \leq \\
   \underbrace{ \liminf_{s \to \infty} E_s\left[\mathbf{1}\left\{\frac{1}{N_1}\sum_{i=1}\alpha_i \in [ \boldsymbol{\hat \alpha}- q(1-\gamma/2|\boldsymbol{X};\hat \delta_s), \boldsymbol{\hat \alpha}- q(\gamma/2|\boldsymbol{X};\hat \delta_s)\right\}-\mathbf{1}\left\{\frac{1}{N_1}\sum_{i=1}\alpha_i \in [ \boldsymbol{\hat \alpha}- q(1-\gamma/2 -l|\boldsymbol{X}), \boldsymbol{\hat \alpha}- q(\gamma/2+l|\boldsymbol{X})\right\}\Big| \boldsymbol{X}\right]}_{\overset{\text{Fatou}}{\geq}0}
    \\ +
\liminf_{s \to \infty} \underbrace{E_s\left[\mathbf{1}\left\{\frac{1}{N_1}\sum_{i=1}\alpha_i \in [ \boldsymbol{\hat \alpha}- q(1-\gamma/2 -l|\boldsymbol{X}), \boldsymbol{\hat \alpha}- q(\gamma/2+l|\boldsymbol{X})\right\}\Big| \boldsymbol{X}\right]}_{\overset{\text{continuity of true distr.}}{=}1-\gamma - 2l} \leq
\\ \liminf_{s \to \infty}  P_s\left[\frac{1}{N_1}\sum_{i=1}\alpha_i \in [ \boldsymbol{\hat \alpha}- q(1-\gamma/2|\boldsymbol{X};\hat\delta_s), \boldsymbol{\hat \alpha}- q(\gamma/2|\boldsymbol{X};\hat\delta_s)\Big| \boldsymbol{X}\right]
    \end{aligned}
\end{equation*}

    By a similar argument, we obtain, by application of the conditional (reverse) Fatou inequality that:
    $$ \limsup_{s \to \infty}  P_s\left[\frac{1}{N_1}\sum_{i=1}\alpha_i \in [ \boldsymbol{\hat \alpha}- q(1-\gamma/2|\boldsymbol{X};\hat\delta_s), \boldsymbol{\hat \alpha}- q(\gamma/2|\boldsymbol{X};\hat\delta_s)\Big| \boldsymbol{X}\right] \leq 1-\gamma + 2l\, ,$$
    and since the choice of $l$ was arbitrarily, we obtain that, almost surely: 

    $$\lim_{s \to \infty}  P_s\left[\frac{1}{N_1}\sum_{i=1}\alpha_i \in [ \boldsymbol{\hat \alpha}- q(1-\gamma/2|\boldsymbol{X};\hat\delta_s), \boldsymbol{\hat \alpha}- q(\gamma/2|\boldsymbol{X};\hat\delta_s)\Big| \boldsymbol{X}\right] = 1-\gamma\, ,$$
which implies the convergence in probability stated in the proposition.

    The proof of the second part is identical -- one replaces conditional expectations and probabilities wrt $\boldsymbol{X}$ with conditioning on $\boldsymbol{X}$ and the treatment effect -- and is therefore omitted.
