\section{Appendices}

\subsection{Extension of Hilbert's theorem to affine spaces}
\label{sec:HilbertAffine}

The classical Hilbert projection theorem states that if $\mathcal{H}$ is a Hilbert space and $\mathcal{V} \subset \mathcal{H}$ is a nonempty closed convex subset, then for every $x \in \mathcal{H}$, there exists a unique point $p \in \mathcal{V}$ such that
\begin{equation}
    \|x - p\| = \inf_{y \in \mathcal{V}} \|x - y\|.
\end{equation}
In particular, when $\mathcal{V}$ is a closed linear subspace, the projection $p$ satisfies
\begin{equation*}
    x - p \perp \mathcal{V} .
\end{equation*}

Now, let $\mathcal{H}$ be a Hilbert space, and let $\mathcal{S}$ be an affine subspace, meaning there exists a closed linear subspace $\mathcal{V}$ and a fixed point $a \in \mathcal{H}$ such that
\begin{equation}
    \mathcal{S} = a + \mathcal{V} = \{ a + v : v \in \mathcal{V} \}.
\end{equation}

\begin{theorem}
    Let $\mathcal{H}$ be a Hilbert space, $\mathcal{V} \subset \mathcal{H}$ \,\,\,a nonempty closed subspace and $\mathcal{S} = a + \mathcal{V}$ a nonempty closed affine subspace. Then for every $x \in \mathcal{H}$, there exists a unique $p \in \mathcal{S}$ such that
    \begin{equation*}
        \|x - p\| = \inf_{y \in \mathcal{S}} \|x - y\|.
    \end{equation*}
    Moreover,
    \begin{equation*}
        x - p \perp \mathcal{V}.
    \end{equation*}
\end{theorem}

\begin{proof}
    Since $\mathcal{S}$ is an affine subspace, we can write $\mathcal{S} = a + \mathcal{V}$. Define the translation $x' = x - a$, so that our problem reduces to projecting $x'$ onto the linear subspace $\mathcal{V}$. By the Hilbert projection theorem for linear subspaces, there exists a unique $v_0 \in \mathcal{V}$ such that
    \begin{equation}
        \|x' - v_0\| = \inf_{v \in \mathcal{V}} \|x' - v\|.
    \end{equation}
    This implies that $x' - v_0$ is orthogonal to $\mathcal{V}$, i.e.,
    \begin{equation}
        x' - v_0 \perp \mathcal{V}.
    \end{equation}
    Setting $p = a + v_0 \in \mathcal{S}$, we obtain
    \begin{equation}
        x - p = (x' - v_0) \perp \mathcal{V}.
    \end{equation}
    Thus, $p$ is the unique closest point in $\mathcal{S}$ to $x$, and the orthogonality condition still holds relative to the associated direction subspace $\mathcal{V}$.
\end{proof}




