\section{Statement of main results}
\label{section:main-results}

To state our main results, we first gather together all of the assumptions that we outlined above and that are implicit in Definition~\ref{defn:dirichlet}.

\begin{hyp} \label{hyp:global-hyp}
    We make the following assumptions:  
    %
    \begin{itemize}
        \item $\Omega \subset \R^n$ is a bounded, connected, open domain. 

        \item  $v$ is a weight with $v\in L^1(\Omega)$, and $Q$ is a matrix function  satisfying inequality~\eqref{eqn:defn:hyp2}.

        \item $f,\, F \in L^2(v,\Omega)$, and $\bG,\, \bH,\, \vecg \in L^2(v,\Omega,\R^N)$ for some $N\in \N$.

        \item $\bR,\, \bS,\, \bT$ are $N$-tuples of degenerate vector fields satisfying~\eqref{eqn:norm-subunit}.

        \item $F,\, \bG, \bS$ satisfy the compatibility condition~\eqref{eqn:compatible}.  

    \end{itemize}
\end{hyp}

We also recall all of our assumptions needed for a Poincar\'e inequality.

\begin{hyp} \label{hyp:poincare}
    Given a quasimetric $\rho$ on a bounded, open set $\Theta$, we will assume that
    \begin{itemize}
    \item The $\rho$-balls are open in the standard topology on $\rn$. 

    \item For each $x\in\Theta$, there exists $\delta(x)>0$ such that if $0<r<\delta(x)$, then $\overline{B_\rho(x,r)} \subset \Theta$. 

    \item The quasimetric $\rho$ satisfies a local, geometric doubling condition:  there exists a function $G : (0,\infty)\rightarrow (0,\infty)$ such that, given any compact set $K\subset \Theta$, there exists $\delta>0$ such that if $0<s<r<\delta$ and $x\in K$, there exist at most $G(r/s)$ points $x_i\in B_\rho(x,r)$ such that the balls $B_\rho(x_i,s)$ are disjoint.
\end{itemize}
\end{hyp}

Our first result assumes the existence of a global Sobolev inequality with gain in the scale of Lebesgue spaces. In this case, we only need to assume the existence of a Poincar\'e inequality on $\Omega$. 

\begin{theorem}\label{thm:main-theorem}
Given  Hypothesis~\ref{hyp:global-hyp}, suppose that the global degenerate Sobolev inequality~\eqref{eqn:global-sobolev} holds with gain $\sigma>1$.  Also suppose the pair $(\Omega, \rho)$  is a quasimetric space that satisfies Hypothesis~\ref{hyp:poincare} and the local  degenerate Poincar\'e inequality~\eqref{eqn:local-poincare-QM}  holds on $\Omega$. If for some $q>2\sigma'$, $\bH,\,\bG \in L^{q}(v,\Omega,\R^N)$  and $F\in L^{\frac{q}{2}}(v,\Omega)$,  then the Dirichlet problem~\eqref{eqn:dirichlet} has a unique degenerate weak solution $ u \in QH_0^{1,2}(v,\Omega) $.
\end{theorem}

Our second result assumes the existence of a global degenerate Sobolev inequality on $\Omega$ in the scale of Orlicz spaces.  

\begin{theorem}\label{thm:log-gain}
Given  Hypothesis~\ref{hyp:global-hyp}, suppose that the global degenerate Sobolev inequality~\eqref{eqn:global-sobolev-orlicz} holds with $A(t)=t^2\log(e+t)^\sigma$, $\sigma>0$.  Also suppose the pair $(\Omega,\rho)$ is a quasimetric space  that satisfies Hypothesis~\ref{hyp:poincare} and the local  Poincar\'e inequality~\eqref{eqn:local-poincare-QM}  holds on $\Omega$. 
If for some $0<\lambda<1$, 
$\bH,\,\bG \in L^{C}(v,\Omega,\R^N)$, and $F\in L^{D}(v,\Omega)$, where $C(t)=\exp{(t^\frac{2}{\lambda\sigma})}-1$ and $D(t)=\exp{(t^\frac{1}{\lambda\sigma})}-1$, then the Dirichlet problem~\eqref{eqn:dirichlet} has a unique degenerate weak solution $ u \in QH_0^{1,2}(v,\Omega) $.
\end{theorem} 

Our next two results only assume the existence of a global degenerate Sobolev inequality without gain.  We can prove a version of the previous two theorems but only with stronger hypotheses.  First we need a size restriction on $\bG$ and $\bH$; in other words, we have a perturbation result.  Second, we also need a local degenerate Poincar\'e inequality on a larger domain $\Theta$. 

\begin{theorem}\label{thm:no-gain}
Given  Hypothesis~\ref{hyp:global-hyp}, suppose that the global degenerate Sobolev inequality~\eqref{eqn:global-sobolev} holds without gain (i.e., $\sigma=1$). Also suppose the pair $(\Theta,\rho)$ is a quasimetric space  that satisfies Hypothesis~\ref{hyp:poincare} and the local  Poincar\'e inequality~\eqref{eqn:local-poincare-QM}  holds on $\Theta$. 
If $F\in L^{\infty}(v,\Omega)$ and $\bH,\,\bG \in L^{\infty}(v,\Omega,\R^N)$, and if 
%
\[ \max(C(\bR),C(\bS))S(2,1))\big( \|\bG\|_{L^\infty(v,\Omega)} + \|\bH\|_{L^\infty(v,\Omega)}\big)<1, \]
%
then the Dirichlet problem~\eqref{eqn:dirichlet} has a unique solution $ u \in QH_0^{1,2}(v,\Omega) $.  
\end{theorem}


If we assume that our equation has no first order terms, then we do not have to assume the existence of a local degenerate Poincar\'e inequality, and we can weaken the assumptions in Hypothesis~\ref{hyp:global-hyp}.  

\begin{theorem} \label{thm:no-gain-no-first-order}
Given  a bounded domain $\Omega$ a weight $v$, and a matrix $Q$ suppose that the global degenerate Sobolev inequality~\eqref{eqn:global-sobolev} holds without gain (i.e., $\sigma=1$). If \hspace{0.02cm} $\bH=\bG=0$,  $F\in L^{\infty}(v,\Omega)$, and $F$ is nonnegative, then the Dirichlet problem~\eqref{eqn:dirichlet} has a unique degenerate weak solution $ u \in QH_0^{1,2}(v,\Omega) $.
\end{theorem} 

\medskip

As a corollary to our main theorems above, we can prove the existence of solutions to the Dirichlet problem with nonzero boundary data.  To state this result we define boundary equality in a weak sense, and then define the equation we are interested in and its degenerate weak solutions.


\begin{defn} 
Given $f,h\in QH^{1,2}(v,\Omega)$, we say that $f=h$ on the boundary $\partial\Omega$ if and only if $(f-h)\in QH^{1,2}_0(v,\Omega)$.  
\end{defn}

\begin{remark}
Note that with this definition, we do not assume, {\em a priori}, that $f$ and $h$ are actually defined outside of $\Omega$; the problem of boundary values and traces for degenerate elliptic operators is quite difficult and we will not consider it here.    
\end{remark}

\begin{defn}
Given  $\varphi\in QH^{1,2}(v,\Omega)$, we say that $u\in QH^{1,2}(v,\Omega)$ is a degenerate weak solution of the Dirichlet problem with boundary data $\varphi$, 
%
\begin{equation} \label{inhomogeneous} 
\begin{cases}
Lu = f + \bT' \vecg, & x \in \Omega, \\
 u = \varphi, & x \in \partial \Omega,
 \end{cases}
\end{equation}
%
if $w = u-\varphi$ is a degenerate weak solution of the  Dirichlet problem 
%
\begin{equation} \label{inhomogeneou2} 
\begin{cases}
Lw = f + \bT' \vecg - L\varphi, & x \in \Omega, \\
 w = 0, & x \in \partial \Omega,
 \end{cases}
\end{equation}
%    
\end{defn}

As an immediate consequence of the results above, we have the following corollary.

\begin{cor} \label{cor:boundary-data}
    Suppose that the hypotheses of Theorem~\ref{thm:main-theorem}, Theorem~\ref{thm:log-gain}, Theorem~\ref{thm:no-gain-no-first-order}, or Theorem~\ref{thm:no-gain} hold.  Then in every case the Dirichlet problem~\eqref{inhomogeneous} has a unique solution  $u \in QH^{1,2}(v,\Omega) $.  
\end{cor}

