\section{Preliminaries on vector fields}
\label{section:prelim-vector}

In this section we establish some preliminary results on the operator $L$ and solutions to the Dirichlet problem.  We begin with a lemma about degenerate subunit vector fields.  

\begin{lemma} \label{lemma:subunicity-cond}
    Let $\bR=(R_1,\ldots,R_N)$ be an $N$-tuple of degenerate subunit vector fields that satisfy~\eqref{eqn:norm-subunit}.   Then for any $u\in QH_0^{1,2}(v,\Omega)$ and a.e. $x\in \Omega$ we have the norm estimate
    %
    \begin{equation} \label{eqn:subunit-norm-cond}
\|\bR u\|_{L^2(v,\Omega)} \leq   C(\bR)\|u\|_{QH^{1,2}(v,\Omega)},
\end{equation}
    %
    where $C(\bR)= [C(R_1)+\cdots+C(R_N)]^{\frac{1}{2}}$.  
    If the vector fields satisfy the stronger pointwise inequality~\eqref{eqn:subunit-pointwise}, then 
    %
    \begin{equation} \label{eqn:subunit-pointwise}
    |\bR u(x)|\leq \frac{\sqrt{N}}{\sqrt{v}}{|\sqrt{Q}\nabla u(x)|},
    \end{equation}
    %
    which in turn implies that~\eqref{eqn:subunit-norm-cond} holds with $C(\bR)=\sqrt{N}$.
\end{lemma}

\begin{remark} \label{remark:subunit-norm-cond}
    If $v$ and $Q$ satisfy the global  Sobolev inequality~\eqref{eqn:global-sobolev} with no gain (i.e., $\sigma= 1$), \eqref{eqn:subunit-norm-cond} implies that% \no gain (i.e., $\sigma=1$ in \eqref{eqn:global-sobolev}), then~\eqref{eqn:subunit-norm-cond} implies that 
    %
    \[ \|\bR u\|_{L^2(v,\Omega)} \leq  C(\bR)(1+S(2,1)) \|\nabla u\|_{QL^2(\Omega)}. \]
\end{remark}

\begin{proof}
 Fix $u \in QH_0^{1,2}(v,\Omega)$.
    Then by inequality~\eqref{eqn:norm-subunit}, 
    %
    \[ \int_\Omega |\bR u|^2\,vdx = \sum_{i=1}^N \int_\Omega |R_i u|^2\,vdx \leq \sum_{i=1}^N C(R_i)^2 \|u\|_{QH^{1,2}(v,\Omega)}^2.
\]
   Similarly, if~\eqref{eqn:subunit-pointwise} holds, then for almost every $x\in \Omega$,
    %
\[     |\bR u(x)|=\bigg(\sum_{j=1}^N (\vecr(x) \cdot \grad u(x))^2 \bigg)^{\frac12}
    \leq\bigg(\sum_{j=1}^N v^{-1}{|\sqrt{Q}\nabla u(x)|}^2\bigg)^{\frac12}
    \leq\frac{\sqrt{N}}{\sqrt{v}}{|\sqrt{Q}\nabla u(x)|}. \]
%
\end{proof}

\medskip

Our next result establishes a product rule for degenerate subunit vector fields.  We need to prove three versions of this result, corresponding to the Sobolev inequality that we assume.

\begin{lemma}\label{product-rule-all-sobolevs}
    Let $ (u, \nabla u), (w, \nabla w) \in  QH^{1,2}_0(v, \Omega)$ and let $S=\textbf{s}\cdot\nabla$ be a degenerate subunit vector field that satisfies~\eqref{eqn:norm-subunit}. Then each of the following hold:
    \begin{enumerate}
    \item If the global Sobolev inequality \eqref{eqn:global-sobolev} holds with gain $\sigma>1$, then  there exists a unique $L^{\frac{2 \sigma}{\sigma + 1}}(v, \Omega)$ function $S(uw)$ such that $S(uw) = uS(w) + wS(u)$ (with equality in $L^{\frac{2 \sigma}{\sigma + 1}}(v, \Omega)$).

    \item If the global Sobolev inequality \eqref{eqn:global-sobolev-orlicz} holds with gain $A(t)=t^2\log(e+t)^\sigma$, then there exists a unique $L^B(v, \Omega)$ function $S(uw)$ such that $S(uw) = uS(w) + wS(u)$ in $L^B(v, \Omega)$, where  $B(t) = t\log(e+t)^\frac{\sigma}{2}$.  

    \item If the global Sobolev inequality \eqref{eqn:global-sobolev} holds with no gain (i.e., $\sigma=1$), then there exists a unique $L^1(v, \Omega)$ function $S(uw)$ such that $S(uw) = uS(w) + wS(u)$ in $L^1(v, \Omega)$.

    \end{enumerate}
\end{lemma}

\begin{remark}
    A version of part (1) of Lemma~\ref{product-rule-all-sobolevs} when $v=1$ was proved in~\cite[Lemma~3.3]{MR2994671}; our proof is adapted from this one.
\end{remark}
\begin{proof}
Fix  $ (u, \nabla u), (w, \nabla w) \in  QH^{1,2}_0(v, \Omega)$ and let $\{u_j\}_{j=1}^\infty$ and $\{w_j\}_{j=1}^\infty$ be sequences in $Q\lip_0(v,\Omega)$ that converge to $u$ and $w$ in $QH^{1,2}_0(v, \Omega)$.  Then by inequality~\eqref{eqn:norm-subunit}, $Su_j\to Su$ in $L^2(v,\Omega)$, since
%
\[ \|S(u_j)-S(u)\|_{L^2(v,\Omega)} \leq C(S) \|u_j-u\|_{QH^{1,2}(v, \Omega)}.     \]
%
For each $j$,
since $u_j,\, w_j \in Q\lip_0(v,\Omega)$, by Rademacher's theorem,
$\grad u_j,\, \grad w_j$ equal the classical gradients of $u_j,\,w_j$ a.e., so we have that $S(u_jw_j) = u_jS(w_j) + w_jS(u_j)$ almost everywhere.

\medskip

We now consider each of the cases outlined above in turn.  Suppose first that $(1)$ holds. 
Let $\gamma = \frac{2 \sigma}{\sigma +1}$;  we will first show that the sequence $\{S(u_jw_j)\}_{j=1}^\infty$ is Cauchy in $L^\gamma(v,\Omega)$.  If we add and subtract $u_iS(w_j)+w_iS(w_j)$, we get that 
%
    \begin{align}\label{eqn:zero-1.0}
        \|S(u_iw_i) - S(u_jw_j)\|_{L^\gamma(v,\Omega)} & \leq \|u_iS(w_i - w_j)\|_{L^\gamma(v,\Omega)} + \|w_iS(u_i - u_j)\|_{L^\gamma(v,\Omega)} \nonumber\\
        &\qquad + \|(u_i-u_j)S(w_j)\|_{L^\gamma(v,\Omega)} + \|(w_i-w_j)S(u_j)\|_{L^\gamma(v,\Omega)} \nonumber \\
        & = I_1+I_2+I_3+I_4.
    \end{align}
%
We first estimate $I_1$.  By  H\"older's inequality with exponents $\sigma + 1$, $\frac{\sigma + 1}{\sigma}$, the Sobolev inequality \eqref{eqn:global-sobolev}, and~\eqref{eqn:norm-subunit},
%
\begin{align}\label{eqn:zero-1.1}
    I_1^\gamma 
     &  \leq \bigg(\int_\Omega |u_i|^{2\sigma}\,\,vdx\bigg)^{\frac{1}{(\sigma +1)}}\bigg( \int_\Omega \big|S(w_i-w_j) \big|^2 v \, dx \bigg)^\frac{\sigma}{\sigma+1} \\
    &  \leq S(2,\sigma)^\gamma\|u_i\|^\gamma_{QH^{1,2}(v, \Omega)} \|S(w_i-w_j)\|^\gamma_{L^2(v,\Omega)} \notag \\
    & \leq  S(2,\sigma)^\gamma C(\bS)^\gamma\|u_i\|^{\gamma}_{QH^{1,2}(v, \Omega)} \|w_i-w_j\|_{QH^{1,2}(v,\Omega)}^{\gamma}. \notag
\end{align}
%
Since the $w_j$ converge in $QH^{1,2}_0(v, \Omega)$, they are Cauchy.  Since the $u_i$ converge, they are uniformly bounded.  Hence $I_1$ tends to $0$ as $i,\,j \to \infty$.  The same or similar estimates hold for $I_2,~I_3$, and $I_4$, possibly exchanging the roles of $u$ and $w$.  Therefore, we have that 
the $S(u_jw_j)$ are Cauchy in $L^\gamma(v,\Omega)$ and so converge.  Denote their limit by $S(uw)$. 

Finally, to show  that $S(uw)=uS(w)+wS(u)$ in $L^\gamma(v,\Omega)$, we will show that  $u_iS(w_i)\to uS(w)$ and  $w_iS(u_i)\to wS(u)$  in $L^\gamma(v,\Omega)$.  The same argument holds for each, and so we will prove the first limit. If we repeat the argument above in~\eqref{eqn:zero-1.1}, adding and subtracting $uS(w_i)$, we have that
%
\begin{align*}
& \|u_iS(w_i) - uS(w)\|_{L^\gamma(v,\Omega)} \\
 & \quad \leq \|(u_i-u)S(w_i)\|_{L^\gamma(v,\Omega)} + \|uS(w_i-w)\|_{L^\gamma(v,\Omega)}   \\  
    &  \quad\leq \|u_i-u\|^\gamma_{L^{2\sigma}(v,\Omega)} \,\|S(w_i)\|^\gamma_{L^2(v,\Omega)}
    + \|u\|^\gamma_{L^{2\sigma}(v,\Omega)} \,\|S(w_i-w)\|^\gamma_{L^2(v,\Omega)} \\
    & \quad\leq S(2,\sigma)^\gamma C(\bS)^\gamma\big[ \|u_i-u\|^\gamma_{QH^{1,2}(v, \Omega)} \|w_i\|^{\gamma}_{QH^{1,2}(v, \Omega)}
    + \|u\|^\gamma_{QH^{1,2}(v, \Omega)} \|w_i-w\|^{\gamma}_{QH^{1,2}(v, \Omega)} \big].  
\end{align*}
%
The last term goes to $0$ as $i\to \infty$; this gives us the desired limit.

\medskip 

Now suppose that $(2)$ holds.  The proof is very similar to the previous proof, except that we need to use H\"older's  inequality in the scale of Orlicz spaces.  We will describe the relevant changes. Arguing as we did before, we have that 
\begin{align*}
\|S(u_iw_i) - S(u_jw_j)\|_{L^B(v,\Omega)} & \leq \|u_iS(w_i - w_j)\|_{L^B(v,\Omega)} + \|w_iS(u_i - u_j)\|_{L^B(v,\Omega)} \\
        &\qquad  + \|(u_i-u_j)S(w_j)\|_{L^B(v,\Omega)} + \|(w_i-w_j)S(u_j)\|_{L^B(v,\Omega)} \\
        & = M_1+M_2+M_3+M_4.
\end{align*}
%
The estimates for each of the four terms are essentially the same, so we only show that for $M_1$.   Since $t^\frac{1}{2}A^{-1}(t) \lesssim B^{-1}(t)$, by \eqref{eqn:gen-orlicz-holder}, \eqref{eqn:norm-subunit} and the Sobolev inequality \eqref{eqn:global-sobolev-orlicz}, we have that
%
\begin{multline*}
M_1 \leq K\|u_i\|_{L^A(v,\Omega)}\|S(w_i-w_j)\|_{L^2(v,\Omega)} \\ 
\leq KS(2,A)C(\bS)\|u_i\|_{QH^{1,2}(v,\Omega)}\|w_i-w_j\|_{QH^{1,2}(v,\Omega)}.
\end{multline*}
%
We have similar estimates for $M_2$, $M_3$, and $M_4$, so we get that the  $S(u_iw_i)$ are Cauchy in $L^B(v,\Omega)$.  Denote their limit in $L^B(v,\Omega)$  by $S(uw)$.  To show that $S(uw) = uSw+wSu$ as $L^B(v,\Omega)$ functions we need to show that 
$u_iS(w_i)\to uS(w)$ and  $w_iS(u_i)\to wS(u)$ in $L^B(v,\Omega)$.  We only show the first limit.  If we essentially repeat the estimate for $M_1$, we get 
\begin{align*}
& \|u_iSw_i - uSw\|_{L^B(v,\Omega)} \\
& \qquad \quad \leq \|u_iS(w_i-w)\|_{L^B(v,\Omega)}
+ \|(u_i-u)Sw\|_{L^B(v,\Omega)}\\
&\qquad \quad \leq C\big[\|u_i\|_{L^A(v,\Omega)}\|S(w_i-w)\|_{L^2(v,\Omega)}+\|u_i-u\|_{L^A(v,\Omega)}\|Sw\|_{L^2(v,\Omega)}\big]\\
&\qquad \quad \leq CS(2,A)\big[\|u_i\|_{QH^{1,2}(v,\Omega)}\|w_i-w\|_{QH^{1,2}(v,\Omega)}
+ \|u_i-u\|_{QH^{1,2}(v,\Omega)}\|w\|_{QH^{1,2}(v,\Omega}\big].
\end{align*}
%
The desired limit follows immediately. 

\medskip

Finally, suppose $(3)$ holds.  Then using the Sobolev inequality \eqref{eqn:global-sobolev} with $\sigma = 1$, and taking $\gamma=1$, we can repeat the entire argument for $(1)$ to show that $S(uw)$ is defined as an $L^1(v,\Omega)$ function and that $S(uw)=uS(w)+wS(u)$.  This completes the proof. 
\end{proof}

\medskip

We now use Lemma~\ref{lemma:subunicity-cond} to prove that we can use functions in $QH^{1,2}_0 (v, \Omega)$ as test functions.

\begin{lemma} \label{lemma:QH1-test-func}
Given Hypothesis~\ref{hyp:global-hyp}, let  $u \in QH^{1,2}_0 (v, \Omega)$ be a degenerate weak solution of 
the Dirichlet problem~\eqref{eqn:dirichlet}, that is, \eqref{eqn:weak-soln} holds for all $\varphi \in Q\lip_0(v,\Omega)$.  Then \eqref{eqn:weak-soln} holds for all $\varphi \in QH^{1,2}_0(v,\Omega)$ if one of the following is true:
%
\begin{enumerate}
    \item The degenerate Sobolev inequality~\eqref{eqn:global-sobolev} holds for some $\sigma>1$, and for some $q>2\sigma'$, $\bG,\,\bH \in L^q(v,\Omega,\R^N)$, $F\in L^{\frac{q}{2}}(v,\Omega)$.

     \item The degenerate Sobolev inequality~\eqref{eqn:global-sobolev-orlicz} holds with $A(t)=t^2\log(e+t)^{\sigma}$ for some $\sigma>0$ and  $\bG,\,\bH \in L^C(v,\Omega,\R^N)$, $F\in L^{D}(v,\Omega)$, where $C(t)=\exp\big(t^{\frac{2}{\lambda\sigma}}\big)-1$ and $D(t)=\exp\big(t^{\frac{1}{\lambda\sigma}}\big)-1$ for some $0<\lambda<1$. 

      \item The degenerate Sobolev inequality~\eqref{eqn:global-sobolev} holds without gain (i.e., $\sigma=1$) and  $\bG,\,\bH \in L^\infty(v,\Omega,\R^N)$, $F\in L^{\infty}(v,\Omega)$.
\end{enumerate}
%
\end{lemma}

\begin{remark}
    As we alluded in Remark~\ref{rem:subunit-defn},  the proof of Lemma~\ref{lemma:QH1-test-func} also shows that with these hypotheses, every integral in~\eqref{eqn:weak-soln} is finite for any $\varphi \in Q\lip_\loc(v,\Omega)$.
\end{remark}

\begin{proof}
 Fix $\varphi \in QH_0^{1,2}(v,\Omega)$ and let $\{\varphi_k\}_{k=1}^\infty$ be a sequence of functions in $Q\lip_\loc(v,\Omega)$ that converge to $\varphi$ in $QH^{1,2}(v,\Omega)$ norm.  We need to show that with our hypotheses, each of the integrals in~\eqref{eqn:weak-soln} is the limit as $k\to \infty$ of the same integral with $\varphi$ replaced by $\varphi_k$.  The proofs are all variations of the same idea, so we will only prove that 
 %
 \begin{equation} \label{eqn:test-func1}
 \lim_{k\to\infty} \int_\Omega u\bG \cdot \bS\varphi_k\, \,vdx = \int_\Omega u\bG \cdot \bS\varphi\, \,vdx. 
 \end{equation}
 %
 By H\"older's inequality and Lemma~\ref{lemma:subunicity-cond},
 %
 \begin{multline} \label{eqn:test-func2}
 \bigg|\int_\Omega u\bG \cdot \bS\varphi_k\, \,vdx - \int_\Omega u\bG \cdot \bS\varphi\, \,vdx\bigg|
 \leq \int_\Omega |u\bG||\bS(\varphi_k-\varphi)|\, \,vdx \\
 \leq \|u\bG\|_{L^2(v,\Omega)}\|\bS(\varphi_k-\varphi)\|_{L^2(v,\Omega)} 
 \leq C(\bS)\|u\bG\|_{L^2(v,\Omega)}\|\varphi_k-\varphi\|_{QH^{1,2}(v,\Omega)}.  
\end{multline}

Suppose now $(1)$ holds.  Then by H\"older's inequality with exponent $\sigma$ and the Sobolev inequality (which also implies that there is a Sobolev inequality without gain), the last term above is bounded by 
%
\begin{multline*} C(\bS)(1+S(2,1)) \|u\|_{L^{2\sigma}(v,\Omega)}^2 \|\bG\|_{L^{2\sigma'}(v,\Omega)}^2\|\varphi_k-\varphi\|_{QL^2(\Omega)} \\
\leq CS(2,\sigma) v(\Omega)^{\frac{4\sigma'}{q}}\|\grad u\|_{QL^2(\Omega)}^2\|\bG\|_{L^{q}(v,\Omega)}^2 \|\varphi_k-\varphi\|_{QL^2(\Omega)}.
\end{multline*}
%
By our assumptions the first three terms are finite and the last term tends to $0$ as $k\to\infty$.  This shows that the limit~\eqref{eqn:test-func1} holds.

If $(2)$ holds, then starting from~\eqref{eqn:test-func2} we can argue as before; we just need to prove that $ \|u\bG\|_{L^2(v,\Omega)}$ is finite.
By H\"older's inequality in the scale of Orlicz spaces with $\Phi(t)=\exp(t^{\frac{1}{\sigma}})-1$ and $\bar{\Phi}(t)\approx t\log(e+t)^\sigma$, and by rescaling,
%
\begin{multline*} \|u\bG\|_{L^2(v,\Omega)} = \|u^2\bG^2\|_{L^1(v,\Omega)}^{\frac{1}{2}} \\
\leq 2\|u^2 \|_{L^{\bar{\Phi}}(v,\Omega)^{\frac{1}{2}}}\|\bG^2\|_{L^\Phi(v,\Omega)}^{\frac12}
\leq C\|u\|_{L^A(v,\Omega)}\|\bG\|_{L^C(v,\Omega)} < \infty. 
\end{multline*}

Finally, if $(3)$ holds, we can argue in exactly the same way, since we have that
%
\[ \|u\bG\|_{L^2(v,\Omega)} \leq \|\bG\|_{L^\infty(v,\Omega)} \|u\|_{L^2(v,\Omega)} < \infty. \]
%
This completes the proof.
\end{proof}

Finally, we prove that the compatibility condition~\eqref{eqn:compatible} holds for a larger collection of test functions.

\begin{lemma} \label{lemma:QH1-compatibility}
    Given Hypothesis~\ref{hyp:global-hyp}, let  $u,\, w \in QH^{1,2}_0 (v, \Omega)$.  If the conditions (1), (2), or (3) in Lemma~\ref{lemma:QH1-test-func} hold, then 
    %
    \begin{equation} \label{eqn:qh1-compatibility} 
    \int_\Omega (\bG \cdot \bS(uw) + Fuw) \,vdx \geq 0.
    \end{equation}
\end{lemma}

\begin{proof}
    The proof is similar to the ideas used in the proofs of Lemmas~\ref{product-rule-all-sobolevs} and~\ref{lemma:QH1-test-func}, and we will refer back for some details. Fix  $u,\,w \in  QH^{1,2}_0(v, \Omega)$ and let $\{u_j\}_{j=1}^\infty$ and $\{w_j\}_{j=1}^\infty$ be sequences in $Q\lip_0(v,\Omega)$ that converge to $u$ and $w$ in $QH^{1,2}_0(v, \Omega)$.  Then for each $j$, $u_jw_j \in Q\lip_0(v,\Omega)$, and so by the compatibility condition \eqref{eqn:compatible},
    %
    \[  \int_\Omega (\bG \cdot \bS(u_jw_j) + Fu_jw_j) \,vdx \geq 0. \]
    %
    Therefore, to prove that~\eqref{eqn:qh1-compatibility} holds, it will suffice to prove that
    %
    \[ \lim_{j\rightarrow \infty}  \bigg( \int_\Omega \bG \cdot \bS(u_jw_j)\,vdx  
    + \int_\Omega Fu_jw_j \,vdx \bigg)
    =  \int_\Omega \bG \cdot \bS(uw)\,vdx + \int_\Omega Fuw \,vdx.\]
    %
    We will prove that the limit of the first integral holds; the proof for the second is similar and somewhat simpler.  

    By Lemma~\ref{product-rule-all-sobolevs} we have that 
    %
    \[ S(uw) = wSu + uSw, \qquad S(u_jw_j) = w_jSu_j + u_jSw_j.\]
    %
    If we apply these identities and add and subtract the terms $w_jSu$ and $u_jSw$, we get that
    %
    \begin{align*}
      &  \bigg| \int_\Omega \bG\cdot \bS(uw) - \bG\cdot \bS(u_jw_j) \,vdx \bigg| \\
      &  \qquad \leq \int_\Omega |\bG||w_j||S(u-u_j)|\,vdx 
       + \int_\Omega |\bG||w- w_j||S(u)|\,vdx \\
      & \qquad \qquad  + \int_\Omega |\bG||u_j||S(w-w_j)|\,vdx 
       + \int_\Omega |\bG||u- u_j||S(w)|\,vdx.
    \end{align*}
    %
    We now argue as we did in the proof of~\eqref{eqn:test-func2} on each of these four terms:  we first apply H\"older's inequality and Lemma~\ref{lemma:subunicity-cond}, and then argue using the hypotheses in case (1), (2), (3).   In each case we get that the integral goes to $0$ as $j\rightarrow 0$ since $u_j\to u$ and $w_j\to w$ in $QH_0^{1,2}(v,\Omega)$.   This completes the proof.
\end{proof}

\section{Uniqueness of solutions of the zero problem}
\label{section:zero}

In this section we show that the zero function, ${\bf u}=(0,0)\in QH^{1,2}_0(v,\Omega)$, which is a degenerate weak solution of the  homogeneous Dirichlet problem (or simply, the zero problem),
\begin{equation}\label{homogeneous problem}
         \begin{cases}
 Lu = 0, & x \in \Omega, \\
 u = 0, & x \in \partial \Omega,
 \end{cases}
    \end{equation}
    is unique, given the hypotheses in Theorems~\ref{thm:main-theorem},~\ref{thm:log-gain}, and~\ref{thm:no-gain}. In particular, we will prove uniqueness assuming that a Sobolev inequality holds with gain $\sigma>1$, with Orlicz gain, and with no gain ($\sigma=1$).  
The uniqueness of the zero solution will be used in the proofs of these results when we apply the Fredholm alternative in the Hilbert space $QH_0^{1,2}(v,\Omega)$. 

\begin{theorem}\label{thm:hom-problem}
Given  Hypothesis~\ref{hyp:global-hyp}, ${\bf u}=(0,0)$ in $QH_0^{1,2}(v,\Omega)$ is the unique solution of the homogeneous Dirichlet problem \eqref{homogeneous problem} if one of the following is true:
%
\begin{enumerate}
    \item The degenerate Sobolev inequality~\eqref{eqn:global-sobolev} holds for some $\sigma>1$, and for some $q>2\sigma'$, $\bG,\,\bH \in L^q(v,\Omega,\R^N)$, $F\in L^{\frac{q}{2}}(v,\Omega)$.

     \item The degenerate Sobolev inequality~\eqref{eqn:global-sobolev-orlicz} holds with $A(t)=t^2\log(e+t)^{\sigma}$ for some $\sigma>0$, and  $\bG,\,\bH \in L^C(v,\Omega,\R^N)$ and $F\in L^{D}(v,\Omega)$, where $C(t)=\exp\big(t^{\frac{2}{\lambda\sigma}}\big)-1$ and $D(t)=\exp\big(t^{\frac{1}{\lambda\sigma}}\big)-1$ for some $0<\lambda<1$. 

      \item The degenerate Sobolev inequality~\eqref{eqn:global-sobolev} holds without gain (i.e., $\sigma=1$),  $F\in L^{\infty}(v,\Omega)$,  $\bG,\,\bH \in L^\infty(v,\Omega,\R^N)$, and
%
\begin{equation} \label{eqn:perturbation}
 \max(C(\bR),C(\bS))S(2,1))\big( \|\bG\|_{L^\infty(v,\Omega)} + \|\bH\|_{L^\infty(v,\Omega)}\big)<1.
\end{equation}

\end{enumerate}
%
\end{theorem}



\begin{remark} 
While case $(3)$ of Theorem \ref{thm:hom-problem} is true for small coefficients $\bH,\bG$, the case where these functions are zero plays an important role in  applications. To emphasize this we note specifically that, under the hypotheses of each case of Theorem~\ref{thm:hom-problem},  the solution ${\bf u}=(0,0)$ of \eqref{homogeneous problem} is unique when $\bH=\bG=0$.
\end{remark}



\begin{proof}[Proof of Theorems~\ref{thm:hom-problem}]
Let $\vecu=(u,\nabla u)\in  QH_0^{1,2}(v,\Omega)$ be a weak solution of the zero problem \eqref{homogeneous problem}.
Recall that $u$ and $\grad u$ are defined as the limit of a sequence of Lipschitz functions and their gradients in $L^2(v,\Omega)\oplus QL^2(\Omega)$; thus, while $u$ and $\grad u$ are unique as limits, we do not have that $\nabla u$ is  uniquely determined by $u$.  Consequently, we must prove separately that  $u=0$ in $L^2(v,\Omega)$ and $\nabla u=0$ in $QL^2(\Omega)$.   However, suppose for the moment that we can show that if $\vecu \in QH_0^{1,2}(v,\Omega)$ is a weak solution, then $u=0$, that is, $\vecu = (0,\vecf)$ for some $\vecf \in QL^2(\Omega)$.  Then by the definition of a weak solution \eqref{eqn:weak-soln} and Lemma~\ref{lemma:QH1-test-func} we have that for any $\vecw = (w,\grad w) \in QH_0^{1,2}(v,\Omega)$,
%
\[ 0 = \int_\Omega Q\vecf \cdot \grad w \,dx + \int_\Omega \bH \cdot \bR \vecf w \, vdx.   \] 
%
In particular, we can take $\vecw=\vecu$, in which case we get
%
\[ \int_\Omega |\sqrt{Q}\vecf|^2\,dx  = 0.  \]
%
Hence, we have that $\vecf=0$ in $QL^2(\Omega)$, which would complete the proof.

\medskip

Therefore, we need to prove that if $\vecu=(u,\nabla u)\in  QH_0^{1,2}(v,\Omega)$ is a weak solution, then $u=0$ in $L^2(v,\Omega)$.  To do so, we will first argue in general, and then treat each case (1), (2), and (3) in the hypotheses separately.  We argue by contradiction.  Suppose to the contrary that there exists a solution $\vecu$ such that  $u\neq 0$. Suppose $\sup_\Omega u>0$.  Note that in this case, by the Sobolev inequality (which holds in each case), $\|\grad u\|_{QL^2(\Omega)}>0$.  

Fix  $k>0$ such that $0<k<\sup_\Omega u$.  By assumption we have that $v\in L^1(\Omega)$ and \eqref{eqn:defn:hyp2} holds, and so,  by~Lemma~\ref{lemma:truncate}, $(w,\nabla w)=((u-k)_+,\chi_{\{x: u(x)>k\}}\nabla u) \in QH_{0}^{1,2}(v,\Omega)$.  Therefore, by Lemma~\ref{lemma:QH1-test-func}, we can use it as a test function for $u$ in \eqref{eqn:weak-soln}.  In other words, we have that
%
\[ \int_\Omega Q\nabla u\cdot \nabla w\, dx + \int_\Omega \bH\cdot\bR u w \, vdx
+ \int_\Omega u\bG \cdot\bS w\, vdx+\int_\Omega Fuw\, vdx=0. \]
%
In each of cases (1)--(3), by Lemma~\ref{product-rule-all-sobolevs} we have that $\bG\cdot\bS(uw)=u\bG\cdot\bS w+w\bG\cdot\bS u$.  Thus the above equality becomes
%
\begin{equation*}
\int_\Omega Q\nabla u \cdot \nabla w\, dx
=\int_\Omega w \big(\bG\cdot\bS u -\bH\cdot\bR u\big)\, vdx
- \int_\Omega \big(\bG\cdot\bS (uw) +Fuw\big)\, vdx.
\end{equation*}
%

We can now estimate as follows.  By Lemma~\ref{lemma:QH1-compatibility},  again in every case we have that the last integral is nonnegative, and so 
%
\[ \int_\Omega Q\nabla u \cdot \nabla w\, dx
\leq \int_\Omega w \big(\bG\cdot\bS u -\bH\cdot\bR u\big)\, vdx. \]
%
Let $\Gamma=\supp(w)$; note that $\supp(\grad w)\subset \Gamma$ and $\grad u = \grad w$ on $\Gamma$.  Therefore, by H\"older's inequality and Lemma~\ref{lemma:subunicity-cond},
\begin{align}
 \qquad   & \int_\Gamma Q\nabla w \cdot \nabla w\, dx
    \leq\int_\Gamma w(\bG\cdot\bS-\bH\cdot\bR) w\, vdx \notag\\
    &  \qquad \leq\int_\Gamma|w|\big(|\bG||\bS w|+|\bH||\bR w|\big)\,vdx; \notag \\
    &  \qquad\leq  \|w|\bG|\|_{L^2(v,\Gamma)}\|\bS w\|_{L^2(v,\Gamma)} + \|w|\bH|\|_{L^2(v,\Gamma)}\|\bR w\|_{L^2(v,\Gamma)} \notag \\
    &  \qquad\leq  \bigg(C(\bS)\|w|\bG|\|_{L^2(v,\Gamma)}+C(\bR)\|w|\bH|\|_{L^2(v,\Gamma)} \bigg)\|w\|_{QH^{1,2}(v,\Gamma)}; \notag
    \intertext{by the Sobolev inequality with no gain (which holds in every case),}
    &  \qquad\leq C\big( \bR, \bS, S(2,1)\big)\bigg(\|w|\bG|\|_{L^2(v,\Gamma)}+\|w|\bH|\|_{L^2(v,\Gamma)}\bigg)\|\nabla w\|_{QL^2(v,\Gamma)}.\label{eq:3.5}
    \end{align}


% 
\medskip

To complete the proof, we treat three cases.  Suppose first that $(1)$ holds.  
We estimate the first term on the righthand side of~\eqref{eq:3.5}.  By  H\"older's inequality with exponents $\frac{q}{2},\frac{q}{q-2}$ we have that
\begin{align*}
    \bigg(\|w|\bG|\|_{L^2(v,\Gamma)}+\|w|\bH|\|_{L^2(v,\Gamma)}\bigg)
    &\leq(\|\bG\|_{L^q(v,\Gamma)}+\|\bH\|_{L^q(v,\Gamma)}) \|w\|_{L^{\frac{2q}{q-2}}(v,\Gamma)}\\
    &=C(\bG,\bH)\|w\|_{L^{\frac{2q}{q-2}}(v,\Gamma)}. \\
    \intertext{Since $q>2\sigma'$, by H\"older's inequality  with exponents
$p=\frac{\sigma(q-2)}{q}>1$ and $p'=\frac{\sigma(q-2)}{\sigma(q-2)-q}$, }
    &\leq C(\bG,\bH)v\left(\Gamma\right)^{\frac{1}{2\sigma'}-\frac{1}{q}} \|w\|_{L^{2\sigma}(v,\Gamma)}. \\
\intertext{By the Sobolev inequality \eqref{eqn:global-sobolev} with gain $\sigma>1$,}
   &\leq C(\bG,\bH)S(2,\sigma)v\left(\Gamma\right)^{\frac{1}{2\sigma'}-\frac{1}{q}} \|\nabla w\|_{QL^2(\Gamma)}.
\end{align*}
%
If we insert this  estimate into \eqref{eq:3.5}, we get
%
\begin{equation*}
    \int_\Gamma |\sqrt{Q}\nabla w|^2~dx\leq C v\left(\Gamma\right)^{\frac{1}{2\sigma'}-\frac{1}{q}}\|\nabla w\|^2_{QL^2(\Gamma)},
\end{equation*}
%
where $C=C({\bf H},{\bf G},{\bf R},{\bf S},S(2,1),S(2,\sigma))>0$ does not depend on $k$. 
If we now divide both sides by $\|\nabla w\|^2_{QL^2(\Gamma)}$ and rearrange terms, then, since $\frac{1}{2\sigma'}-\frac{1}{q}>0$, we get
%
     \begin{equation*}
         v\left(\Gamma\right)\geq C^{-\frac{2q\sigma'}{q-2\sigma'}}>0. 
         \end{equation*}
% 
In other words, $\supp(w)$ 
has positive $v$-measure independent of $k$.  But, as  $k\to \sup_\Omega u$, since $u\in L^p(v,\Omega)$, we must have that  $w\rightarrow 0$ $v$-a.e. in $\Omega$, and so $v(\Gamma)\to 0$.  Thus, we have a contradiction, and so we must have that $\sup_\Omega u \leq 0$.   If we now assume that $\inf_\Omega u <0$, then we can repeat the above argument with  $k>0$ such that $0<k<-\inf_\Omega u$ and $w=((u+k)_-,\chi_{\{x: u(x)<-k\}}\nabla u)$.  This again yields a contradiction, and so we must have $\inf_\Omega u\geq 0$.  
 Therefore, $u=0$ $v$-a.e. in $\Omega$.

\medskip

Now suppose that $(2)$ holds.  The proof is very similar, but we use H\"older's inequality in the scale of Orlicz spaces.   Let $\Phi(t) = C(t^{\frac{1}{2}}) = \exp(t^\frac{1}{\lambda\sigma})-1$; then $\bar{\Phi}(t)\approx t\log(e+t)^{\lambda \sigma}$.  Then by  inequality \eqref{eqn:orlicz-holder} and rescaling, we get that
%
\begin{align*}
    \|w|\bG|\|_{L^2(v,\Gamma)}
    & \leq \big(2\|w^2\|_{L^{\bar{\Phi}}(v,\Gamma)}\||\bG|^2\|_{L^\Phi(v,\Gamma)}\big)^\frac{1}{2} \\
    & = \sqrt{2}\|w\|_{L^{\bar{\Phi}_2}(v,\Gamma)}\||\bG|\|_{L^{\Phi_2}(v,\Gamma)}. \\
    \intertext{Let $\Psi(t)=\exp(t^\frac{2}{\sigma(1-\lambda)})-1$; since $A^{-1}(t)\Psi^{-1}(t) \lesssim \bar{\Phi}^{-1}(t)$, by the generalized Orlicz Hölder inequality \eqref{eqn:gen-orlicz-holder} and the Sobolev inequality \eqref{eqn:global-sobolev-orlicz},}
    & \leq C(\bG) K\|w\|_{L^{A}(v,\Gamma)}\|\chi_\Gamma\|_{L^{\Psi}(v,\Gamma)} \\
    & \leq C(\bG,K)S(2,A)\|\grad w\|_{QL^{2}(v,\Gamma)}\|\chi_\Gamma\|_{L^{\Psi}(v,\Gamma)}.
\end{align*}
%
The same estimate also holds with $\bG$ replaced by $\bH$.  

If we now insert these estimates into~\eqref{eq:3.5}, we get
%
\begin{equation*}
      \int_\Omega Q\nabla w \cdot \nabla w\, dx\leq C\|\chi_\Gamma\|_{L^\Psi(v,\Gamma)}\|\nabla w\|^2_{{QL^2}(\Gamma)},
\end{equation*}
%
where $C=C(\bH,\bG,\bR,\bS,S(2,1),S(2,A))\geq 1$.  Rearranging terms, this becomes
%
\begin{equation*}
     C\|\chi_\Gamma\|_{L^\Psi(v,\Gamma)} \geq 1.
\end{equation*}
%
If we use the formula $\|\chi_\Gamma\|_{L^\Psi(v,\Gamma)}=[\Psi^{-1}(v(\Gamma)^{-1})]^{-1}$ and solve for $v(\Gamma)$, we get
%
\begin{equation*}
    v(\Gamma) \ge \big(\exp(C^{\frac{2}{\sigma(1-\lambda)}}\big)^{-1}  > 0.
\end{equation*}
%
We can now argue exactly as we did at the end of previous case, and again conclude that $u=0$ $v$-a.e. in $\Omega$.

\medskip 

Finally, suppose that $(3)$ holds.  This case is much simpler.  We repeat the argument that produced~\eqref{eq:3.5} using $u$ as a test function in place of $w$, and keeping the domain of integration $\Omega$.  We then get, after keeping careful track of the constants, that
%
\begin{align*}
& \int_\Omega \nabla Qu \cdot \nabla u \, dx \\
&\qquad \qquad  \leq  \max(C(\bR),C(\bS))S(2,1)) \big( \|u|\bG| \|_{L^2(v,\Omega)} + \|u|\bH| \|_{L^2(v,\Omega)}\big)
\|\grad u\|_{L^2{(v,\Gamma)}} \\
& \qquad \qquad \leq  \max(C(\bR),C(\bS))S(2,1))\big( \|\bG\|_{L^\infty(v,\Omega)} + \|\bH\|_{L^\infty(v,\Omega)}\big)
\|\grad u\|_{L^2{(v,\Gamma)}}.
\end{align*}
%
If we rearrange terms we get
%
\[  \max(C(\bR),C(\bS))S(2,1))\big( \|\bG\|_{L^\infty(v,\Omega)} + \|\bH\|_{L^\infty(v,\Omega)}\big)\geq 1, \]
%
which contradicts our assumption that~ \eqref{eqn:perturbation} holds.  We again conclude that $u=0$ $v$-a.e. in $\Omega$.  This completes the proof.
\end{proof}



\section{Boundedness and coercivity:  Sobolev inequality with  power gain}
\label{section:coerce-power-gain}

In order to prove the existence and uniqueness of solutions to our Dirichlet problem, we are going to apply techniques from functional analysis.  In order to do so, we will consider the properties of the bilinear form defined by the lefthand side of~\eqref{eqn:weak-soln}.  More precisely, define  $\mathcal{L}:QH_0^{1,2}(v,\Omega)\times QH_0^{1,2}(v,\Omega)\to \R$ by
%
\begin{equation} \label{bilinear}
    \mathcal{L}(u,w)=\int_{\Omega} \nabla Qw\cdot \nabla u\, dx +\int_{\Omega}\bH\cdot\bR u\,w \, vdx+\int_{\Omega} u\bG \cdot \bS w\, v dx+\int_{\Omega}Fuw\, vdx.
\end{equation}
%
We will need that the bilinear form $\mathcal{L}$ is bounded and almost coercive.  In this section we will prove this assuming that there is a Sobolev inequality with power gain.  In Section~\ref{section:coerce-weaker-gain} we will prove this assuming a Sobolev inequality with Orlicz gain or with no gain.

\begin{lemma} \label{lemma:bounded-power-gain}
Given  Hypothesis~\ref{hyp:global-hyp}, suppose that the global degenerate Sobolev inequality~\eqref{eqn:global-sobolev} holds with gain $\sigma>1$.   If for some $q>2\sigma'$, $\bH,\,\bG \in L^{q}(v,\Omega,\R^N)$  and $F\in L^{\frac{q}{2}}(v,\Omega)$,  then the bilinear form $\mathcal{L}$ is bounded: that is, there is a $C>0$  such that for every $u,\,w \in QH_0^{1,2}(v,\Omega)$,
    \begin{equation*}
        |\mathcal{L}(u,w)|\leq C\|u\|_{QH^{1,2}(v,\Omega)}\cdot\|w\|_{QH^{1,2}(v,\Omega)}.
    \end{equation*}
     %
\end{lemma}
\begin{proof}
    Fix $u,w \in QH_0^{1,2}(v,\Omega)$. Then by H\"older's inequality and  Lemma~\ref{lemma:subunicity-cond}, 
    %
\begin{align}\label{first part of bil.bdd}
  |\mathcal{L}(u,w)|
   & \leq \int_\Omega|Q\nabla u\cdot \nabla w|\,dx
   +\int_\Omega|\bH||\bR u||w|\,v dx \notag \\
   & \qquad +\int_\Omega|u||\bG||\bS w|\,v dx
   +\int_\Omega|Fuw|\,v dx \notag \\
   &\leq \|\nabla u\|_{QL^2(\Omega)}\|\nabla w\|_{QL^2(\Omega)} 
  +  \|w|\bH|\|_{L^2(v,\Omega)} \|\bR u\|_{L^2(v,\Omega)}  \notag \\
   &\qquad + \| u|\bG| \|_{L^2(v,\Omega)} \|\bS w\|_{L^2(v,\Omega)} 
    + \| F^{\frac{1}{2}}u \|_{L^2(v,\Omega)}  \|F^{\frac{1}{2}}w \|_{L^2(v,\Omega)} \notag \\
   &\leq \| u\|_{QH^{1,2}(v,\Omega)}\| w\|_{QH^{1,2}(v,\Omega)} 
  +   C(\bR) \|w|\bH|\|_{L^2(v,\Omega)} \| u\|_{QH^{1,2}(v,\Omega)}  \notag \\
   &  \qquad+   C(\bS) \| u|\bG| \|_{L^2(v,\Omega)} \| w\|_{QH^{1,2}(v,\Omega)} 
    + \| F^{\frac{1}{2}}u \|_{L^2(v,\Omega)} \|F^{\frac{1}{2}}w \|_{L^2(v,\Omega)}. \\  
    \intertext{Now apply H\"older's inequality with exponents $\sigma$ and $\sigma'$ in the last three terms to get}
        &\leq\|u\|_{QH^{1,2}(v,\Omega)}\|w\|_{QH^{1,2}(v,\Omega)} \notag \\
        & \qquad +  C(\bR)\|\textbf{H}\|_{L^{2\sigma'}(v,\Omega)}\|w\|_{L^{2\sigma}(v,\Omega)}\|u\|_{QH^{1,2}(v,\Omega)} \notag \\
        &\quad\quad+ C(\bS)\|\textbf{G}\|_{L^{2\sigma'}(v,\Omega)}\|u\|_{L^{2\sigma}(v,\Omega)}\|w\|_{QH^{1,2}(v,\Omega)} \notag \\
        & \qquad +\|F\|_{L^{\sigma'}(v,\Omega)}\|u\|_{L^{2\sigma}(v,\Omega)}\|w\|_{L^{2\sigma}(v,\Omega)}. \notag 
        \intertext{Finally, by the Sobolev inequality \eqref{eqn:global-sobolev},}
        & \leq C\|u\|_{QH^{1,2}(v,\Omega)}\|w\|_{QH^{1,2}(v,\Omega)}\notag, 
\end{align}
%
where 
%
\[ C=1+ S(2,\sigma)\big( C(\bR)\|\textbf{H}\|_{L^{2\sigma'}(v,\Omega)}+
 C(\bS)\|\textbf{G}\|_{L^{2\sigma'}(v,\Omega)}
+S(2,\sigma)\|F\|_{L^{\sigma'}(v,\Omega)}\big). \]
%
\end{proof}

In our next result  we prove that the bilinear form $\mathcal L$ is almost coercive.

\begin{lemma}\label{power-gain-almost-coercivity}
Given  Hypothesis~\ref{hyp:global-hyp}, suppose that the global degenerate Sobolev inequality~\eqref{eqn:global-sobolev} holds with gain $\sigma>1$. If for some $q>2\sigma'$, $\bH,\,\bG \in L^{q}(v,\Omega,\R^N)$  and $F\in L^{\frac{q}{2}}(v,\Omega)$,  then the bilinear form $\mathcal{L}$ is almost coercive: that is, there exist constants $c_1,\,C_3>0$ such that for every $u\in QH_0^{1,2}(v,\Omega)$, 
    %
    \begin{equation}\label{almcoercivity}
        \mathcal{L}(u,u)\geq c_1\|u\|_{QH^{1,2}(v,\Omega)}^2-C_3\|u\|_{L^2(v,\Omega)}^2.
    \end{equation}
    % 
\end{lemma}
\begin{proof}
    Fix $u\in QH_0^{1,2}(v,\Omega)$; then we have that
    %
    \begin{equation}\label{eq-coer}
    \begin{split}
        \mathcal{L}(u,u)&\geq \int_\Omega|\sqrt{Q}\nabla u|^2 dx
        -\bigg|\int_\Omega u\big(\bH\cdot\bR+\bG \cdot\bS\big) u\,vdx\bigg|
        -\bigg|\int_\Omega Fu^2\,vdx\bigg|\\
                &\geq \|\nabla u\|_{QL^2(\Omega)}^2-I_1-I_2.
    \end{split}
    \end{equation}
    %
   We first estimate $I_1$.  By H\"older's inequality, Lemma~\ref{lemma:subunicity-cond}, and the Sobolev inequality with no gain (which holds in this case),
   %
\begin{align}\label{eq:I1}
    I_1 
    & \leq \int_\Omega |u||\bH||\bR u| +|u\|\bG||\bS u|\,vdx  \\
    & \leq \|u |\bH|\|_{L^2(v,\Omega)}\|\bR u\|_{L^2(v,\Omega)} 
        + \|u |\bG|\|_{L^2(v,\Omega)}\|\bS u\|_{L^2(v,\Omega)} \notag \\
    & \leq  C(\bR)S(2,1) \|u |\bH|\|_{L^2(v,\Omega)}\| \grad u\|_{QL^2(\Omega)} \notag \\
    &  \qquad \quad +  C(\bS) S(2,1)\|u |\bG|\|_{L^2(v,\Omega)}\|\grad u\|_{QL^2(\Omega)}; \notag \\
        \intertext{if we now apply Hölder's inequality with the exponents $\frac{q}{2}$ and $(\frac{q}{2})'=\frac{q}{q-2}$, we get}
    & \leq C(\bR)S(2,1)\|\bH\|_{L^q(v,\Omega) }\|u^2\|_{L^\frac{q}{q-2}(v,\Omega)}^{\frac{1}{2}}\|\nabla u\|_{QL^2(\Omega)} \notag \\
    & \qquad \quad + C(\bS)S(2,1)\|\bG\|_{L^q(v,\Omega) }\|u^2\|_{L^\frac{q}{q-2}(v,\Omega)}^{\frac{1}{2}} \|\nabla u\|_{QL^2(\Omega)}\notag \\
    &  = C_0 \|u^2\|_{L^\frac{q}{q-2}(v,\Omega)}^{\frac{1}{2}}\|\nabla u\|_{QL^2(\Omega)}, \notag
\end{align}
%
where $C_0=C(\bR)S(2,1)\|\bH\|_{L^q(v,\Omega) }+C(\bS)S(2,1)\|\bG\|_{L^q(v,\Omega) }$.

Since $1<(\frac{q}{2})'<\sigma$, by the interpolation of the Lebesgue norms (see~\cite[inequality~(7.9)]{MR1814364}), Young's inequality~\eqref{eqn:youngs-ineq} with $p=\frac{1}{\lambda}$ and $\eta=\epsilon$ ($\epsilon>0$ to be fixed below), and by rescaling, we have that 
%
\begin{multline*}  \|u^2\|_{L^{\frac{q}{q-2}}(v,\Omega)} 
 =\|u^{2\lambda}u^{2(1-\lambda)}\|_{L^{\frac{q}{q-2}}(v,\Omega)}
 \leq \|u^2\|^\lambda_{L^\sigma(v,\Omega)}\|u^2\|^{1-\lambda}_{L^1(v,\Omega)} \\
 \leq \epsilon\|u^2\|_{L^\sigma(v,\Omega)}+\epsilon^{-\mu}\|u^2\|_{L{^1}(v,\Omega)}
        =\epsilon\|u\|^2_{L^{2\sigma}(v,\Omega)}+
        \epsilon^{-\mu}\|u\|^{2}_{L^{2}(v,\Omega)},
\end{multline*}
%
where $\mu=\frac{1-\lambda}{\lambda}$.        
If we combine this with the previous estimate and use the Sobolev inequality~\eqref{eqn:global-sobolev}, we get
%
\begin{align*}
        I_1&\leq C_0\big(\epsilon^{\frac{1}{2}}\|u\|_{L^{2\sigma}(v,\Omega)}+\epsilon^{\frac{-\mu}{2}}\|u\|_{L^2(v,\Omega)}\big) \|\nabla u\|_{QL^2(\Omega)}\\
    &=C_0S(2,\sigma)\epsilon^{\frac{1}{2}}\|\grad u\|_{QL^{2}(\Omega)}^2
    + C_0 \epsilon^{\frac{-\mu}{2}}\|u\|_{L^2(v,\Omega)}\|\nabla u\|_{QL^2(\Omega)}.\\
    \intertext{If we apply Young's inequality~\eqref{eqn:youngs-ineq} with $p=2$ and $\eta=\epsilon^{\frac{-(\mu+1)}{2}}$, we get }
    &\leq C_0 (S(2,\sigma)+1)\epsilon^{\frac{1}{2}}  \|\nabla u\|^2_{QL^2(\Omega)}
    + C_0\epsilon^{\frac{-(2\mu+1)}{2}}\|u\|^2_{L^2(v,\Omega)}.
   \end{align*}
%
Therefore, if we let $\epsilon= (4C_0(S(2,\sigma)+1)^{-2}$ and $C_1=C_0\epsilon^{\frac{-(2\mu+1)}{2}}$ we get 
%
\begin{equation}\label{eq:A}
    I_1\leq\frac{1}{4}\|\nabla u\|_{QL^2(\Omega)}^2+ C_{1}\|u\|_{L^2(v,\Omega)}^2.
\end{equation}

\medskip

We now estimate $I_2$.  The argument is similar to the above but simpler.  We use H\"older's inequality with exponents  $\frac{q}{2}$ and $(\frac{q}{2})'=\frac{q}{q-2}$, the estimate for $\|u^2\|_{L^{\frac{q}{q-2}}(v,\Omega)}$, and the Sobolev inequality  to get 
%
\begin{align*}
      I_2 \leq 
      &\|F\|_{L^{\frac{q}{2}}(v,\Omega)}\|u^2\|_{L^{\frac{q}{q-2}}(v,\Omega)}.\\
      &\leq\|F\|_{L^\frac{q}{2}(v,\Omega)}\big(\epsilon\|u\|_{L^{2\sigma}(v,\Omega)}^2+
        \epsilon^{-\mu}\|u\|_{L^{2}(v,\Omega)}^2\big)\\
        &\leq \|F\|_{L^\frac{q}{2}(v,\Omega)}\bigg(\epsilon{S(2,\sigma)}^2\|\nabla u\|_{QL^2(\Omega)}^2+
        \epsilon^{-\mu}\|u\|_{L^{2}(v,\Omega)}^2\bigg).
\end{align*}
%
Therefore, if we now set $\epsilon=\big(4S(2,\sigma)^2\|F\|_{L^{\frac{q}{2}}(v,\Omega)}\big)^{-1}$ and $C_2=\epsilon^{-\mu}\|F\|_{L^{\frac{q}{2}}(v,\Omega)}$ we get
%
\begin{equation}\label{eq:B}
    I_2\leq\frac{1}{4}\|\nabla u\|_{QL^2(\Omega)}^2+C_{2}\|u\|_{L^2(v,\Omega)}^2.
\end{equation}


If we now insert \eqref{eq:A} and \eqref{eq:B} into \eqref{eq-coer}, and then apply the Sobolev inequality with no gain, we get
%
\begin{equation*}
        \mathcal{L}(u,u) \geq \frac{1}{2}\|\nabla u\|_{QL^2(\Omega)}^2 -(C_1+C_2)\|u\|_{L^2(v,\Omega)}^2 \geq c_1\|u\|^2_{QH^{1,2}(v,\Omega)}-C_3\|u\|^2_{L^2(v,\Omega)},
 \end{equation*}
%
where $c_1=\big(\sqrt{2}(1+S(2,1))\big)^{-2}$ and $C_3=C_1+C_2$.  This completes the proof
\end{proof}

\section{Boundedness and coercivity:  Sobolev inequality with Orlicz gain or no gain}
\label{section:coerce-weaker-gain}

In this section we prove that the bilinear form~\eqref{bilinear} is bounded and almost coercive assuming the existence of a Sobolev inequality with Orlicz gain or no gain. We first consider the case of Orlicz gain.


\begin{lemma}\label{orlicz-gain-boundedness}
Given  Hypothesis~\ref{hyp:global-hyp}, suppose that the global degenerate Sobolev inequality~\eqref{eqn:global-sobolev-orlicz} holds with $A(t)=t^2\log(e+t)^\sigma$, $\sigma>0$.  
If for some $0<\lambda<1$, 
$\bH,\,\bG \in L^{C}(v,\Omega,\R^N)$, and $F\in L^{D}(v,\Omega)$, where $C(t)=\exp{(t^\frac{2}{\lambda\sigma})}-1$ and $D(t)=\exp{(t^\frac{1}{\lambda\sigma})}-1$, then
 the bilinear form $\mathcal{L}$ is bounded in $QH_0^{1,2}(v,\Omega)$: that is, there exists $C>0$  such that for every $u,w \in QH_0^{1,2}(v,\Omega)$,
    \begin{equation*}
        |\mathcal{L}(u,w)|\leq C\|u\|_{QH^{1,2}(v,\Omega)}\cdot\|w\|_{QH^{1,2}(v,\Omega)}
    \end{equation*}
    %
\end{lemma}
\begin{proof}
    Fix $u,\,w \in QH_0^{1,2}(v,\Omega)$. We first argue as we did in the proof of Lemma~\ref{lemma:bounded-power-gain} to get inequality~\eqref{first part of bil.bdd}.   To complete the proof we need to estimate the last three terms in this inequality.  To estimate the first of these, note that $C^{-1}(t)\Psi^{-1}(t)\lesssim t^{\frac{1}{2}}$, where $\Psi(t)=t^2\log(e+t)^{\lambda\sigma} \lesssim A(t)$.  Therefore, by the generalized H\"older's inequality~\eqref{eqn:gen-orlicz-holder} and the Sobolev inequality~\eqref{eqn:global-sobolev-orlicz} with gain $\Psi$, we get
    %
    \begin{multline*} \|w |\bH| \|_{L^2(v, \Omega)} 
    \leq K \|\bH\|_{L^{C}(v,\Omega)} \|w\|_{L^{\Psi}(v,\Omega)}\\
    \leq KS(2,\Psi)\|\bH\|_{L^{C}(v,\Omega)} \|\grad w\|_{QL^2(\Omega)}
    \leq KS(2,\Psi)\|\bH\|_{L^{C}(v,\Omega)} \|w\|_{QH^{1,2}(v,\Omega)}.
    \end{multline*}
    %
Similarly, we have that 
\begin{equation*}
      \|u\bG\|_{L^2(v, \Omega)} 
      \leq K S(2, \Psi)\|\bG\|_{L^{C}(v,\Omega)}\|w\|_{QH^{1,2}(v,\Omega)}.
\end{equation*}
%
To estimate the final term, we argue exactly as we did for the first term; by rescaling we get
%
\begin{equation*} \|F^{\frac{1}{2}}u \|^2_{L^2(v, \Omega)} 
    \leq K \|F^{\frac{1}{2}}u\|_{L^{C}(v,\Omega)} \|u\|_{L^{\Psi}(v,\Omega)}\\
    \leq KS(2,\Psi)\|F\|_{L^{D}(v,\Omega)}^{\frac{1}{2}}  \|u\|_{QH^{1,2}(v,\Omega)}.
\end{equation*}
% 
The same inequality holds with $u$ replaced by $w$.  If we now combine these three estimates with inequality~\eqref{first part of bil.bdd}, we get
%
\[ |\mathcal{L}(u,w)| \leq C\|u\|_{QH^{1,2}(v,\Omega)}\|w\|_{QH^{1,2}(v,\Omega)}, \]
%
where 
%
$$C=  KS(2,\Psi)\big( C(\bR)\|\bH\|_{L^C(v,\Omega)} + C(\bS)\|\bG\|_{L^C(v,\Omega)}
+ KS(2,\Psi)\|F\|_{L^D(v,\Omega)}\big).$$
\end{proof}

Next, we prove that with the same hypotheses the bilinear form is almost coercive.


\begin{lemma}\label{orlicz-gain-almost-coercivity}
Given  Hypothesis~\ref{hyp:global-hyp}, suppose that the global degenerate Sobolev inequality~\eqref{eqn:global-sobolev-orlicz} holds with $A(t)=t^2\log(e+t)^\sigma$, $\sigma>0$.  
If for some $0<\lambda<1$, 
$\bH,\,\bG \in L^{C}(v,\Omega,\R^N)$, and $F\in L^{D}(v,\Omega)$, where $C(t)=\exp{(t^\frac{2}{\lambda\sigma})}-1$ and $D(t)=\exp{(t^\frac{1}{\lambda\sigma})}-1$, then
 the bilinear form $\mathcal{L}$ is almost coercive: that is, there exist constants $c_1,\, C_3>0$ such that for every $u \in QH^{1,2}_0(v,\Omega)$,
 %
    \begin{equation*}
        \mathcal{L}(u,u) \geq c_1\|u\|^2_{QH^{1,2}(v,\Omega)} - C_3\|u\|^2_{L^2(v,\Omega)}.
    \end{equation*}
%
\end{lemma}

\begin{proof}
Fix $u \in QH_0^{1,2}(v,\Omega)$. We first argue as we did in the proof of Lemma~\ref{power-gain-almost-coercivity}, dividing the estimate into three parts as in~\eqref{eq-coer}.  We first estimate $I_1$ by arguing as in~\eqref{eq:I1}, but then applying H\"older's inequality in the scale of Orlicz spaces~\eqref{eqn:orlicz-holder} and rescaling to get
%
\begin{align*}
   I_1 & \leq \sqrt{2}C(\bR)S(2,1)\||\bH|^2\|_{L^D(v,\Omega)}^{\frac{1}{2}} \|u^2\|_{L^{\bar{D}}(v,\Omega)}^{\frac{1}{2}} \|\grad u \|_{QL^2(\Omega)} \\
   & \qquad \qquad + \sqrt{2}C(\bS)S(2,1)\||\bG|^2\|_{L^D(v,\Omega)}^{\frac{1}{2}} \|u^2\|_{L^{\bar{D}}(v,\Omega)}^{\frac{1}{2}} \|\grad u \|_{QL^2(\Omega)} \\
      & \leq \sqrt{2}S(2,1)(C(\bR) \|\bH\|_{L^C(v,\Omega)}  + C(\bS) \|\bG\|_{L^C(v,\Omega)})
      \|u^2\|_{L^{\bar{D}}(v,\Omega)}^{\frac{1}{2}} \|\grad u \|_{QL^2(\Omega)} \\
      & = C_0\|u^2\|_{L^{\bar{D}}(v,\Omega)}^{\frac{1}{2}} \|\grad u \|_{QL^2(\Omega)}.
\end{align*}

If we let $\Psi(t)=t\log(e+t)^\sigma$, then $t^{1-\lambda}\Psi^{-1}(t)^\lambda \lesssim \bar{D}(t)^{-1}$, and so by Theorem~\ref{scottinterp2} we have that 
%
\begin{equation}\label{Orlicz interpolation}
            \|u^2\|_{L^{\Bar{\Phi}}(v,\Omega)}
           =\epsilon\|u\|_{L^A(v,\Omega)}^2+K^{\mu+1}
        \epsilon^{-\mu}\|u\|_{L^2(v,\Omega)}^2
\end{equation}
%
 where $\mu=\frac{1-\lambda}{\lambda}$ and  $\epsilon >0$ will be fixed below.  
 Therefore, if we combine these two inequalities and use the Sobolev inequality~\eqref{eqn:global-sobolev-orlicz}, we get
%
\begin{align*}
 I_1 
 & \leq C_0\big(\epsilon^\frac{1}{2}\|u\|_{L^A(v,\Omega)}+K^{\frac{\mu+1}{2}}\epsilon^{\frac{-\mu}{2}}\|u\|_{L^2(v,\Omega)}\big) 
 \|\grad u \|_{QL^2(\Omega)} \\
 & \leq C_0S(2,A)\epsilon^\frac{1}{2}\|\grad u \|_{QL^2(\Omega)}^2
 + C_0K^{\frac{\mu+1}{2}}\epsilon^{\frac{-\mu}{2}}\|u\|_{L^2(v,\Omega)}\|\grad u \|_{QL^2(\Omega)}.
 \intertext{If we apply Young's inequality~\eqref{eqn:youngs-ineq} m with $p=2$ and  $\eta= \epsilon^{-\frac{(\mu+1)}{2}}K^{\frac{\mu+1}{2}}$, we get }
 & \leq C_0S(2,A)\epsilon^\frac{1}{2}\|\grad u \|_{QL^2(\Omega)}^2
 + C_0\epsilon^\frac{1}{2}\|\grad u \|_{QL^2(\Omega)}^2+ C_0K^{\mu+1}\epsilon^{-\frac{2\mu+1}{2}}\|u\|_{L^2(v,\Omega)}^2.
\end{align*}
%
Therefore, if we let $\epsilon=(4C_0S(2,A)+C_0)^{-2}$ and $C_1= C_0K^{\mu+1}\epsilon^{-\frac{2\mu+1}{2}}$, we have shown that
%
   \begin{equation}\label{eq:I1 Orlicz}
    I_1\leq \frac{1}{4}\|\nabla u\|_{QL^2(\Omega)}^2+C_{1}\|u\|_{L^2(v,\Omega)}^2.
\end{equation}

\medskip

We now estimate $I_2$ in \eqref{eq-coer}.  We proceed as above:  we apply the Orlicz H\"older inequality,  the interpolation inequality~\eqref{Orlicz interpolation}, and the Sobolev inequality to get
%
\begin{align*} 
    I_2
    & \leq 2\|F\|_{L^D(v,\Omega)}\|u^2\|_{L^{\Bar{D}}(v,\Omega)} \\
    & \leq 2\|F\|_{L^D(v,\Omega)}(\epsilon\|u\|_{L^A(v,\Omega)}^2+K^{\mu+1}
        \epsilon^{-\mu}\|u\|_{L^2(v,\Omega)}^2) \\
    & \leq 2\|F\|_{L^D(v,\Omega)}(\epsilon S(2,A)^2 \|\grad u\|_{QL^2(\Omega)}^2 +K^{\mu+1}
        \epsilon^{-\mu}\|u\|_{L^2(v,\Omega)}^2). 
\end{align*}
%
If we now let $\epsilon=(8{S(2,A)}^2\|F\|_{L^\Phi(v,\Omega)})^{-1}$, we get
%
\begin{equation}\label{eq:I2 Orlicz}
    I_2\leq \frac{1}{4}\|\nabla u\|_{QL^2(\Omega)}^2+C_{2}\|u\|_{L^2(v,\Omega)}^2.
\end{equation}
where $C_{2}=2K^{\mu+1}\epsilon^{-\mu}\|F\|_{L^\Phi(v,\Omega)}$.

If we now combine \eqref{eq:I1 Orlicz} and \eqref{eq:I2 Orlicz} with \eqref{eq-coer}, and use the Sobolev inequality with no gain, we get
%
\begin{align*} \mathcal{L}(u,u)
& \geq \|\nabla u\|_{QL^2(\Omega)}^2-\frac{1}{2}\|\nabla u\|_{QL^2(\Omega)}^2-(C_{1}+C_2)\| u\|_{L^2(v,\Omega)}^2 \\
& \geq c_1 \|u\|_{QH^{1,2}(v,\Omega)} - C_3\| u\|_{L^2(v,\Omega)}^2,
\end{align*}
where $C_3=C_{1}+C_{2}$ and $c_1=(\sqrt{2}(1+S(2,1)))^{-2}$. This completes the proof.
\end{proof}

\medskip

We now consider the case of a Sobolev inequality with no gain.  

\begin{lemma}\label{no-gain-boundedness} 
Given  Hypothesis~\ref{hyp:global-hyp}, suppose that the global degenerate Sobolev inequality~\eqref{eqn:global-sobolev} holds without gain (i.e., $\sigma=1$). 
If $F\in L^{\infty}(v,\Omega)$ and $\bH,\,\bG \in L^{\infty}(v,\Omega,\R^N)$,  then the bilinear form $\mathcal{L}$ is bounded in $QH_0^{1,2}(v,\Omega)$: that is, there is a $C>0$  such that for all $u,\,w \in QH_0^{1,2}(v,\Omega)$,
%
    \begin{equation*}
        |\mathcal{L}(u,w)|\leq C\|u\|_{QH^{1,2}(v,\Omega)}\cdot\|w\|_{QH^{1,2}(v,\Omega)}.
    \end{equation*}
 %   
\end{lemma}

\begin{proof}
Let $u,w \in QH_0^{1,2}(v,\Omega)$. We argue as in~\eqref{first part of bil.bdd} but instead of using H\"older's inequality we use the fact that all the coefficients are in $L^\infty$ to get
%
\begin{align*}
   |\mathcal{L}(u,w)|
   &\leq  \|u\|_{QH^{1,2}(v,\Omega)}\|w\|_{QH^{1,2}(v,\Omega)}  \\
   & \qquad \quad + C(\bR)\|\bH\|_{L^{\infty}(v,\Omega)}\|w\|_{L^2(v,\Omega)}\|u\|_{QH^{1,2}(v,\Omega)}\\
    &\qquad \quad+ C(\bS)\|\bG\|_{L^{\infty}(v,\Omega)}\|u\|_{L^2(v,\Omega)}\|w\|_{QH^{1,2}(v,\Omega)} \\
    & \qquad \quad  +\|F\|_{L^{\infty}(v,\Omega)}\|u\|_{L^2(v,\Omega)}\|w\|_{L^2(v,\Omega)}. 
 \intertext{If we now apply the Sobolev inequality, we get}
  & \leq  \|u\|_{QH^{1,2}(v,\Omega)}\|w\|_{QH^{1,2}(v,\Omega)}  \\
   & \qquad \quad + C(\bR)S(2,1)\|\bH\|_{L^{\infty}(v,\Omega)}
   \|\grad w\|_{QL^2(\Omega)}\|u\|_{QH^{1,2}(v,\Omega)}\\
    &\qquad \quad+ C(\bS)S(2,1)\|\bG\|_{L^{\infty}(v,\Omega)}
    \|\grad u\|_{QL^2(\Omega)}\|w\|_{QH^{1,2}(v,\Omega)} \\
    & \qquad \quad  +S(2,1)^2\|F\|_{L^{\infty}(v,\Omega)}\|\grad u\|_{QL^2(\Omega)}\|\grad w\|_{QL^2(\Omega)} \\ 
    & \leq  C\|u\|_{QH^{1,2}(v,\Omega)}\|w\|_{QH^{1,2}(v,\Omega)},
\end{align*}
%
where 
%
$$C=1+ C(\bR)S(2,1)\|\bH\|_{L^{\infty}(v,\Omega)}+ C(\bS)S(2,1)\|\bG\|_{L^{\infty}(v,\Omega)}+S(2,1)^2\|F\|_{L^\infty(v,\Omega)}.$$
\end{proof}


\begin{lemma}\label{no-gain-almost-coercivity}
Given  Hypothesis~\ref{hyp:global-hyp}, suppose that the global degenerate Sobolev inequality~\eqref{eqn:global-sobolev} holds without gain (i.e., $\sigma=1$). 
If $F\in L^{\infty}(v,\Omega)$ and $\bH,\,\bG \in L^{\infty}(v,\Omega,\R^N)$,  then the bilinear form $\mathcal{L}$ is almost coercive:  that is, there exist constants $c_1,\,C_3>0$ such that for every $u \in QH^{1,2}_0(v,\Omega)$,
%
\begin{equation*}
     \mathcal{L}(u,u) \geq c_1\|u\|^2_{QH^{1,2}(v,\Omega)} - C_3\|u\|^2_{L^2(v,\Omega)}.
    \end{equation*}
%
\end{lemma}

\begin{proof}
   We argue as we did above, starting with \eqref{eq-coer} and \eqref{eq:I1}.  Instead of applying H\"older's inequality we use the fact that the coefficients are in $L^\infty$ and Young's inequality~\eqref{eqn:youngs-ineq} with $p=2$ and $\eta=\epsilon$ (to be chosen below) to get
   %
\begin{align*}
I_1 
& \leq S(2,1)(C(\bR)\|\bH\|_{L^\infty(\Omega)} + C(\bS)\|\bG\|_{L^\infty(\Omega)})
\|u\|_{L^2(v,\Omega)}\|\nabla u\|_{QL^2(\Omega)} \\
& \leq S(2,1)(C(\bR)\|\bH\|_{L^\infty(\Omega)} + C(\bS)\|\bG\|_{L^\infty(\Omega)})
\big(\epsilon\|\nabla u\|^2_{QL^2( \Omega)} + \epsilon^{-1}\| u\|^2_{L^2(v,\Omega)}\big).
\end{align*}     
%
If we let $\epsilon=\big( 2S(2,1)(C(\bR)\|\bH\|_{L^\infty(\Omega)} + C(\bS)\|\bG\|_{L^\infty(\Omega)})\big)^{-1}$, we get
%
   \begin{equation}\label{eq:I1 Infty}
    I_1\leq \frac{1}{2}\|\nabla u\|_{QL^2(\Omega)}^2+C_1\|u\|_{L^2(v,\Omega)}^2
\end{equation}
where $C_1= \epsilon^{-1}S(2,1)(C(\bR)\|\bH\|_{L^\infty(\Omega)} + C(\bS)\|\bG\|_{L^\infty(\Omega)})$.

\medskip

The estimate for $I_2$ is imediate:

\begin{equation} \label{eqn:I2-infty}
      I_2\leq \int_\Omega |F||u^2|\,vdx\leq \|F\|_{L^\infty(\Omega)}\|u\|_{L^{2}(v,\Omega)}^2 = C_2\|u\|_{L^{2}(v,\Omega)}^2.
  \end{equation}
  %
  Therefore, if we insert \eqref{eq:I1 Infty} and \eqref{eqn:I2-infty} into \eqref{eq-coer}, and apply the Sobolev inequality, we get
  %
  \begin{equation*}
        \mathcal{L}(u,u)
         \geq \frac{1}{2}\|\nabla u\|_{QL^2(\Omega)}^2-C_3\| u\|_{L^2(v,\Omega)}^2 
         \geq c_1\|u\|_{QH^{1,2}(v,\Omega)}-C_3\| u\|_{L^2(v,\Omega)}^2, 
\end{equation*}
%
where $c_1=\big(\sqrt{2}(S(2,1)+1)\big)^{-2}$ and  $C_3=C_1+C_2$. 
\end{proof}

\section{Proof of main results}
\label{section:main-proofs}

In this section we prove Theorems~\ref{thm:main-theorem}--\ref{thm:no-gain}. For clarity, in this section we will not   follow the convention used above of writing (for instance) $u\in QH^{1,2}(v,\Omega)$.  Here we will use the fact that $QH^{1,2}_0(v,\Omega)$ is a Hilbert space whose elements are pairs: ${\bf u} = (u,\grad u)\in L^2(v,\Omega)\oplus QL^2(\Omega)$.  Define the projection mapping $\mathcal{P}_2:QH^{1,2}_0(v,\Omega)\rightarrow L^2(v,\Omega)$  by $\cP_2({\bf u}) = u$.  In our proof below we will need that $\mathcal{P}$ is a compact operator.  We prove this in the next two lemmas.  Since without additional work we can prove a more general result, we will prove that for $1< p<\infty$, the  projection  $\mathcal{P}_p:QH^{1,p}(v,\Omega)\rightarrow L^p(v,\Omega)$, $\cP_p({\bf u}) = u$, is compact.



\begin{lemma} \label{lemma:compact-gain}
Given $1<p<\infty$ and $\Omega$ and $v$ as in Hypothesis~\ref{hyp:global-hyp}, suppose that either the global degenerate Sobolev inequality~\eqref{eqn:global-sobolev} holds with gain $\sigma>1$, or the  Sobolev inequality~\eqref{eqn:global-sobolev-orlicz} holds with $A(t)=t^p\log(e+t)^\sigma$, $\sigma>0$.  Suppose further that the pair $(\Omega, \rho)$  is a quasimetric space that satisfies Hypothesis~\ref{hyp:poincare} and the local  degenerate Poincar\'e inequality~\eqref{eqn:local-poincare-QM}  holds on $\Omega$.  Then the projection mapping $\cP_p:QH^{1,p}_0(v,\Omega)\rightarrow L^p(v,\Omega)$ is compact.
\end{lemma}

The first part of Lemma~\ref{lemma:compact-gain}, assuming a Sobolev inequality with power gain, is a special case of a result due to Monticelli and the fourth author~\cite[Theorem~1.8]{MR4069608}.  The proof of this result was only sketched.  Since we can adapt the short proof of the case we need to also prove the second part, we include the details.

\begin{proof}
    We first assume that inequality~\eqref{eqn:global-sobolev} holds.  To show that $\cP_p$ is compact, fix any sequence $\{ \vecu_n \}_{n=1}^\infty  = \{(u_n,\grad u_n)\}_{n=1}^\infty$ such that for all $n$, $\|\vecu_n \|_{QH^{1,p}(v,\Omega)} \leq M$.  We will show that there exists a subsequence that is Cauchy in $L^p(v,\Omega)$ and so converges.   

    Since $\{u_n\}_{n=1}^\infty$ is uniformly bounded in $L^p(v,\Omega)$, which is reflexive, it has a  weakly convergent subsequence (see Yosida~\cite[p.~126]{MR1336382}).  Therefore, by passing to a subsequence, we may assume that $\{u_n\}_{n=1}^\infty$ is weakly Cauchy in $L^p(v,\Omega)$.   We will show that it is strongly Cauchy.  

    Fix $\epsilon>0$.  Since $v\in L^1(\Omega)$, there exists a compact set $K\subset \Omega$ such that
    %
    \[ v(\Omega\setminus K)^{\frac{1}{p\sigma'}} \leq \epsilon. \]
    %
    Therefore, for all $n>m$, 
    %
    \[ 
        \|u_n-u_m\|_{L^p(v,\Omega)} 
    \leq 
    \|u_n-u_m\|_{L^p(v,K)}
    +
    \|u_n-u_m\|_{L^p(v,\Omega\setminus K)} = I_1 + I_2. \]
%
We will estimate each term separately.  The second is straightforward:  by H\"older's inequality and inequality~\eqref{eqn:global-sobolev},
%
\begin{multline*} I_2 
\leq \|u_n-u_m\|_{L^{\sigma p}(v,\Omega)} v(\Omega\setminus K)^{\frac{1}{p\sigma'}} \\
\leq S(p,\sigma)\|\grad u_n-\grad u_m\|_{QL^p(\Omega)}v(\Omega\setminus K)^{\frac{1}{p\sigma'}}
\leq  2MS(p,\sigma)v(\Omega\setminus K)^{\frac{1}{p\sigma'}}
    \leq  2MS(p,\sigma)\epsilon. 
\end{multline*}

To estimate $I_2$, note that since the $\rho$-balls satisfy the geometric doubling property, by~\cite[Lemma~2.3]{MR4069608} there exists $\delta_0>0$ such that for every $0<r<\delta_0$, there is a finite collection of $\rho$-balls $\{B_j\}_{j=1}^J = \{ B_\rho(x_j,r)\}_{j=1}^J$ with $x_j \in K$ such that
%
\[  K \subset \bigcup_{j=1}^J B_j \subset \bigcup_{j=1}^J cB_j \subset \Omega, \]
%
where $c\geq 1$ is the constant in the Poincar\'e inequality~\eqref{eqn:local-poincare-QM}, and 
%
\[  \sum_{j=1}^J \chi_{cB_j}(x) \leq P. \]
% 
The constant $P$ is independent of the choice of $r$.  Fix such a collection of balls with $r$ such that the constant in~\eqref{eqn:local-poincare-QM} is $\epsilon$.  Then we have that 
%
\begin{align*} 
I_1^p 
& \leq \sum_{j=1}^J \int_{B_j} |u_n-u_m|^p\,vdx \\
& \leq 2^p \sum_{j=1}^J \int_{B_j} |u_n-u_m- (u_n-u_m)_{B_j,v}|^p\,vdx  
+ 2^p \sum_{j=1}^J |(u_n-u_m)_{B_j,v}|^p v(B_j) \\
& = 2^pI_3 + 2^p I_4.
\end{align*}

We again estimate each term separately.  To estimate $I_3$ we use the Poincar\'e inequality:
%
\begin{align*}
 I_3 
& \leq \epsilon^p \sum_{j=1}^J \|\vecu_n - \vecu_m\|_{QH^{1,p}(v,cB_j)}^p \\
& \leq \epsilon^p 2^p\sum_{j=1}^J \big[ \|u_n-u_m\|_{L^p(v,cB_j)}^p + \|\grad u_n-\grad u_m\|_{QL^p(cB_j)}^p] \\
& \leq \epsilon^p 2^pP \|\vecu_n - \vecu_m\|_{QH^{1,p}(v,)}^p \\
& \leq \epsilon^p 2^{2p}PM^p.
\end{align*}

Finally, to estimate $I_4$, since the sequence $\{u_n\}_{n=1}^\infty$ is weakly Cauchy in $L^p(v,\Omega)$, and since $\chi_{B_j} \in L^{p'}(v,\Omega)$, we have that there exists $L>1$ such that if $n>m\geq L$, then
%
\[ I_4 = \sum_{j=1}^J v(B_j)^{1-p}\bigg|\int_{\Omega} (u_n-u_m)\chi_{B_j}\,vdx\bigg|^p \leq \epsilon^p.  \]

If we combine the above estimates we see that for all such $n,\,m$ we have that
%
\[ \|u_n-u_m\|_{L^p(v,\Omega)} \leq 2^3PM\epsilon + 2\epsilon + 2MS(p,\sigma)\epsilon. \]
%
It follows that the sequence $\{u_n\}_{n=1}^\infty$ is strongly Cauchy.  

\medskip

Now suppose that~\eqref{eqn:global-sobolev-orlicz} holds with $A(t)=t^p\log(e+t)^\sigma$, $\sigma>0$. The only part of the above proof that changes is the estimate for $I_2$.  Fix $K\subset \Omega$ such that 
%
\[ \|\chi_{\Omega\setminus K}\|_{L^{\bar{A}}(v,\Omega)} = \bar{A}^{-1}\big(v(\Omega\setminus K)^{-1}\big)^{-1} 
\approx v(\Omega\setminus K)^{\frac{1}{p'}}\log(e+v(\Omega\setminus K)^{-1})^{-\frac{\sigma}{p}} \leq \epsilon.\]
%
Then by H\"older's inequality in the scale of Orlicz spaces~\eqref{eqn:orlicz-holder} and~\eqref{eqn:global-sobolev-orlicz},
%
\begin{multline*}
I_2 \leq 2\|u_n-u_m\|_{L^A(v,\Omega)}\|\chi_{\Omega\setminus K}\|_{L^{\bar{A}}(v,\Omega)} \\
\leq 2S(p,A)\|\grad u_n-\grad u_m\|_{QL^p(\Omega)}\|\chi_{\Omega\setminus K}\|_{L^{\bar{A}}(v,\Omega)}
\leq 4MS(p,A)\epsilon.
\end{multline*}
\end{proof}


\begin{lemma} \label{lemma:compact-no-gain}
 Given $1<p<\infty$ and $\Omega$ and $v$ as in Hypothesis~\ref{hyp:global-hyp}, and a bounded open set $\Theta$ such that $\bar{\Omega}\subset \Theta$,  suppose the pair $(\Theta,\rho)$ is a quasimetric space  that satisfies Hypothesis~\ref{hyp:poincare} and the local  Poincar\'e inequality~\eqref{eqn:local-poincare-QM}  holds on $\Theta$. Then the projection mapping $\cP_p:QH^{1,p}(v,\Omega)\rightarrow L^p(v,\Omega)$ is compact.
\end{lemma}

A more general version of Lemma~\ref{lemma:compact-no-gain} was proved in~\cite[Theorem~1.7]{MR4069608}.  The proof of our result is gotten by modifying the proof of Lemma~\ref{lemma:compact-gain} and so for completeness we sketch the changes.

\begin{proof}
    The proof is essentially the same as the proof of Lemma~\ref{lemma:compact-gain}.  We replace $\Omega$ by $\Theta$, and $K$ by $\bar{\Omega}$.  To prove that the sequence $\{u_n\}_{L^p(v,\Omega)}$ is weakly Cauchy we do not need to estimate the integral on $\Theta\setminus \bar{\Omega}$, so we do not need to estimate $I_2$, where we used the Sobolev inequality.  The rest of the proof is the same.
\end{proof}

\medskip
\begin{proof}[Proof of Theorems~\ref{thm:main-theorem},~\ref{thm:log-gain}, and~\ref{thm:no-gain}]
The proofs of these results are essentially the same.  We will use the Fredholm alternative to show that a unique solution exists; the results we proved above will show that the hypotheses of this result are satisfied.

Given an element ${\bf u}=(u,\grad u) \in QH^{1,2}_0(\Omega)$, it is a degenerate weak solution of the Dirichlet problem \eqref{eqn:dirichlet} if and only if
%
\begin{equation}\label{scottsol1}
\mathcal{L}({\bf u},{\bf h}) = \mathcal{F}({\bf h})
\end{equation}
%
for all ${\bf h}=(h,\grad h)\in QH^{1,2}_0(v,\Omega)$, where $\mathcal L$ is the bilinear form~\eqref{bilinear} and the linear functional $\mathcal{F}$ in  $QH^{1,2}_0(v,\Omega)^*$ is given by
%
$$\mathcal{F}({\bf h})= \int_\Omega fh\,vdx + \int_\Omega {\bf g}\cdot \bT{ h}\,vdx.$$
%
As we proved above (Lemmas~\ref{lemma:bounded-power-gain} and~\ref{power-gain-almost-coercivity} for Theorem~\ref{thm:main-theorem}, Lemmas~\ref{orlicz-gain-boundedness} and~\ref{orlicz-gain-almost-coercivity} for Theorem~\ref{thm:log-gain}, and Lemmas~\ref{no-gain-boundedness} and~\ref{no-gain-almost-coercivity} for Theorem~\ref{thm:no-gain}) the bilinear form $\mathcal{L}$ is bounded and almost coercive on $QH^{1,2}_0(v,\Omega)$.  Therefore, we can define a bounded and coercive operator as follows.  Define  $\mathcal{T}:L^2(v,\Omega)\rightarrow L^2(v,\Omega)^*$ by 
%
$$\mathcal{T}u(w) = \int_\Omega uw\,vdx$$
%
for all $w\in L^2(v,\Omega)$.  Then, for $\beta>C_3$ (as in Lemmas~\ref{power-gain-almost-coercivity},~\ref{orlicz-gain-almost-coercivity}, and~\ref{no-gain-almost-coercivity}), the associated bilinear form given by
$$\mathcal{B}({\bf u},{\bf h}) = \mathcal{L}({\bf u},{\bf h})  + \beta\int_\Omega uh\,vdx$$
is both bounded and coercive.  Hence, by the Lax-Milgram Theorem~\cite[Theorem~5.8]{MR1814364}, for every $\mathcal{G}\in QH^{1,2}_0(v,\Omega)^*$, there is a unique ${\bf w}\in QH^{1,2}_0(v,\Omega)$ such that
\begin{align}\label{augmentedBilinear}
\mathcal{B}({\bf w},{\bf h}) = \mathcal{G}({\bf h})
\end{align}
for all ${\bf h}\in QH^{1,2}_0(v,\Omega)$.  Thus, we can define a linear, invertible ``solution map" $J:QH^{1,2}_0(v,\Omega)^*\rightarrow QH^{1,2}_0(v,\Omega)$ by 
%
$${\bf w} = J(\mathcal{G})$$
%
where ${\bf w}$ is the unique element of $QH^{1,2}_0(v,\Omega)$ satisfying \eqref{augmentedBilinear}.

If we now add $\beta \mathcal{T}\mathcal{P}_2{\bf u}$ to each side, we see that equation \eqref{scottsol1} is equivalent to the equation 
%
\begin{align}\label{scottsol2}
\mathcal{B}({\bf u},{\bf h}) = \mathcal{G}({\bf h})
\end{align}
%
for all ${\bf h}\in QH^{1,2}_0(v,\Omega)$ where the linear functional $\mathcal{G}\in QH^{1,2}_0(v,\Omega)^*$ is defined by 
%
$$\mathcal{G} = \mathcal{F} + \beta\mathcal{T}\mathcal{P}_2({\bf u}).$$
%
Furthermore, ${\bf u}$ satisfies \eqref{scottsol2} if and only if $J\mathcal{B}({\bf u},\cdot)={\bf u}$.  Thus, $\vecu$ is a weak solution of our Dirichlet problem if and only if ${\bf u}$ satisfies the equation
%
\begin{align}\label{scottsol3}
(I-K){\bf u} = {\bf s}
\end{align}
%
where $K:QH^{1,2}_0(v,\Omega)\rightarrow QH^{1,2}_0(v,\Omega)$ is defined by $K=\beta J\mathcal{T}\mathcal{P}_2$ and ${\bf s} = J\mathcal{F}\in QH^{1,2}_0(\Omega)$.  Since each of the mappings $J,\mathcal{G},\mathcal{T}$ is continuous, $K$ is a compact operator if the projection map $\mathcal{P}_2$ is compact.  But this follows from Lemma~\ref{lemma:compact-gain} (for Theorems~\ref{thm:main-theorem} and~\ref{thm:log-gain}) and Lemma~\ref{lemma:compact-no-gain} (for Theorem~\ref{thm:no-gain}).   Therefore, by the Fredholm alternative \cite[Theorem~5.11]{MR1814364}, for each ${\bf s}\in QH^{1,2}_0(\Omega)$, equation \eqref{scottsol3} has exactly one solution ${\bf u} \in QH^{1,2}_0(v,\Omega)$ precisely when the kernel of $I-K$ is trivial.  Since ${\bf w}\in \textrm{Ker}(I-K)$ if and only if ${\bf w}=K{\bf w}$, if we apply $J^{-1}$ to each side we get that for every ${\bf h}\in QH^{1,2}_0(v,\Omega)$,
%
$$\mathcal{B}({\bf w},{\bf h}) = \beta\int_\Omega wh\,vdx.$$
%
Equivalently,  ${\bf w}\in \textrm{Ker}(I-K)$ if and only if
$$\mathcal{L}({\bf w},{\bf h}) = 0$$
for ${\bf h}\in QH^{1,2}_0(v,\Omega)$.
That is, ${\bf w}$ is a weak solution of the zero problem~\eqref{homogeneous problem}.
By Theorem~\ref{thm:hom-problem} (which holds given the hypotheses of Theorems~\ref{thm:main-theorem},~\ref{thm:log-gain}, or~\ref{thm:no-gain}),  $(0,0)\in QH^{1,2}_0(v,\Omega)$ is the unique degenerate weak solution of the zero problem, and so $\textrm{Ker}(I-K)$ is  trivial.  Therefore, we have shown that for every ${\bf s}\in QH^{1,2}_0(v,\Omega)$, there is a unique solution ${\bf u}\in QH^{1,2}_0(v,\Omega)$ of \eqref{scottsol3} and so there is a unique degenerate weak solution to the Dirichlet problem \eqref{eqn:dirichlet}.
\end{proof}

\medskip

\begin{proof}[Proof of Theorem~\ref{thm:no-gain-no-first-order}]
    The proof of this result is much simpler than the others.  Just assuming $v$ is nonnegative and measurable (i.e., a weight), we have that $QH_0^{1,2}(v,\Omega)$ is still a Hilbert space.  
    Since $\bG=\bH=0$, then it follows from the proofs of Lemmas~\ref{no-gain-boundedness} and~\ref{no-gain-almost-coercivity} that the bilinear form $\mathcal L$ is bounded and coercive.  (We use the Sobolev inequality without gain and the fact that $F$ is nonnegative, instead of the compatibility condition~\eqref{eqn:compatible}, to prove coercivity.)  Therefore, with the notation used above, by the Lax-Migram theorem there exists a unique $\vecu$ such that
    %
    \[ {\mathcal L}(\vecu,\vech) = {\mathcal F}(\vech); \]
    %
    equivalently, $\vecu$ is the unique degenerate weak solution to the Dirichlet problem \eqref{eqn:dirichlet}.
\end{proof}


\section{Proof of Corollary~\ref{cor:boundary-data}}
\label{section:cor-proofs}

Fix $\varphi\in QH^{1,2}(v,\Omega)$.  Recall that an element $u\in QH^{1,2}(v,\Omega)$ is a degenerate weak solution of the Dirichlet problem with boundary data $\varphi$,
%
\begin{equation}\label{inhomogeneousxx}
\begin{cases}
Lu = f+T'{\bf g}, & x\in \Omega,\\
u =\varphi, & x\in \partial\Omega,
\end{cases}
\end{equation}
%
if $w=u-\varphi \in QH^{1,2}(v,\Omega)$ is a solution of the Dirichlet problem 
%
\begin{equation}\label{inhomogeneous2xx}
\begin{cases}
Lw = f+{\bf T}'{\bf g} - L\varphi, & x \in \Omega,\\
w=0, & x\in \partial\Omega.
\end{cases}
\end{equation}
%
That is, for each $y \in QH^{1,2}_0(v,\Omega)$,
\begin{align*}
& \int_\Omega \nabla w \cdot Q\nabla y\,dx + \int_\Omega \bH\cdot\bR w y\,vdx 
+ \int_\Omega w\bG \cdot \bS y\,vdx + \int_\Omega Fwy\,vdx\\
&\qquad = \int_\Omega fy \,vdx + \int_\Omega {\bf g}\cdot {\bf T}y \,vdx \\
&\qquad \qquad - \int_\Omega \nabla \varphi\cdot Q\nabla y~dx -\int_\Omega \varphi \bH\cdot \bR y \,vdx 
- \int_\Omega \varphi \bG\cdot \bS y\,vdx - \int_\Omega Fy \varphi \,vdx\\
& \qquad =\int_\Omega \left[f - \varphi \bH\cdot \bR -F\varphi \right]y \,vdx \\
& \qquad \qquad +\int_\Omega \left[ {\bf g}\cdot {\bf T} - \frac{1}{\sqrt{v}}\sqrt{Q}\nabla \varphi \cdot \frac{1}{\sqrt{v}}\sqrt{Q}\nabla -\varphi\bG \cdot \bS \right]y\,vdx\\
&= \int_\Omega f_1y\,vdx + \int_\Omega {\bf g}_1{\cdot \bf T}_{1}y \,vdx, 
\end{align*}

where 
$f_1 = f - {\bf HR}\varphi - F\varphi$, 
%
$${\bf g}_1 = (g_1,..,g_N,-V_1\varphi,...,-V_n\varphi,-\varphi G_1,...,-\varphi G_N), $$
%
and
%
$${\bf T_1} = (T_1,...,T_N,V_1,...,V_n,S_1,...,S_N),$$
%
with $V_i = \frac{1}{\sqrt{v}}{\bf q_i}\cdot\nabla$ and ${\bf q_i}$ the $i$-th row vector of $\sqrt{Q}$.

It follows from Hypothesis~\ref{hyp:global-hyp} that  $f_1\in L^2(v,\Omega)$, ${\bf g_1}\in L^2(v,\Omega,\R^{2N+n})$, and  ${\bf T_1}$ a $(2N+n)$-tuple of degenerate subunit vector fields that satisfy \eqref{eqn:norm-subunit}.  Thus, if the hypotheses of one of Theorems \ref{thm:main-theorem}, \ref{thm:log-gain}, \ref{thm:no-gain}, or \ref{thm:no-gain-no-first-order}  hold, then this implies that there exists a unique degenerate weak solution $w\in QH^{1,2}_0(v,\Omega)$ of the Dirichlet problem \eqref{inhomogeneous2xx}.  Hence, $u=w+\varphi$ is a degenerate weak solution of \eqref{inhomogeneousxx}.  This completes the proof.

%Arguments needed:

%\begin{enumerate}
