    \entry{atlasfootnote}{misc}{}
      \field{sortinit}{1}
      \field{sortinithash}{4f6aaa89bab872aa0999fec09ff8e98a}
      \field{note}{ATLAS uses a right-handed coordinate system with its origin at the nominal interaction point (IP) in the center of the detector and the \(z\)-axis along the beam pipe. The \(x\)-axis points from the IP to the center of the LHC ring, and the \(y\)-axis points upwards. Polar coordinates \((r,\phi)\) are used in the transverse plane, \(\phi\) being the azimuthal angle around the \(z\)-axis. The pseudorapidity is defined in terms of the polar angle \(\theta\) as \(\eta = -\ln \tan(\theta/2)\) and is equal to the rapidity $ y = \frac{1}{2} \ln \left( \frac{E + p_z}{E - p_z} \right) $ in the relativistic limit. Angular distance is measured in units of \(\Delta R \equiv \sqrt{(\Delta y)^{2} + (\Delta\phi)^{2}}\).}
    \endentry
